INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe0e1958-1b2f-4c25-b013-4c68913fba30', '奉和聖製行次成皐途經先聖擒建德之所感而成詩應制', '奉和圣制行次成皐途经先圣擒建德之所感而成诗应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6f22\\u6771\\u4e0d\\u57f7\\u8c61\\uff0c\\u6cb3\\u6714\\u65b9\\u9b2c\\u9f8d\\u3002\", \"\\u590f\\u6ec5\\u6f38\\u5be7\\u4e82\\uff0c\\u5510\\u8208\\u7d42\\u596e\\u5eb8\\u3002\", \"\\u7687\\u5a01\\u6b63\\u8d6b\\u8d6b\\uff0c\\u5175\\u6c23\\u4f55\\u5308\\u5308\\u3002\", \"\\u7528\\u6b66\\u4e09\\u5ddd\\u9707\\uff0c\\u6b78\\u6df3\\u516d\\u4ee3\\u91b2\\u3002\", \"\\u6210\\u81ef\\u89a9\\u738b\\u696d\\uff0c\\u5929\\u4e0b\\u81f4\\u4eba\\u96cd\\u3002\", \"\\u5373\\u6b64\\u5de1\\u65bc\\u5cb1\\uff0c\\u66fe\\u5b6b\\u53d7\\u547d\\u5c01\\u3002\"]"', '"[\"\\u6c49\\u4e1c\\u4e0d\\u6267\\u8c61\\uff0c\\u6cb3\\u6714\\u65b9\\u9b2c\\u9f99\\u3002\", \"\\u590f\\u706d\\u6e10\\u5b81\\u4e71\\uff0c\\u5510\\u5174\\u7ec8\\u594b\\u5eb8\\u3002\", \"\\u7687\\u5a01\\u6b63\\u8d6b\\u8d6b\\uff0c\\u5175\\u6c14\\u4f55\\u5308\\u5308\\u3002\", \"\\u7528\\u6b66\\u4e09\\u5ddd\\u9707\\uff0c\\u5f52\\u6df3\\u516d\\u4ee3\\ud872\\udea9\\u3002\", \"\\u6210\\u81ef\\u89a9\\u738b\\u4e1a\\uff0c\\u5929\\u4e0b\\u81f4\\u4eba\\u96cd\\u3002\", \"\\u5373\\u6b64\\u5de1\\u4e8e\\u5cb1\\uff0c\\u66fe\\u5b59\\u53d7\\u547d\\u5c01\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製行次成皐途經先聖擒建德之所感而成詩應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d81c2f90-7a7b-455e-a3f2-389d5f3e7fbf', '奉和聖製登蒲州逍遙樓應制', '奉和圣制登蒲州逍遥楼应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5728\\u6614\\u582f\\u821c\\u79b9\\uff0c\\u907a\\u5875\\u6210\\u5178\\u8b28\\u3002\", \"\\u8056\\u7687\\u6771\\u5de1\\u72e9\\uff0c\\u6cc1\\u4e43\\u7d93\\u6b64\\u90fd\\u3002\", \"\\u6a13\\u89c0\\u7d1b\\u8fe4\\u9090\\uff0c\\u6cb3\\u5c71\\u5e7e\\u7e08\\u7d06\\u3002\", \"\\u7dec\\u61f7\\u7956\\u5b97\\u696d\\uff0c\\u76f8\\u7e7c\\u6587\\u6b66\\u5716\\u3002\", \"\\u5c1a\\u5fb7\\u65e2\\u7121\\u96aa\\uff0c\\u89c0\\u98a8\\u8ad2\\u6709\\u5b5a\\u3002\", \"\\u8c48\\u5982\\u6c7e\\u6c34\\u4e0a\\uff0c\\u7c2b\\u9f13\\u4e8b\\u904a\\u5a1b\\u3002\"]"', '"[\"\\u5728\\u6614\\u5c27\\u821c\\u79b9\\uff0c\\u9057\\u5c18\\u6210\\u5178\\u8c1f\\u3002\", \"\\u5723\\u7687\\u4e1c\\u5de1\\u72e9\\uff0c\\u51b5\\u4e43\\u7ecf\\u6b64\\u90fd\\u3002\", \"\\u697c\\u89c2\\u7eb7\\u8fe4\\u9026\\uff0c\\u6cb3\\u5c71\\u51e0\\u8426\\u7ea1\\u3002\", \"\\u7f05\\u6000\\u7956\\u5b97\\u4e1a\\uff0c\\u76f8\\u7ee7\\u6587\\u6b66\\u56fe\\u3002\", \"\\u5c1a\\u5fb7\\u65e2\\u65e0\\u9669\\uff0c\\u89c2\\u98ce\\u8c05\\u6709\\u5b5a\\u3002\", \"\\u5c82\\u5982\\u6c7e\\u6c34\\u4e0a\\uff0c\\u7bab\\u9f13\\u4e8b\\u6e38\\u5a31\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製登蒲州逍遙樓應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b2d165-05e6-418f-8a3a-f80872851807', '幸白鹿觀應制', '幸白鹿观应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u78a7\\u865b\\u6e05\\u5439\\u4e0b\\uff0c\\u85f9\\u85f9\\u5165\\u4ed9\\u5bae\\u3002\", \"\\u677e\\u78f4\\u6500\\u96f2\\u7d55\\uff0c\\u82b1\\u6e90\\u63a5\\u6f97\\u7a7a\\u3002\", \"\\u53d7\\u7b26\\u9080\\u7fbd\\u4f7f\\uff0c\\u50b3\\u8a23\\u6ce8\\u9999\\u7ae5\\u3002\", \"\\u8a4e\\u4f3c\\u9591\\u5c45\\u65e5\\uff0c\\u5f92\\u805e\\u6709\\u9806\\u98a8\\u3002\"]"', '"[\"\\u78a7\\u865a\\u6e05\\u5439\\u4e0b\\uff0c\\u853c\\u853c\\u5165\\u4ed9\\u5bab\\u3002\", \"\\u677e\\u78f4\\u6500\\u4e91\\u7edd\\uff0c\\u82b1\\u6e90\\u63a5\\u6da7\\u7a7a\\u3002\", \"\\u53d7\\u7b26\\u9080\\u7fbd\\u4f7f\\uff0c\\u4f20\\u8bc0\\u6ce8\\u9999\\u7ae5\\u3002\", \"\\u8bb5\\u4f3c\\u95f2\\u5c45\\u65e5\\uff0c\\u5f92\\u95fb\\u6709\\u987a\\u98ce\\u3002\"]"', '诗', 'shi', '', NULL, '幸白鹿觀應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ab1d190-a632-40f2-ac28-e43e91e72a56', '奉和聖製幸韋嗣立莊應制', '奉和圣制幸韦嗣立庄应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6a39\\u8272\\u53c3\\u5dee\\u96b1\\u7fe0\\u5fae\\uff0c\\u6cc9\\u6d41\\u767e\\u5c3a\\u5411\\u7a7a\\u98db\\u3002\", \"\\u50b3\\u805e\\u6b64\\u8655\\u6295\\u7aff\\u4f4f\\uff0c\\u9042\\u4f7f\\u8332\\u8fb0\\u6248\\u8e55\\u6b78\\u3002\"]"', '"[\"\\u6811\\u8272\\u53c2\\u5dee\\u9690\\u7fe0\\u5fae\\uff0c\\u6cc9\\u6d41\\u767e\\u5c3a\\u5411\\u7a7a\\u98de\\u3002\", \"\\u4f20\\u95fb\\u6b64\\u5904\\u6295\\u7aff\\u4f4f\\uff0c\\u9042\\u4f7f\\u5179\\u8fb0\\u6248\\u8df8\\u5f52\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製幸韋嗣立莊應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bbd1ab1-c266-4886-bc6d-9b4f23c58983', '奉和聖製過晉陽宮應制', '奉和圣制过晋阳宫应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u968b\\u904b\\u8207\\u5929\\u7d55\\uff0c\\u751f\\u9748\\u53ad\\u6c1b\\u660f\\u3002\", \"\\u8056\\u671f\\u5728\\u5be7\\u4e82\\uff0c\\u58eb\\u99ac\\u8208\\u592a\\u539f\\u3002\", \"\\u7acb\\u6975\\u842c\\u90a6\\u63a8\\uff0c\\u767b\\u5eb8\\u56db\\u6d77\\u5c0a\\u3002\", \"\\u6176\\u81ba\\u795e\\u6b66\\u5e1d\\uff0c\\u696d\\u4ed8\\u7687\\u66fe\\u5b6b\\u3002\", \"\\u7dec\\u6155\\u5c01\\u5510\\u9053\\uff0c\\u8ffd\\u60df\\u6b78\\u6c9b\\u9b42\\u3002\", \"\\u8a54\\u66f8\\u611f\\u5148\\u7fa9\\uff0c\\u5178\\u79ae\\u5de1\\u820a\\u85e9\\u3002\", \"\\u9ad8\\u6bbf\\u7db5\\u96f2\\u5408\\uff0c\\u6625\\u65d7\\u7965\\u98a8\\u7ffb\\u3002\", \"\\u7387\\u897f\\u898b\\u6c7e\\u6c34\\uff0c\\u5954\\u5317\\u7a7a\\u585e\\u57a3\\u3002\", \"\\u6b3e\\u66f2\\u7ae5\\u5152\\u4f50\\uff0c\\u4f9d\\u9072\\u6545\\u8001\\u8a00\\u3002\", \"\\u91cc\\u9812\\u6148\\u60e0\\u8cde\\uff0c\\u5bb6\\u53d7\\u5fa9\\u9664\\u6069\\u3002\", \"\\u4e0b\\u8f26\\u5d07\\u4e09\\u6559\\uff0c\\u5efa\\u7891\\u7576\\u4e5d\\u9580\\u3002\", \"\\u5b5d\\u601d\\u6566\\u81f3\\u7f8e\\uff0c\\u5104\\u8f09\\u5949\\u958b\\u5143\\u3002\"]"', '"[\"\\u968b\\u8fd0\\u4e0e\\u5929\\u7edd\\uff0c\\u751f\\u7075\\u538c\\u6c1b\\u660f\\u3002\", \"\\u5723\\u671f\\u5728\\u5b81\\u4e71\\uff0c\\u58eb\\u9a6c\\u5174\\u592a\\u539f\\u3002\", \"\\u7acb\\u6781\\u4e07\\u90a6\\u63a8\\uff0c\\u767b\\u5eb8\\u56db\\u6d77\\u5c0a\\u3002\", \"\\u5e86\\u81ba\\u795e\\u6b66\\u5e1d\\uff0c\\u4e1a\\u4ed8\\u7687\\u66fe\\u5b59\\u3002\", \"\\u7f05\\u6155\\u5c01\\u5510\\u9053\\uff0c\\u8ffd\\u60df\\u5f52\\u6c9b\\u9b42\\u3002\", \"\\u8bcf\\u4e66\\u611f\\u5148\\u4e49\\uff0c\\u5178\\u793c\\u5de1\\u65e7\\u85e9\\u3002\", \"\\u9ad8\\u6bbf\\u5f69\\u4e91\\u5408\\uff0c\\u6625\\u65d7\\u7965\\u98ce\\u7ffb\\u3002\", \"\\u7387\\u897f\\u89c1\\u6c7e\\u6c34\\uff0c\\u5954\\u5317\\u7a7a\\u585e\\u57a3\\u3002\", \"\\u6b3e\\u66f2\\u7ae5\\u513f\\u4f50\\uff0c\\u4f9d\\u8fdf\\u6545\\u8001\\u8a00\\u3002\", \"\\u91cc\\u9881\\u6148\\u60e0\\u8d4f\\uff0c\\u5bb6\\u53d7\\u590d\\u9664\\u6069\\u3002\", \"\\u4e0b\\u8f87\\u5d07\\u4e09\\u6559\\uff0c\\u5efa\\u7891\\u5f53\\u4e5d\\u95e8\\u3002\", \"\\u5b5d\\u601d\\u6566\\u81f3\\u7f8e\\uff0c\\u4ebf\\u8f7d\\u5949\\u5f00\\u5143\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製過晉陽宮應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb09e2ea-d8bf-4290-b034-f3249a088d56', '奉和姚令公溫湯舊館永懷故人盧公之作', '奉和姚令公温汤旧馆永怀故人卢公之作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6a39\\u5fb7\\u8c48\\u5b64\\u9081\\uff0c\\u964d\\u795e\\u826f\\u7add\\u51fa\\u3002\", \"\\u5049\\u8332\\u5eca\\u5edf\\u6968\\uff0c\\u8abf\\u5f7c\\u9e7d\\u6885\\u5be6\\u3002\", \"\\u6b63\\u6085\\u865e\\u5782\\u8209\\uff0c\\u7ffb\\u60b2\\u912d\\u50d1\\u5352\\u3002\", \"\\u540c\\u5fc3\\u4e0d\\u53ef\\u5fd8\\uff0c\\u4ea4\\u81c2\\u4f55\\u7232\\u5931\\u3002\", \"\\u6e05\\u8def\\u8377\\u524d\\u5e78\\uff0c\\u660e\\u6642\\u7a31\\u53f3\\u5f3c\\u3002\", \"\\u66fe\\u806f\\u91ce\\u5916\\u904a\\uff0c\\u5c1a\\u8a18\\u5e37\\u4e2d\\u5bc6\\u3002\", \"\\u65b0\\u615f\\u60c5\\u83ab\\u9063\\uff0c\\u820a\\u904a\\u8a5e\\u66f4\\u8ff0\\u3002\", \"\\u7a7a\\u4ee4\\u9084\\u8fb1\\u548c\\uff0c\\u9577\\u6b4e\\u77e5\\u97f3\\u65e5\\u3002\"]"', '"[\"\\u6811\\u5fb7\\u5c82\\u5b64\\u8fc8\\uff0c\\u964d\\u795e\\u826f\\u7add\\u51fa\\u3002\", \"\\u4f1f\\u5179\\u5eca\\u5e99\\u6862\\uff0c\\u8c03\\u5f7c\\u76d0\\u6885\\u5b9e\\u3002\", \"\\u6b63\\u60a6\\u865e\\u5782\\u4e3e\\uff0c\\u7ffb\\u60b2\\u90d1\\u4fa8\\u5352\\u3002\", \"\\u540c\\u5fc3\\u4e0d\\u53ef\\u5fd8\\uff0c\\u4ea4\\u81c2\\u4f55\\u4e3a\\u5931\\u3002\", \"\\u6e05\\u8def\\u8377\\u524d\\u5e78\\uff0c\\u660e\\u65f6\\u79f0\\u53f3\\u5f3c\\u3002\", \"\\u66fe\\u8054\\u91ce\\u5916\\u6e38\\uff0c\\u5c1a\\u8bb0\\u5e37\\u4e2d\\u5bc6\\u3002\", \"\\u65b0\\u6078\\u60c5\\u83ab\\u9063\\uff0c\\u65e7\\u6e38\\u8bcd\\u66f4\\u8ff0\\u3002\", \"\\u7a7a\\u4ee4\\u8fd8\\u8fb1\\u548c\\uff0c\\u957f\\u53f9\\u77e5\\u97f3\\u65e5\\u3002\"]"', '诗', 'shi', '', NULL, '奉和姚令公溫湯舊館永懷故人盧公之作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('106f24fc-5222-4d03-984e-99a4f012f5a6', '和杜主簿春日有所思', '和杜主簿春日有所思', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u671d\\u4e0a\\u9ad8\\u6a13\\u4e0a\\uff0c\\u4fef\\u898b\\u6d1b\\u967d\\u964c\\u3002\", \"\\u6416\\u8569\\u5439\\u82b1\\u98a8\\uff0c\\u843d\\u82f1\\u7d1b\\u5df2\\u7a4d\\u3002\", \"\\u7f8e\\u4eba\\u4e0d\\u5171\\u6b64\\uff0c\\u82b3\\u597d\\u7a7a\\u6240\\u60dc\\u3002\", \"\\u652c\\u93e1\\u5875\\u7db2\\u6ecb\\uff0c\\u7576\\u7a97\\u82d4\\u861a\\u78a7\\u3002\", \"\\u7dec\\u61f7\\u5728\\u96f2\\u6f22\\uff0c\\u826f\\u9858\\u668c\\u6795\\u5e2d\\u3002\", \"\\u7ffb\\u4f3c\\u7121\\u898b\\u6642\\uff0c\\u5982\\u4f55\\u4e45\\u7232\\u5ba2\\u3002\"]"', '"[\"\\u671d\\u4e0a\\u9ad8\\u697c\\u4e0a\\uff0c\\u4fef\\u89c1\\u6d1b\\u9633\\u964c\\u3002\", \"\\u6447\\u8361\\u5439\\u82b1\\u98ce\\uff0c\\u843d\\u82f1\\u7eb7\\u5df2\\u79ef\\u3002\", \"\\u7f8e\\u4eba\\u4e0d\\u5171\\u6b64\\uff0c\\u82b3\\u597d\\u7a7a\\u6240\\u60dc\\u3002\", \"\\u63fd\\u955c\\u5c18\\u7f51\\u6ecb\\uff0c\\u5f53\\u7a97\\u82d4\\u85d3\\u78a7\\u3002\", \"\\u7f05\\u6000\\u5728\\u4e91\\u6c49\\uff0c\\u826f\\u613f\\u668c\\u6795\\u5e2d\\u3002\", \"\\u7ffb\\u4f3c\\u65e0\\u89c1\\u65f6\\uff0c\\u5982\\u4f55\\u4e45\\u4e3a\\u5ba2\\u3002\"]"', '诗', 'shi', '', NULL, '和杜主簿春日有所思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92802726-3cdb-4107-a673-286b4e74c829', '餞郢州李使君', '饯郢州李使君', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u695a\\u6709\\u7ae0\\u83ef\\u81fa\\uff0c\\u9059\\u9059\\u96f2\\u5922\\u6fa4\\u3002\", \"\\u5fa9\\u805e\\u64c1\\u7b26\\u50b3\\uff0c\\u53ca\\u662f\\u6536\\u5716\\u7c4d\\u3002\", \"\\u4f73\\u653f\\u5728\\u96e2\\u4eba\\uff0c\\u80fd\\u8072\\u5bc4\\u4faf\\u4f2f\\u3002\", \"\\u96e2\\u61f7\\u6714\\u98a8\\u8d77\\uff0c\\u8a66\\u671b\\u79cb\\u9670\\u7a4d\\u3002\", \"\\u4e2d\\u8def\\u60bd\\u4ee5\\u5bd2\\uff0c\\u7fa3\\u5c71\\u9744\\u5c07\\u5915\\u3002\", \"\\u50b7\\u5fc3\\u804a\\u628a\\u8882\\uff0c\\u600a\\u60b5\\u9e92\\u9e9f\\u5ba2\\u3002\"]"', '"[\"\\u695a\\u6709\\u7ae0\\u534e\\u53f0\\uff0c\\u9065\\u9065\\u4e91\\u68a6\\u6cfd\\u3002\", \"\\u590d\\u95fb\\u62e5\\u7b26\\u4f20\\uff0c\\u53ca\\u662f\\u6536\\u56fe\\u7c4d\\u3002\", \"\\u4f73\\u653f\\u5728\\u79bb\\u4eba\\uff0c\\u80fd\\u58f0\\u5bc4\\u4faf\\u4f2f\\u3002\", \"\\u79bb\\u6000\\u6714\\u98ce\\u8d77\\uff0c\\u8bd5\\u671b\\u79cb\\u9634\\u79ef\\u3002\", \"\\u4e2d\\u8def\\u51c4\\u4ee5\\u5bd2\\uff0c\\u7fa4\\u5c71\\u972d\\u5c06\\u5915\\u3002\", \"\\u4f24\\u5fc3\\u804a\\u628a\\u8882\\uff0c\\u600a\\u6005\\u9e92\\u9e9f\\u5ba2\\u3002\"]"', '诗', 'shi', '', NULL, '餞郢州李使君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce615b30-ecf1-4e72-ba3f-3623f2382fbf', '餞唐州高使君赴任', '饯唐州高使君赴任', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6c38\\u65e5\\u594f\\u6587\\u6642\\uff0c\\u6771\\u98a8\\u6416\\u8569\\u5915\\u3002\", \"\\u6d69\\u7136\\u601d\\u6a02\\u4e8b\\uff0c\\u7ffb\\u5fa9\\u991e\\u5f81\\u5ba2\\u3002\", \"\\u6dee\\u6c34\\u6625\\u6d41\\u6e05\\uff0c\\u695a\\u5c71\\u66ae\\u96f2\\u767d\\u3002\", \"\\u52ff\\u8a00\\u884c\\u8def\\u9060\\uff0c\\u6240\\u8cb4\\u5c08\\u57ce\\u4f2f\\u3002\"]"', '"[\"\\u6c38\\u65e5\\u594f\\u6587\\u65f6\\uff0c\\u4e1c\\u98ce\\u6447\\u8361\\u5915\\u3002\", \"\\u6d69\\u7136\\u601d\\u4e50\\u4e8b\\uff0c\\u7ffb\\u590d\\u996f\\u5f81\\u5ba2\\u3002\", \"\\u6dee\\u6c34\\u6625\\u6d41\\u6e05\\uff0c\\u695a\\u5c71\\u66ae\\u4e91\\u767d\\u3002\", \"\\u52ff\\u8a00\\u884c\\u8def\\u8fdc\\uff0c\\u6240\\u8d35\\u4e13\\u57ce\\u4f2f\\u3002\"]"', '诗', 'shi', '', NULL, '餞唐州高使君赴任 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a64d6c7-0139-4f69-9271-c6030e584e25', '曉濟膠川南入密界', '晓济胶川南入密界', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u98f2\\u99ac\\u81a0\\u5ddd\\u4e0a\\uff0c\\u508d\\u81a0\\u5357\\u8da3\\u5bc6\\u3002\", \"\\u6797\\u9059\\u98db\\u9ce5\\u9072\\uff0c\\u96f2\\u53bb\\u6674\\u5c71\\u51fa\\u3002\", \"\\u843d\\u6689\\u96b1\\u6851\\u67d8\\uff0c\\u79cb\\u539f\\u88ab\\u82b1\\u5be6\\u3002\", \"\\u6158\\u7136\\u904a\\u5b50\\u5bd2\\uff0c\\u98a8\\u9732\\u5c07\\u856d\\u745f\\u3002\"]"', '"[\"\\u996e\\u9a6c\\u80f6\\u5ddd\\u4e0a\\uff0c\\u508d\\u80f6\\u5357\\u8da3\\u5bc6\\u3002\", \"\\u6797\\u9065\\u98de\\u9e1f\\u8fdf\\uff0c\\u4e91\\u53bb\\u6674\\u5c71\\u51fa\\u3002\", \"\\u843d\\u6656\\u9690\\u6851\\u67d8\\uff0c\\u79cb\\u539f\\u88ab\\u82b1\\u5b9e\\u3002\", \"\\u60e8\\u7136\\u6e38\\u5b50\\u5bd2\\uff0c\\u98ce\\u9732\\u5c06\\u8427\\u745f\\u3002\"]"', '诗', 'shi', '', NULL, '曉濟膠川南入密界 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47ed0d19-9151-4877-824a-e71f85229c83', '夜發三泉即事', '夜发三泉即事', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6697\\u767c\\u4e09\\u6cc9\\u5c71\\uff0c\\u7aae\\u79cb\\u807d\\u9a37\\u5c51\\u3002\", \"\\u5317\\u6797\\u591c\\u9cf4\\u96e8\\uff0c\\u5357\\u671b\\u66c9\\u6210\\u96ea\\u3002\", \"\\u7957\\u8a60\\u5317\\u98a8\\u6dbc\\uff0c\\u8a4e\\u77e5\\u5357\\u571f\\u71b1\\u3002\", \"\\u6c99\\u6eaa\\u5ffd\\u6cb8\\u6e2d\\uff0c\\u77f3\\u9053\\u4e4d\\u660e\\u6ec5\\u3002\", \"\\u5b9b\\u82e5\\u9280\\u78e7\\u6a6b\\uff0c\\u5fa9\\u5982\\u7464\\u81fa\\u7d50\\u3002\", \"\\u6307\\u7a0b\\u8ce6\\u6240\\u6200\\uff0c\\u9047\\u865e\\u4e0d\\u9051\\u6b47\\u3002\", \"\\u91cd\\u7e8a\\u6fe1\\u83ab\\u89e3\\uff0c\\u61f8\\u65cc\\u51cd\\u7336\\u63ed\\u3002\", \"\\u4e0b\\u5954\\u6ce5\\u68e7\\u69b0\\uff0c\\u4e0a\\u89af\\u96f2\\u68af\\u8a2d\\u3002\", \"[\\u640f]\\u9830\\u7fb8\\u99ac\\u9813\\uff0c\\u56de\\u7738\\u60f4\\u4eba\\u8dcc\\u3002\", \"\\u61a7\\u61a7\\u5f80\\u5fa9\\u9084\\uff0c\\u5fc3\\u6ce8\\u601d\\u903e\\u5207\\u3002\", \"\\u5189\\u5189\\u5e74\\u5c07\\u75c5\\uff0c\\u529b\\u56f0\\u8870\\u6020\\u7aed\\u3002\", \"\\u5929\\u5f6d\\u4fe1\\u65b9\\u9685\\uff0c\\u5730\\u52e2\\u8aa0\\u6597\\u7d55\\u3002\", \"\\u5fdd\\u66f3\\u5c1a\\u66f8\\u5c65\\uff0c\\u53e8\\u517c\\u4f7f\\u81e3\\u7bc0\\u3002\", \"\\u4eac\\u577b\\u6709\\u6b72\\u9952\\uff0c\\u4ead\\u969c\\u7121\\u908a\\u5b7d\\u3002\", \"\\u6b78\\u594f\\u4e39\\u5880\\u5de6\\uff0c\\u9a2b\\u80fd\\u4fdf\\u4f86\\u54f2\\u3002\"]"', '"[\"\\u6697\\u53d1\\u4e09\\u6cc9\\u5c71\\uff0c\\u7a77\\u79cb\\u542c\\u9a9a\\u5c51\\u3002\", \"\\u5317\\u6797\\u591c\\u9e23\\u96e8\\uff0c\\u5357\\u671b\\u6653\\u6210\\u96ea\\u3002\", \"\\u7957\\u548f\\u5317\\u98ce\\u51c9\\uff0c\\u8bb5\\u77e5\\u5357\\u571f\\u70ed\\u3002\", \"\\u6c99\\u6eaa\\u5ffd\\u6cb8\\u6e2d\\uff0c\\u77f3\\u9053\\u4e4d\\u660e\\u706d\\u3002\", \"\\u5b9b\\u82e5\\u94f6\\u789b\\u6a2a\\uff0c\\u590d\\u5982\\u7476\\u53f0\\u7ed3\\u3002\", \"\\u6307\\u7a0b\\u8d4b\\u6240\\u604b\\uff0c\\u9047\\u865e\\u4e0d\\u9051\\u6b47\\u3002\", \"\\u91cd\\u7ea9\\u6fe1\\u83ab\\u89e3\\uff0c\\u60ac\\u65cc\\u51bb\\u72b9\\u63ed\\u3002\", \"\\u4e0b\\u5954\\u6ce5\\u6808\\u69b0\\uff0c\\u4e0a\\u89cf\\u4e91\\u68af\\u8bbe\\u3002\", \"[\\u640f]\\u988a\\u7fb8\\u9a6c\\u987f\\uff0c\\u56de\\u7738\\u60f4\\u4eba\\u8dcc\\u3002\", \"\\u61a7\\u61a7\\u5f80\\u590d\\u8fd8\\uff0c\\u5fc3\\u6ce8\\u601d\\u903e\\u5207\\u3002\", \"\\u5189\\u5189\\u5e74\\u5c06\\u75c5\\uff0c\\u529b\\u56f0\\u8870\\u6020\\u7aed\\u3002\", \"\\u5929\\u5f6d\\u4fe1\\u65b9\\u9685\\uff0c\\u5730\\u52bf\\u8bda\\u6597\\u7edd\\u3002\", \"\\u5fdd\\u66f3\\u5c1a\\u4e66\\u5c65\\uff0c\\u53e8\\u517c\\u4f7f\\u81e3\\u8282\\u3002\", \"\\u4eac\\u577b\\u6709\\u5c81\\u9976\\uff0c\\u4ead\\u969c\\u65e0\\u8fb9\\u5b7d\\u3002\", \"\\u5f52\\u594f\\u4e39\\u5880\\u5de6\\uff0c\\u9a9e\\u80fd\\u4fdf\\u6765\\u54f2\\u3002\"]"', '诗', 'shi', '', NULL, '夜發三泉即事 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caf2f7b9-372f-43f1-bbd1-3faabd0069b5', '小園納涼即事', '小园纳凉即事', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u7169\\u6691\\u907f\\u84b8\\u9b31\\uff0c\\u5c45\\u9591\\u7fd2\\u9ad8\\u660e\\u3002\", \"\\u9577\\u98a8\\u81ea\\u9060\\u4f86\\uff0c\\u5c64\\u95a3\\u6709\\u9918\\u6e05\\u3002\", \"\\u6563\\u7051\\u7d0d\\u6dbc\\u6c23\\uff0c\\u856d\\u689d\\u907a\\u4e16\\u60c5\\u3002\", \"\\u5948\\u4f55\\u8a87\\u5927\\u96b1\\uff0c\\u7d42\\u65e5\\u7e6b\\u5875\\u7e93\\u3002\"]"', '"[\"\\u70e6\\u6691\\u907f\\u84b8\\u90c1\\uff0c\\u5c45\\u95f2\\u4e60\\u9ad8\\u660e\\u3002\", \"\\u957f\\u98ce\\u81ea\\u8fdc\\u6765\\uff0c\\u5c42\\u9601\\u6709\\u4f59\\u6e05\\u3002\", \"\\u6563\\u6d12\\u7eb3\\u51c9\\u6c14\\uff0c\\u8427\\u6761\\u9057\\u4e16\\u60c5\\u3002\", \"\\u5948\\u4f55\\u5938\\u5927\\u9690\\uff0c\\u7ec8\\u65e5\\u7cfb\\u5c18\\u7f28\\u3002\"]"', '诗', 'shi', '', NULL, '小園納涼即事 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a01e17f1-6dbc-4b4e-b859-ed698cdaf86c', '昆明池晏坐答王兵部珣三韻見示', '昆明池晏坐答王兵部珣三韵见示', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u756b\\u8238\\u75be\\u5982\\u98db\\uff0c\\u9059\\u9059\\u6c4e\\u5915\\u6689\\u3002\", \"\\u77f3\\u9ee5\\u5439\\u6d6a\\u96b1\\uff0c\\u7389\\u5973\\u6b65\\u5875\\u6b78\\u3002\", \"\\u7368\\u6709\\u929c\\u6069\\u8655\\uff0c\\u660e\\u73e0\\u5728\\u91e3\\u78ef\\u3002\"]"', '"[\"\\u753b\\u8238\\u75be\\u5982\\u98de\\uff0c\\u9065\\u9065\\u6cdb\\u5915\\u6656\\u3002\", \"\\u77f3\\u9ee5\\u5439\\u6d6a\\u9690\\uff0c\\u7389\\u5973\\u6b65\\u5c18\\u5f52\\u3002\", \"\\u72ec\\u6709\\u8854\\u6069\\u5904\\uff0c\\u660e\\u73e0\\u5728\\u9493\\u77f6\\u3002\"]"', '诗', 'shi', '', NULL, '昆明池晏坐答王兵部珣三韻見示 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e50379-1882-4fd1-9e61-9b63d0528b67', '題壽安王主簿池館', '题寿安王主簿池馆', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6d1b\\u9091\\u901a\\u99b3\\u9053\\uff0c\\u97d3\\u90ca\\u5728\\u5c6c\\u57ce\\u3002\", \"\\u9928\\u5c07\\u82b1\\u96e8\\u6620\\uff0c\\u6f6d\\u8207\\u7af9\\u8072\\u6e05\\u3002\", \"\\u8ce2\\u4fca\\u9e1e\\u68f2\\u68d8\\uff0c\\u8cd3\\u904a\\u99ac\\u4f69\\u8861\\u3002\", \"\\u9858\\u8a00\\u96a8\\u72ce\\u9ce5\\uff0c\\u5f9e\\u6b64\\u6fef\\u543e\\u7e93\\u3002\"]"', '"[\"\\u6d1b\\u9091\\u901a\\u9a70\\u9053\\uff0c\\u97e9\\u90ca\\u5728\\u5c5e\\u57ce\\u3002\", \"\\u9986\\u5c06\\u82b1\\u96e8\\u6620\\uff0c\\u6f6d\\u4e0e\\u7af9\\u58f0\\u6e05\\u3002\", \"\\u8d24\\u4fca\\u9e3e\\u6816\\u68d8\\uff0c\\u5bbe\\u6e38\\u9a6c\\u4f69\\u8861\\u3002\", \"\\u613f\\u8a00\\u968f\\u72ce\\u9e1f\\uff0c\\u4ece\\u6b64\\u6fef\\u543e\\u7f28\\u3002\"]"', '诗', 'shi', '', NULL, '題壽安王主簿池館 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d69ab328-4934-4278-a54a-4a8169a6aef5', '扈從溫泉奉和姚令公喜雪', '扈从温泉奉和姚令公喜雪', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6e05\\u9053\\u8c50\\u4eba\\u671b\\uff0c\\u4e58\\u6642\\u6f22\\u4e3b\\u904a\\u3002\", \"\\u6069\\u6689\\u96a8\\u9730\\u4e0b\\uff0c\\u6176\\u6fa4\\u8207\\u96f2\\u6d6e\\u3002\", \"\\u6cc9\\u6696\\u9a5a\\u9280\\u78e7\\uff0c\\u82b1\\u5bd2\\u611b\\u7389\\u6a13\\u3002\", \"\\u9f0e\\u81e3\\u4eca\\u6709\\u554f\\uff0c\\u6cb3\\u4f2f\\u4e14\\u61c9\\u7559\\u3002\"]"', '"[\"\\u6e05\\u9053\\u4e30\\u4eba\\u671b\\uff0c\\u4e58\\u65f6\\u6c49\\u4e3b\\u6e38\\u3002\", \"\\u6069\\u6656\\u968f\\u9730\\u4e0b\\uff0c\\u5e86\\u6cfd\\u4e0e\\u4e91\\u6d6e\\u3002\", \"\\u6cc9\\u6696\\u60ca\\u94f6\\u789b\\uff0c\\u82b1\\u5bd2\\u7231\\u7389\\u697c\\u3002\", \"\\u9f0e\\u81e3\\u4eca\\u6709\\u95ee\\uff0c\\u6cb3\\u4f2f\\u4e14\\u5e94\\u7559\\u3002\"]"', '诗', 'shi', '', NULL, '扈從溫泉奉和姚令公喜雪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ed9973-1f11-4384-a1d3-41a5006446d6', '奉和聖製春臺望應制', '奉和圣制春台望应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u58ef\\u9e97\\u5929\\u4e4b\\u5e9c\\uff0c\\u795e\\u660e\\u738b\\u8005\\u5b85\\u3002\", \"\\u5927\\u541b\\u4e58\\u98db\\u9f8d\\uff0c\\u767b\\u5f7c\\u5fa9\\u61f7\\u6614\\u3002\", \"\\u5713\\u95d5\\u6731\\u5149\\u71c4\\uff0c\\u6a6b\\u5c71\\u7fe0\\u5fae\\u7a4d\\u3002\", \"\\u6cb3\\u6c67\\u6d41\\u4f5c\\u8868\\uff0c\\u7e23\\u805a\\u958b\\u6210\\u964c\\u3002\", \"\\u5373\\u820a\\u5728\\u7687\\u5bb6\\uff0c\\u7dad\\u65b0\\u5177\\u7269\\u83ef\\u3002\", \"\\u96f2\\u9023\\u6240\\u4e0a\\u5c45\\u6046\\u5c6c\\uff0c\\u65e5\\u66f4\\u6642\\u4e2d\\u671b\\u4e0d\\u659c\\u3002\", \"\\u4e09\\u6708\\u6ec4\\u6c60\\u6416\\u7a4d\\u6c34\\uff0c\\u842c\\u5e74\\u9752\\u6a39\\u7db4\\u65b0\\u82b1\\u3002\", \"\\u66b4\\u5b34\\u570b\\u6b64\\u5617\\u5716\\u9738\\uff0c\\u9738\\u696d\\u5f8c\\u4ec1\\u5148\\u4ee5\\u8a50\\u3002\", \"\\u6771\\u7834\\u8af8\\u4faf\\u897f\\u5165\\u79e6\\uff0c\\u54b8\\u967d\\u5317\\u962a\\u5357\\u6e2d\\u6d25\\u3002\", \"\\u8a69\\u66f8\\u711a\\u7207\\u6563\\u5b78\\u58eb\\uff0c\\u9ad8\\u95a3\\u5962\\u8e30\\u5b0c\\u7f8e\\u4eba\\u3002\", \"\\u4e8b\\u5f80\\u8986\\u8f08\\u7d93\\u9060\\u55bb\\uff0c\\u6625\\u9084\\u6309\\u8e55\\u6191\\u9ad8\\u8ce6\\u3002\", \"\\u620e\\u89c0\\u611b\\u529b\\u6df1\\u60df\\u7701\\uff0c\\u8d8a\\u53ad\\u9673\\u65b9\\u4f55\\u8db3\\u52d9\\u3002\", \"\\u6e05\\u5439\\u9059\\u9059\\u767c\\u5e1d\\u81fa\\uff0c\\u5bb8\\u6587\\u803f\\u803f\\u7167\\u5929\\u8ff4\\u3002\", \"\\u4f2f\\u5937\\u4f4d\\u4e8b\\u611a\\u81e3\\u5fdd\\uff0c\\u559c\\u594f\\u8072\\u6210\\u9cf3\\u9ce5\\u4f86\\u3002\"]"', '"[\"\\u58ee\\u4e3d\\u5929\\u4e4b\\u5e9c\\uff0c\\u795e\\u660e\\u738b\\u8005\\u5b85\\u3002\", \"\\u5927\\u541b\\u4e58\\u98de\\u9f99\\uff0c\\u767b\\u5f7c\\u590d\\u6000\\u6614\\u3002\", \"\\u5706\\u9619\\u6731\\u5149\\u71c4\\uff0c\\u6a2a\\u5c71\\u7fe0\\u5fae\\u79ef\\u3002\", \"\\u6cb3\\u6c67\\u6d41\\u4f5c\\u8868\\uff0c\\u53bf\\u805a\\u5f00\\u6210\\u964c\\u3002\", \"\\u5373\\u65e7\\u5728\\u7687\\u5bb6\\uff0c\\u7ef4\\u65b0\\u5177\\u7269\\u534e\\u3002\", \"\\u4e91\\u8fde\\u6240\\u4e0a\\u5c45\\u6052\\u5c5e\\uff0c\\u65e5\\u66f4\\u65f6\\u4e2d\\u671b\\u4e0d\\u659c\\u3002\", \"\\u4e09\\u6708\\u6ca7\\u6c60\\u6447\\u79ef\\u6c34\\uff0c\\u4e07\\u5e74\\u9752\\u6811\\u7f00\\u65b0\\u82b1\\u3002\", \"\\u66b4\\u5b34\\u56fd\\u6b64\\u5c1d\\u56fe\\u9738\\uff0c\\u9738\\u4e1a\\u540e\\u4ec1\\u5148\\u4ee5\\u8bc8\\u3002\", \"\\u4e1c\\u7834\\u8bf8\\u4faf\\u897f\\u5165\\u79e6\\uff0c\\u54b8\\u9633\\u5317\\u962a\\u5357\\u6e2d\\u6d25\\u3002\", \"\\u8bd7\\u4e66\\u711a\\ud85b\\udd9f\\u6563\\u5b66\\u58eb\\uff0c\\u9ad8\\u9601\\u5962\\u903e\\u5a07\\u7f8e\\u4eba\\u3002\", \"\\u4e8b\\u5f80\\u8986\\u8f80\\u7ecf\\u8fdc\\u55bb\\uff0c\\u6625\\u8fd8\\u6309\\u8df8\\u51ed\\u9ad8\\u8d4b\\u3002\", \"\\u620e\\u89c2\\u7231\\u529b\\u6df1\\u60df\\u7701\\uff0c\\u8d8a\\u538c\\u9648\\u65b9\\u4f55\\u8db3\\u52a1\\u3002\", \"\\u6e05\\u5439\\u9065\\u9065\\u53d1\\u5e1d\\u53f0\\uff0c\\u5bb8\\u6587\\u803f\\u803f\\u7167\\u5929\\u56de\\u3002\", \"\\u4f2f\\u5937\\u4f4d\\u4e8b\\u611a\\u81e3\\u5fdd\\uff0c\\u559c\\u594f\\u58f0\\u6210\\u51e4\\u9e1f\\u6765\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製春臺望應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d89959e-48bf-48d4-a3c9-a945fb524c33', '長相思', '长相思', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u541b\\u4e0d\\u898b\\u5929\\u6d25\\u6a4b\\u4e0b\\u6771\\u6d41\\u6c34\\uff0c\\u5357\\u671b\\u9f8d\\u9580\\u5317\\u671d\\u5e02\\u3002\", \"\\u694a\\u67f3\\u9752\\u9752\\u5b9b\\u5730\\u5782\\uff0c\\u6843\\u7d05\\u674e\\u767d\\u82b1\\u53c3\\u5dee\\u3002\", \"\\u82b1\\u53c3\\u5dee\\uff0c\\u67f3\\u582a\\u7d50\\uff0c\\u6b64\\u6642\\u61b6\\u541b\\u5fc3\\u65b7\\u7d55\\u3002\"]"', '"[\"\\u541b\\u4e0d\\u89c1\\u5929\\u6d25\\u6865\\u4e0b\\u4e1c\\u6d41\\u6c34\\uff0c\\u5357\\u671b\\u9f99\\u95e8\\u5317\\u671d\\u5e02\\u3002\", \"\\u6768\\u67f3\\u9752\\u9752\\u5b9b\\u5730\\u5782\\uff0c\\u6843\\u7ea2\\u674e\\u767d\\u82b1\\u53c2\\u5dee\\u3002\", \"\\u82b1\\u53c2\\u5dee\\uff0c\\u67f3\\u582a\\u7ed3\\uff0c\\u6b64\\u65f6\\u5fc6\\u541b\\u5fc3\\u65ad\\u7edd\\u3002\"]"', '诗', 'shi', '', NULL, '長相思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f15dddef-ce75-47cd-a516-a3058101d894', '蜀城哭台州樂安少府', '蜀城哭台州乐安少府', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u9060\\u904a\\u8e8b\\u5292\\u95a3\\uff0c\\u9577\\u60f3\\u5c6c\\u5929\\u53f0\\u3002\", \"\\u842c\\u91cc\\u9694\\u4e09\\u8f09\\uff0c\\u6b64\\u90a6\\u4f59\\u91cd\\u4f86\\u3002\", \"\\u97f3\\u5bb9\\u66e0\\u4e0d\\u89a9\\uff0c\\u5922\\u5bd0\\u6b8a\\u60a0\\u54c9\\u3002\", \"\\u908a\\u90e1\\u9952\\u85c9\\u85c9\\uff0c\\u665a\\u5ead\\u6b63\\u56de\\u56de\\u3002\", \"\\u559c\\u50b3\\u4e0a\\u90fd\\u5c01\\uff0c\\u56e0\\u4fc3\\u508d\\u540f\\u958b\\u3002\", \"\\u5411\\u609f\\u6d77\\u9e7d\\u5ba2\\uff0c\\u5df2\\u800c\\u6881\\u6728\\u6467\\u3002\", \"\\u8b8a\\u8863\\u5be2\\u9580\\u5916\\uff0c\\u63ee\\u6d95\\u5c11\\u57ce\\u9688\\u3002\", \"\\u5374\\u8a18\\u5206\\u660e\\u5f97\\uff0c\\u7336\\u6301\\u59d4\\u66f2\\u731c\\u3002\", \"\\u5e2b\\u5112\\u6614\\u8a13\\u734e\\uff0c\\u4ef2\\u5b63\\u6642\\u7ae5\\u5b69\\u3002\", \"\\u670d\\u7fa9\\u984c\\u66f8\\u7bcb\\uff0c\\u9080\\u6b61\\u6c4e\\u9152\\u676f\\u3002\", \"\\u8e54\\u4ee4\\u98a8\\u96e8\\u6563\\uff0c\\u4ecd\\u8feb\\u6b72\\u6642\\u8ff4\\u3002\", \"\\u5176\\u9053\\u60df\\u6b63\\u76f4\\uff0c\\u5176\\u4eba\\u4fe1\\u7f8e\\u5072\\u3002\", \"\\u767d\\u982d\\u9084\\u4f5c\\u5c09\\uff0c\\u9ec3\\u7dac\\u56fa\\u975e\\u624d\\u3002\", \"\\u53ef\\u6b4e\\u61f8\\u86c7\\u75be\\uff0c\\u5148\\u8cbd\\u554f\\u9d69\\u707d\\u3002\", \"\\u6545\\u9109\\u9589\\u7aae\\u58e4\\uff0c\\u5bbf\\u8349\\u751f\\u5bd2\\u8344\\u3002\", \"\\u96f6\\u843d\\u4e5d\\u539f\\u53bb\\uff0c\\u8e49\\u8dce\\u56db\\u5e8f\\u50ac\\u3002\", \"\\u66e9\\u671f\\u51ac\\u8d08\\u6a58\\uff0c\\u4eca\\u54ed\\u590f\\u6210\\u6885\\u3002\", \"\\u57f7\\u79ae\\u8ab0\\u7232\\u8cf5\\uff0c\\u5c45\\u5e38\\u4e0d\\u5f87\\u8ca1\\u3002\", \"\\u5317\\u767b\\u5d54\\ud847\\udef1\\u5742\\uff0c\\u6771\\u671b\\u59d1\\u8607\\u81fa\\u3002\", \"\\u5929\\u8def\\u672c\\u61f8\\u7d55\\uff0c\\u6c5f\\u6ce2\\u5fa9\\u6cdd\\u6d04\\u3002\", \"\\u5ff5\\u5b64\\u5fc3\\u6613\\u65b7\\uff0c\\u8ffd\\u5f80\\u6068\\u8271\\u88c1\\u3002\", \"\\u4e0d\\u9042\\u537f\\u5c07\\u4f2f\\uff0c\\u5b70\\u4e91\\u9673\\u8207\\u96f7\\u3002\", \"\\u543e\\u8870\\u4ea6\\u5982\\u6b64\\uff0c\\u592b\\u5b50\\u5fa9\\u4f55\\u54c0\\u3002\"]"', '"[\"\\u8fdc\\u6e38\\u8dfb\\u5292\\u9601\\uff0c\\u957f\\u60f3\\u5c5e\\u5929\\u53f0\\u3002\", \"\\u4e07\\u91cc\\u9694\\u4e09\\u8f7d\\uff0c\\u6b64\\u90a6\\u4f59\\u91cd\\u6765\\u3002\", \"\\u97f3\\u5bb9\\u65f7\\u4e0d\\u89a9\\uff0c\\u68a6\\u5bd0\\u6b8a\\u60a0\\u54c9\\u3002\", \"\\u8fb9\\u90e1\\u9976\\u85c9\\u85c9\\uff0c\\u665a\\u5ead\\u6b63\\u56de\\u56de\\u3002\", \"\\u559c\\u4f20\\u4e0a\\u90fd\\u5c01\\uff0c\\u56e0\\u4fc3\\u508d\\u540f\\u5f00\\u3002\", \"\\u5411\\u609f\\u6d77\\u76d0\\u5ba2\\uff0c\\u5df2\\u800c\\u6881\\u6728\\u6467\\u3002\", \"\\u53d8\\u8863\\u5bdd\\u95e8\\u5916\\uff0c\\u6325\\u6d95\\u5c11\\u57ce\\u9688\\u3002\", \"\\u5374\\u8bb0\\u5206\\u660e\\u5f97\\uff0c\\u72b9\\u6301\\u59d4\\u66f2\\u731c\\u3002\", \"\\u5e08\\u5112\\u6614\\u8bad\\u5956\\uff0c\\u4ef2\\u5b63\\u65f6\\u7ae5\\u5b69\\u3002\", \"\\u670d\\u4e49\\u9898\\u4e66\\u7ba7\\uff0c\\u9080\\u6b22\\u6cdb\\u9152\\u676f\\u3002\", \"\\ud86c\\udfd0\\u4ee4\\u98ce\\u96e8\\u6563\\uff0c\\u4ecd\\u8feb\\u5c81\\u65f6\\u56de\\u3002\", \"\\u5176\\u9053\\u60df\\u6b63\\u76f4\\uff0c\\u5176\\u4eba\\u4fe1\\u7f8e\\u5072\\u3002\", \"\\u767d\\u5934\\u8fd8\\u4f5c\\u5c09\\uff0c\\u9ec4\\u7ef6\\u56fa\\u975e\\u624d\\u3002\", \"\\u53ef\\u53f9\\u60ac\\u86c7\\u75be\\uff0c\\u5148\\u8d3b\\u95ee\\ud86d\\udef3\\u707e\\u3002\", \"\\u6545\\u4e61\\u95ed\\u7a77\\u58e4\\uff0c\\u5bbf\\u8349\\u751f\\u5bd2\\u8344\\u3002\", \"\\u96f6\\u843d\\u4e5d\\u539f\\u53bb\\uff0c\\u8e49\\u8dce\\u56db\\u5e8f\\u50ac\\u3002\", \"\\u66e9\\u671f\\u51ac\\u8d60\\u6a58\\uff0c\\u4eca\\u54ed\\u590f\\u6210\\u6885\\u3002\", \"\\u6267\\u793c\\u8c01\\u4e3a\\u8d57\\uff0c\\u5c45\\u5e38\\u4e0d\\u5f87\\u8d22\\u3002\", \"\\u5317\\u767b\\u5d54\\ud847\\udef1\\u5742\\uff0c\\u4e1c\\u671b\\u59d1\\u82cf\\u53f0\\u3002\", \"\\u5929\\u8def\\u672c\\u60ac\\u7edd\\uff0c\\u6c5f\\u6ce2\\u590d\\u6eaf\\u6d04\\u3002\", \"\\u5ff5\\u5b64\\u5fc3\\u6613\\u65ad\\uff0c\\u8ffd\\u5f80\\u6068\\u8270\\u88c1\\u3002\", \"\\u4e0d\\u9042\\u537f\\u5c06\\u4f2f\\uff0c\\u5b70\\u4e91\\u9648\\u4e0e\\u96f7\\u3002\", \"\\u543e\\u8870\\u4ea6\\u5982\\u6b64\\uff0c\\u592b\\u5b50\\u590d\\u4f55\\u54c0\\u3002\"]"', '诗', 'shi', '', NULL, '蜀城哭台州樂安少府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f528586-3940-4d2a-8145-474ef8202668', '立春日侍宴內出剪綵花應制', '立春日侍宴内出剪彩花应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u66c9\\u5165\\u5b9c\\u6625\\u82d1\\uff0c\\u7a60\\u82b3\\u5410\\u7981\\u4e2d\\u3002\", \"\\u526a\\u5200\\u56e0\\u88c2\\u7d20\\uff0c\\u599d\\u7c89\\u7232\\u958b\\u7d05\\u3002\", \"\\u5f69\\u7570\\u9a5a\\u6d41\\u96ea\\uff0c\\u9999\\u9952\\u9ede\\u4fbf\\u98a8\\u3002\", \"\\u88c1\\u6210\\u8b58\\u5929\\u610f\\uff0c\\u842c\\u7269\\u8207\\u82b1\\u540c\\u3002\"]"', '"[\"\\u6653\\u5165\\u5b9c\\u6625\\u82d1\\uff0c\\u79fe\\u82b3\\u5410\\u7981\\u4e2d\\u3002\", \"\\u526a\\u5200\\u56e0\\u88c2\\u7d20\\uff0c\\u5986\\u7c89\\u4e3a\\u5f00\\u7ea2\\u3002\", \"\\u5f69\\u5f02\\u60ca\\u6d41\\u96ea\\uff0c\\u9999\\u9976\\u70b9\\u4fbf\\u98ce\\u3002\", \"\\u88c1\\u6210\\u8bc6\\u5929\\u610f\\uff0c\\u4e07\\u7269\\u4e0e\\u82b1\\u540c\\u3002\"]"', '诗', 'shi', '', NULL, '立春日侍宴內出剪綵花應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0be48092-4737-4052-a441-cf232f41af7e', '春日芙蓉園侍宴應制', '春日芙蓉园侍宴应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5fa1\\u9053\\u7d05\\u65d7\\u51fa\\uff0c\\u82b3\\u5712\\u7fe0\\u8f26\\u904a\\u3002\", \"\\u7e5e\\u82b1\\u958b\\u6c34\\u6bbf\\uff0c\\u67b6\\u7af9\\u8d77\\u5c71\\u6a13\\u3002\", \"\\u8377\\u82b0\\u8f15\\u85b0\\u5e44\\uff0c\\u9b5a\\u9f8d\\u51fa\\u8ca0\\u821f\\u3002\", \"\\u5be7\\u77e5\\u7a46\\u5929\\u5b50\\uff0c\\u7a7a\\u8ce6\\u767d\\u96f2\\u79cb\\u3002\"]"', '"[\"\\u5fa1\\u9053\\u7ea2\\u65d7\\u51fa\\uff0c\\u82b3\\u56ed\\u7fe0\\u8f87\\u6e38\\u3002\", \"\\u7ed5\\u82b1\\u5f00\\u6c34\\u6bbf\\uff0c\\u67b6\\u7af9\\u8d77\\u5c71\\u697c\\u3002\", \"\\u8377\\u82b0\\u8f7b\\u85b0\\u5e44\\uff0c\\u9c7c\\u9f99\\u51fa\\u8d1f\\u821f\\u3002\", \"\\u5b81\\u77e5\\u7a46\\u5929\\u5b50\\uff0c\\u7a7a\\u8d4b\\u767d\\u4e91\\u79cb\\u3002\"]"', '诗', 'shi', '', NULL, '春日芙蓉園侍宴應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('159307b8-e963-4996-8162-ab4653a298b3', '奉和聖製人日清暉閣宴羣臣遇雪應制', '奉和圣制人日清晖阁宴群臣遇雪应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6a13\\u89c0\\u7a7a\\u7159\\u88cf\\uff0c\\u521d\\u5e74\\u745e\\u96ea\\u904e\\u3002\", \"\\u82d1\\u82b1\\u9f4a\\u7389\\u6a39\\uff0c\\u6c60\\u6c34\\u4f5c\\u9280\\u6cb3\\u3002\", \"\\u4e03\\u65e5\\u7965\\u5716\\u5553\\uff0c\\u5343\\u6625\\u5fa1\\u8cde\\u591a\\u3002\", \"\\u8f15\\u98db\\u50b3\\u7db5\\u52dd\\uff0c\\u5929\\u4e0a\\u5949\\u85b0\\u6b4c\\u3002\"]"', '"[\"\\u697c\\u89c2\\u7a7a\\u70df\\u91cc\\uff0c\\u521d\\u5e74\\u745e\\u96ea\\u8fc7\\u3002\", \"\\u82d1\\u82b1\\u9f50\\u7389\\u6811\\uff0c\\u6c60\\u6c34\\u4f5c\\u94f6\\u6cb3\\u3002\", \"\\u4e03\\u65e5\\u7965\\u56fe\\u542f\\uff0c\\u5343\\u6625\\u5fa1\\u8d4f\\u591a\\u3002\", \"\\u8f7b\\u98de\\u4f20\\u5f69\\u80dc\\uff0c\\u5929\\u4e0a\\u5949\\u85b0\\u6b4c\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製人日清暉閣宴羣臣遇雪應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df81720-68ee-4257-9536-d0685cce5e26', '奉和七夕宴兩儀殿應制', '奉和七夕宴两仪殿应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u9748\\u5a9b\\u4e58\\u79cb\\u767c\\uff0c\\u4ed9\\u88dd\\u8b66\\u591c\\u50ac\\u3002\", \"\\u6708\\u5149\\u7aba\\u6b32\\u6e21\\uff0c\\u6cb3\\u8272\\u8fa8\\u61c9\\u4f86\\u3002\", \"\\u6a5f\\u77f3\\u5929\\u6587\\u5beb\\uff0c\\u91dd\\u6a13\\u5fa1\\u8cde\\u958b\\u3002\", \"\\u7aca\\u89c0\\u68f2\\u9ce5\\u81f3\\uff0c\\u7591\\u5411\\u9d72\\u6a4b\\u8ff4\\u3002\"]"', '"[\"\\u7075\\u5a9b\\u4e58\\u79cb\\u53d1\\uff0c\\u4ed9\\u88c5\\u8b66\\u591c\\u50ac\\u3002\", \"\\u6708\\u5149\\u7aa5\\u6b32\\u6e21\\uff0c\\u6cb3\\u8272\\u8fa8\\u5e94\\u6765\\u3002\", \"\\u673a\\u77f3\\u5929\\u6587\\u5199\\uff0c\\u9488\\u697c\\u5fa1\\u8d4f\\u5f00\\u3002\", \"\\u7a83\\u89c2\\u6816\\u9e1f\\u81f3\\uff0c\\u7591\\u5411\\u9e4a\\u6865\\u56de\\u3002\"]"', '诗', 'shi', '', NULL, '奉和七夕宴兩儀殿應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc67c445-07f7-4832-b519-86868d613ce3', '奉和九日幸臨渭亭登高應制得時字', '奉和九日幸临渭亭登高应制得时字', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5609\\u6703\\u5b9c\\u9577\\u65e5\\uff0c\\u9ad8\\u7b75\\u9806\\u52d5\\u6642\\u3002\", \"\\u66c9\\u5149\\u96f2\\u5916\\u6d17\\uff0c\\u6674\\u8272\\u96e8\\u9918\\u6ecb\\u3002\", \"\\u964d\\u9db4\\u56e0\\u97f6\\u5fb7\\uff0c\\u5439\\u82b1\\u5165\\u5fa1\\u8a5e\\u3002\", \"\\u9858\\u966a\\u967d\\u6578\\u7bc0\\uff0c\\u5104\\u842c\\u4e5d\\u79cb\\u671f\\u3002\"]"', '"[\"\\u5609\\u4f1a\\u5b9c\\u957f\\u65e5\\uff0c\\u9ad8\\u7b75\\u987a\\u52a8\\u65f6\\u3002\", \"\\u6653\\u5149\\u4e91\\u5916\\u6d17\\uff0c\\u6674\\u8272\\u96e8\\u4f59\\u6ecb\\u3002\", \"\\u964d\\u9e64\\u56e0\\u97f6\\u5fb7\\uff0c\\u5439\\u82b1\\u5165\\u5fa1\\u8bcd\\u3002\", \"\\u613f\\u966a\\u9633\\u6570\\u8282\\uff0c\\u4ebf\\u4e07\\u4e5d\\u79cb\\u671f\\u3002\"]"', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得時字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ca540c1-3bfa-4b0a-bc27-ac5fd7cde86f', '游禁苑幸臨渭亭遇雪應制', '游禁苑幸临渭亭遇雪应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5e73\\u660e\\u655e\\u5e1d\\u5c45\\uff0c\\u9730\\u96ea\\u4e0b\\u51cc\\u865b\\u3002\", \"\\u5beb\\u6708\\u542b\\u73e0\\u7db4\\uff0c\\u5f9e\\u98a8\\u8584\\u7dba\\u758f\\u3002\", \"\\u5e74\\u9a5a\\u82b1\\u7d6e\\u65e9\\uff0c\\u6625\\u591c\\u7ba1\\u5f26\\u521d\\u3002\", \"\\u5df2\\u5c6c\\u96f2\\u5929\\u5916\\uff0c\\u6b23\\u627f\\u9708\\u6fa4\\u9918\\u3002\"]"', '"[\"\\u5e73\\u660e\\u655e\\u5e1d\\u5c45\\uff0c\\u9730\\u96ea\\u4e0b\\u51cc\\u865a\\u3002\", \"\\u5199\\u6708\\u542b\\u73e0\\u7f00\\uff0c\\u4ece\\u98ce\\u8584\\u7eee\\u758f\\u3002\", \"\\u5e74\\u60ca\\u82b1\\u7d6e\\u65e9\\uff0c\\u6625\\u591c\\u7ba1\\u5f26\\u521d\\u3002\", \"\\u5df2\\u5c5e\\u4e91\\u5929\\u5916\\uff0c\\u6b23\\u627f\\u9708\\u6cfd\\u4f59\\u3002\"]"', '诗', 'shi', '', NULL, '游禁苑幸臨渭亭遇雪應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df411b69-4327-4ab0-81cc-1bdca8b6ad83', '奉和送金城公主適西蕃應制', '奉和送金城公主适西蕃应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5e1d\\u5973\\u51fa\\u5929\\u6d25\\uff0c\\u548c\\u620e\\u8f49\\u7f7d\\u8f2a\\u3002\", \"\\u5ddd\\u7d93\\u65b7\\u8178\\u671b\\uff0c\\u5730\\u8207\\u6790\\u652f\\u9130\\u3002\", \"\\u594f\\u66f2\\u98a8\\u5636\\u99ac\\uff0c\\u929c\\u60b2\\u6708\\u4f34\\u4eba\\u3002\", \"\\u65cb\\u77e5\\u5043\\u5175\\u9769\\uff0c\\u9577\\u662f\\u6f22\\u5bb6\\u89aa\\u3002\"]"', '"[\"\\u5e1d\\u5973\\u51fa\\u5929\\u6d25\\uff0c\\u548c\\u620e\\u8f6c\\u7f7d\\u8f6e\\u3002\", \"\\u5ddd\\u7ecf\\u65ad\\u80a0\\u671b\\uff0c\\u5730\\u4e0e\\u6790\\u652f\\u90bb\\u3002\", \"\\u594f\\u66f2\\u98ce\\u5636\\u9a6c\\uff0c\\u8854\\u60b2\\u6708\\u4f34\\u4eba\\u3002\", \"\\u65cb\\u77e5\\u5043\\u5175\\u9769\\uff0c\\u957f\\u662f\\u6c49\\u5bb6\\u4eb2\\u3002\"]"', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b197aa21-a571-49a8-80eb-e01c503a0cfc', '奉和聖製登驪山高頂寓目應制', '奉和圣制登骊山高顶寓目应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u4ed9\\u8e55\\u5fa1\\u5c64\\u6c1b\\uff0c\\u9ad8\\u9ad8\\u7a4d\\u7fe0\\u5206\\u3002\", \"\\u5dd6\\u8072\\u4e2d\\u8c37\\u61c9\\uff0c\\u5929\\u8a9e\\u534a\\u7a7a\\u805e\\u3002\", \"\\u8c50\\u6a39\\u9023\\u9ec3\\u8449\\uff0c\\u51fd\\u95dc\\u5165\\u7d2b\\u96f2\\u3002\", \"\\u8056\\u5716\\u6062\\u5b87\\u7e23\\uff0c\\u6b4c\\u8ce6\\u5c0f\\u6a6b\\u6c7e\\u3002\"]"', '"[\"\\u4ed9\\u8df8\\u5fa1\\u5c42\\u6c1b\\uff0c\\u9ad8\\u9ad8\\u79ef\\u7fe0\\u5206\\u3002\", \"\\u5ca9\\u58f0\\u4e2d\\u8c37\\u5e94\\uff0c\\u5929\\u8bed\\u534a\\u7a7a\\u95fb\\u3002\", \"\\u4e30\\u6811\\u8fde\\u9ec4\\u53f6\\uff0c\\u51fd\\u5173\\u5165\\u7d2b\\u4e91\\u3002\", \"\\u5723\\u56fe\\u6062\\u5b87\\u53bf\\uff0c\\u6b4c\\u8d4b\\u5c0f\\u6a2a\\u6c7e\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製登驪山高頂寓目應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('431d0b6c-81af-4e69-a83b-6e1c42e56d78', '侍宴桃花園詠桃花應制', '侍宴桃花园咏桃花应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6843\\u82b1\\u707c\\u707c\\u6709\\u5149\\u8f1d\\uff0c\\u7121\\u6578\\u6210\\u8e4a\\u9ede\\u66f4\\u98db\\u3002\", \"\\u7232\\u898b\\u82b3\\u6797\\u542b\\u7b11\\u5f85\\uff0c\\u9042\\u540c\\u6eab\\u6a39\\u4e0d\\u8a00\\u6b78\\u3002\"]"', '"[\"\\u6843\\u82b1\\u707c\\u707c\\u6709\\u5149\\u8f89\\uff0c\\u65e0\\u6570\\u6210\\u8e4a\\u70b9\\u66f4\\u98de\\u3002\", \"\\u4e3a\\u89c1\\u82b3\\u6797\\u542b\\u7b11\\u5f85\\uff0c\\u9042\\u540c\\u6e29\\u6811\\u4e0d\\u8a00\\u5f52\\u3002\"]"', '诗', 'shi', '', NULL, '侍宴桃花園詠桃花應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('102e706b-89de-48c7-9a68-b6a08b25c9b5', '秋社日崇讓園宴得新字', '秋社日崇让园宴得新字', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u9cf4\\u7235\\u4e09\\u8fb2\\u7a14\\uff0c\\u52fe\\u9f8d\\u767e\\u4ee3\\u795e\\u3002\", \"\\u904b\\u660c\\u53e8\\u8f14\\u5f3c\\uff0c\\u6642\\u6cf0\\u559c\\u9ece\\u6c11\\u3002\", \"\\u6a39\\u7f3a\\u6c60\\u5149\\u8fd1\\uff0c\\u96f2\\u958b\\u65e5\\u5f71\\u65b0\\u3002\", \"\\u751f\\u5168\\u61c9\\u6709\\u5730\\uff0c\\u9577\\u9858\\u6a02\\u4ea4\\u89aa\\u3002\"]"', '"[\"\\u9e23\\u7235\\u4e09\\u519c\\u7a14\\uff0c\\u52fe\\u9f99\\u767e\\u4ee3\\u795e\\u3002\", \"\\u8fd0\\u660c\\u53e8\\u8f85\\u5f3c\\uff0c\\u65f6\\u6cf0\\u559c\\u9ece\\u6c11\\u3002\", \"\\u6811\\u7f3a\\u6c60\\u5149\\u8fd1\\uff0c\\u4e91\\u5f00\\u65e5\\u5f71\\u65b0\\u3002\", \"\\u751f\\u5168\\u5e94\\u6709\\u5730\\uff0c\\u957f\\u613f\\u4e50\\u4ea4\\u4eb2\\u3002\"]"', '诗', 'shi', '', NULL, '秋社日崇讓園宴得新字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c05330b-1f5e-4b8e-a7b8-bb090ae92808', '奉和魏僕射秋日還鄉有懷之作', '奉和魏仆射秋日还乡有怀之作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5357\\u5bae\\u5919\\u62dc\\u7f77\\uff0c\\u6771\\u9053\\u665d\\u904a\\u521d\\u3002\", \"\\u98f2\\u991e\\u50be\\u51a0\\u84cb\\uff0c\\u50b3\\u547c\\u554f\\u91cc\\u95ad\\u3002\", \"\\u6a39\\u60b2\\u61f8\\u5292\\u6240\\uff0c\\u6eaa\\u60f3\\u91e3\\u749c\\u9918\\u3002\", \"\\u660e\\u767c\\u8f1d\\u5149\\u81f3\\uff0c\\u589e\\u69ae\\u99df\\u99ac\\u8eca\\u3002\"]"', '"[\"\\u5357\\u5bab\\u5919\\u62dc\\u7f62\\uff0c\\u4e1c\\u9053\\u663c\\u6e38\\u521d\\u3002\", \"\\u996e\\u996f\\u503e\\u51a0\\u76d6\\uff0c\\u4f20\\u547c\\u95ee\\u91cc\\u95fe\\u3002\", \"\\u6811\\u60b2\\u60ac\\u5292\\u6240\\uff0c\\u6eaa\\u60f3\\u9493\\u749c\\u4f59\\u3002\", \"\\u660e\\u53d1\\u8f89\\u5149\\u81f3\\uff0c\\u589e\\u8363\\u9a77\\u9a6c\\u8f66\\u3002\"]"', '诗', 'shi', '', NULL, '奉和魏僕射秋日還鄉有懷之作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e40ff6-e0e9-4252-847c-ef59cb447495', '武[擔]山寺', '武[担]山寺', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6b66[\\u64d4]\\u7368\\u84bc\\u7136\\uff0c\\u58b3\\u5c71\\u4e0b\\u7389\\u6cc9\\u3002\", \"\\u9c49\\u9748\\u6642\\u5171\\u76e1\\uff0c\\u9f8d\\u5973\\u4e8b\\u540c\\u9077\\u3002\", \"\\u677e\\u67cf\\u929c\\u54c0\\u8655\\uff0c\\u5e61\\u82b1\\u7a2e\\u798f\\u7530\\u3002\", \"\\u8a4e\\u77e5\\u7559\\u93e1\\u77f3\\uff0c\\u9577\\u8207\\u6cd5\\u8f2a\\u5713\\u3002\"]"', '"[\"\\u6b66[\\u62c5]\\u72ec\\u82cd\\u7136\\uff0c\\u575f\\u5c71\\u4e0b\\u7389\\u6cc9\\u3002\", \"\\u9cd6\\u7075\\u65f6\\u5171\\u5c3d\\uff0c\\u9f99\\u5973\\u4e8b\\u540c\\u8fc1\\u3002\", \"\\u677e\\u67cf\\u8854\\u54c0\\u5904\\uff0c\\u5e61\\u82b1\\u79cd\\u798f\\u7530\\u3002\", \"\\u8bb5\\u77e5\\u7559\\u955c\\u77f3\\uff0c\\u957f\\u4e0e\\u6cd5\\u8f6e\\u5706\\u3002\"]"', '诗', 'shi', '', NULL, '武[擔]山寺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a38183b4-3508-4ec9-b868-b4ada737a761', '餞潞州陸長史再守汾州', '饯潞州陆长史再守汾州', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6cb3\\u5c39\\u653f\\u6210\\u671f\\uff0c\\u7232\\u6c7e\\u6614\\u6240\\u63a8\\u3002\", \"\\u4e0d\\u69ae\\u4e09\\u5165\\u5730\\uff0c\\u9084\\u7f8e\\u518d\\u81e8\\u6642\\u3002\", \"\\u64c1\\u50b3\\u96f2\\u521d\\u5408\\uff0c\\u805e\\u9daf\\u65e5\\u6b63\\u9072\\u3002\", \"\\u9053\\u508d\\u591a\\u51fa\\u991e\\uff0c\\u5225\\u6709\\u540f\\u6c11\\u601d\\u3002\"]"', '"[\"\\u6cb3\\u5c39\\u653f\\u6210\\u671f\\uff0c\\u4e3a\\u6c7e\\u6614\\u6240\\u63a8\\u3002\", \"\\u4e0d\\u8363\\u4e09\\u5165\\u5730\\uff0c\\u8fd8\\u7f8e\\u518d\\u4e34\\u65f6\\u3002\", \"\\u62e5\\u4f20\\u4e91\\u521d\\u5408\\uff0c\\u95fb\\u83ba\\u65e5\\u6b63\\u8fdf\\u3002\", \"\\u9053\\u508d\\u591a\\u51fa\\u996f\\uff0c\\u522b\\u6709\\u540f\\u6c11\\u601d\\u3002\"]"', '诗', 'shi', '', NULL, '餞潞州陸長史再守汾州 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b7c4bd-b35c-4f56-81f0-a29f1b427a29', '餞荆州崔司馬', '饯荆州崔司马', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u8302\\u79ae\\u96d5\\u9f8d\\u6614\\uff0c\\u9999\\u540d\\u5c55\\u9a65\\u521d\\u3002\", \"\\u6c34\\u9023\\u5357\\u6d77\\u6f32\\uff0c\\u661f\\u62f1\\u5317\\u8fb0\\u5c45\\u3002\", \"\\u7a0d\\u767c\\u4ed9\\u4eba\\u5c65\\uff0c\\u5c07\\u984c\\u5225\\u99d5\\u8f3f\\u3002\", \"\\u660e\\u5e74\\u5fb5\\u62dc\\u5165\\uff0c\\u8346\\u7389\\u4e0d\\u85cf\\u8af8\\u3002\"]"', '"[\"\\u8302\\u793c\\u96d5\\u9f99\\u6614\\uff0c\\u9999\\u540d\\u5c55\\u9aa5\\u521d\\u3002\", \"\\u6c34\\u8fde\\u5357\\u6d77\\u6da8\\uff0c\\u661f\\u62f1\\u5317\\u8fb0\\u5c45\\u3002\", \"\\u7a0d\\u53d1\\u4ed9\\u4eba\\u5c65\\uff0c\\u5c06\\u9898\\u522b\\u9a7e\\u8206\\u3002\", \"\\u660e\\u5e74\\u5f81\\u62dc\\u5165\\uff0c\\u8346\\u7389\\u4e0d\\u85cf\\u8bf8\\u3002\"]"', '诗', 'shi', '', NULL, '餞荆州崔司馬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d24e38e5-b873-42f2-8f43-02ef2d6b61d0', '送吏部李侍郎東歸得歸字', '送吏部李侍郎东归得归字', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u964c\\u4e0a\\u6709\\u5149\\u8f1d\\uff0c\\u62ab\\u96f2\\u5411\\u6d1b\\u757f\\u3002\", \"\\u8cde\\u4f86\\u69ae\\u6248\\u5f9e\\uff0c\\u5225\\u81f3\\u60dc\\u5206\\u98db\\u3002\", \"\\u6cc9\\u6e9c\\u542b\\u98a8\\u6025\\uff0c\\u5c71\\u7159\\u5e36\\u65e5\\u5fae\\u3002\", \"\\u8302\\u66f9\\u4eca\\u53bb\\u77e3\\uff0c\\u4eba\\u7269\\u559c\\u6771\\u6b78\\u3002\"]"', '"[\"\\u964c\\u4e0a\\u6709\\u5149\\u8f89\\uff0c\\u62ab\\u4e91\\u5411\\u6d1b\\u757f\\u3002\", \"\\u8d4f\\u6765\\u8363\\u6248\\u4ece\\uff0c\\u522b\\u81f3\\u60dc\\u5206\\u98de\\u3002\", \"\\u6cc9\\u6e9c\\u542b\\u98ce\\u6025\\uff0c\\u5c71\\u70df\\u5e26\\u65e5\\u5fae\\u3002\", \"\\u8302\\u66f9\\u4eca\\u53bb\\u77e3\\uff0c\\u4eba\\u7269\\u559c\\u4e1c\\u5f52\\u3002\"]"', '诗', 'shi', '', NULL, '送吏部李侍郎東歸得歸字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06b6a208-f048-40c0-9f03-b076f891c028', '送光祿姚卿還都', '送光禄姚卿还都', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6f22\\u5ba4\\u6709\\u82f1\\u53f0\\uff0c\\u8340\\u5bb6\\u5bf5\\u4fca\\u624d\\u3002\", \"\\u4e5d\\u537f\\u671d\\u5df2\\u5165\\uff0c\\u4e09\\u5b50\\u66ae\\u540c\\u4f86\\u3002\", \"\\u4e0d\\u6388\\u7db8\\u7232\\u8349\\uff0c\\u9084\\u53f8\\u9f0e\\u7528\\u6885\\u3002\", \"\\u5169\\u4eac\\u738b\\u8005\\u5b85\\uff0c\\u99df\\u99ac\\u65e5\\u61c9\\u8ff4\\u3002\"]"', '"[\"\\u6c49\\u5ba4\\u6709\\u82f1\\u53f0\\uff0c\\u8340\\u5bb6\\u5ba0\\u4fca\\u624d\\u3002\", \"\\u4e5d\\u537f\\u671d\\u5df2\\u5165\\uff0c\\u4e09\\u5b50\\u66ae\\u540c\\u6765\\u3002\", \"\\u4e0d\\u6388\\u7eb6\\u4e3a\\u8349\\uff0c\\u8fd8\\u53f8\\u9f0e\\u7528\\u6885\\u3002\", \"\\u4e24\\u4eac\\u738b\\u8005\\u5b85\\uff0c\\u9a77\\u9a6c\\u65e5\\u5e94\\u56de\\u3002\"]"', '诗', 'shi', '', NULL, '送光祿姚卿還都 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ae47935-e2df-4070-b7e0-e273ebc48549', '春晚送瑕丘田少府還任因寄洛中鏡上人', '春晚送瑕丘田少府还任因寄洛中镜上人', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u805e\\u9053\\u9084\\u6c82\\u4e0a\\uff0c\\u56e0\\u8072\\u5bc4\\u6d1b\\u6ff1\\u3002\", \"\\u5225\\u6642\\u82b1\\u6b32\\u76e1\\uff0c\\u6b78\\u8655\\u9152\\u61c9\\u6625\\u3002\", \"\\u805a\\u6563\\u540c\\u884c\\u5ba2\\uff0c\\u60b2\\u6b61\\u5c6c\\u6545\\u4eba\\u3002\", \"\\u5c11\\u5e74\\u8ffd\\u6a02\\u5730\\uff0c\\u9059\\u8d08\\u4e00\\u9711\\u5dfe\\u3002\"]"', '"[\"\\u95fb\\u9053\\u8fd8\\u6c82\\u4e0a\\uff0c\\u56e0\\u58f0\\u5bc4\\u6d1b\\u6ee8\\u3002\", \"\\u522b\\u65f6\\u82b1\\u6b32\\u5c3d\\uff0c\\u5f52\\u5904\\u9152\\u5e94\\u6625\\u3002\", \"\\u805a\\u6563\\u540c\\u884c\\u5ba2\\uff0c\\u60b2\\u6b22\\u5c5e\\u6545\\u4eba\\u3002\", \"\\u5c11\\u5e74\\u8ffd\\u4e50\\u5730\\uff0c\\u9065\\u8d60\\u4e00\\u6cbe\\u5dfe\\u3002\"]"', '诗', 'shi', '', NULL, '春晚送瑕丘田少府還任因寄洛中鏡上人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('160135e4-5dc7-46b0-8ec2-ba5430b0e05e', '送賈起居奉使入洛取圖書因便拜覲', '送贾起居奉使入洛取图书因便拜觐', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u820a\\u570b\\u624d\\u56e0\\u5730\\uff0c\\u7576\\u671d\\u53f2\\u547d\\u5b98\\u3002\", \"\\u907a\\u6587\\u5fb5\\u95d5\\u7c21\\uff0c\\u9084\\u601d\\u91c7\\u82b3\\u862d\\u3002\", \"\\u50b3\\u767c\\u95dc\\u9580\\u5019\\uff0c\\u89f4\\u7a31\\u9091\\u91cc\\u6b61\\u3002\", \"\\u65e9\\u6301\\u4eac\\u526f\\u5165\\uff0c\\u65cb\\u4f47\\u6d1b\\u66f8\\u520a\\u3002\"]"', '"[\"\\u65e7\\u56fd\\u624d\\u56e0\\u5730\\uff0c\\u5f53\\u671d\\u53f2\\u547d\\u5b98\\u3002\", \"\\u9057\\u6587\\u5f81\\u9619\\u7b80\\uff0c\\u8fd8\\u601d\\u91c7\\u82b3\\u5170\\u3002\", \"\\u4f20\\u53d1\\u5173\\u95e8\\u5019\\uff0c\\u89de\\u79f0\\u9091\\u91cc\\u6b22\\u3002\", \"\\u65e9\\u6301\\u4eac\\u526f\\u5165\\uff0c\\u65cb\\u4f2b\\u6d1b\\u4e66\\u520a\\u3002\"]"', '诗', 'shi', '', NULL, '送賈起居奉使入洛取圖書因便拜覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce6d8141-f62a-44e9-a533-0a88f7cce28e', '送常侍舒公歸覲', '送常侍舒公归觐', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u671d\\u805e\\u8b1b\\u85dd\\u9918\\uff0c\\u6668\\u7701\\u62dc\\u6069\\u521d\\u3002\", \"\\u8a13\\u80c4\\u5c0a\\u5ea0\\u5e8f\\uff0c\\u69ae\\u89aa\\u8000\\u91cc\\u95ad\\u3002\", \"\\u6731\\u4e39\\u83ef\\u8f42\\u9001\\uff0c\\u6591\\u767d\\u7dba\\u7b75\\u8212\\u3002\", \"\\u6c5f\\u4e0a\\u6625\\u6d41\\u6eff\\uff0c\\u9084\\u61c9\\u85a6\\u8e8d\\u9b5a\\u3002\"]"', '"[\"\\u671d\\u95fb\\u8bb2\\u827a\\u4f59\\uff0c\\u6668\\u7701\\u62dc\\u6069\\u521d\\u3002\", \"\\u8bad\\u80c4\\u5c0a\\u5ea0\\u5e8f\\uff0c\\u8363\\u4eb2\\u8000\\u91cc\\u95fe\\u3002\", \"\\u6731\\u4e39\\u534e\\u6bc2\\u9001\\uff0c\\u6591\\u767d\\u7eee\\u7b75\\u8212\\u3002\", \"\\u6c5f\\u4e0a\\u6625\\u6d41\\u6ee1\\uff0c\\u8fd8\\u5e94\\u8350\\u8dc3\\u9c7c\\u3002\"]"', '诗', 'shi', '', NULL, '送常侍舒公歸覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae418edf-29f6-4110-89d8-add12c322b15', '興州出行', '兴州出行', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5371\\u9014\\u66c9\\u672a\\u5206\\uff0c\\u9a45\\u99ac\\u508d\\u6c5f\\u6fc6\\u3002\", \"\\u6ef4\\u6ef4\\u6ce3\\u82b1\\u9732\\uff0c\\u5fae\\u5fae\\u51fa\\u5cab\\u96f2\\u3002\", \"\\u677e\\u68a2\\u534a\\u5410\\u6708\\uff0c\\u863f\\u7ff3\\u6f38\\u79fb\\u66db\\u3002\", \"\\u65c5\\u5ba2\\u8178\\u61c9\\u65b7\\uff0c\\u541f\\u733f\\u66f4\\u4f7f\\u805e\\u3002\"]"', '"[\"\\u5371\\u9014\\u6653\\u672a\\u5206\\uff0c\\u9a71\\u9a6c\\u508d\\u6c5f\\ud84f\\ude23\\u3002\", \"\\u6ef4\\u6ef4\\u6ce3\\u82b1\\u9732\\uff0c\\u5fae\\u5fae\\u51fa\\u5cab\\u4e91\\u3002\", \"\\u677e\\u68a2\\u534a\\u5410\\u6708\\uff0c\\u841d\\u7ff3\\u6e10\\u79fb\\u66db\\u3002\", \"\\u65c5\\u5ba2\\u80a0\\u5e94\\u65ad\\uff0c\\u541f\\u733f\\u66f4\\u4f7f\\u95fb\\u3002\"]"', '诗', 'shi', '', NULL, '興州出行 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f752d20-1dce-4bbd-a5fc-0d15970f2c70', '邊秋薄暮', '边秋薄暮', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6d77\\u5916\\u79cb\\u9df9\\u64ca\\uff0c\\u971c\\u524d\\u65c5\\u96c1\\u6b78\\u3002\", \"\\u908a\\u98a8\\u601d\\u979e\\u9f13\\uff0c\\u843d\\u65e5\\u6158\\u65cc\\u9ebe\\u3002\", \"\\u6d66\\u6697\\u6f01\\u821f\\u5165\\uff0c\\u5ddd\\u9577\\u7375\\u9a0e\\u7a00\\u3002\", \"\\u5ba2\\u60b2\\u9022\\u8584\\u66ae\\uff0c\\u6cc1\\u4e43\\u4e8b\\u620e\\u6a5f\\u3002\"]"', '"[\"\\u6d77\\u5916\\u79cb\\u9e70\\u51fb\\uff0c\\u971c\\u524d\\u65c5\\u96c1\\u5f52\\u3002\", \"\\u8fb9\\u98ce\\u601d\\u979e\\u9f13\\uff0c\\u843d\\u65e5\\u60e8\\u65cc\\u9ebe\\u3002\", \"\\u6d66\\u6697\\u6e14\\u821f\\u5165\\uff0c\\u5ddd\\u957f\\u730e\\u9a91\\u7a00\\u3002\", \"\\u5ba2\\u60b2\\u9022\\u8584\\u66ae\\uff0c\\u51b5\\u4e43\\u4e8b\\u620e\\u673a\\u3002\"]"', '诗', 'shi', '', NULL, '邊秋薄暮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c36dcb-3ef4-4ce3-b03a-e3ec1394fd01', '曉發方騫驛', '晓发方骞驿', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u50b3\\u7f6e\\u9060\\u5c71\\u8e4a\\uff0c\\u9f8d\\u937e\\u8e74\\u6f97\\u6ce5\\u3002\", \"\\u7247\\u9670\\u5e38\\u4f5c\\u96e8\\uff0c\\u5fae\\u7167\\u5df2\\u751f\\u9713\\u3002\", \"\\u9b22\\u9aea\\u6101\\u6c1b\\u63db\\uff0c\\u5fc3\\u60c5\\u96aa\\u8def\\u8ff7\\u3002\", \"\\u65b9\\u77e5\\u5411\\u8700\\u8005\\uff0c\\u504f\\u8b58\\u5b50\\u898f\\u557c\\u3002\"]"', '"[\"\\u4f20\\u7f6e\\u8fdc\\u5c71\\u8e4a\\uff0c\\u9f99\\u949f\\u8e74\\u6da7\\u6ce5\\u3002\", \"\\u7247\\u9634\\u5e38\\u4f5c\\u96e8\\uff0c\\u5fae\\u7167\\u5df2\\u751f\\u9713\\u3002\", \"\\u9b13\\u9aea\\u6101\\u6c1b\\u6362\\uff0c\\u5fc3\\u60c5\\u9669\\u8def\\u8ff7\\u3002\", \"\\u65b9\\u77e5\\u5411\\u8700\\u8005\\uff0c\\u504f\\u8bc6\\u5b50\\u89c4\\u557c\\u3002\"]"', '诗', 'shi', '', NULL, '曉發方騫驛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a62f9110-f7b5-4972-b3a4-3d111557335e', '經三泉路作', '经三泉路作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u4e09\\u6708\\u677e\\u4f5c\\u82b1\\uff0c\\u6625\\u884c\\u65e5\\u6f38\\u8cd2\\u3002\", \"\\u7af9\\u969c\\u5c71\\u9ce5\\u8def\\uff0c\\u85e4\\u8513\\u91ce\\u4eba\\u5bb6\\u3002\", \"\\u900f\\u77f3\\u98db\\u6881\\u4e0b\\uff0c\\u5c0b\\u96f2\\u7d55\\u78f4\\u659c\\u3002\", \"\\u6b64\\u4e2d\\u8ab0\\u8207\\u6a02\\uff0c\\u63ee\\u6d95\\u8a9e\\u5e74\\u83ef\\u3002\"]"', '"[\"\\u4e09\\u6708\\u677e\\u4f5c\\u82b1\\uff0c\\u6625\\u884c\\u65e5\\u6e10\\u8d4a\\u3002\", \"\\u7af9\\u969c\\u5c71\\u9e1f\\u8def\\uff0c\\u85e4\\u8513\\u91ce\\u4eba\\u5bb6\\u3002\", \"\\u900f\\u77f3\\u98de\\u6881\\u4e0b\\uff0c\\u5bfb\\u4e91\\u7edd\\u78f4\\u659c\\u3002\", \"\\u6b64\\u4e2d\\u8c01\\u4e0e\\u4e50\\uff0c\\u6325\\u6d95\\u8bed\\u5e74\\u534e\\u3002\"]"', '诗', 'shi', '', NULL, '經三泉路作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c61d3f0-f9c9-4a21-83bc-91a2b4eb26c2', '故高安大長公主挽詞', '故高安大长公主挽词', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5f64\\u7ba1\\u627f\\u5e2b\\u8a13\\uff0c\\u9752\\u572d\\u5099\\u79ae\\u5bb9\\u3002\", \"\\u5b5f\\u5b6b\\u5bb6\\u4ee3\\u5bf5\\uff0c\\u5143\\u5973\\u570b\\u671d\\u5c01\\u3002\", \"\\u67d4\\u8ecc\\u984c\\u8c9e\\u9806\\uff0c\\u9591\\u898f\\u8ce6\\u8085\\u96cd\\u3002\", \"\\u5be7\\u77e5\\u843d\\u7167\\u76e1\\uff0c\\u971c\\u5439\\u5165\\u60b2\\u677e\\u3002\"]"', '"[\"\\u5f64\\u7ba1\\u627f\\u5e08\\u8bad\\uff0c\\u9752\\u572d\\u5907\\u793c\\u5bb9\\u3002\", \"\\u5b5f\\u5b59\\u5bb6\\u4ee3\\u5ba0\\uff0c\\u5143\\u5973\\u56fd\\u671d\\u5c01\\u3002\", \"\\u67d4\\u8f68\\u9898\\u8d1e\\u987a\\uff0c\\u95f2\\u89c4\\u8d4b\\u8083\\u96cd\\u3002\", \"\\u5b81\\u77e5\\u843d\\u7167\\u5c3d\\uff0c\\u971c\\u5439\\u5165\\u60b2\\u677e\\u3002\"]"', '诗', 'shi', '', NULL, '故高安大長公主挽詞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65ba98bf-17d0-4920-888c-d7b7ea34cd0f', '贈司徒豆盧府君挽詞', '赠司徒豆卢府君挽词', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5bf5\\u8d08\\u8ffd\\u80e1\\u5ee3\\uff0c\\u89aa\\u81e8\\u6bd4\\u8cc0\\u5faa\\u3002\", \"\\u5e7e\\u805e\\u6295\\u5292\\u5ba2\\uff0c\\u591a\\u6703\\u670d\\u7de6\\u4eba\\u3002\", \"\\u8349\\u9589\\u58b3\\u5c07\\u53e4\\uff0c\\u677e\\u9670\\u5730\\u4e0d\\u6625\\u3002\", \"\\u4e8c\\u9675\\u7336\\u53ef\\u671b\\uff0c\\u5b58\\u6b7f\\u6709\\u5fe0\\u81e3\\u3002\"]"', '"[\"\\u5ba0\\u8d60\\u8ffd\\u80e1\\u5e7f\\uff0c\\u4eb2\\u4e34\\u6bd4\\u8d3a\\u5faa\\u3002\", \"\\u51e0\\u95fb\\u6295\\u5292\\u5ba2\\uff0c\\u591a\\u4f1a\\u670d\\u7f0c\\u4eba\\u3002\", \"\\u8349\\u95ed\\u575f\\u5c06\\u53e4\\uff0c\\u677e\\u9634\\u5730\\u4e0d\\u6625\\u3002\", \"\\u4e8c\\u9675\\u72b9\\u53ef\\u671b\\uff0c\\u5b58\\u6b81\\u6709\\u5fe0\\u81e3\\u3002\"]"', '诗', 'shi', '', NULL, '贈司徒豆盧府君挽詞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c519f0-d28d-4991-a888-23b3b51a2aa4', '故右散騎常侍舒國公褚公挽詞', '故右散骑常侍舒国公褚公挽词', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u967d\\u7fdf\\u758f\\u8c50\\u69cb\\uff0c\\u81e8\\u5e73\\u6f14\\u6176\\u6e90\\u3002\", \"\\u5b78\\u7b75\\u5c0a\\u6388\\u51e0\\uff0c\\u5112\\u670d\\u5bf5\\u4e58\\u8ed2\\u3002\", \"\\u5be9\\u8aed\\u7559\\u4e2d\\u5bc6\\uff0c\\u958b\\u9673\\u8207\\u4e0a\\u8a00\\u3002\", \"\\u5f82\\u6689\\u4e00\\u4e0d\\u501f\\uff0c\\u7a7a\\u6709\\u8cdc\\u6771\\u5712\\u3002\"]"', '"[\"\\u9633\\u7fdf\\u758f\\u4e30\\u6784\\uff0c\\u4e34\\u5e73\\u6f14\\u5e86\\u6e90\\u3002\", \"\\u5b66\\u7b75\\u5c0a\\u6388\\u51e0\\uff0c\\u5112\\u670d\\u5ba0\\u4e58\\u8f69\\u3002\", \"\\u5ba1\\u8c15\\u7559\\u4e2d\\u5bc6\\uff0c\\u5f00\\u9648\\u4e0e\\u4e0a\\u8a00\\u3002\", \"\\u5f82\\u6656\\u4e00\\u4e0d\\u501f\\uff0c\\u7a7a\\u6709\\u8d50\\u4e1c\\u56ed\\u3002\"]"', '诗', 'shi', '', NULL, '故右散騎常侍舒國公褚公挽詞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('368efa80-0488-4b26-b662-e16c5ddb2392', '奉和初春幸太平公主南莊應制', '奉和初春幸太平公主南庄应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u4e3b\\u7b2c\\u5c71\\u9580\\u8d77\\u705e\\u5ddd\\uff0c\\u5bb8\\u904a\\u98a8\\u666f\\u5165\\u521d\\u5e74\\u3002\", \"\\u9cf3\\u7687\\u6a13\\u4e0b\\u4ea4\\u5929\\u4ed7\\uff0c\\u70cf\\u9d72\\u6a4b\\u982d\\u655e\\u5fa1\\u7b75\\u3002\", \"\\u5f80\\u5f80\\u82b1\\u9593\\u9022\\u7db5\\u77f3\\uff0c\\u6642\\u6642\\u7af9\\u88cf\\u898b\\u7d05\\u6cc9\\u3002\", \"\\u4eca\\u671d\\u6248\\u8e55\\u5e73\\u967d\\u9928\\uff0c\\u4e0d\\u7fa8\\u4e58\\u69ce\\u96f2\\u6f22\\u908a\\u3002\"]"', '"[\"\\u4e3b\\u7b2c\\u5c71\\u95e8\\u8d77\\u705e\\u5ddd\\uff0c\\u5bb8\\u6e38\\u98ce\\u666f\\u5165\\u521d\\u5e74\\u3002\", \"\\u51e4\\u7687\\u697c\\u4e0b\\u4ea4\\u5929\\u4ed7\\uff0c\\u4e4c\\u9e4a\\u6865\\u5934\\u655e\\u5fa1\\u7b75\\u3002\", \"\\u5f80\\u5f80\\u82b1\\u95f4\\u9022\\u5f69\\u77f3\\uff0c\\u65f6\\u65f6\\u7af9\\u91cc\\u89c1\\u7ea2\\u6cc9\\u3002\", \"\\u4eca\\u671d\\u6248\\u8df8\\u5e73\\u9633\\u9986\\uff0c\\u4e0d\\u7fa1\\u4e58\\u69ce\\u4e91\\u6c49\\u8fb9\\u3002\"]"', '诗', 'shi', '', NULL, '奉和初春幸太平公主南莊應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c09a89-52ef-41fc-9a7b-73a7879b3d79', '奉和春日幸望春宮應制', '奉和春日幸望春宫应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6771\\u671b\\u671b\\u6625\\u6625\\u53ef\\u6190\\uff0c\\u66f4\\u9022\\u6674\\u65e5\\u67f3\\u542b\\u7159\\u3002\", \"\\u5bae\\u4e2d\\u4e0b\\u898b\\u5357\\u5c71\\u76e1\\uff0c\\u57ce\\u4e0a\\u5e73\\u81e8\\u5317\\u6597\\u61f8\\u3002\", \"\\u7d30\\u8349\\u5fa7\\u627f\\u56de\\u8f26\\u8655\\uff0c\\u8f15\\u82b1\\u5fae\\u843d\\u5949\\u89f4\\u524d\\u3002\", \"\\u5bb8\\u904a\\u5c0d\\u6b64\\u6b61\\u7121\\u6975\\uff0c\\u9ce5\\u54e2\\u8072\\u8072\\u5165\\u7ba1\\u7d43\\u3002\"]"', '"[\"\\u4e1c\\u671b\\u671b\\u6625\\u6625\\u53ef\\u601c\\uff0c\\u66f4\\u9022\\u6674\\u65e5\\u67f3\\u542b\\u70df\\u3002\", \"\\u5bab\\u4e2d\\u4e0b\\u89c1\\u5357\\u5c71\\u5c3d\\uff0c\\u57ce\\u4e0a\\u5e73\\u4e34\\u5317\\u6597\\u60ac\\u3002\", \"\\u7ec6\\u8349\\u5fa7\\u627f\\u56de\\u8f87\\u5904\\uff0c\\u8f7b\\u82b1\\u5fae\\u843d\\u5949\\u89de\\u524d\\u3002\", \"\\u5bb8\\u6e38\\u5bf9\\u6b64\\u6b22\\u65e0\\u6781\\uff0c\\u9e1f\\u54e2\\u58f0\\u58f0\\u5165\\u7ba1\\u5f26\\u3002\"]"', '诗', 'shi', '', NULL, '奉和春日幸望春宮應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b92be3fe-0794-4f94-af48-4201f980535f', '人日重宴大明宮恩賜綵縷人勝應制', '人日重宴大明宫恩赐彩缕人胜应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u758f\\u9f8d\\u78f4\\u9053\\u5207\\u662d\\u56de\\uff0c\\u5efa\\u9cf3\\u65d7\\u9580\\u7e5e\\u5e1d\\u81fa\\u3002\", \"\\u4e03\\u8449\\u4ed9\\u84c2\\u4f9d\\u6708\\u5410\\uff0c\\u5343\\u682a\\u5fa1\\u67f3\\u62c2\\u7159\\u958b\\u3002\", \"\\u521d\\u5e74\\u7af6\\u8cbc\\u5b9c\\u6625\\u52dd\\uff0c\\u9577\\u547d\\u5148\\u6d6e\\u737b\\u58fd\\u676f\\u3002\", \"\\u662f\\u65e5\\u7687\\u9748\\u77e5\\u7aca\\u5e78\\uff0c\\u7fa3\\u5fc3\\u5c31\\u6367\\u5927\\u660e\\u4f86\\u3002\"]"', '"[\"\\u758f\\u9f99\\u78f4\\u9053\\u5207\\u662d\\u56de\\uff0c\\u5efa\\u51e4\\u65d7\\u95e8\\u7ed5\\u5e1d\\u53f0\\u3002\", \"\\u4e03\\u53f6\\u4ed9\\u84c2\\u4f9d\\u6708\\u5410\\uff0c\\u5343\\u682a\\u5fa1\\u67f3\\u62c2\\u70df\\u5f00\\u3002\", \"\\u521d\\u5e74\\u7ade\\u8d34\\u5b9c\\u6625\\u80dc\\uff0c\\u957f\\u547d\\u5148\\u6d6e\\u732e\\u5bff\\u676f\\u3002\", \"\\u662f\\u65e5\\u7687\\u7075\\u77e5\\u7a83\\u5e78\\uff0c\\u7fa4\\u5fc3\\u5c31\\u6367\\u5927\\u660e\\u6765\\u3002\"]"', '诗', 'shi', '', NULL, '人日重宴大明宮恩賜綵縷人勝應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36574aff-4df8-4f62-b800-b9de5bb03f5c', '侍宴安樂公主山莊應制', '侍宴安乐公主山庄应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u99f8\\u99f8\\u7fbd\\u9a0e\\u6b77\\u57ce\\u6c60\\uff0c\\u5e1d\\u5973\\u6a13\\u81fa\\u5411\\u665a\\u62ab\\u3002\", \"\\u9727\\u7051\\u65cc\\u65d7\\u96f2\\u5916\\u51fa\\uff0c\\u98a8\\u56de\\u5dd6\\u5cab\\u96e8\\u4e2d\\u79fb\\u3002\", \"\\u7576\\u8ed2\\u534a\\u843d\\u5929\\u6cb3\\u6c34\\uff0c\\u7e5e\\u5f91\\u5168\\u4f4e\\u6708\\u6a39\\u679d\\u3002\", \"\\u7c2b\\u9f13\\u5bb8\\u904a\\u966a\\u5bb4\\u65e5\\uff0c\\u548c\\u9cf4\\u96d9\\u9cf3\\u559c\\u4f86\\u5100\\u3002\"]"', '"[\"\\u9a8e\\u9a8e\\u7fbd\\u9a91\\u5386\\u57ce\\u6c60\\uff0c\\u5e1d\\u5973\\u697c\\u53f0\\u5411\\u665a\\u62ab\\u3002\", \"\\u96fe\\u6d12\\u65cc\\u65d7\\u4e91\\u5916\\u51fa\\uff0c\\u98ce\\u56de\\u5ca9\\u5cab\\u96e8\\u4e2d\\u79fb\\u3002\", \"\\u5f53\\u8f69\\u534a\\u843d\\u5929\\u6cb3\\u6c34\\uff0c\\u7ed5\\u5f84\\u5168\\u4f4e\\u6708\\u6811\\u679d\\u3002\", \"\\u7bab\\u9f13\\u5bb8\\u6e38\\u966a\\u5bb4\\u65e5\\uff0c\\u548c\\u9e23\\u53cc\\u51e4\\u559c\\u6765\\u4eea\\u3002\"]"', '诗', 'shi', '', NULL, '侍宴安樂公主山莊應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99eb1aa8-4fd8-4e54-8340-c0ba019478c1', '興慶池侍宴應制', '兴庆池侍宴应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u964d\\u9db4\\u6c60\\u524d\\u56de\\u6b65\\u8f26\\uff0c\\u68f2\\u9e1e\\u6a39\\u676a\\u51fa\\u884c\\u5bae\\u3002\", \"\\u5c71\\u5149\\u7a4d\\u7fe0\\u9059\\u7591\\u903c\\uff0c\\u6c34\\u614b\\u542b\\u9752\\u8fd1\\u82e5\\u7a7a\\u3002\", \"\\u76f4\\u8996\\u5929\\u6cb3\\u5782\\u8c61\\u5916\\uff0c\\u4fef\\u7aba\\u4eac\\u5ba4\\u756b\\u5716\\u4e2d\\u3002\", \"\\u7687\\u6b61\\u672a\\u4f7f\\u6069\\u6ce2\\u6975\\uff0c\\u65e5\\u66ae\\u6a13\\u8239\\u66f4\\u8d77\\u98a8\\u3002\"]"', '"[\"\\u964d\\u9e64\\u6c60\\u524d\\u56de\\u6b65\\u8f87\\uff0c\\u6816\\u9e3e\\u6811\\u676a\\u51fa\\u884c\\u5bab\\u3002\", \"\\u5c71\\u5149\\u79ef\\u7fe0\\u9065\\u7591\\u903c\\uff0c\\u6c34\\u6001\\u542b\\u9752\\u8fd1\\u82e5\\u7a7a\\u3002\", \"\\u76f4\\u89c6\\u5929\\u6cb3\\u5782\\u8c61\\u5916\\uff0c\\u4fef\\u7aa5\\u4eac\\u5ba4\\u753b\\u56fe\\u4e2d\\u3002\", \"\\u7687\\u6b22\\u672a\\u4f7f\\u6069\\u6ce2\\u6781\\uff0c\\u65e5\\u66ae\\u697c\\u8239\\u66f4\\u8d77\\u98ce\\u3002\"]"', '诗', 'shi', '', NULL, '興慶池侍宴應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d73f2b-66de-4a73-b974-8afeb27df095', '廣達樓下夜侍酺宴應制', '广达楼下夜侍酺宴应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6771\\u5dbd\\u5c01\\u5efb\\u5bb4\\u6d1b\\u4eac\\uff0c\\u897f\\u5889\\u901a\\u665a\\u6703\\u516c\\u537f\\u3002\", \"\\u6a13\\u81fa\\u7d55\\u52dd\\u5b9c\\u6625\\u82d1\\uff0c\\u71c8\\u706b\\u9084\\u540c\\u4e0d\\u591c\\u57ce\\u3002\", \"\\u6b63\\u89a9\\u4eba\\u9593\\u671d\\u5e02\\u6a02\\uff0c\\u5ffd\\u805e\\u5929\\u4e0a\\u7ba1\\u5f26\\u8072\\u3002\", \"\\u917a\\u4f86\\u842c\\u821e\\u7fa3\\u81e3\\u9189\\uff0c\\u559c\\u6234\\u5343\\u5e74\\u8056\\u4e3b\\u660e\\u3002\"]"', '"[\"\\u4e1c\\u5cb3\\u5c01\\u5efb\\u5bb4\\u6d1b\\u4eac\\uff0c\\u897f\\u5889\\u901a\\u665a\\u4f1a\\u516c\\u537f\\u3002\", \"\\u697c\\u53f0\\u7edd\\u80dc\\u5b9c\\u6625\\u82d1\\uff0c\\u706f\\u706b\\u8fd8\\u540c\\u4e0d\\u591c\\u57ce\\u3002\", \"\\u6b63\\u89a9\\u4eba\\u95f4\\u671d\\u5e02\\u4e50\\uff0c\\u5ffd\\u95fb\\u5929\\u4e0a\\u7ba1\\u5f26\\u58f0\\u3002\", \"\\u917a\\u6765\\u4e07\\u821e\\u7fa4\\u81e3\\u9189\\uff0c\\u559c\\u6234\\u5343\\u5e74\\u5723\\u4e3b\\u660e\\u3002\"]"', '诗', 'shi', '', NULL, '廣達樓下夜侍酺宴應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8efe434-9077-4f89-bf28-488c63ad157e', '龍池樂章', '龙池乐章', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u897f\\u4eac\\u9cf3\\u90b8\\u8e8d\\u9f8d\\u6cc9\\uff0c\\u4f73\\u6c23\\u4f11\\u5149\\u93ae\\u5728\\u5929\\u3002\", \"\\u8ed2\\u540e\\u9727\\u5716\\u4eca\\u5df2\\u5f97\\uff0c\\u79e6\\u738b\\u6c34\\u5292\\u6614\\u5e38\\u50b3\\u3002\", \"\\u6069\\u9b5a\\u4e0d\\u5165\\u6606\\u660e\\u91e3\\uff0c\\u745e\\u9db4\\u9577\\u5982\\u592a\\u6db2\\u4ed9\\u3002\", \"\\u9858\\u4f8d\\u5de1\\u904a\\u540c\\u820a\\u91cc\\uff0c\\u66f4\\u805e\\u7c2b\\u9f13\\u6fdf\\u6a13\\u8239\\u3002\"]"', '"[\"\\u897f\\u4eac\\u51e4\\u90b8\\u8dc3\\u9f99\\u6cc9\\uff0c\\u4f73\\u6c14\\u4f11\\u5149\\u9547\\u5728\\u5929\\u3002\", \"\\u8f69\\u540e\\u96fe\\u56fe\\u4eca\\u5df2\\u5f97\\uff0c\\u79e6\\u738b\\u6c34\\u5292\\u6614\\u5e38\\u4f20\\u3002\", \"\\u6069\\u9c7c\\u4e0d\\u5165\\u6606\\u660e\\u9493\\uff0c\\u745e\\u9e64\\u957f\\u5982\\u592a\\u6db2\\u4ed9\\u3002\", \"\\u613f\\u4f8d\\u5de1\\u6e38\\u540c\\u65e7\\u91cc\\uff0c\\u66f4\\u95fb\\u7bab\\u9f13\\u6d4e\\u697c\\u8239\\u3002\"]"', '诗', 'shi', '', NULL, '龍池樂章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b30853-6c81-403a-a561-d2a06836882b', '扈從鄠杜間奉呈刑部尚書舅崔黃門馬常侍', '扈从鄠杜间奉呈刑部尚书舅崔黄门马常侍', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u7fe0\\u8f26\\u7d05\\u65d7\\u51fa\\u5e1d\\u4eac\\uff0c\\u9577\\u694a\\u9120\\u675c\\u6614\\u77e5\\u540d\\u3002\", \"\\u96f2\\u5c71\\u4e00\\u4e00\\u770b\\u7686\\u7f8e\\uff0c\\u7af9\\u6a39\\u856d\\u856d\\u756b\\u4e0d\\u6210\\u3002\", \"\\u7fbd\\u9a0e\\u5c07\\u904e\\u6301\\u8882\\u62c2\\uff0c\\u9999\\u8eca\\u6b32\\u5ea6\\u6372\\u7c3e\\u884c\\u3002\", \"\\u6f22\\u5bb6\\u66fe\\u8349\\u5de1\\u904a\\u8ce6\\uff0c\\u4f55\\u4f3c\\u4eca\\u4f86\\u61c9\\u8056\\u660e\\u3002\"]"', '"[\"\\u7fe0\\u8f87\\u7ea2\\u65d7\\u51fa\\u5e1d\\u4eac\\uff0c\\u957f\\u6768\\u9120\\u675c\\u6614\\u77e5\\u540d\\u3002\", \"\\u4e91\\u5c71\\u4e00\\u4e00\\u770b\\u7686\\u7f8e\\uff0c\\u7af9\\u6811\\u8427\\u8427\\u753b\\u4e0d\\u6210\\u3002\", \"\\u7fbd\\u9a91\\u5c06\\u8fc7\\u6301\\u8882\\u62c2\\uff0c\\u9999\\u8f66\\u6b32\\u5ea6\\u5377\\u5e18\\u884c\\u3002\", \"\\u6c49\\u5bb6\\u66fe\\u8349\\u5de1\\u6e38\\u8d4b\\uff0c\\u4f55\\u4f3c\\u4eca\\u6765\\u5e94\\u5723\\u660e\\u3002\"]"', '诗', 'shi', '', NULL, '扈從鄠杜間奉呈刑部尚書舅崔黃門馬常侍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b3c9272-1897-44f9-bd65-efa4d09f435b', '景龍觀送裴士曹', '景龙观送裴士曹', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6614\\u65e5\\u5617\\u805e\\u516c\\u4e3b\\u7b2c\\uff0c\\u4eca\\u6642\\u8b8a\\u4f5c\\u5217\\u4ed9\\u5bb6\\u3002\", \"\\u6c60\\u508d\\u5750\\u5ba2\\u7a7f\\u53e2\\u7be0\\uff0c\\u6a39\\u4e0b\\u904a\\u4eba\\u6383\\u843d\\u82b1\\u3002\", \"\\u96e8\\u96ea\\u9577\\u7591\\u5411\\u51fd\\u8c37\\uff0c\\u5c71\\u6cc9\\u76f4\\u4f3c\\u5230\\u6d41\\u6c99\\u3002\", \"\\u541b\\u9084\\u6d1b\\u9091\\u5206\\u660e\\u8a18\\uff0c\\u6b64\\u8655\\u540c\\u4f86\\u95b1\\u6b72\\u83ef\\u3002\"]"', '"[\"\\u6614\\u65e5\\u5c1d\\u95fb\\u516c\\u4e3b\\u7b2c\\uff0c\\u4eca\\u65f6\\u53d8\\u4f5c\\u5217\\u4ed9\\u5bb6\\u3002\", \"\\u6c60\\u508d\\u5750\\u5ba2\\u7a7f\\u4e1b\\u7b7f\\uff0c\\u6811\\u4e0b\\u6e38\\u4eba\\u626b\\u843d\\u82b1\\u3002\", \"\\u96e8\\u96ea\\u957f\\u7591\\u5411\\u51fd\\u8c37\\uff0c\\u5c71\\u6cc9\\u76f4\\u4f3c\\u5230\\u6d41\\u6c99\\u3002\", \"\\u541b\\u8fd8\\u6d1b\\u9091\\u5206\\u660e\\u8bb0\\uff0c\\u6b64\\u5904\\u540c\\u6765\\u9605\\u5c81\\u534e\\u3002\"]"', '诗', 'shi', '', NULL, '景龍觀送裴士曹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d73fbb46-ff55-4a4f-b437-5a4478a934ca', '春晚紫微省直寄內', '春晚紫微省直寄内', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u76f4\\u7701\\u6e05\\u83ef\\u63a5\\u5efa\\u7ae0\\uff0c\\u5411\\u4f86\\u7121\\u4e8b\\u65e5\\u7336\\u9577\\u3002\", \"\\u82b1\\u9593\\u71d5\\u5b50\\u68f2\\u9cf7\\u9d72\\uff0c\\u7af9\\u4e0b\\u9d77\\u96db\\u7e5e\\u9cf3\\u7687\\u3002\", \"\\u5167\\u53f2\\u901a\\u5bb5\\u627f\\u7d2b\\u8aa5\\uff0c\\u4e2d\\u4eba\\u843d\\u665a\\u611b\\u7d05\\u599d\\u3002\", \"\\u5225\\u96e2\\u4e0d\\u6163\\u7121\\u7aae\\u61b6\\uff0c\\u83ab\\u8aa4\\u537f\\u537f\\u5b78\\u592a\\u5e38\\u3002\"]"', '"[\"\\u76f4\\u7701\\u6e05\\u534e\\u63a5\\u5efa\\u7ae0\\uff0c\\u5411\\u6765\\u65e0\\u4e8b\\u65e5\\u72b9\\u957f\\u3002\", \"\\u82b1\\u95f4\\u71d5\\u5b50\\u6816\\ud86d\\udedb\\u9e4a\\uff0c\\u7af9\\u4e0b\\u9e53\\u96cf\\u7ed5\\u51e4\\u7687\\u3002\", \"\\u5185\\u53f2\\u901a\\u5bb5\\u627f\\u7d2b\\u8bf0\\uff0c\\u4e2d\\u4eba\\u843d\\u665a\\u7231\\u7ea2\\u5986\\u3002\", \"\\u522b\\u79bb\\u4e0d\\u60ef\\u65e0\\u7a77\\u5fc6\\uff0c\\u83ab\\u8bef\\u537f\\u537f\\u5b66\\u592a\\u5e38\\u3002\"]"', '诗', 'shi', '', NULL, '春晚紫微省直寄內 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53a7b4d1-3328-4002-b75e-29f49edae2c7', '贈彭州權別駕', '赠彭州权别驾', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u96d9\\u6d41\\u8108\\u8108\\u9326\\u57ce\\u958b\\uff0c\\u8ffd\\u991e\\u5e74\\u5e74\\u5f80\\u5fa9\\u5efb\\u3002\", \"\\u79ea\\u9053\\u6b4c\\u8b20\\u8fce\\u534a\\u523a\\uff0c\\u5f92\\u805e\\u79ae\\u6578\\u63d6\\u4e2d\\u53f0\\u3002\", \"\\u9ec3\\u9daf\\u6025\\u56c0\\u6625\\u98a8\\u76e1\\uff0c\\u6591\\u99ac\\u9577\\u5636\\u843d\\u666f\\u50ac\\u3002\", \"\\u83ab\\u6134\\u5206\\u98db\\u5c90\\u8def\\u5225\\uff0c\\u9084\\u7576\\u594f\\u6700\\u6396\\u57a3\\u4f86\\u3002\"]"', '"[\"\\u53cc\\u6d41\\u8109\\u8109\\u9526\\u57ce\\u5f00\\uff0c\\u8ffd\\u996f\\u5e74\\u5e74\\u5f80\\u590d\\u5efb\\u3002\", \"\\u79ea\\u9053\\u6b4c\\u8c23\\u8fce\\u534a\\u523a\\uff0c\\u5f92\\u95fb\\u793c\\u6570\\u63d6\\u4e2d\\u53f0\\u3002\", \"\\u9ec4\\u83ba\\u6025\\u556d\\u6625\\u98ce\\u5c3d\\uff0c\\u6591\\u9a6c\\u957f\\u5636\\u843d\\u666f\\u50ac\\u3002\", \"\\u83ab\\u6006\\u5206\\u98de\\u5c90\\u8def\\u522b\\uff0c\\u8fd8\\u5f53\\u594f\\u6700\\u6396\\u57a3\\u6765\\u3002\"]"', '诗', 'shi', '', NULL, '贈彭州權別駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22eb983d-591b-4403-96a4-0d47d8a8ae6a', '寒食宴于中舍別駕兄弟宅', '寒食宴于中舍别驾兄弟宅', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5b50\\u63a8\\u5c71\\u4e0a\\u6b4c\\u9f8d\\u7f77\\uff0c\\u5b9a\\u570b\\u9580\\u524d\\u7d50\\u99df\\u4f86\\u3002\", \"\\u59cb\\u89a9\\u5143\\u6606\\u93d8\\u7389\\u81f3\\uff0c\\u65cb\\u805e\\u5b63\\u5b50\\u4f69\\u5200\\u5efb\\u3002\", \"\\u6674\\u82b1\\u8655\\u8655\\u56e0\\u98a8\\u8d77\\uff0c\\u5fa1\\u67f3\\u689d\\u689d\\u5411\\u65e5\\u958b\\u3002\", \"\\u81ea\\u6709\\u9577\\u7b75\\u6b61\\u4e0d\\u6975\\uff0c\\u9084\\u5c07\\u7db5\\u670d\\u8a60\\u5357\\u9654\\u3002\"]"', '"[\"\\u5b50\\u63a8\\u5c71\\u4e0a\\u6b4c\\u9f99\\u7f62\\uff0c\\u5b9a\\u56fd\\u95e8\\u524d\\u7ed3\\u9a77\\u6765\\u3002\", \"\\u59cb\\u89a9\\u5143\\u6606\\u9535\\u7389\\u81f3\\uff0c\\u65cb\\u95fb\\u5b63\\u5b50\\u4f69\\u5200\\u5efb\\u3002\", \"\\u6674\\u82b1\\u5904\\u5904\\u56e0\\u98ce\\u8d77\\uff0c\\u5fa1\\u67f3\\u6761\\u6761\\u5411\\u65e5\\u5f00\\u3002\", \"\\u81ea\\u6709\\u957f\\u7b75\\u6b22\\u4e0d\\u6781\\uff0c\\u8fd8\\u5c06\\u5f69\\u670d\\u548f\\u5357\\u9654\\u3002\"]"', '诗', 'shi', '', NULL, '寒食宴于中舍別駕兄弟宅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcc1d431-4432-47c0-9e01-192be1ac7e07', '九月九日望蜀臺', '九月九日望蜀台', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u8700\\u738b\\u671b\\u8700\\u820a\\u81fa\\u524d\\uff0c\\u4e5d\\u65e5\\u5206\\u660e\\u898b\\u4e00\\u5ddd\\u3002\", \"\\u5317\\u6599\\u9109\\u95dc\\u65b9\\u81ea\\u6b64\\uff0c\\u5357\\u8fad\\u57ce\\u90ed\\u5fa9\\u4f9d\\u7136\\u3002\", \"\\u9752\\u677e\\u7e6b\\u99ac\\u6522\\u5dd6\\u7554\\uff0c\\u9ec3\\u83ca\\u7559\\u4eba\\u7c4d\\u9053\\u908a\\u3002\", \"\\u81ea\\u6614\\u767b\\u81e8\\u6e6e\\u6ec5\\u76e1\\uff0c\\u7368\\u805e\\u5fe0\\u5b5d\\u5169\\u80fd\\u50b3\\u3002\"]"', '"[\"\\u8700\\u738b\\u671b\\u8700\\u65e7\\u53f0\\u524d\\uff0c\\u4e5d\\u65e5\\u5206\\u660e\\u89c1\\u4e00\\u5ddd\\u3002\", \"\\u5317\\u6599\\u4e61\\u5173\\u65b9\\u81ea\\u6b64\\uff0c\\u5357\\u8f9e\\u57ce\\u90ed\\u590d\\u4f9d\\u7136\\u3002\", \"\\u9752\\u677e\\u7cfb\\u9a6c\\u6512\\u5ca9\\u7554\\uff0c\\u9ec4\\u83ca\\u7559\\u4eba\\u7c4d\\u9053\\u8fb9\\u3002\", \"\\u81ea\\u6614\\u767b\\u4e34\\u6e6e\\u706d\\u5c3d\\uff0c\\u72ec\\u95fb\\u5fe0\\u5b5d\\u4e24\\u80fd\\u4f20\\u3002\"]"', '诗', 'shi', '', NULL, '九月九日望蜀臺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faf2b068-c36d-455c-b6b9-2564b888dabc', '奉和晦日幸昆明池應制', '奉和晦日幸昆明池应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u708e\\u66c6\\u4e8b\\u908a\\u9672\\uff0c\\u6606\\u660e\\u59cb\\u947f\\u6c60\\u3002\", \"\\u8c6b\\u904a\\u5149\\u5f8c\\u8056\\uff0c\\u5f81\\u6230\\u7f77\\u524d\\u898f\\u3002\", \"\\u973d\\u8272\\u6e05\\u73cd\\u5b87\\uff0c\\u5e74\\u82b3\\u5165\\u9326\\u9642\\u3002\", \"\\u5fa1\\u676f\\u862d\\u85a6\\u8449\\uff0c\\u4ed9\\u4ed7\\u67f3\\u4ea4\\u679d\\u3002\", \"\\u4e8c\\u77f3\\u5206\\u6cb3\\u7009\\uff0c\\u96d9\\u73e0\\u4ee3\\u6708\\u79fb\\u3002\", \"\\u5fae\\u81e3\\u6bd4\\u7fd4\\u6cf3\\uff0c\\u6069\\u5ee3\\u81ea\\u7121\\u6daf\\u3002\"]"', '"[\"\\u708e\\u5386\\u4e8b\\u8fb9\\u9672\\uff0c\\u6606\\u660e\\u59cb\\u51ff\\u6c60\\u3002\", \"\\u8c6b\\u6e38\\u5149\\u540e\\u5723\\uff0c\\u5f81\\u6218\\u7f62\\u524d\\u89c4\\u3002\", \"\\u9701\\u8272\\u6e05\\u73cd\\u5b87\\uff0c\\u5e74\\u82b3\\u5165\\u9526\\u9642\\u3002\", \"\\u5fa1\\u676f\\u5170\\u8350\\u53f6\\uff0c\\u4ed9\\u4ed7\\u67f3\\u4ea4\\u679d\\u3002\", \"\\u4e8c\\u77f3\\u5206\\u6cb3\\u6cfb\\uff0c\\u53cc\\u73e0\\u4ee3\\u6708\\u79fb\\u3002\", \"\\u5fae\\u81e3\\u6bd4\\u7fd4\\u6cf3\\uff0c\\u6069\\u5e7f\\u81ea\\u65e0\\u6daf\\u3002\"]"', '诗', 'shi', '', NULL, '奉和晦日幸昆明池應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb13e75-afcd-4f2a-b32b-882fe049f6a3', '奉和聖製幸禮部尚書竇希玠宅應制', '奉和圣制幸礼部尚书窦希玠宅应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5c1a\\u66f8\\u5217\\u4faf\\u7b2c\\uff0c\\u5916\\u621a\\u8fd1\\u81e3\\u5bb6\\u3002\", \"\\u98db\\u68df\\u81e8\\u9752\\u7dba\\uff0c\\u8ff4\\u8f3f\\u8f49\\u7fe0\\u83ef\\u3002\", \"\\u65e5\\u4ea4\\u7576\\u6236\\u6a39\\uff0c\\u6cc9\\u6f3e\\u6eff\\u6c60\\u82b1\\u3002\", \"\\u5713\\u9802\\u5716\\u5d69\\u77f3\\uff0c\\u65b9\\u6d41\\u64c1\\u9b4f\\u6c99\\u3002\", \"\\u8c6b\\u904a\\u4eca\\u807d\\u5c65\\uff0c\\u4f8d\\u5f9e\\u6614\\u9cf4\\u7b33\\u3002\", \"\\u81ea\\u6709\\u5929\\u6587\\u964d\\uff0c\\u7121\\u52de\\u8a2a\\u6d77\\u69ce\\u3002\"]"', '"[\"\\u5c1a\\u4e66\\u5217\\u4faf\\u7b2c\\uff0c\\u5916\\u621a\\u8fd1\\u81e3\\u5bb6\\u3002\", \"\\u98de\\u680b\\u4e34\\u9752\\u7eee\\uff0c\\u56de\\u8206\\u8f6c\\u7fe0\\u534e\\u3002\", \"\\u65e5\\u4ea4\\u5f53\\u6237\\u6811\\uff0c\\u6cc9\\u6f3e\\u6ee1\\u6c60\\u82b1\\u3002\", \"\\u5706\\u9876\\u56fe\\u5d69\\u77f3\\uff0c\\u65b9\\u6d41\\u62e5\\u9b4f\\u6c99\\u3002\", \"\\u8c6b\\u6e38\\u4eca\\u542c\\u5c65\\uff0c\\u4f8d\\u4ece\\u6614\\u9e23\\u7b33\\u3002\", \"\\u81ea\\u6709\\u5929\\u6587\\u964d\\uff0c\\u65e0\\u52b3\\u8bbf\\u6d77\\u69ce\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製幸禮部尚書竇希玠宅應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('522bf8ea-f6c7-4618-af8c-59dc63773fb3', '奉和幸韋嗣立山莊應制', '奉和幸韦嗣立山庄应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6450\\u91d1\\u5bd2\\u91ce\\u973d\\uff0c\\u6b65\\u7389\\u66c9\\u5c71\\u5e7d\\u3002\", \"\\u5e1d\\u5e44\\u671f\\u677e\\u5b50\\uff0c\\u81e3\\u5eec\\u8a2a\\u845b\\u4faf\\u3002\", \"\\u767e\\u5de5\\u5fb5\\u5f80\\u5922\\uff0c\\u4e03\\u8056\\u6248\\u4f86\\u904a\\u3002\", \"\\u6597\\u67c4\\u4e58\\u6642\\u8f49\\uff0c\\u81fa\\u968e\\u6367\\u65e5\\u7559\\u3002\", \"\\u6a39\\u91cd\\u5dd6\\u7c5f\\u5408\\uff0c\\u6cc9\\u8ff8\\u6c34\\u5149\\u6d6e\\u3002\", \"\\u77f3\\u5f91\\u55a7\\u671d\\u5c65\\uff0c\\u749c\\u6eaa\\u64c1\\u91e3\\u821f\\u3002\", \"\\u6069\\u5982\\u72af\\u661f\\u591c\\uff0c\\u6b61\\u64ec\\u6fdf\\u6cb3\\u79cb\\u3002\", \"\\u4e0d\\u5b78\\u582f\\u5e74\\u96b1\\uff0c\\u7a7a\\u4ee4\\u50b2\\u8a31\\u7531\\u3002\"]"', '"[\"\\ud86a\\udf62\\u91d1\\u5bd2\\u91ce\\u9701\\uff0c\\u6b65\\u7389\\u6653\\u5c71\\u5e7d\\u3002\", \"\\u5e1d\\u5e44\\u671f\\u677e\\u5b50\\uff0c\\u81e3\\u5e90\\u8bbf\\u845b\\u4faf\\u3002\", \"\\u767e\\u5de5\\u5f81\\u5f80\\u68a6\\uff0c\\u4e03\\u5723\\u6248\\u6765\\u6e38\\u3002\", \"\\u6597\\u67c4\\u4e58\\u65f6\\u8f6c\\uff0c\\u53f0\\u9636\\u6367\\u65e5\\u7559\\u3002\", \"\\u6811\\u91cd\\u5ca9\\u7c41\\u5408\\uff0c\\u6cc9\\u8ff8\\u6c34\\u5149\\u6d6e\\u3002\", \"\\u77f3\\u5f84\\u55a7\\u671d\\u5c65\\uff0c\\u749c\\u6eaa\\u62e5\\u9493\\u821f\\u3002\", \"\\u6069\\u5982\\u72af\\u661f\\u591c\\uff0c\\u6b22\\u62df\\u6d4e\\u6cb3\\u79cb\\u3002\", \"\\u4e0d\\u5b66\\u5c27\\u5e74\\u9690\\uff0c\\u7a7a\\u4ee4\\u50b2\\u8bb8\\u7531\\u3002\"]"', '诗', 'shi', '', NULL, '奉和幸韋嗣立山莊應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9f60f36-ca4c-42d2-8e6d-732c27498f66', '奉和聖製送張說上集賢學士賜宴得茲字', '奉和圣制送张说上集贤学士赐宴得兹字', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u8085\\u8085\\u91d1\\u6bbf\\u88cf\\uff0c\\u62db\\u8ce2\\u56fa\\u5728\\u8332\\u3002\", \"\\u93d8\\u93d8\\u77f3\\u6e20\\u5167\\uff0c\\u5e8f\\u62dc\\u4ea6\\u540c\\u6642\\u3002\", \"\\u5bb4\\u932b\\u6b61\\u8ac7\\u9053\\uff0c\\u6587\\u6210\\u8cb4\\u8aaa\\u8a69\\u3002\", \"\\u7528\\u5112\\u4eca\\u4f5c\\u76f8\\uff0c\\u6566\\u5b78\\u820a\\u7232\\u5e2b\\u3002\", \"\\u4e0b\\u969b\\u5929\\u5149\\u8fd1\\uff0c\\u4e2d\\u4f86\\u5e1d\\u6e25\\u6ecb\\u3002\", \"\\u570b\\u671d\\u826f\\u53f2\\u8f09\\uff0c\\u80fd\\u4e8b\\u65e5\\u8ad6\\u601d\\u3002\"]"', '"[\"\\u8083\\u8083\\u91d1\\u6bbf\\u91cc\\uff0c\\u62db\\u8d24\\u56fa\\u5728\\u5179\\u3002\", \"\\u9535\\u9535\\u77f3\\u6e20\\u5185\\uff0c\\u5e8f\\u62dc\\u4ea6\\u540c\\u65f6\\u3002\", \"\\u5bb4\\u9521\\u6b22\\u8c08\\u9053\\uff0c\\u6587\\u6210\\u8d35\\u8bf4\\u8bd7\\u3002\", \"\\u7528\\u5112\\u4eca\\u4f5c\\u76f8\\uff0c\\u6566\\u5b66\\u65e7\\u4e3a\\u5e08\\u3002\", \"\\u4e0b\\u9645\\u5929\\u5149\\u8fd1\\uff0c\\u4e2d\\u6765\\u5e1d\\u6e25\\u6ecb\\u3002\", \"\\u56fd\\u671d\\u826f\\u53f2\\u8f7d\\uff0c\\u80fd\\u4e8b\\u65e5\\u8bba\\u601d\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴得茲字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd5f48c4-f9ff-46f3-a608-00062add51ae', '奉和聖製途經華嶽應制', '奉和圣制途经华岳应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u671d\\u671b\\u84ee\\u83ef\\u5dbd\\uff0c\\u795e\\u5fc3\\u5c31\\u65e5\\u4f86\\u3002\", \"\\u6674\\u89c0\\u4e94\\u5343\\u4ede\\uff0c\\u4ed9\\u638c\\u62d3\\u5c71\\u958b\\u3002\", \"\\u53d7\\u547d\\u91d1\\u7b26\\u53f6\\uff0c\\u904e\\u7965\\u7389\\u745e\\u966a\\u3002\", \"\\u9727\\u62ab\\u4e58\\u9e7f\\u898b\\uff0c\\u96f2\\u8d77\\u99ad\\u9f8d\\u5efb\\u3002\", \"\\u5043\\u6a39\\u679d\\u5c01\\u96ea\\uff0c\\u6b98\\u7891\\u77f3\\u5190\\u82d4\\u3002\", \"\\u8056\\u7687\\u60df\\u9053\\u5951\\uff0c\\u6587\\u5b57\\u52d2\\u5dd6\\u9688\\u3002\"]"', '"[\"\\u671d\\u671b\\u83b2\\u534e\\u5cb3\\uff0c\\u795e\\u5fc3\\u5c31\\u65e5\\u6765\\u3002\", \"\\u6674\\u89c2\\u4e94\\u5343\\u4ede\\uff0c\\u4ed9\\u638c\\u62d3\\u5c71\\u5f00\\u3002\", \"\\u53d7\\u547d\\u91d1\\u7b26\\u53f6\\uff0c\\u8fc7\\u7965\\u7389\\u745e\\u966a\\u3002\", \"\\u96fe\\u62ab\\u4e58\\u9e7f\\u89c1\\uff0c\\u4e91\\u8d77\\u9a6d\\u9f99\\u5efb\\u3002\", \"\\u5043\\u6811\\u679d\\u5c01\\u96ea\\uff0c\\u6b8b\\u7891\\u77f3\\u5190\\u82d4\\u3002\", \"\\u5723\\u7687\\u60df\\u9053\\u5951\\uff0c\\u6587\\u5b57\\u52d2\\u5ca9\\u9688\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製途經華嶽應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46170aeb-d938-4b8a-9702-f27efc551ebf', '奉和聖製經河上公廟應制', '奉和圣制经河上公庙应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6cb3\\u6d41\\u7121\\u65e5\\u591c\\uff0c\\u6cb3\\u4e0a\\u6709\\u795e\\u4ed9\\u3002\", \"\\u8f26\\u8def\\u66fe\\u7d93\\u6b64\\uff0c\\u58c7\\u5834\\u5373\\u5b9b\\u7136\\u3002\", \"\\u4e0b\\u7591\\u6210\\u6d1e\\u7a74\\uff0c\\u9ad8\\u82e5\\u5728\\u7a7a\\u7159\\u3002\", \"\\u5584\\u7269\\u907a\\u65b9\\u5916\\uff0c\\u548c\\u5149\\u7e5e\\u9053\\u908a\\u3002\", \"\\u4e8b\\u56e0\\u5468\\u53f2\\u5f97\\uff0c\\u8a00\\u8207\\u6f22\\u738b\\u50b3\\u3002\", \"\\u559c\\u5c6c\\u81ba\\u671f\\u8056\\uff0c\\u90a6\\u5bb6\\u696d\\u53c8\\u7384\\u3002\"]"', '"[\"\\u6cb3\\u6d41\\u65e0\\u65e5\\u591c\\uff0c\\u6cb3\\u4e0a\\u6709\\u795e\\u4ed9\\u3002\", \"\\u8f87\\u8def\\u66fe\\u7ecf\\u6b64\\uff0c\\u575b\\u573a\\u5373\\u5b9b\\u7136\\u3002\", \"\\u4e0b\\u7591\\u6210\\u6d1e\\u7a74\\uff0c\\u9ad8\\u82e5\\u5728\\u7a7a\\u70df\\u3002\", \"\\u5584\\u7269\\u9057\\u65b9\\u5916\\uff0c\\u548c\\u5149\\u7ed5\\u9053\\u8fb9\\u3002\", \"\\u4e8b\\u56e0\\u5468\\u53f2\\u5f97\\uff0c\\u8a00\\u4e0e\\u6c49\\u738b\\u4f20\\u3002\", \"\\u559c\\u5c5e\\u81ba\\u671f\\u5723\\uff0c\\u90a6\\u5bb6\\u4e1a\\u53c8\\u7384\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製經河上公廟應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26ec06db-c688-4ab6-b7bc-f9b83d0bad97', '奉和聖製答張說出雀鼠谷', '奉和圣制答张说出雀鼠谷', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u96e8\\u65bd\\u5de1\\u65b9\\u7f77\\uff0c\\u96f2\\u5f9e\\u8a13\\u4fd7\\u5efb\\u3002\", \"\\u5bc6\\u9014\\u6c7e\\u6c34\\u885e\\uff0c\\u6e05\\u8e55\\u6649\\u90ca\\u966a\\u3002\", \"\\u5bd2\\u8457\\u5c71\\u908a\\u76e1\\uff0c\\u6625\\u7576\\u65e5\\u4e0b\\u4f86\\u3002\", \"\\u5fa1\\u7960\\u7384\\u9ce5\\u61c9\\uff0c\\u4ed9\\u4ed7\\u7da0\\u694a\\u958b\\u3002\", \"\\u4f5c\\u980c\\u97f3\\u50b3\\u96c5\\uff0c\\u89c0\\u6587\\u8272\\u52d5\\u53f0\\u3002\", \"\\u66f4\\u77e5\\u897f\\u5411\\u6a02\\uff0c\\u5bb8\\u85fb\\u5354\\u9e7d\\u6885\\u3002\"]"', '"[\"\\u96e8\\u65bd\\u5de1\\u65b9\\u7f62\\uff0c\\u4e91\\u4ece\\u8bad\\u4fd7\\u5efb\\u3002\", \"\\u5bc6\\u9014\\u6c7e\\u6c34\\u885e\\uff0c\\u6e05\\u8df8\\u664b\\u90ca\\u966a\\u3002\", \"\\u5bd2\\u8457\\u5c71\\u8fb9\\u5c3d\\uff0c\\u6625\\u5f53\\u65e5\\u4e0b\\u6765\\u3002\", \"\\u5fa1\\u7960\\u7384\\u9e1f\\u5e94\\uff0c\\u4ed9\\u4ed7\\u7eff\\u6768\\u5f00\\u3002\", \"\\u4f5c\\u9882\\u97f3\\u4f20\\u96c5\\uff0c\\u89c2\\u6587\\u8272\\u52a8\\u53f0\\u3002\", \"\\u66f4\\u77e5\\u897f\\u5411\\u4e50\\uff0c\\u5bb8\\u85fb\\u534f\\u76d0\\u6885\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製答張說出雀鼠谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff1cc006-2214-40ee-90e8-24604113b2e0', '奉和恩賜樂遊園宴應制', '奉和恩赐乐游园宴应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6a02\\u904a\\u5149\\u5730\\u9078\\uff0c\\u917a\\u98f2\\u6176\\u5929\\u5f9e\\u3002\", \"\\u5ea7\\u5bc6\\u5343\\u5b98\\u76db\\uff0c\\u5834\\u958b\\u767e\\u6232\\u5bb9\\u3002\", \"\\u7da0\\u584d\\u969b\\u5c71\\u76e1\\uff0c\\u7df9\\u5e55\\u501a\\u96f2\\u91cd\\u3002\", \"\\u4e0b\\u4e0a\\u82b1\\u9f4a\\u767c\\uff0c\\u5468\\u5efb\\u67f3\\u904d\\u6fc3\\u3002\", \"\\u596a\\u6674\\u7d1b\\u5292\\u5c65\\uff0c\\u55a7\\u807d\\u96dc\\u6b4c\\u9418\\u3002\", \"\\u65e5\\u665a\\u929c\\u6069\\u6563\\uff0c\\u582f\\u4eba\\u5002\\u53ef\\u5c01\\u3002\"]"', '"[\"\\u4e50\\u6e38\\u5149\\u5730\\u9009\\uff0c\\u917a\\u996e\\u5e86\\u5929\\u4ece\\u3002\", \"\\u5ea7\\u5bc6\\u5343\\u5b98\\u76db\\uff0c\\u573a\\u5f00\\u767e\\u620f\\u5bb9\\u3002\", \"\\u7eff\\u584d\\u9645\\u5c71\\u5c3d\\uff0c\\u7f07\\u5e55\\u501a\\u4e91\\u91cd\\u3002\", \"\\u4e0b\\u4e0a\\u82b1\\u9f50\\u53d1\\uff0c\\u5468\\u5efb\\u67f3\\u904d\\u6d53\\u3002\", \"\\u593a\\u6674\\u7eb7\\u5292\\u5c65\\uff0c\\u55a7\\u542c\\u6742\\u6b4c\\u949f\\u3002\", \"\\u65e5\\u665a\\u8854\\u6069\\u6563\\uff0c\\u5c27\\u4eba\\u5002\\u53ef\\u5c01\\u3002\"]"', '诗', 'shi', '', NULL, '奉和恩賜樂遊園宴應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d318ccf2-93b8-4d54-aa08-398cdd79255f', '恩制尚書省僚宴昆明池同用堯字', '恩制尚书省僚宴昆明池同用尧字', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u9732\\u6e25\\u7051\\u96f2\\u9704\\uff0c\\u5929\\u5b98\\u6b21\\u6597\\u6753\\u3002\", \"\\u6606\\u660e\\u56db\\u5341\\u91cc\\uff0c\\u7a7a\\u6c34\\u6975\\u6674\\u671d\\u3002\", \"\\u96c1\\u4f3c\\u929c\\u7d05\\u8449\\uff0c\\u9be8\\u7591\\u5674\\u6d77\\u6f6e\\u3002\", \"\\u7fe0\\u5c71\\u4f86\\u5fb9\\u5e95\\uff0c\\u767d\\u65e5\\u53bb\\u5efb\\u6a19\\u3002\", \"\\u6cf3\\u5ee3\\u6f01\\u6748\\u6ea2\\uff0c\\u6d6e\\u6df1\\u5993\\u822b\\u6416\\u3002\", \"\\u98fd\\u6069\\u7686\\u9189\\u6b62\\uff0c\\u5408\\u821e\\u5171\\u6b4c\\u582f\\u3002\"]"', '"[\"\\u9732\\u6e25\\u6d12\\u4e91\\u9704\\uff0c\\u5929\\u5b98\\u6b21\\u6597\\u6753\\u3002\", \"\\u6606\\u660e\\u56db\\u5341\\u91cc\\uff0c\\u7a7a\\u6c34\\u6781\\u6674\\u671d\\u3002\", \"\\u96c1\\u4f3c\\u8854\\u7ea2\\u53f6\\uff0c\\u9cb8\\u7591\\u55b7\\u6d77\\u6f6e\\u3002\", \"\\u7fe0\\u5c71\\u6765\\u5f7b\\u5e95\\uff0c\\u767d\\u65e5\\u53bb\\u5efb\\u6807\\u3002\", \"\\u6cf3\\u5e7f\\u6e14\\u6748\\u6ea2\\uff0c\\u6d6e\\u6df1\\u5993\\u822b\\u6447\\u3002\", \"\\u9971\\u6069\\u7686\\u9189\\u6b62\\uff0c\\u5408\\u821e\\u5171\\u6b4c\\u5c27\\u3002\"]"', '诗', 'shi', '', NULL, '恩制尚書省僚宴昆明池同用堯字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('101c2839-0938-4a8c-8cfb-ccb7395ccf8c', '題杜工部墳', '题杜工部坟', 32928470-9fa1-40a4-b62d-b86cc4225b76, '唐', '"[\"\\u4f55\\u4eba\\u947f\\u958b\\u6df7\\u6c8c\\u6bbc\\uff0c\\u4e8c\\u6c23\\u7531\\u4f86\\u6709\\u6e05\\u6fc1\\u3002\", \"\\u5b55\\u5176\\u6e05\\u8005\\u7232\\u8056\\u8ce2\\uff0c\\u937e\\u5176\\u6fc1\\u8005\\u6210\\u611a\\u6a38\\u3002\", \"\\u82f1\\u8c6a\\u96d6\\u6c92\\u540d\\u7336\\u5609\\uff0c\\u4e0d\\u8096\\u865b\\u6b7b\\u84ec\\u9ebb\\u3002\", \"\\u69ae\\u83ef\\u4e00\\u65e6\\u4e16\\u4fd7\\u773c\\uff0c\\u5fe0\\u5b5d\\u842c\\u53e4\\u8ce2\\u4eba\\u82bd\\u3002\", \"\\u6709\\u5510\\u6587\\u7269\\u76db\\u5fa9\\u5168\\uff0c\\u540d\\u66f8\\u53f2\\u518a\\u4ff1\\u624d\\u8ce2\\u3002\", \"\\u4e2d\\u9593\\u8a69\\u7b46\\u8ab0\\u6e05\\u65b0\\uff1f\\u5c48\\u6307\\u90fd\\u7121\\u56db\\u4e94\\u4eba\\u3002\", \"\\u7368\\u6709\\u5de5\\u90e8\\u7a31\\u5168\\u7f8e\\uff0c\\u7576\\u65e5\\u8a69\\u4eba\\u7121\\u64ec\\u502b\\u3002\", \"\\u7b46\\u8ffd\\u6e05\\u98a8\\u6d17\\u4fd7\\u8033\\uff0c\\u5fc3\\u596a\\u9020\\u5316\\u56de\\u967d\\u6625\\u3002\", \"\\u5929\\u5149\\u6674\\u5c04\\u6d1e\\u5ead\\u79cb\\uff0c\\u5bd2\\u7389\\u842c\\u9803\\u6e05\\u5149\\u6d41\\u3002\", \"\\u6211\\u5e38\\u611b\\u6155\\u5982\\u9951\\u6e34\\uff0c\\u4e0d\\u898b\\u5176\\u9762\\u751f\\u9591\\u6101\\u3002\", \"\\u4eca\\u6625\\u5076\\u5ba2\\u8012\\u967d\\u8def\\uff0c\\u60bd\\u6158\\u53bb\\u5c0b\\u6c5f\\u4e0a\\u5893\\u3002\", \"\\u53ec\\u670b\\u7279\\u5730\\u8e0f\\u7159\\u9727\\uff0c\\u8def\\u5165\\u6eaa\\u6751\\u6578\\u767e\\u6b65\\u3002\", \"\\u62db\\u624b\\u501f\\u554f\\u9a0e\\u725b\\u5152\\uff0c\\u7267\\u5152\\u6307\\u6211\\u7960\\u5802\\u8def\\u3002\", \"\\u5165\\u9580\\u53e4\\u5c4b\\u4e09\\u56db\\u9593\\uff0c\\u8349\\u8305\\u7de3\\u780c\\u751f\\u7121\\u6578\\u3002\", \"\\u5bd2\\u7af9\\u73ca\\u73ca\\u6416\\u665a\\u98a8\\uff0c\\u91ce\\u8513\\u5c64\\u5c64\\u7e8f\\u5ead\\u6236\\u3002\", \"\\u5347\\u5802\\u518d\\u62dc\\u5fc3\\u60fb\\u7136\\uff0c\\u5fc3\\u6b32\\u8654\\u5553\\u4e0d\\u6210\\u8a9e\\u3002\", \"\\u4e00\\u5806\\u7a7a\\u571f\\u7159\\u856a\\u88cf\\uff0c\\u865b\\u4f7f\\u8a69\\u4eba\\u6b4e\\u60b2\\u8d77\\u3002\", \"\\u6028\\u8072\\u5343\\u53e4\\u5bc4\\u897f\\u98a8\\uff0c\\u5bd2\\u9aa8\\u4e00\\u591c\\u6c89\\u79cb\\u6c34\\u3002\", \"\\u6b78\\u6642\\u8655\\u8655\\u591a\\u767d\\u9152\\uff0c\\u751f\\u8089\\u5982\\u4eca\\u5bb6\\u5bb6\\u6709\\u3002\", \"\\u98f2\\u9152\\u98df\\u8089\\u4eca\\u5982\\u6b64\\uff0c\\u4f55\\u6545\\u5e38\\u4eba\\u7121\\u98fd\\u6b7b\\uff1f\", \"\\u5b50\\u7f8e\\u6b78\\u65e5\\u7a31\\u624d\\u8ce2\\uff0c\\u8076\\u4faf\\u898b\\u5f85\\u8aa0\\u975e\\u559c\\u3002\", \"\\u6d0e\\u4e4e\\u8056\\u610f\\u518d\\u641c\\u6c42\\uff0c\\u59e6\\u81e3\\u4ee5\\u6b64\\u6b3a\\u5929\\u5b50\\u3002\", \"\\u6349\\u6708\\u8d70\\u5165\\u5343\\u4e08\\u6ce2\\uff0c\\u5fe0\\u8aeb\\u4fbf\\u6c89\\u6c69\\u7f85\\u5e95\\u3002\", \"\\u56fa\\u77e5\\u5929\\u610f\\u6709\\u6240\\u5b58\\uff0c\\u4e09\\u8ce2\\u6240\\u6b78\\u540c\\u4e00\\u6c34\\u3002\", \"\\u904e\\u5ba2\\u7559\\u8a69\\u5343\\u767e\\u4eba\\uff0c\\u4f73\\u8a5e\\u7e61\\u53e5\\u865b\\u76f8\\u7f8e\\u3002\", \"\\u58b3\\u7a7a\\u98eb\\u6b7b\\u5df2\\u50b3\\u805e\\uff0c\\u5343\\u53e4\\u919c\\u8072\\u7adf\\u8ab0\\u6d17\\uff1f\", \"\\u660e\\u6642\\u597d\\u53e4\\u75be\\u60e1\\u4eba\\uff0c\\u61c9\\u4ee5\\u6211\\u610f\\u77e5\\u7d42\\u59cb\\u3002\", \"\\uff08\\u8521\\u5922\\u5f3c\\u300a\\u96c6\\u6ce8\\u8349\\u5802\\u675c\\u5de5\\u90e8\\u8a69\\u5916\\u96c6\\u916c\\u5531\\u9644\\u9304\\u300b\\u5f15\\uff09\\uff08\\u30161\\u3017\\u8521\\u5922\\u5f3c\\u8dcb\\u4e91\\uff1a\\u300c\\u6b64\\u9000\\u4e4b\\u300a\\u984c\\u675c\\u5de5\\u90e8\\u58b3\\u300b\\uff0c\\u60df\\u898b\\u65bc\\u5289\\u65a7\\u300a\\u646d\\u907a\\u5c0f\\u8aaa\\u300b\\uff0c\\u97d3\\u660c\\u9ece\\u6b63\\u96c6\\u7121\\u4e4b\\uff0c\\u4f3c\\u975e\\u9000\\u4e4b\\u6240\\u4f5c\\u3002\", \"\\u7136\\u5927\\u66c6\\u3001\\u5143\\u548c\\uff0c\\u6642\\u4e4b\\u76f8\\u53bb\\u7336\\u672a\\u7232\\u9060\\uff0c\\u4e0d\\u6b78\\u8207\\u672c\\u96c6\\u62b5\\u727e\\u82e5\\u662f\\u3002\", \"\\u4e43\\u5f8c\\u4e4b\\u597d\\u4e8b\\u4fd7\\u4f11\\u5112\\u8a17\\u800c\\u7232\\u4e4b\\uff0c\\u4ee5\\u539a\\u8aa3\\u9000\\u4e4b\\uff0c\\u6c7a\\u975e\\u9000\\u4e4b\\u6240\\u4f5c\\u4e5f\\u7744\\u77e3\\u3002\", \"\\u5922\\u5f3c\\u4eca\\u8b3e\\u9304\\u65bc\\u6b64\\uff0c\\u4ee5\\u5099\\u5f8c\\u4eba\\u89c0\\u89bd\\u4e5f\\u3002\", \"\\u300d\\uff09\\u3002\"]"', '"[\"\\u4f55\\u4eba\\u51ff\\u5f00\\u6df7\\u6c8c\\u58f3\\uff0c\\u4e8c\\u6c14\\u7531\\u6765\\u6709\\u6e05\\u6d4a\\u3002\", \"\\u5b55\\u5176\\u6e05\\u8005\\u4e3a\\u5723\\u8d24\\uff0c\\u949f\\u5176\\u6d4a\\u8005\\u6210\\u611a\\u6734\\u3002\", \"\\u82f1\\u8c6a\\u867d\\u6ca1\\u540d\\u72b9\\u5609\\uff0c\\u4e0d\\u8096\\u865a\\u6b7b\\u84ec\\u9ebb\\u3002\", \"\\u8363\\u534e\\u4e00\\u65e6\\u4e16\\u4fd7\\u773c\\uff0c\\u5fe0\\u5b5d\\u4e07\\u53e4\\u8d24\\u4eba\\u82bd\\u3002\", \"\\u6709\\u5510\\u6587\\u7269\\u76db\\u590d\\u5168\\uff0c\\u540d\\u4e66\\u53f2\\u518c\\u4ff1\\u624d\\u8d24\\u3002\", \"\\u4e2d\\u95f4\\u8bd7\\u7b14\\u8c01\\u6e05\\u65b0\\uff1f\\u5c48\\u6307\\u90fd\\u65e0\\u56db\\u4e94\\u4eba\\u3002\", \"\\u72ec\\u6709\\u5de5\\u90e8\\u79f0\\u5168\\u7f8e\\uff0c\\u5f53\\u65e5\\u8bd7\\u4eba\\u65e0\\u62df\\u4f26\\u3002\", \"\\u7b14\\u8ffd\\u6e05\\u98ce\\u6d17\\u4fd7\\u8033\\uff0c\\u5fc3\\u593a\\u9020\\u5316\\u56de\\u9633\\u6625\\u3002\", \"\\u5929\\u5149\\u6674\\u5c04\\u6d1e\\u5ead\\u79cb\\uff0c\\u5bd2\\u7389\\u4e07\\u9877\\u6e05\\u5149\\u6d41\\u3002\", \"\\u6211\\u5e38\\u7231\\u6155\\u5982\\u9965\\u6e34\\uff0c\\u4e0d\\u89c1\\u5176\\u9762\\u751f\\u95f2\\u6101\\u3002\", \"\\u4eca\\u6625\\u5076\\u5ba2\\u8012\\u9633\\u8def\\uff0c\\u51c4\\u60e8\\u53bb\\u5bfb\\u6c5f\\u4e0a\\u5893\\u3002\", \"\\u53ec\\u670b\\u7279\\u5730\\u8e0f\\u70df\\u96fe\\uff0c\\u8def\\u5165\\u6eaa\\u6751\\u6570\\u767e\\u6b65\\u3002\", \"\\u62db\\u624b\\u501f\\u95ee\\u9a91\\u725b\\u513f\\uff0c\\u7267\\u513f\\u6307\\u6211\\u7960\\u5802\\u8def\\u3002\", \"\\u5165\\u95e8\\u53e4\\u5c4b\\u4e09\\u56db\\u95f4\\uff0c\\u8349\\u8305\\u7f18\\u780c\\u751f\\u65e0\\u6570\\u3002\", \"\\u5bd2\\u7af9\\u73ca\\u73ca\\u6447\\u665a\\u98ce\\uff0c\\u91ce\\u8513\\u5c42\\u5c42\\u7f20\\u5ead\\u6237\\u3002\", \"\\u5347\\u5802\\u518d\\u62dc\\u5fc3\\u607b\\u7136\\uff0c\\u5fc3\\u6b32\\u8654\\u542f\\u4e0d\\u6210\\u8bed\\u3002\", \"\\u4e00\\u5806\\u7a7a\\u571f\\u70df\\u829c\\u91cc\\uff0c\\u865a\\u4f7f\\u8bd7\\u4eba\\u53f9\\u60b2\\u8d77\\u3002\", \"\\u6028\\u58f0\\u5343\\u53e4\\u5bc4\\u897f\\u98ce\\uff0c\\u5bd2\\u9aa8\\u4e00\\u591c\\u6c89\\u79cb\\u6c34\\u3002\", \"\\u5f52\\u65f6\\u5904\\u5904\\u591a\\u767d\\u9152\\uff0c\\u751f\\u8089\\u5982\\u4eca\\u5bb6\\u5bb6\\u6709\\u3002\", \"\\u996e\\u9152\\u98df\\u8089\\u4eca\\u5982\\u6b64\\uff0c\\u4f55\\u6545\\u5e38\\u4eba\\u65e0\\u9971\\u6b7b\\uff1f\", \"\\u5b50\\u7f8e\\u5f52\\u65e5\\u79f0\\u624d\\u8d24\\uff0c\\u8042\\u4faf\\u89c1\\u5f85\\u8bda\\u975e\\u559c\\u3002\", \"\\u6d0e\\u4e4e\\u5723\\u610f\\u518d\\u641c\\u6c42\\uff0c\\u5978\\u81e3\\u4ee5\\u6b64\\u6b3a\\u5929\\u5b50\\u3002\", \"\\u6349\\u6708\\u8d70\\u5165\\u5343\\u4e08\\u6ce2\\uff0c\\u5fe0\\u8c0f\\u4fbf\\u6c89\\u6c69\\u7f57\\u5e95\\u3002\", \"\\u56fa\\u77e5\\u5929\\u610f\\u6709\\u6240\\u5b58\\uff0c\\u4e09\\u8d24\\u6240\\u5f52\\u540c\\u4e00\\u6c34\\u3002\", \"\\u8fc7\\u5ba2\\u7559\\u8bd7\\u5343\\u767e\\u4eba\\uff0c\\u4f73\\u8bcd\\u7ee3\\u53e5\\u865a\\u76f8\\u7f8e\\u3002\", \"\\u575f\\u7a7a\\u996b\\u6b7b\\u5df2\\u4f20\\u95fb\\uff0c\\u5343\\u53e4\\u4e11\\u58f0\\u7adf\\u8c01\\u6d17\\uff1f\", \"\\u660e\\u65f6\\u597d\\u53e4\\u75be\\u6076\\u4eba\\uff0c\\u5e94\\u4ee5\\u6211\\u610f\\u77e5\\u7ec8\\u59cb\\u3002\", \"\\uff08\\u8521\\u68a6\\u5f3c\\u300a\\u96c6\\u6ce8\\u8349\\u5802\\u675c\\u5de5\\u90e8\\u8bd7\\u5916\\u96c6\\u916c\\u5531\\u9644\\u5f55\\u300b\\u5f15\\uff09\\uff08\\u30161\\u3017\\u8521\\u68a6\\u5f3c\\u8dcb\\u4e91\\uff1a\\u300c\\u6b64\\u9000\\u4e4b\\u300a\\u9898\\u675c\\u5de5\\u90e8\\u575f\\u300b\\uff0c\\u60df\\u89c1\\u4e8e\\u5218\\u65a7\\u300a\\u646d\\u9057\\u5c0f\\u8bf4\\u300b\\uff0c\\u97e9\\u660c\\u9ece\\u6b63\\u96c6\\u65e0\\u4e4b\\uff0c\\u4f3c\\u975e\\u9000\\u4e4b\\u6240\\u4f5c\\u3002\", \"\\u7136\\u5927\\u5386\\u3001\\u5143\\u548c\\uff0c\\u65f6\\u4e4b\\u76f8\\u53bb\\u72b9\\u672a\\u4e3a\\u8fdc\\uff0c\\u4e0d\\u5f52\\u4e0e\\u672c\\u96c6\\u62b5\\u727e\\u82e5\\u662f\\u3002\", \"\\u4e43\\u540e\\u4e4b\\u597d\\u4e8b\\u4fd7\\u4f11\\u5112\\u6258\\u800c\\u4e3a\\u4e4b\\uff0c\\u4ee5\\u539a\\u8bec\\u9000\\u4e4b\\uff0c\\u51b3\\u975e\\u9000\\u4e4b\\u6240\\u4f5c\\u4e5f\\u7744\\u77e3\\u3002\", \"\\u68a6\\u5f3c\\u4eca\\u8c29\\u5f55\\u4e8e\\u6b64\\uff0c\\u4ee5\\u5907\\u540e\\u4eba\\u89c2\\u89c8\\u4e5f\\u3002\", \"\\u300d\\uff09\\u3002\"]"', '诗', 'shi', '', NULL, '題杜工部墳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88687eb5-de72-4500-bb64-31b57ddae28c', '奉和聖製幸望春宮送[朔方]大總管張仁亶', '奉和圣制幸望春宫送[朔方]大总管张仁亶', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5317\\u98a8\\u5439\\u65e9\\u96c1\\uff0c\\u65e5\\u5915\\u6e21\\u6cb3\\u98db\\u3002\", \"\\u6c23\\u51b7\\u81a0\\u61c9\\u6298\\uff0c\\u971c\\u660e\\u8349\\u6b63\\u8153\\u3002\", \"\\u8001\\u81e3\\u5e37\\u5e44\\u7b6d\\uff0c\\u5143\\u5bb0\\u5edf\\u5802\\u6a5f\\u3002\", \"\\u991e\\u98f2\\u5efb\\u4ed9\\u8e55\\uff0c\\u81e8\\u620e\\u89e3\\u5fa1\\u8863\\u3002\", \"\\u8ecd\\u88dd\\u4e58\\u66c9\\u767c\\uff0c\\u5e2b\\u5f8b\\u5019\\u6625\\u6b78\\u3002\", \"\\u65b9\\u4f47\\u52f3\\u5eb8\\u76db\\uff0c\\u5929\\u8a5e\\u964d\\u7d2b\\u5fae\\u3002\"]"', '"[\"\\u5317\\u98ce\\u5439\\u65e9\\u96c1\\uff0c\\u65e5\\u5915\\u6e21\\u6cb3\\u98de\\u3002\", \"\\u6c14\\u51b7\\u80f6\\u5e94\\u6298\\uff0c\\u971c\\u660e\\u8349\\u6b63\\u8153\\u3002\", \"\\u8001\\u81e3\\u5e37\\u5e44\\u7b6d\\uff0c\\u5143\\u5bb0\\u5e99\\u5802\\u673a\\u3002\", \"\\u996f\\u996e\\u5efb\\u4ed9\\u8df8\\uff0c\\u4e34\\u620e\\u89e3\\u5fa1\\u8863\\u3002\", \"\\u519b\\u88c5\\u4e58\\u6653\\u53d1\\uff0c\\u5e08\\u5f8b\\u5019\\u6625\\u5f52\\u3002\", \"\\u65b9\\u4f2b\\u52cb\\u5eb8\\u76db\\uff0c\\u5929\\u8bcd\\u964d\\u7d2b\\u5fae\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製幸望春宮送[朔方]大總管張仁亶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1be6103d-5cae-4585-bcc0-3e3744dcf82e', '奉和聖製登太行山中言志應制', '奉和圣制登太行山中言志应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5317\\u5c71\\u6771\\u5165\\u6d77\\uff0c\\u99b3\\u9053\\u4e0a\\u9023\\u5929\\u3002\", \"\\u9806\\u52d5\\u4e09\\u5149\\u67f1\\uff0c\\u767b\\u81e8\\u842c\\u8c61\\u61f8\\u3002\", \"\\u4fdb\\u89c0\\u6cb3\\u5167\\u9091\\uff0c\\u5e73\\u6307\\u6d1b\\u967d\\u5ddd\\u3002\", \"\\u6309\\u8e55\\u5937\\u95dc\\u96aa\\uff0c\\u5f35\\u65d7\\u4e99\\u4e95\\u6cc9\\u3002\", \"\\u66c9\\u5dd6\\u4e2d\\u8b66\\u67dd\\uff0c\\u6625\\u4e8b\\u4e0b\\u8490\\u7530\\u3002\", \"\\u5fb7\\u91cd\\u5468\\u738b\\u554f\\uff0c\\u6b4c\\u8f15\\u6f22\\u540e\\u50b3\\u3002\", \"\\u5bb8\\u904a\\u92ea\\u4ee4\\u5178\\uff0c\\u777f\\u601d\\u8d77\\u82b3\\u5e74\\u3002\", \"\\u9858\\u4ee5\\u5c01\\u66f8\\u594f\\uff0c\\u5efb\\u947e\\u79aa\\u8085\\u7136\\u3002\"]"', '"[\"\\u5317\\u5c71\\u4e1c\\u5165\\u6d77\\uff0c\\u9a70\\u9053\\u4e0a\\u8fde\\u5929\\u3002\", \"\\u987a\\u52a8\\u4e09\\u5149\\u67f1\\uff0c\\u767b\\u4e34\\u4e07\\u8c61\\u60ac\\u3002\", \"\\u4fdb\\u89c2\\u6cb3\\u5185\\u9091\\uff0c\\u5e73\\u6307\\u6d1b\\u9633\\u5ddd\\u3002\", \"\\u6309\\u8df8\\u5937\\u5173\\u9669\\uff0c\\u5f20\\u65d7\\u4e98\\u4e95\\u6cc9\\u3002\", \"\\u6653\\u5ca9\\u4e2d\\u8b66\\u67dd\\uff0c\\u6625\\u4e8b\\u4e0b\\u641c\\u7530\\u3002\", \"\\u5fb7\\u91cd\\u5468\\u738b\\u95ee\\uff0c\\u6b4c\\u8f7b\\u6c49\\u540e\\u4f20\\u3002\", \"\\u5bb8\\u6e38\\u94fa\\u4ee4\\u5178\\uff0c\\u777f\\u601d\\u8d77\\u82b3\\u5e74\\u3002\", \"\\u613f\\u4ee5\\u5c01\\u4e66\\u594f\\uff0c\\u5efb\\u92ae\\u7985\\u8083\\u7136\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製登太行山中言志應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0da030d3-1efb-41ba-b860-128eda93f7ad', '奉和聖製漕橋東送新除岳牧', '奉和圣制漕桥东送新除岳牧', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5bf6\\u8ce2\\u4e0d\\u907a\\u4fca\\uff0c\\u81fa\\u95a3\\u76e1\\u9d77\\u9e1e\\u3002\", \"\\u672a\\u82e5\\u8abf\\u4eba\\u5207\\uff0c\\u5176\\u5982\\u7c21\\u5e1d\\u96e3\\u3002\", \"\\u4e0a\\u624d\\u81ba\\u51fa\\u5178\\uff0c\\u4e2d\\u65e8\\u5ff5\\u5206\\u5b98\\u3002\", \"\\u7279\\u4ee5\\u5c08\\u57ce\\u8cb4\\uff0c\\u6df1\\u60df\\u5217\\u90e1\\u5b89\\u3002\", \"\\u653f\\u884c\\u601d\\u52d9\\u672c\\uff0c\\u98a8\\u9761\\u5c6c\\u52dd\\u6b98\\u3002\", \"\\u6709\\u4ee4\\u7530\\u77e5\\u6025\\uff0c\\u7121\\u5206\\u7344\\u5728\\u5bec\\u3002\", \"\\u81f3\\u8a00\\u984c\\u777f\\u672d\\uff0c\\u6b8a\\u6e25\\u7051\\u4ed9\\u7ff0\\u3002\", \"\\u8a54\\u991e\\u4e09\\u53f0\\u964d\\uff0c\\u671d\\u69ae\\u842c\\u570b\\u6b61\\u3002\", \"\\u8209\\u676f\\u81e8\\u6c34\\u767c\\uff0c\\u5f35\\u6a02\\u64c1\\u6a4b\\u89c0\\u3002\", \"\\u5f0f\\u4f47\\u6771\\u5c01\\u6703\\uff0c\\u93d8\\u93d8\\u6aa2\\u7389\\u58c7\\u3002\"]"', '"[\"\\u5b9d\\u8d24\\u4e0d\\u9057\\u4fca\\uff0c\\u53f0\\u9601\\u5c3d\\u9e53\\u9e3e\\u3002\", \"\\u672a\\u82e5\\u8c03\\u4eba\\u5207\\uff0c\\u5176\\u5982\\u7b80\\u5e1d\\u96be\\u3002\", \"\\u4e0a\\u624d\\u81ba\\u51fa\\u5178\\uff0c\\u4e2d\\u65e8\\u5ff5\\u5206\\u5b98\\u3002\", \"\\u7279\\u4ee5\\u4e13\\u57ce\\u8d35\\uff0c\\u6df1\\u60df\\u5217\\u90e1\\u5b89\\u3002\", \"\\u653f\\u884c\\u601d\\u52a1\\u672c\\uff0c\\u98ce\\u9761\\u5c5e\\u80dc\\u6b8b\\u3002\", \"\\u6709\\u4ee4\\u7530\\u77e5\\u6025\\uff0c\\u65e0\\u5206\\u72f1\\u5728\\u5bbd\\u3002\", \"\\u81f3\\u8a00\\u9898\\u777f\\u672d\\uff0c\\u6b8a\\u6e25\\u6d12\\u4ed9\\u7ff0\\u3002\", \"\\u8bcf\\u996f\\u4e09\\u53f0\\u964d\\uff0c\\u671d\\u8363\\u4e07\\u56fd\\u6b22\\u3002\", \"\\u4e3e\\u676f\\u4e34\\u6c34\\u53d1\\uff0c\\u5f20\\u4e50\\u62e5\\u6865\\u89c2\\u3002\", \"\\u5f