INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4912a8f1-83a7-4e8b-a925-122101089369', '奉和聖製途次舊居應制', '奉和圣制途次旧居应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6f5e\\u570b\\u81e8\\u6dc4\\u90b8\\uff0c\\u5929\\u738b\\u5225\\u99d5\\u8f3f\\u3002\", \"\\u51fa\\u6f5b\\u96e2\\u96b1\\u969b\\uff0c\\u5c0f\\u5f80\\u5927\\u4f86\\u521d\\u3002\", \"\\u6771\\u9678\\u884c\\u6625\\u5178\\uff0c\\u5357\\u967d\\u5373\\u820a\\u5c45\\u3002\", \"\\u7d04\\u5ddd\\u661f\\u7f55\\u99d0\\uff0c\\u6276\\u9053\\u65e5\\u65c2\\u8212\\u3002\", \"\\u96f2\\u8986\\u9023\\u884c\\u5728\\uff0c\\u98a8\\u5efb\\u52a9\\u6383\\u9664\\u3002\", \"\\u6728\\u884c\\u57ce\\u9091\\u671b\\uff0c\\u81ef\\u843d\\u571f\\u7530\\u758f\\u3002\", \"\\u6614\\u8a66\\u90a6\\u8208\\u540e\\uff0c\\u4eca\\u904e\\u4fd7\\u5faf\\u4e88\\u3002\", \"\\u793a\\u5a01\\u5be7\\u6821\\u7375\\uff0c\\u5d07\\u8b93\\u4e0d\\u9673\\u9b5a\\u3002\", \"\\u5e9c\\u540f\\u8da8\\u5bb8\\u6246\\uff0c\\u9109\\u8006\\u6367\\u5e1d\\u8eca\\u3002\", \"\\u5e33\\u50be\\u4e09\\u98f2\\u8655\\uff0c\\u9591\\u6574\\u516d\\u98db\\u9918\\u3002\", \"\\u76db\\u696d\\u9298\\u6c7e\\u9f0e\\uff0c\\u660c\\u671f\\u61c9\\u6d1b\\u66f8\\u3002\", \"\\u9858\\u966a\\u6b4c\\u8ce6\\u672b\\uff0c\\u7559\\u6bd4\\u8700\\u76f8\\u5982\\u3002\"]"', '"[\"\\u6f5e\\u56fd\\u4e34\\u6dc4\\u90b8\\uff0c\\u5929\\u738b\\u522b\\u9a7e\\u8206\\u3002\", \"\\u51fa\\u6f5c\\u79bb\\u9690\\u9645\\uff0c\\u5c0f\\u5f80\\u5927\\u6765\\u521d\\u3002\", \"\\u4e1c\\u9646\\u884c\\u6625\\u5178\\uff0c\\u5357\\u9633\\u5373\\u65e7\\u5c45\\u3002\", \"\\u7ea6\\u5ddd\\u661f\\u7f55\\u9a7b\\uff0c\\u6276\\u9053\\u65e5\\u65d7\\u8212\\u3002\", \"\\u4e91\\u8986\\u8fde\\u884c\\u5728\\uff0c\\u98ce\\u5efb\\u52a9\\u626b\\u9664\\u3002\", \"\\u6728\\u884c\\u57ce\\u9091\\u671b\\uff0c\\u81ef\\u843d\\u571f\\u7530\\u758f\\u3002\", \"\\u6614\\u8bd5\\u90a6\\u5174\\u540e\\uff0c\\u4eca\\u8fc7\\u4fd7\\u5faf\\u4e88\\u3002\", \"\\u793a\\u5a01\\u5b81\\u6821\\u730e\\uff0c\\u5d07\\u8ba9\\u4e0d\\u9648\\u9c7c\\u3002\", \"\\u5e9c\\u540f\\u8d8b\\u5bb8\\u6246\\uff0c\\u4e61\\u8006\\u6367\\u5e1d\\u8f66\\u3002\", \"\\u5e10\\u503e\\u4e09\\u996e\\u5904\\uff0c\\u95f2\\u6574\\u516d\\u98de\\u4f59\\u3002\", \"\\u76db\\u4e1a\\u94ed\\u6c7e\\u9f0e\\uff0c\\u660c\\u671f\\u5e94\\u6d1b\\u4e66\\u3002\", \"\\u613f\\u966a\\u6b4c\\u8d4b\\u672b\\uff0c\\u7559\\u6bd4\\u8700\\u76f8\\u5982\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製途次舊居應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03528ca3-b63f-41c3-9199-a58685d10b9b', '奉和聖製至長春宮登樓望稼穡之作', '奉和圣制至长春宫登楼望稼穑之作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5e1d\\u8ff9\\u595a\\u5176\\u9060\\uff0c\\u7687\\u7b26\\u4e4b\\u6240\\u5d07\\u3002\", \"\\u656c\\u6642\\u582f\\u52d9\\u4f5c\\uff0c\\u76e1\\u529b\\u79b9\\u7a31\\u529f\\u3002\", \"\\u8d6b\\u8d6b\\u60df\\u5143\\u540e\\uff0c\\u7d93\\u71df\\u81ea\\u5de6\\u99ae\\u3002\", \"\\u8b8a\\u856a\\u79d4\\u7a3b\\u5be6\\uff0c\\u6d41\\u60e1\\u6c34\\u6cc9\\u901a\\u3002\", \"\\u570b\\u961c\\u7336\\u524d\\u8c79\\uff0c\\u4eba\\u75b2\\u8a4e\\u6614\\u718a\\u3002\", \"\\u9ec3\\u5716\\u5de1\\u6c83\\u91ce\\uff0c\\u6e05\\u5439\\u5165\\u96e2\\u5bae\\u3002\", \"\\u662f\\u95b1\\u4eac\\u577b\\u5bcc\\uff0c\\u4ecd\\u89c0\\u90fd\\u9091\\u96c4\\u3002\", \"\\u6191\\u8ed2\\u4e00\\u4f55\\u7dba\\uff0c\\u7a4d\\u6e9c\\u5beb\\u6674\\u7a7a\\u3002\", \"\\u79ae\\u7bc0\\u5bb6\\u5b89\\u5916\\uff0c\\u548c\\u5e73\\u4fd7\\u5728\\u4e2d\\u3002\", \"\\u898b\\u9f8d\\u5782\\u6e2d\\u5317\\uff0c\\u8fad\\u96c1\\u6307\\u6cb3\\u6771\\u3002\", \"\\u777f\\u601d\\u65b9\\u5c45\\u93ac\\uff0c\\u5bb8\\u904a\\u82e5\\u98f2\\u8c50\\u3002\", \"\\u5be7\\u8a87\\u5b50\\u96f2\\u5f9e\\uff0c\\u79ea\\u7232\\u7375\\u6276\\u98a8\\u3002\"]"', '"[\"\\u5e1d\\u8ff9\\u595a\\u5176\\u8fdc\\uff0c\\u7687\\u7b26\\u4e4b\\u6240\\u5d07\\u3002\", \"\\u656c\\u65f6\\u5c27\\u52a1\\u4f5c\\uff0c\\u5c3d\\u529b\\u79b9\\u79f0\\u529f\\u3002\", \"\\u8d6b\\u8d6b\\u60df\\u5143\\u540e\\uff0c\\u7ecf\\u8425\\u81ea\\u5de6\\u51af\\u3002\", \"\\u53d8\\u829c\\u79d4\\u7a3b\\u5b9e\\uff0c\\u6d41\\u6076\\u6c34\\u6cc9\\u901a\\u3002\", \"\\u56fd\\u961c\\u72b9\\u524d\\u8c79\\uff0c\\u4eba\\u75b2\\u8bb5\\u6614\\u718a\\u3002\", \"\\u9ec4\\u56fe\\u5de1\\u6c83\\u91ce\\uff0c\\u6e05\\u5439\\u5165\\u79bb\\u5bab\\u3002\", \"\\u662f\\u9605\\u4eac\\u577b\\u5bcc\\uff0c\\u4ecd\\u89c2\\u90fd\\u9091\\u96c4\\u3002\", \"\\u51ed\\u8f69\\u4e00\\u4f55\\u7eee\\uff0c\\u79ef\\u6e9c\\u5199\\u6674\\u7a7a\\u3002\", \"\\u793c\\u8282\\u5bb6\\u5b89\\u5916\\uff0c\\u548c\\u5e73\\u4fd7\\u5728\\u4e2d\\u3002\", \"\\u89c1\\u9f99\\u5782\\u6e2d\\u5317\\uff0c\\u8f9e\\u96c1\\u6307\\u6cb3\\u4e1c\\u3002\", \"\\u777f\\u601d\\u65b9\\u5c45\\u9550\\uff0c\\u5bb8\\u6e38\\u82e5\\u996e\\u4e30\\u3002\", \"\\u5b81\\u5938\\u5b50\\u4e91\\u4ece\\uff0c\\u79ea\\u4e3a\\u730e\\u6276\\u98ce\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製至長春宮登樓望稼穡之作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58ad7653-c9d3-4318-9b10-dfbc881f9ace', '利州北佛龕前重于去歲題處作', '利州北佛龛前重于去岁题处作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u91cd\\u5dd6\\u8f09\\u770b\\u7f8e\\uff0c\\u5206\\u5854\\u8d77\\u5c64\\u6a19\\u3002\", \"\\u8700\\u5b88\\u7d93\\u5857\\u8655\\uff0c\\u5df4\\u4eba\\u4f5c\\u79ae\\u671d\\u3002\", \"\\u5730\\u7591\\u4e09\\u754c\\u51fa\\uff0c\\u7a7a\\u662f\\u516d\\u5875\\u92b7\\u3002\", \"\\u81e5\\u77f3\\u92ea\\u84bc\\u861a\\uff0c\\u884c\\u584d\\u8986\\u7da0\\u689d\\u3002\", \"\\u6b72\\u5e74\\u66f8\\u6709\\u8a18\\uff0c\\u975e\\u7232\\u5b78\\u984c\\u6a4b\\u3002\"]"', '"[\"\\u91cd\\u5ca9\\u8f7d\\u770b\\u7f8e\\uff0c\\u5206\\u5854\\u8d77\\u5c42\\u6807\\u3002\", \"\\u8700\\u5b88\\u7ecf\\u6d82\\u5904\\uff0c\\u5df4\\u4eba\\u4f5c\\u793c\\u671d\\u3002\", \"\\u5730\\u7591\\u4e09\\u754c\\u51fa\\uff0c\\u7a7a\\u662f\\u516d\\u5c18\\u9500\\u3002\", \"\\u5367\\u77f3\\u94fa\\u82cd\\u85d3\\uff0c\\u884c\\u584d\\u8986\\u7eff\\u6761\\u3002\", \"\\u5c81\\u5e74\\u4e66\\u6709\\u8bb0\\uff0c\\u975e\\u4e3a\\u5b66\\u9898\\u6865\\u3002\"]"', '诗', 'shi', '', NULL, '利州北佛龕前重于去歲題處作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('450259f5-8a70-4c40-a69e-5df11d387595', '閑園即事寄韋侍郎', '闲园即事寄韦侍郎', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u7d50\\u5eec\\u6771\\u57ce\\u4e0b\\uff0c\\u76f4\\u671b\\u6c5f\\u5357\\u5c71\\u3002\", \"\\u9752\\u9744\\u9060\\u76f8\\u63a5\\uff0c\\u767d\\u96f2\\u4f86\\u5fa9\\u9084\\u3002\", \"\\u62c2\\u7b75\\u7d05\\u861a\\u4e0a\\uff0c\\u958b\\u5e54\\u7da0\\u689d\\u9593\\u3002\", \"\\u7269\\u61c9\\u6625\\u504f\\u597d\\uff0c\\u60c5\\u5fd8\\u8da3\\u8f49\\u9591\\u3002\", \"\\u61b2\\u81e3\\u9952\\u7f8e\\u5ea6\\uff0c\\u806f\\u4e8b\\u60dc\\u5f82\\u984f\\u3002\", \"\\u6709\\u9152\\u7a7a\\u76c8\\u914c\\uff0c\\u9ad8\\u8eca\\u4e0d\\u53ef\\u6500\\u3002\"]"', '"[\"\\u7ed3\\u5e90\\u4e1c\\u57ce\\u4e0b\\uff0c\\u76f4\\u671b\\u6c5f\\u5357\\u5c71\\u3002\", \"\\u9752\\u972d\\u8fdc\\u76f8\\u63a5\\uff0c\\u767d\\u4e91\\u6765\\u590d\\u8fd8\\u3002\", \"\\u62c2\\u7b75\\u7ea2\\u85d3\\u4e0a\\uff0c\\u5f00\\u5e54\\u7eff\\u6761\\u95f4\\u3002\", \"\\u7269\\u5e94\\u6625\\u504f\\u597d\\uff0c\\u60c5\\u5fd8\\u8da3\\u8f6c\\u95f2\\u3002\", \"\\u5baa\\u81e3\\u9976\\u7f8e\\u5ea6\\uff0c\\u8054\\u4e8b\\u60dc\\u5f82\\u989c\\u3002\", \"\\u6709\\u9152\\u7a7a\\u76c8\\u914c\\uff0c\\u9ad8\\u8f66\\u4e0d\\u53ef\\u6500\\u3002\"]"', '诗', 'shi', '', NULL, '閑園即事寄韋侍郎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b46df177-a230-4fe8-b44d-59f94e0755e5', '扈從溫泉同紫微黃門羣公汎渭川得齊字', '扈从温泉同紫微黄门群公泛渭川得齐字', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u8679\\u65d7\\u6620\\u7da0\\u8351\\uff0c\\u6625\\u4ed7\\u6f22\\u8c50\\u897f\\u3002\", \"\\u4f8d\\u8e55\\u6d6e\\u6e05\\u6e2d\\uff0c\\u63da\\u8232\\u964d\\u7d2b\\u6ce5\\u3002\", \"\\u8fd1\\u81e8\\u921e\\u77f3\\u5730\\uff0c\\u9059\\u6307\\u91e3\\u749c\\u6eaa\\u3002\", \"\\u5cb8\\u8f49\\u5e06\\u98db\\u75be\\uff0c\\u5ddd\\u5e73\\u68f9\\u8209\\u9f4a\\u3002\", \"\\u5085\\u821f\\u4f86\\u662f\\u7528\\uff0c\\u8ed2\\u99ad\\u5f80\\u61c9\\u8ff7\\u3002\", \"\\u8208\\u95cb\\u83f1\\u6b4c\\u52d5\\uff0c\\u6c99\\u6d32\\u4e82\\u5915\\u9dd6\\u3002\"]"', '"[\"\\u8679\\u65d7\\u6620\\u7eff\\u8351\\uff0c\\u6625\\u4ed7\\u6c49\\u4e30\\u897f\\u3002\", \"\\u4f8d\\u8df8\\u6d6e\\u6e05\\u6e2d\\uff0c\\u626c\\u8232\\u964d\\u7d2b\\u6ce5\\u3002\", \"\\u8fd1\\u4e34\\u94a7\\u77f3\\u5730\\uff0c\\u9065\\u6307\\u9493\\u749c\\u6eaa\\u3002\", \"\\u5cb8\\u8f6c\\u5e06\\u98de\\u75be\\uff0c\\u5ddd\\u5e73\\u68f9\\u4e3e\\u9f50\\u3002\", \"\\u5085\\u821f\\u6765\\u662f\\u7528\\uff0c\\u8f69\\u9a6d\\u5f80\\u5e94\\u8ff7\\u3002\", \"\\u5174\\u9615\\u83f1\\u6b4c\\u52a8\\uff0c\\u6c99\\u6d32\\u4e71\\u5915\\u9e65\\u3002\"]"', '诗', 'shi', '', NULL, '扈從溫泉同紫微黃門羣公汎渭川得齊字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e87730e1-5547-48c3-af7d-c993c3a37614', '餞趙尚書攝御史大夫赴朔方軍', '饯赵尚书摄御史大夫赴朔方军', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u52c1\\u865c\\u6b32\\u5357\\u7aba\\uff0c\\u63da\\u5175\\u8b77\\u6714\\u9672\\u3002\", \"\\u8d99\\u582f\\u5be7\\u6613\\u5370\\uff0c\\u9127\\u79b9\\u5373\\u5206\\u9ebe\\u3002\", \"\\u91ce\\u991e\\u5efb\\u4e09\\u5091\\uff0c\\u8ecd\\u8b00\\u7528\\u516d\\u5947\\u3002\", \"\\u96f2\\u908a\\u6101\\u51fa\\u585e\\uff0c\\u65e5\\u4e0b\\u6134\\u81e8\\u5c90\\u3002\", \"\\u62d4\\u5292\\u884c\\u4eba\\u821e\\uff0c\\u63ee\\u6208\\u6230\\u99ac\\u99b3\\u3002\", \"\\u660e\\u5e74\\u9e9f\\u95a3\\u4e0a\\uff0c\\u5145\\u570b\\u756b\\u65bc\\u65af\\u3002\"]"', '"[\"\\u52b2\\u864f\\u6b32\\u5357\\u7aa5\\uff0c\\u626c\\u5175\\u62a4\\u6714\\u9672\\u3002\", \"\\u8d75\\u5c27\\u5b81\\u6613\\u5370\\uff0c\\u9093\\u79b9\\u5373\\u5206\\u9ebe\\u3002\", \"\\u91ce\\u996f\\u5efb\\u4e09\\u6770\\uff0c\\u519b\\u8c0b\\u7528\\u516d\\u5947\\u3002\", \"\\u4e91\\u8fb9\\u6101\\u51fa\\u585e\\uff0c\\u65e5\\u4e0b\\u6006\\u4e34\\u5c90\\u3002\", \"\\u62d4\\u5292\\u884c\\u4eba\\u821e\\uff0c\\u6325\\u6208\\u6218\\u9a6c\\u9a70\\u3002\", \"\\u660e\\u5e74\\u9e9f\\u9601\\u4e0a\\uff0c\\u5145\\u56fd\\u753b\\u4e8e\\u65af\\u3002\"]"', '诗', 'shi', '', NULL, '餞趙尚書攝御史大夫赴朔方軍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74974879-8c00-456a-bf6f-e5a6207c7b2e', '句', '句', 3154bfd6-de4f-4405-b1be-88124a58e97f, '唐', '"[\"\\u5ebe\\u5dba\\u6771\\u908a\\u540f\\u96b1\\u5dde\\uff0c\\u6eaa\\u5c71\\u7af9\\u6a39\\u4ea6\\u6e05\\u5e7d\\u3002\"]"', '"[\"\\u5ebe\\u5cad\\u4e1c\\u8fb9\\u540f\\u9690\\u5dde\\uff0c\\u6eaa\\u5c71\\u7af9\\u6811\\u4ea6\\u6e05\\u5e7d\\u3002\"]"', '诗', 'shi', '', NULL, '句 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f685aa82-7edc-4d38-ad69-ab59d0e550d8', '曉發興州入陳平路', '晓发兴州入陈平路', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u65cc\\u7bc0\\u6307\\u5df4\\u5cb7\\uff0c\\u5e74\\u5e74\\u884c\\u4e14\\u5de1\\u3002\", \"\\u66ae\\u4f86\\u9752\\u5d82\\u5bbf\\uff0c\\u671d\\u53bb\\u7da0\\u6c5f\\u6625\\u3002\", \"\\u9b5a\\u8cab\\u6881\\u7de3\\u99ac\\uff0c\\u733f\\u5954\\u6a39\\u606f\\u4eba\\u3002\", \"\\u9091\\u7960\\u7336\\u662f\\u6f22\\uff0c\\u6eaa\\u9053\\u5373\\u540d\\u9673\\u3002\", \"\\u820a\\u53f2\\u9952\\u9077\\u8b2b\\uff0c\\u6046\\u60c5\\u53ad\\u82e6\\u8f9b\\u3002\", \"\\u5be7\\u77e5\\u5831\\u6069\\u8005\\uff0c\\u5929\\u5b50\\u4e00\\u5fe0\\u81e3\\u3002\"]"', '"[\"\\u65cc\\u8282\\u6307\\u5df4\\u5cb7\\uff0c\\u5e74\\u5e74\\u884c\\u4e14\\u5de1\\u3002\", \"\\u66ae\\u6765\\u9752\\u5d82\\u5bbf\\uff0c\\u671d\\u53bb\\u7eff\\u6c5f\\u6625\\u3002\", \"\\u9c7c\\u8d2f\\u6881\\u7f18\\u9a6c\\uff0c\\u733f\\u5954\\u6811\\u606f\\u4eba\\u3002\", \"\\u9091\\u7960\\u72b9\\u662f\\u6c49\\uff0c\\u6eaa\\u9053\\u5373\\u540d\\u9648\\u3002\", \"\\u65e7\\u53f2\\u9976\\u8fc1\\u8c2a\\uff0c\\u6052\\u60c5\\u538c\\u82e6\\u8f9b\\u3002\", \"\\u5b81\\u77e5\\u62a5\\u6069\\u8005\\uff0c\\u5929\\u5b50\\u4e00\\u5fe0\\u81e3\\u3002\"]"', '诗', 'shi', '', NULL, '曉發興州入陳平路 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38fef39a-1cf3-40c3-80cf-178fff3584f3', '同餞陽將軍兼源州都督御史中丞', '同饯阳将军兼源州都督御史中丞', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u53f3\\u5730\\u63a5\\u9f9c\\u6c99\\uff0c\\u4e2d\\u671d\\u4efb\\u864e\\u7259\\u3002\", \"\\u7136\\u660e\\u65b9\\u6539\\u4fd7\\uff0c\\u53bb\\u75c5\\u4e0d\\u7232\\u5bb6\\u3002\", \"\\u5c07\\u79ae\\u767b\\u58c7\\u76db\\uff0c\\u8ecd\\u5bb9\\u51fa\\u585e\\u83ef\\u3002\", \"\\u6714\\u98a8\\u6416\\u6f22\\u9f13\\uff0c\\u908a\\u99ac\\u601d\\u80e1\\u7b33\\u3002\", \"\\u65d7\\u5408\\u7121\\u9080\\u6b63\\uff0c\\u51a0\\u5371\\u6709\\u89f8\\u90aa\\u3002\", \"\\u7576\\u770b\\u52de\\u9084\\u65e5\\uff0c\\u53ca\\u6b64\\u5fa1\\u6e9d\\u82b1\\u3002\"]"', '"[\"\\u53f3\\u5730\\u63a5\\u9f9f\\u6c99\\uff0c\\u4e2d\\u671d\\u4efb\\u864e\\u7259\\u3002\", \"\\u7136\\u660e\\u65b9\\u6539\\u4fd7\\uff0c\\u53bb\\u75c5\\u4e0d\\u4e3a\\u5bb6\\u3002\", \"\\u5c06\\u793c\\u767b\\u575b\\u76db\\uff0c\\u519b\\u5bb9\\u51fa\\u585e\\u534e\\u3002\", \"\\u6714\\u98ce\\u6447\\u6c49\\u9f13\\uff0c\\u8fb9\\u9a6c\\u601d\\u80e1\\u7b33\\u3002\", \"\\u65d7\\u5408\\u65e0\\u9080\\u6b63\\uff0c\\u51a0\\u5371\\u6709\\u89e6\\u90aa\\u3002\", \"\\u5f53\\u770b\\u52b3\\u8fd8\\u65e5\\uff0c\\u53ca\\u6b64\\u5fa1\\u6c9f\\u82b1\\u3002\"]"', '诗', 'shi', '', NULL, '同餞陽將軍兼源州都督御史中丞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1221c3d7-5fe3-453a-884d-783de671f2be', '扈從鳳泉和崔黃門喜恩旨解嚴罷圍之作', '扈从凤泉和崔黄门喜恩旨解严罢围之作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u8f26\\u8def\\u5c90\\u5c71\\u66f2\\uff0c\\u5132\\u80e5\\u6e2d\\u6c34\\u6e44\\u3002\", \"\\u6559\\u6210\\u63d0\\u5c07\\u9f13\\uff0c\\u79ae\\u5099\\u690d\\u865e\\u65d7\\u3002\", \"\\u4e0d\\u53d6\\u5f9e\\u754b\\u6a02\\uff0c\\u5148\\u6d41\\u53bb\\u6bba\\u6148\\u3002\", \"\\u821c\\u97f6\\u540c\\u821e\\u65e5\\uff0c\\u6e6f\\u795d\\u76e1\\u98db\\u6642\\u3002\", \"\\u7269\\u61c9\\u967d\\u548c\\u65bd\\uff0c\\u4eba\\u77e5\\u96e8\\u9732\\u79c1\\u3002\", \"\\u4f55\\u5982\\u7a46\\u5929\\u5b50\\uff0c\\u4e03\\u8403\\u5e7e\\u52de\\u5e2b\\u3002\"]"', '"[\"\\u8f87\\u8def\\u5c90\\u5c71\\u66f2\\uff0c\\u50a8\\u80e5\\u6e2d\\u6c34\\u6e44\\u3002\", \"\\u6559\\u6210\\u63d0\\u5c06\\u9f13\\uff0c\\u793c\\u5907\\u690d\\u865e\\u65d7\\u3002\", \"\\u4e0d\\u53d6\\u4ece\\u754b\\u4e50\\uff0c\\u5148\\u6d41\\u53bb\\u6740\\u6148\\u3002\", \"\\u821c\\u97f6\\u540c\\u821e\\u65e5\\uff0c\\u6c64\\u795d\\u5c3d\\u98de\\u65f6\\u3002\", \"\\u7269\\u5e94\\u9633\\u548c\\u65bd\\uff0c\\u4eba\\u77e5\\u96e8\\u9732\\u79c1\\u3002\", \"\\u4f55\\u5982\\u7a46\\u5929\\u5b50\\uff0c\\u4e03\\u8403\\u51e0\\u52b3\\u5e08\\u3002\"]"', '诗', 'shi', '', NULL, '扈從鳳泉和崔黃門喜恩旨解嚴罷圍之作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10fc94b3-093d-4459-af16-bdaeb519da28', '秋夜寓直中書呈黃門舅', '秋夜寓直中书呈黄门舅', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u7c3e\\u6af3\\u4e0a\\u591c\\u9264\\uff0c\\u6e05\\u5217\\u807d\\u66f4\\u7c4c\\u3002\", \"\\u5ffd\\u5171\\u96de\\u679d\\u8001\\uff0c\\u9084\\u5982\\u9a0e\\u7701\\u79cb\\u3002\", \"\\u5faa\\u5ead\\u559c\\u4e09\\u5165\\uff0c\\u5c0d\\u6e1a\\u61b6\\u96d9\\u904a\\u3002\", \"\\u7d2b\\u7d31\\u540d\\u521d\\u62dc\\uff0c\\u9ec3\\u7e11\\u8ff9\\u5c1a\\u7559\\u3002\", \"\\u6708\\u8212\\u7576\\u5317\\u5e4c\\uff0c\\u96f2\\u8ce6\\u76f4\\u6771\\u6a13\\u3002\", \"\\u6069\\u6e25\\u8ff7\\u5929\\u65bd\\uff0c\\u7ae5\\u8499\\u6170\\u6211\\u6c42\\u3002\", \"\\u9072\\u541b\\u53f0\\u9f0e\\u7bc0\\uff0c\\u805e\\u7fa9\\u4e00\\u627f\\u6d41\\u3002\"]"', '"[\"\\u5e18\\u680a\\u4e0a\\u591c\\u94a9\\uff0c\\u6e05\\u5217\\u542c\\u66f4\\u7b79\\u3002\", \"\\u5ffd\\u5171\\u9e21\\u679d\\u8001\\uff0c\\u8fd8\\u5982\\u9a91\\u7701\\u79cb\\u3002\", \"\\u5faa\\u5ead\\u559c\\u4e09\\u5165\\uff0c\\u5bf9\\u6e1a\\u5fc6\\u53cc\\u6e38\\u3002\", \"\\u7d2b\\u7ec2\\u540d\\u521d\\u62dc\\uff0c\\u9ec4\\u7f23\\u8ff9\\u5c1a\\u7559\\u3002\", \"\\u6708\\u8212\\u5f53\\u5317\\u5e4c\\uff0c\\u4e91\\u8d4b\\u76f4\\u4e1c\\u697c\\u3002\", \"\\u6069\\u6e25\\u8ff7\\u5929\\u65bd\\uff0c\\u7ae5\\u8499\\u6170\\u6211\\u6c42\\u3002\", \"\\u8fdf\\u541b\\u53f0\\u9f0e\\u8282\\uff0c\\u95fb\\u4e49\\u4e00\\u627f\\u6d41\\u3002\"]"', '诗', 'shi', '', NULL, '秋夜寓直中書呈黃門舅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31f294dc-b15f-4daa-9cf7-2ae62b2004bc', '先是新昌小園期京兆尹一訪兼郎官數子自頃沈痾年復一年茲願不果率然成章', '先是新昌小园期京兆尹一访兼郎官数子自顷沈疴年复一年兹愿不果率然成章', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u7368\\u597d\\u4e2d\\u6797\\u96b1\\uff0c\\u5148\\u671f\\u4e0a\\u6708\\u6625\\u3002\", \"\\u9591\\u82b1\\u508d\\u6236\\u843d\\uff0c\\u55a7\\u9ce5\\u903c\\u6a90\\u99b4\\u3002\", \"\\u5bc2\\u5bde\\u6771\\u5761\\u53df\\uff0c\\u50b3\\u547c\\u5317\\u91cc\\u4eba\\u3002\", \"\\u5728\\u5c71\\u7434\\u6613\\u8abf\\uff0c\\u958b\\u7515\\u9152\\u6b78\\u9187\\u3002\", \"\\u4f47\\u671b\\u61c9\\u4e09\\u63a5\\uff0c\\u5f4c\\u7559\\u5ffd\\u5e7e\\u65ec\\u3002\", \"\\u4e0d\\u7591\\u4e39\\u706b\\u8b8a\\uff0c\\u7a7a\\u8ca0\\u7da0\\u689d\\u65b0\\u3002\", \"\\u9b2c\\u87fb\\u805e\\u5e38\\u65e5\\uff0c\\u6b4c\\u9f8d\\u503c\\u6b64\\u8fb0\\u3002\", \"\\u5176\\u5982\\u8846\\u541b\\u5b50\\uff0c\\u5609\\u6703\\u963b\\u6e05\\u5875\\u3002\"]"', '"[\"\\u72ec\\u597d\\u4e2d\\u6797\\u9690\\uff0c\\u5148\\u671f\\u4e0a\\u6708\\u6625\\u3002\", \"\\u95f2\\u82b1\\u508d\\u6237\\u843d\\uff0c\\u55a7\\u9e1f\\u903c\\u6a90\\u9a6f\\u3002\", \"\\u5bc2\\u5bde\\u4e1c\\u5761\\u53df\\uff0c\\u4f20\\u547c\\u5317\\u91cc\\u4eba\\u3002\", \"\\u5728\\u5c71\\u7434\\u6613\\u8c03\\uff0c\\u5f00\\u74ee\\u9152\\u5f52\\u9187\\u3002\", \"\\u4f2b\\u671b\\u5e94\\u4e09\\u63a5\\uff0c\\u5f25\\u7559\\u5ffd\\u51e0\\u65ec\\u3002\", \"\\u4e0d\\u7591\\u4e39\\u706b\\u53d8\\uff0c\\u7a7a\\u8d1f\\u7eff\\u6761\\u65b0\\u3002\", \"\\u9b2c\\u8681\\u95fb\\u5e38\\u65e5\\uff0c\\u6b4c\\u9f99\\u503c\\u6b64\\u8fb0\\u3002\", \"\\u5176\\u5982\\u4f17\\u541b\\u5b50\\uff0c\\u5609\\u4f1a\\u963b\\u6e05\\u5c18\\u3002\"]"', '诗', 'shi', '', NULL, '先是新昌小園期京兆尹一訪兼郎官數子自頃沈痾年復一年茲願不果率然成章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a615d35-ef20-4a73-90df-6fc1821dfc28', '奉和馬常侍寺中之作', '奉和马常侍寺中之作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6028\\u6691\\u6642\\u4e91\\u8b1d\\uff0c\\u6106\\u967d\\u6fa4\\u66ab\\u504f\\u3002\", \"\\u9f0e\\u9673\\u5f9e\\u7940\\u65e5\\uff0c\\u9470\\u52d5\\u554f\\u5211\\u5e74\\u3002\", \"\\u7d73\\u670d\\u9f8d\\u96e9\\u5be2\\uff0c\\u7384\\u51a0\\u99ac\\u4f7f\\u65cb\\u3002\", \"\\u4f5c\\u9716\\u671f\\u5085\\u8aaa\\uff0c\\u7232\\u65f1\\u807d\\u5468\\u5ba3\\u3002\", \"\\u6cb3\\u5dbd\\u9670\\u7b26\\u5553\\uff0c\\u661f\\u8fb0\\u6697\\u6a84\\u50b3\\u3002\", \"\\u6d6e\\u6dbc\\u5439\\u666f\\u6c23\\uff0c\\u98db\\u52d5\\u7051\\u7a7a\\u7159\\u3002\", \"\\u98af\\u98af\\u5c07\\u79cb\\u8fd1\\uff0c\\u6c88\\u6c88\\u8207\\u669d\\u9023\\u3002\", \"\\u5206\\u6e4d\\u6d87\\u6c34\\u77f3\\uff0c\\u5408\\u7a4e\\u96cd\\u5dde\\u7530\\u3002\", \"\\u5fb7\\u65bd\\u8d85\\u4e09\\u4e94\\uff0c\\u6587\\u96c4\\u8ce6\\u5341\\u5343\\u3002\", \"\\u53ca\\u65af\\u4f55\\u4ee5\\u6a02\\uff0c\\u660e\\u4e3b\\u656c\\u4eba\\u5929\\u3002\"]"', '"[\"\\u6028\\u6691\\u65f6\\u4e91\\u8c22\\uff0c\\u6106\\u9633\\u6cfd\\u6682\\u504f\\u3002\", \"\\u9f0e\\u9648\\u4ece\\u7940\\u65e5\\uff0c\\u94a5\\u52a8\\u95ee\\u5211\\u5e74\\u3002\", \"\\u7edb\\u670d\\u9f99\\u96e9\\u5bdd\\uff0c\\u7384\\u51a0\\u9a6c\\u4f7f\\u65cb\\u3002\", \"\\u4f5c\\u9716\\u671f\\u5085\\u8bf4\\uff0c\\u4e3a\\u65f1\\u542c\\u5468\\u5ba3\\u3002\", \"\\u6cb3\\u5cb3\\u9634\\u7b26\\u542f\\uff0c\\u661f\\u8fb0\\u6697\\u6a84\\u4f20\\u3002\", \"\\u6d6e\\u51c9\\u5439\\u666f\\u6c14\\uff0c\\u98de\\u52a8\\u6d12\\u7a7a\\u70df\\u3002\", \"\\u98d2\\u98d2\\u5c06\\u79cb\\u8fd1\\uff0c\\u6c88\\u6c88\\u4e0e\\u669d\\u8fde\\u3002\", \"\\u5206\\u6e4d\\u6cfe\\u6c34\\u77f3\\uff0c\\u5408\\u9896\\u96cd\\u5dde\\u7530\\u3002\", \"\\u5fb7\\u65bd\\u8d85\\u4e09\\u4e94\\uff0c\\u6587\\u96c4\\u8d4b\\u5341\\u5343\\u3002\", \"\\u53ca\\u65af\\u4f55\\u4ee5\\u4e50\\uff0c\\u660e\\u4e3b\\u656c\\u4eba\\u5929\\u3002\"]"', '诗', 'shi', '', NULL, '奉和馬常侍寺中之作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54bf6cae-f614-46fe-b036-0189229eb143', '慈恩寺二月半寓言', '慈恩寺二月半寓言', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u4e8c\\u6708\\u97f6\\u6625\\u534a\\uff0c\\u4e09\\u7a7a\\u973d\\u666f\\u521d\\u3002\", \"\\u737b\\u4f86\\u61c9\\u6709\\u53d7\\uff0c\\u6ec5\\u76e1\\u7adf\\u7121\\u9918\\u3002\", \"\\u5316\\u8ff9\\u50b3\\u5b98\\u5bfa\\uff0c\\u6b78\\u8aa0\\u8b01\\u68b5\\u5c45\\u3002\", \"\\u6bbf\\u5802\\u82b1\\u8986\\u5e2d\\uff0c\\u89c0\\u95a3\\u67f3\\u5782\\u758f\\u3002\", \"\\u5171\\u547d\\u679d\\u9593\\u9ce5\\uff0c\\u9577\\u751f\\u6c34\\u4e0a\\u9b5a\\u3002\", \"\\u554f\\u6d25\\u7aba\\u5f7c\\u5cb8\\uff0c\\u8ff7\\u8def\\u5f97\\u771f\\u8eca\\u3002\", \"\\u884c\\u5bc6\\u5e7d\\u95dc\\u975c\\uff0c\\u8ac7\\u7cbe\\u4fd7\\u614b\\u795b\\u3002\", \"\\u7a3b\\u9ebb\\u6b23\\u6240\\u9047\\uff0c\\u84ec\\u7c5c\\u6134\\u7109\\u5982\\u3002\", \"\\u4e0d\\u99d0\\u79e6\\u4eac\\u964c\\uff0c\\u9084\\u984c\\u8700\\u90e1\\u8f3f\\u3002\", \"\\u611b\\u96e2\\u65b9\\u81ea\\u6b64\\uff0c\\u5efb\\u671b\\u7368\\u8e8a\\u8e87\\u3002\"]"', '"[\"\\u4e8c\\u6708\\u97f6\\u6625\\u534a\\uff0c\\u4e09\\u7a7a\\u9701\\u666f\\u521d\\u3002\", \"\\u732e\\u6765\\u5e94\\u6709\\u53d7\\uff0c\\u706d\\u5c3d\\u7adf\\u65e0\\u4f59\\u3002\", \"\\u5316\\u8ff9\\u4f20\\u5b98\\u5bfa\\uff0c\\u5f52\\u8bda\\u8c12\\u68b5\\u5c45\\u3002\", \"\\u6bbf\\u5802\\u82b1\\u8986\\u5e2d\\uff0c\\u89c2\\u9601\\u67f3\\u5782\\u758f\\u3002\", \"\\u5171\\u547d\\u679d\\u95f4\\u9e1f\\uff0c\\u957f\\u751f\\u6c34\\u4e0a\\u9c7c\\u3002\", \"\\u95ee\\u6d25\\u7aa5\\u5f7c\\u5cb8\\uff0c\\u8ff7\\u8def\\u5f97\\u771f\\u8f66\\u3002\", \"\\u884c\\u5bc6\\u5e7d\\u5173\\u9759\\uff0c\\u8c08\\u7cbe\\u4fd7\\u6001\\u795b\\u3002\", \"\\u7a3b\\u9ebb\\u6b23\\u6240\\u9047\\uff0c\\u84ec\\u7ba8\\u6006\\u7109\\u5982\\u3002\", \"\\u4e0d\\u9a7b\\u79e6\\u4eac\\u964c\\uff0c\\u8fd8\\u9898\\u8700\\u90e1\\u8206\\u3002\", \"\\u7231\\u79bb\\u65b9\\u81ea\\u6b64\\uff0c\\u5efb\\u671b\\u72ec\\u8e0c\\u8e87\\u3002\"]"', '诗', 'shi', '', NULL, '慈恩寺二月半寓言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50bebdb1-a333-4104-b987-bfa69fcdfafc', '餞澤州盧使君赴任', '饯泽州卢使君赴任', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u805e\\u9053\\u964d\\u7db8\\u66f8\\uff0c\\u7232\\u90a6\\u5efa\\u7db5\\u65df\\u3002\", \"\\u653f\\u6191\\u5faa\\u540f\\u5f80\\uff0c\\u624d\\u4ee5\\u8cb4\\u537f\\u9664\\u3002\", \"\\u8a5e\\u8ce6\\u826f\\u7121\\u6575\\uff0c\\u8072\\u83ef\\u85f9\\u6709\\u9918\\u3002\", \"\\u69ae\\u627f\\u56db\\u5cb3\\u5f8c\\uff0c\\u8acb\\u7d55\\u4e94\\u5929\\u521d\\u3002\", \"\\u95dc\\u8def\\u901a\\u79e6\\u58c1\\uff0c\\u57ce\\u6c60\\u63a5\\u6649\\u589f\\u3002\", \"\\u64b0\\u671f\\u884c\\u5b50\\u8ce6\\uff0c\\u5206\\u5178\\u5217\\u4faf\\u5c45\\u3002\", \"\\u5225\\u671b\\u55a7\\u8ffd\\u991e\\uff0c\\u96e2\\u8a00\\u7e6b\\u6158\\u8212\\u3002\", \"\\u5e73\\u856a\\u5bd2\\u86ec\\u4e82\\uff0c\\u55ac\\u6728\\u591c\\u87ec\\u758e\\u3002\", \"\\u5be5\\u6cec\\u79cb\\u5148\\u8d77\\uff0c\\u63a8\\u79fb\\u6708\\u5411\\u8af8\\u3002\", \"\\u820a\\u4ea4\\u4f55\\u4ee5\\u8d08\\uff0c\\u5ba2\\u81f3\\u5f85\\u70f9\\u9b5a\\u3002\"]"', '"[\"\\u95fb\\u9053\\u964d\\u7eb6\\u4e66\\uff0c\\u4e3a\\u90a6\\u5efa\\u5f69\\u65df\\u3002\", \"\\u653f\\u51ed\\u5faa\\u540f\\u5f80\\uff0c\\u624d\\u4ee5\\u8d35\\u537f\\u9664\\u3002\", \"\\u8bcd\\u8d4b\\u826f\\u65e0\\u654c\\uff0c\\u58f0\\u534e\\u853c\\u6709\\u4f59\\u3002\", \"\\u8363\\u627f\\u56db\\u5cb3\\u540e\\uff0c\\u8bf7\\u7edd\\u4e94\\u5929\\u521d\\u3002\", \"\\u5173\\u8def\\u901a\\u79e6\\u58c1\\uff0c\\u57ce\\u6c60\\u63a5\\u664b\\u589f\\u3002\", \"\\u64b0\\u671f\\u884c\\u5b50\\u8d4b\\uff0c\\u5206\\u5178\\u5217\\u4faf\\u5c45\\u3002\", \"\\u522b\\u671b\\u55a7\\u8ffd\\u996f\\uff0c\\u79bb\\u8a00\\u7cfb\\u60e8\\u8212\\u3002\", \"\\u5e73\\u829c\\u5bd2\\u86ec\\u4e71\\uff0c\\u4e54\\u6728\\u591c\\u8749\\u758e\\u3002\", \"\\u5be5\\u6cec\\u79cb\\u5148\\u8d77\\uff0c\\u63a8\\u79fb\\u6708\\u5411\\u8bf8\\u3002\", \"\\u65e7\\u4ea4\\u4f55\\u4ee5\\u8d60\\uff0c\\u5ba2\\u81f3\\u5f85\\u70f9\\u9c7c\\u3002\"]"', '诗', 'shi', '', NULL, '餞澤州盧使君赴任 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98220b7-a1b4-41d2-aa83-131a62d4e249', '陳倉別隴州司戶李維深', '陈仓别陇州司户李维深', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u4eac\\u570b\\u81ea\\u651c\\u624b\\uff0c\\u540c\\u9014\\u6b23\\u89e3\\u9824\\u3002\", \"\\u60c5\\u8a00\\u6b63\\u7684\\u7684\\uff0c\\u6625\\u7269\\u5b9b\\u9072\\u9072\\u3002\", \"\\u5ffd\\u80cc\\u96d5\\u620e\\u5f79\\uff0c\\u65cb\\u77bb\\u7372\\u5bf6\\u7960\\u3002\", \"\\u8700\\u57ce\\u4f59\\u51fa\\u5b88\\uff0c\\u5433\\u5cb3\\u723e\\u6b78\\u601d\\u3002\", \"\\u6b61\\u611c\\u66f4\\u50b7\\u6b64\\uff0c\\u7737\\u6bb7\\u6b8a\\u5ff5\\u8332\\u3002\", \"\\u63da\\u9ebe\\u5317\\u6797\\u5f91\\uff0c\\u8dc2\\u77f3\\u5357\\u6f97\\u6e44\\u3002\", \"\\u4e2d\\u4f5c\\u58fa\\u89f4\\u991e\\uff0c\\u56de\\u6dfb\\u9053\\u8def\\u60b2\\u3002\", \"\\u6578\\u82b1\\u81e8\\u78f4\\u65e5\\uff0c\\u767e\\u8349\\u8986\\u7530\\u6642\\u3002\", \"\\u6709\\u7f8e\\u540c\\u4eba\\u610f\\uff0c\\u7121\\u7232\\u884c\\u5b50\\u8fad\\u3002\", \"\\u9163\\u6b4c\\u62d4\\u5292\\u8d77\\uff0c\\u6bcb\\u662f\\u7b54\\u6069\\u79c1\\u3002\"]"', '"[\"\\u4eac\\u56fd\\u81ea\\u643a\\u624b\\uff0c\\u540c\\u9014\\u6b23\\u89e3\\u9890\\u3002\", \"\\u60c5\\u8a00\\u6b63\\u7684\\u7684\\uff0c\\u6625\\u7269\\u5b9b\\u8fdf\\u8fdf\\u3002\", \"\\u5ffd\\u80cc\\u96d5\\u620e\\u5f79\\uff0c\\u65cb\\u77bb\\u83b7\\u5b9d\\u7960\\u3002\", \"\\u8700\\u57ce\\u4f59\\u51fa\\u5b88\\uff0c\\u5434\\u5cb3\\u5c14\\u5f52\\u601d\\u3002\", \"\\u6b22\\u60ec\\u66f4\\u4f24\\u6b64\\uff0c\\u7737\\u6bb7\\u6b8a\\u5ff5\\u5179\\u3002\", \"\\u626c\\u9ebe\\u5317\\u6797\\u5f84\\uff0c\\u8dc2\\u77f3\\u5357\\u6da7\\u6e44\\u3002\", \"\\u4e2d\\u4f5c\\u58f6\\u89de\\u996f\\uff0c\\u56de\\u6dfb\\u9053\\u8def\\u60b2\\u3002\", \"\\u6570\\u82b1\\u4e34\\u78f4\\u65e5\\uff0c\\u767e\\u8349\\u8986\\u7530\\u65f6\\u3002\", \"\\u6709\\u7f8e\\u540c\\u4eba\\u610f\\uff0c\\u65e0\\u4e3a\\u884c\\u5b50\\u8f9e\\u3002\", \"\\u9163\\u6b4c\\u62d4\\u5292\\u8d77\\uff0c\\u6bcb\\u662f\\u7b54\\u6069\\u79c1\\u3002\"]"', '诗', 'shi', '', NULL, '陳倉別隴州司戶李維深 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5e67277-835c-4513-987e-d2cf9d7a95e3', '奉和崔尚書贈大理陸卿鴻臚劉卿見示之作', '奉和崔尚书赠大理陆卿鸿胪刘卿见示之作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6232\\u85fb\\u5609\\u9b5a\\u6a02\\uff0c\\u68f2\\u68a7\\u898b\\u9cf3\\u98db\\u3002\", \"\\u985e\\u5f9e\\u7686\\u6709\\u53ec\\uff0c\\u8072\\u61c9\\u4e43\\u7121\\u9055\\u3002\", \"\\u7f8e\\u50f9\\u9022\\u6642\\u51fa\\uff0c\\u5947\\u624d\\u9078\\u8846\\u7a00\\u3002\", \"\\u907f\\u5802\\u8cbd\\u5f8c\\u653f\\uff0c\\u6383\\u7b2c\\u767c\\u524d\\u5e7e\\u3002\", \"\\u51fa\\u66f3\\u4ed9\\u4eba\\u5c65\\uff0c\\u9084\\u718f\\u4f8d\\u5973\\u8863\\u3002\", \"\\u7701\\u4e2d\\u4f55\\u8d6b\\u5955\\uff0c\\u5ead\\u969b\\u6eff\\u82b3\\u83f2\\u3002\", \"\\u540f\\u90e8\\u7aef\\u6e05\\u9452\\uff0c\\u4e1e\\u90ce\\u8085\\u7d2b\\u6a5f\\u3002\", \"\\u6703\\u5fc3\\u6b4c\\u8a60\\u662f\\uff0c\\u5efb\\u8ff9\\u5bb4\\u8a00\\u975e\\u3002\", \"\\u5317\\u5bfa\\u9130\\u7384\\u95d5\\uff0c\\u5357\\u57ce\\u5beb\\u7fe0\\u5fae\\u3002\", \"\\u53c3\\u5dee\\u4ea4\\u96b1\\u898b\\uff0c\\u9ae3\\u9af4\\u63a5\\u5149\\u8f1d\\u3002\", \"\\u8cd3\\u5e8f\\u5617\\u67d4\\u5fb7\\uff0c\\u5211\\u5b5a\\u5df2\\u973d\\u5a01\\u3002\", \"\\u5de8\\u6e90\\u6797\\u4e0b\\u5951\\uff0c\\u4e0d\\u901f\\u81ea\\u540c\\u6b78\\u3002\"]"', '"[\"\\u620f\\u85fb\\u5609\\u9c7c\\u4e50\\uff0c\\u6816\\u68a7\\u89c1\\u51e4\\u98de\\u3002\", \"\\u7c7b\\u4ece\\u7686\\u6709\\u53ec\\uff0c\\u58f0\\u5e94\\u4e43\\u65e0\\u8fdd\\u3002\", \"\\u7f8e\\u4ef7\\u9022\\u65f6\\u51fa\\uff0c\\u5947\\u624d\\u9009\\u4f17\\u7a00\\u3002\", \"\\u907f\\u5802\\u8d3b\\u540e\\u653f\\uff0c\\u626b\\u7b2c\\u53d1\\u524d\\u51e0\\u3002\", \"\\u51fa\\u66f3\\u4ed9\\u4eba\\u5c65\\uff0c\\u8fd8\\u718f\\u4f8d\\u5973\\u8863\\u3002\", \"\\u7701\\u4e2d\\u4f55\\u8d6b\\u5955\\uff0c\\u5ead\\u9645\\u6ee1\\u82b3\\u83f2\\u3002\", \"\\u540f\\u90e8\\u7aef\\u6e05\\u9274\\uff0c\\u4e1e\\u90ce\\u8083\\u7d2b\\u673a\\u3002\", \"\\u4f1a\\u5fc3\\u6b4c\\u548f\\u662f\\uff0c\\u5efb\\u8ff9\\u5bb4\\u8a00\\u975e\\u3002\", \"\\u5317\\u5bfa\\u90bb\\u7384\\u9619\\uff0c\\u5357\\u57ce\\u5199\\u7fe0\\u5fae\\u3002\", \"\\u53c2\\u5dee\\u4ea4\\u9690\\u89c1\\uff0c\\u9ae3\\u9af4\\u63a5\\u5149\\u8f89\\u3002\", \"\\u5bbe\\u5e8f\\u5c1d\\u67d4\\u5fb7\\uff0c\\u5211\\u5b5a\\u5df2\\u9701\\u5a01\\u3002\", \"\\u5de8\\u6e90\\u6797\\u4e0b\\u5951\\uff0c\\u4e0d\\u901f\\u81ea\\u540c\\u5f52\\u3002\"]"', '诗', 'shi', '', NULL, '奉和崔尚書贈大理陸卿鴻臚劉卿見示之作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8d310be-c6ff-436d-8b5c-2b44bbd44743', '敬和崔尚書大明朝堂雨後望終南山見示之作', '敬和崔尚书大明朝堂雨后望终南山见示之作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5955\\u5955\\u8f15\\u8eca\\u81f3\\uff0c\\u6e05\\u6668\\u671d\\u672a\\u592e\\u3002\", \"\\u672a\\u592e\\u5728\\u9704\\u6975\\uff0c\\u4e2d\\u8def\\u8996\\u54b8\\u967d\\u3002\", \"\\u59d4\\u66f2\\u6f22\\u4eac\\u8fd1\\uff0c\\u5468\\u5efb\\u79e6\\u585e\\u9577\\u3002\", \"\\u65e5\\u83ef\\u52d5\\u6d87\\u6e2d\\uff0c\\u5929\\u7fe0\\u5408\\u5c90\\u6881\\u3002\", \"\\u4e94\\u4e08\\u65cc\\u65d7\\u8272\\uff0c\\u767e\\u5c64\\u678c\\u6a51\\u5149\\u3002\", \"\\u6771\\u9023\\u6b78\\u99ac\\u5730\\uff0c\\u5357\\u6307\\u9b2c\\u96de\\u5834\\u3002\", \"\\u6674\\u58d1\\u7167\\u91d1\\u623a\\uff0c\\u79cb\\u96f2\\u542b\\u74a7\\u74ab\\u3002\", \"\\u7531\\u4f59\\u7aba\\u9738\\u570b\\uff0c\\u856d\\u76f8\\u5949\\u8208\\u738b\\u3002\", \"\\u529f\\u5f79\\u96b1\\u4e0d\\u898b\\uff0c\\u980c\\u8072\\u5b58\\u5fa9\\u63da\\u3002\", \"\\u6b0a\\u5b9c\\u73cd\\u69cb\\u7d55\\uff0c\\u8056\\u4f5c\\u5bf6\\u5716\\u660c\\u3002\", \"\\u5728\\u5fb7\\u671f\\u5de2\\u71e7\\uff0c\\u5c45\\u5b89\\u6cd5\\u79b9\\u6e6f\\u3002\", \"\\u51a2\\u537f\\u624d\\u9806\\u7f8e\\uff0c\\u591a\\u58eb\\u8ce6\\u6210\\u7ae0\\u3002\", \"\\u50f9\\u91cd\\u4e09\\u81fa\\u4fca\\uff0c\\u540d\\u8d85\\u767e\\u90e1\\u826f\\u3002\", \"\\u7109\\u77e5\\u6396\\u57a3\\u4e0b\\uff0c\\u9673\\u529b\\u81ea\\u8ff7\\u65b9\\u3002\"]"', '"[\"\\u5955\\u5955\\u8f7b\\u8f66\\u81f3\\uff0c\\u6e05\\u6668\\u671d\\u672a\\u592e\\u3002\", \"\\u672a\\u592e\\u5728\\u9704\\u6781\\uff0c\\u4e2d\\u8def\\u89c6\\u54b8\\u9633\\u3002\", \"\\u59d4\\u66f2\\u6c49\\u4eac\\u8fd1\\uff0c\\u5468\\u5efb\\u79e6\\u585e\\u957f\\u3002\", \"\\u65e5\\u534e\\u52a8\\u6cfe\\u6e2d\\uff0c\\u5929\\u7fe0\\u5408\\u5c90\\u6881\\u3002\", \"\\u4e94\\u4e08\\u65cc\\u65d7\\u8272\\uff0c\\u767e\\u5c42\\u678c\\u6a51\\u5149\\u3002\", \"\\u4e1c\\u8fde\\u5f52\\u9a6c\\u5730\\uff0c\\u5357\\u6307\\u9b2c\\u9e21\\u573a\\u3002\", \"\\u6674\\u58d1\\u7167\\u91d1\\u623a\\uff0c\\u79cb\\u4e91\\u542b\\u74a7\\u73f0\\u3002\", \"\\u7531\\u4f59\\u7aa5\\u9738\\u56fd\\uff0c\\u8427\\u76f8\\u5949\\u5174\\u738b\\u3002\", \"\\u529f\\u5f79\\u9690\\u4e0d\\u89c1\\uff0c\\u9882\\u58f0\\u5b58\\u590d\\u626c\\u3002\", \"\\u6743\\u5b9c\\u73cd\\u6784\\u7edd\\uff0c\\u5723\\u4f5c\\u5b9d\\u56fe\\u660c\\u3002\", \"\\u5728\\u5fb7\\u671f\\u5de2\\u71e7\\uff0c\\u5c45\\u5b89\\u6cd5\\u79b9\\u6c64\\u3002\", \"\\u51a2\\u537f\\u624d\\u987a\\u7f8e\\uff0c\\u591a\\u58eb\\u8d4b\\u6210\\u7ae0\\u3002\", \"\\u4ef7\\u91cd\\u4e09\\u53f0\\u4fca\\uff0c\\u540d\\u8d85\\u767e\\u90e1\\u826f\\u3002\", \"\\u7109\\u77e5\\u6396\\u57a3\\u4e0b\\uff0c\\u9648\\u529b\\u81ea\\u8ff7\\u65b9\\u3002\"]"', '诗', 'shi', '', NULL, '敬和崔尚書大明朝堂雨後望終南山見示之作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('118b9a18-0004-453d-bdf5-16aae9ddbcdb', '夜聞故梓州韋使君明當引紼感而成章', '夜闻故梓州韦使君明当引绋感而成章', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u60fb\\u77e3\\u5357\\u9130\\u554f\\uff0c\\u51a5\\u7136\\u6771\\u5cb1\\u5e7d\\u3002\", \"\\u91cc\\u9588\\u5be7\\u76f8\\u6775\\uff0c\\u671d\\u6b4e\\u5ffd\\u9077\\u821f\\u3002\", \"\\u541b\\u5fc3\\u60df\\u4f2f\\u4ef2\\uff0c\\u543e\\u4eba\\u5fa9\\u6b3e\\u904a\\u3002\", \"\\u5c0d\\u9023\\u6642\\u4ea6\\u65e9\\uff0c\\u4ea4\\u559c\\u6b72\\u7e94\\u5468\\u3002\", \"\\u5e8f\\u767c\\u6276\\u967d\\u8d08\\uff0c\\u6587\\u56e0\\u53f8\\u5bc7\\u916c\\u3002\", \"\\u8a4e\\u671f\\u5371\\u9732\\u76e1\\uff0c\\u76f8\\u7e8c\\u901d\\u5ddd\\u6d41\\u3002\", \"\\u81e5\\u75be\\u7121\\u4e09\\u5f14\\uff0c\\u5c45\\u9591\\u6709\\u767e\\u6182\\u3002\", \"\\u632f\\u98a8\\u541f\\u9f13\\u5915\\uff0c\\u660e\\u6708\\u7167\\u5e37\\u79cb\\u3002\", \"\\u861a\\u99c1\\u984c\\u8a69\\u9928\\uff0c\\u694a\\u758e\\u594f\\u4f0e\\u6a13\\u3002\", \"\\u5171\\u5c07\\u6b4c\\u7b11\\u6b4e\\uff0c\\u8f49\\u7232\\u5f1f\\u5144\\u7559\\u3002\", \"\\u611f\\u7269\\u5b58\\u5982\\u5922\\uff0c\\u89c0\\u751f\\u53bb\\u82e5\\u6d6e\\u3002\", \"\\u4f59\\u975e\\u5fd8\\u60c5\\u8005\\uff0c\\u96ea\\u6d95\\u5831\\u6797\\u4e18\\u3002\"]"', '"[\"\\u607b\\u77e3\\u5357\\u90bb\\u95ee\\uff0c\\u51a5\\u7136\\u4e1c\\u5cb1\\u5e7d\\u3002\", \"\\u91cc\\u95ec\\u5b81\\u76f8\\u6775\\uff0c\\u671d\\u53f9\\u5ffd\\u8fc1\\u821f\\u3002\", \"\\u541b\\u5fc3\\u60df\\u4f2f\\u4ef2\\uff0c\\u543e\\u4eba\\u590d\\u6b3e\\u6e38\\u3002\", \"\\u5bf9\\u8fde\\u65f6\\u4ea6\\u65e9\\uff0c\\u4ea4\\u559c\\u5c81\\u624d\\u5468\\u3002\", \"\\u5e8f\\u53d1\\u6276\\u9633\\u8d60\\uff0c\\u6587\\u56e0\\u53f8\\u5bc7\\u916c\\u3002\", \"\\u8bb5\\u671f\\u5371\\u9732\\u5c3d\\uff0c\\u76f8\\u7eed\\u901d\\u5ddd\\u6d41\\u3002\", \"\\u5367\\u75be\\u65e0\\u4e09\\u540a\\uff0c\\u5c45\\u95f2\\u6709\\u767e\\u5fe7\\u3002\", \"\\u632f\\u98ce\\u541f\\u9f13\\u5915\\uff0c\\u660e\\u6708\\u7167\\u5e37\\u79cb\\u3002\", \"\\u85d3\\u9a73\\u9898\\u8bd7\\u9986\\uff0c\\u6768\\u758e\\u594f\\u4f0e\\u697c\\u3002\", \"\\u5171\\u5c06\\u6b4c\\u7b11\\u53f9\\uff0c\\u8f6c\\u4e3a\\u5f1f\\u5144\\u7559\\u3002\", \"\\u611f\\u7269\\u5b58\\u5982\\u68a6\\uff0c\\u89c2\\u751f\\u53bb\\u82e5\\u6d6e\\u3002\", \"\\u4f59\\u975e\\u5fd8\\u60c5\\u8005\\uff0c\\u96ea\\u6d95\\u62a5\\u6797\\u4e18\\u3002\"]"', '诗', 'shi', '', NULL, '夜聞故梓州韋使君明當引紼感而成章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32c567a9-e8f2-4de3-a5cf-084d88f94e55', '御箭連中雙兔', '御箭连中双兔', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5bb8\\u904a\\u7d93\\u4e0a\\u82d1\\uff0c\\u7fbd\\u7375\\u5411\\u9591\\u7530\\u3002\", \"\\u72e1\\u5154\\u521d\\u8ff7\\u7a9f\\uff0c\\u7e96\\u9a6a\\u8a4e\\u8457\\u97ad\\u3002\", \"\\u4e09\\u9a45\\u4ecd\\u767e\\u6b65\\uff0c\\u4e00\\u767c\\u9042\\u96d9\\u9023\\u3002\", \"\\u5f71\\u5c04\\u542b\\u971c\\u8349\\uff0c\\u9b42\\u6d88\\u5411\\u6708\\u5f26\\u3002\", \"\\u6b61\\u8072\\u52d5\\u5bd2\\u6728\\uff0c\\u559c\\u6c23\\u6eff\\u6674\\u5929\\u3002\", \"\\u90a3\\u4f3c\\u9673\\u738b\\u610f\\uff0c\\u7a7a\\u96a8\\u6a02\\u5e9c\\u7bc7\\u3002\"]"', '"[\"\\u5bb8\\u6e38\\u7ecf\\u4e0a\\u82d1\\uff0c\\u7fbd\\u730e\\u5411\\u95f2\\u7530\\u3002\", \"\\u72e1\\u5154\\u521d\\u8ff7\\u7a9f\\uff0c\\u7ea4\\u9a8a\\u8bb5\\u8457\\u97ad\\u3002\", \"\\u4e09\\u9a71\\u4ecd\\u767e\\u6b65\\uff0c\\u4e00\\u53d1\\u9042\\u53cc\\u8fde\\u3002\", \"\\u5f71\\u5c04\\u542b\\u971c\\u8349\\uff0c\\u9b42\\u6d88\\u5411\\u6708\\u5f26\\u3002\", \"\\u6b22\\u58f0\\u52a8\\u5bd2\\u6728\\uff0c\\u559c\\u6c14\\u6ee1\\u6674\\u5929\\u3002\", \"\\u90a3\\u4f3c\\u9648\\u738b\\u610f\\uff0c\\u7a7a\\u968f\\u4e50\\u5e9c\\u7bc7\\u3002\"]"', '诗', 'shi', '', NULL, '御箭連中雙兔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7774fc6-59ce-485a-8e9a-4eb8878fa623', '奉和聖製過潼津關', '奉和圣制过潼津关', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5728\\u5fb7\\u4f55\\u5937\\u96aa\\uff0c\\u89c0\\u98a8\\u5fa9\\u5f80\\u9084\\u3002\", \"\\u81ea\\u80fd\\u540c\\u5584\\u9589\\uff0c\\u4e2d\\u8def\\u53ef\\u7121\\u95dc\\u3002\"]"', '"[\"\\u5728\\u5fb7\\u4f55\\u5937\\u9669\\uff0c\\u89c2\\u98ce\\u590d\\u5f80\\u8fd8\\u3002\", \"\\u81ea\\u80fd\\u540c\\u5584\\u95ed\\uff0c\\u4e2d\\u8def\\u53ef\\u65e0\\u5173\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製過潼津關 shi');
