INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6fc5392-053d-40aa-b6b2-9290137ee14c', '詠死兔', '咏死兔', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u5154\\u5b50\\u6b7b\\u862d\\u5f48\\uff0c\\u6301\\u4f86\\u6302\\u7af9\\u7aff\\u3002\", \"\\u8a66\\u5c07\\u660e\\u93e1\\u7167\\uff0c\\u4f55\\u7570\\u6708\\u4e2d\\u770b\\u3002\"]"', '"[\"\\u5154\\u5b50\\u6b7b\\u5170\\u5f39\\uff0c\\u6301\\u6765\\u6302\\u7af9\\u7aff\\u3002\", \"\\u8bd5\\u5c06\\u660e\\u955c\\u7167\\uff0c\\u4f55\\u5f02\\u6708\\u4e2d\\u770b\\u3002\"]"', '诗', 'shi', '', NULL, '詠死兔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e532bc99-6904-4b18-8bd0-6c4dc90422ec', '夜宴安樂公主新宅', '夜宴安乐公主新宅', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u8eca\\u5982\\u6d41\\u6c34\\u99ac\\u5982\\u9f8d\\uff0c\\u4ed9\\u4f7f\\u9ad8\\u81fa\\u5341\\u4e8c\\u91cd\\u3002\", \"\\u5929\\u4e0a\\u521d\\u79fb\\u8861\\u6f22\\u5339\\uff0c\\u53ef\\u6190\\u6b4c\\u821e\\u591c\\u76f8\\u5f9e\\u3002\"]"', '"[\"\\u8f66\\u5982\\u6d41\\u6c34\\u9a6c\\u5982\\u9f99\\uff0c\\u4ed9\\u4f7f\\u9ad8\\u53f0\\u5341\\u4e8c\\u91cd\\u3002\", \"\\u5929\\u4e0a\\u521d\\u79fb\\u8861\\u6c49\\u5339\\uff0c\\u53ef\\u601c\\u6b4c\\u821e\\u591c\\u76f8\\u4ece\\u3002\"]"', '诗', 'shi', '', NULL, '夜宴安樂公主新宅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bffdd7c5-b649-4f79-807c-caa66bfd0144', '子夜冬歌', '子夜冬歌', 54976b02-68a2-4322-912d-f289fa325386, '唐', '"[\"\\u6714\\u98a8\\u6263\\u7fa3\\u6728\\uff0c\\u56b4\\u971c\\u51cb\\u767e\\u8349\\u3002\", \"\\u501f\\u554f\\u6708\\u4e2d\\u4eba\\uff0c\\u5b89\\u5f97\\u9577\\u4e0d\\u8001\\u3002\"]"', '"[\"\\u6714\\u98ce\\u6263\\u7fa4\\u6728\\uff0c\\u4e25\\u971c\\u51cb\\u767e\\u8349\\u3002\", \"\\u501f\\u95ee\\u6708\\u4e2d\\u4eba\\uff0c\\u5b89\\u5f97\\u957f\\u4e0d\\u8001\\u3002\"]"', '诗', 'shi', '', NULL, '子夜冬歌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef747161-4212-4c1a-872d-1a0af41f23a6', '重送舒公', '重送舒公', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u6563\\u9a0e\\u91d1\\u8c82\\u670d\\u7db5\\u8863\\uff0c\\u677e\\u82b1\\u6c34\\u4e0a\\u9010\\u6625\\u6b78\\u3002\", \"\\u61f8\\u77e5\\u9091\\u91cc\\u9059\\u76f8\\u671b\\uff0c\\u4e8b\\u4e3b\\u69ae\\u89aa\\u4ee3\\u6240\\u7a00\\u3002\"]"', '"[\"\\u6563\\u9a91\\u91d1\\u8c82\\u670d\\u5f69\\u8863\\uff0c\\u677e\\u82b1\\u6c34\\u4e0a\\u9010\\u6625\\u5f52\\u3002\", \"\\u60ac\\u77e5\\u9091\\u91cc\\u9065\\u76f8\\u671b\\uff0c\\u4e8b\\u4e3b\\u8363\\u4eb2\\u4ee3\\u6240\\u7a00\\u3002\"]"', '诗', 'shi', '', NULL, '重送舒公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a12ff87-f925-4106-b830-f3d425cc01e0', '句', '句', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '"[\"\\u98db\\u57c3\\u7d50\\u7d05\\u9727\\uff0c\\u904a\\u84cb\\u98c4\\u9752\\u96f2\\u3002\", \"\\u6307\\u5982\\u5341\\u633a\\u58a8\\uff0c\\u8033\\u4f3c\\u5169\\u5f35\\u5319\\u3002\", \"\\u4e11\\u96d6\\u6709\\u8db3\\uff0c\\u7532\\u4e0d\\u5168\\u8eab\\u3002\", \"\\u898b\\u541b\\u7121\\u53e3\\uff0c\\u77e5\\u4f0a\\u5c11\\u4eba\\u3002\"]"', '"[\"\\u98de\\u57c3\\u7ed3\\u7ea2\\u96fe\\uff0c\\u6e38\\u76d6\\u98d8\\u9752\\u4e91\\u3002\", \"\\u6307\\u5982\\u5341\\u633a\\u58a8\\uff0c\\u8033\\u4f3c\\u4e24\\u5f20\\u5319\\u3002\", \"\\u4e11\\u867d\\u6709\\u8db3\\uff0c\\u7532\\u4e0d\\u5168\\u8eab\\u3002\", \"\\u89c1\\u541b\\u65e0\\u53e3\\uff0c\\u77e5\\u4f0a\\u5c11\\u4eba\\u3002\"]"', '诗', 'shi', '', NULL, '句 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e63ad01-8db7-4c41-810d-720779c95b46', '龍池篇', '龙池篇', ae8c3020-d4ba-4bee-963b-49f0a201e070, '唐', '"[\"\\u9748\\u6cbc\\u7e08\\u5efb\\u90b8\\u7b2c\\u524d\\uff0c\\u6d74\\u65e5\\u6db5\\u6625\\u5beb\\u66d9\\u5929\\u3002\", \"\\u59cb\\u898b\\u9f8d\\u81fa\\u6607\\u9cf3\\u95d5\\uff0c\\u61c9\\u5982\\u9704\\u6f22\\u8d77\\u795e\\u6cc9\\u3002\", \"\\u77f3\\u5331\\u6e1a\\u508d\\u9084\\u5553\\u8056\\uff0c\\u6843\\u674e\\u521d\\u751f\\u66f4\\u6709\\u4ed9\\u3002\", \"\\u6b32\\u5316\\u5e1d\\u5716\\u5f9e\\u6b64\\u53d7\\uff0c\\u6b63\\u540c\\u6cb3\\u8b8a\\u4e00\\u5343\\u5e74\\u3002\"]"', '"[\"\\u7075\\u6cbc\\u8426\\u5efb\\u90b8\\u7b2c\\u524d\\uff0c\\u6d74\\u65e5\\u6db5\\u6625\\u5199\\u66d9\\u5929\\u3002\", \"\\u59cb\\u89c1\\u9f99\\u53f0\\u5347\\u51e4\\u9619\\uff0c\\u5e94\\u5982\\u9704\\u6c49\\u8d77\\u795e\\u6cc9\\u3002\", \"\\u77f3\\u532e\\u6e1a\\u508d\\u8fd8\\u542f\\u5723\\uff0c\\u6843\\u674e\\u521d\\u751f\\u66f4\\u6709\\u4ed9\\u3002\", \"\\u6b32\\u5316\\u5e1d\\u56fe\\u4ece\\u6b64\\u53d7\\uff0c\\u6b63\\u540c\\u6cb3\\u53d8\\u4e00\\u5343\\u5e74\\u3002\"]"', '诗', 'shi', '', NULL, '龍池篇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fa0f38c-518d-4298-943c-12b455da1c6a', '龍池篇', '龙池篇', a07e6f8e-c950-45f5-be42-05fb14d71bd1, '唐', '"[\"\\u9f8d\\u6c60\\u521d\\u51fa\\u6b64\\u9f8d\\u5c71\\uff0c\\u5e38\\u7d93\\u6b64\\u5730\\u8b01\\u9f8d\\u984f\\u3002\", \"\\u65e5\\u65e5\\u8299\\u84c9\\u751f\\u590f\\u6c34\\uff0c\\u5e74\\u5e74\\u694a\\u67f3\\u8b8a\\u6625\\u7063\\u3002\", \"\\u582f\\u58c7\\u5bf6\\u5323\\u9918\\u7159\\u9727\\uff0c\\u821c\\u6d77\\u6f01\\u821f\\u5c1a\\u5f80\\u9084\\u3002\", \"\\u9858\\u4f3c\\u98c4\\u98bb\\u4e94\\u96f2\\u5f71\\uff0c\\u5f9e\\u4f86\\u5f9e\\u53bb\\u4e5d\\u5929\\u95dc\\u3002\"]"', '"[\"\\u9f99\\u6c60\\u521d\\u51fa\\u6b64\\u9f99\\u5c71\\uff0c\\u5e38\\u7ecf\\u6b64\\u5730\\u8c12\\u9f99\\u989c\\u3002\", \"\\u65e5\\u65e5\\u8299\\u84c9\\u751f\\u590f\\u6c34\\uff0c\\u5e74\\u5e74\\u6768\\u67f3\\u53d8\\u6625\\u6e7e\\u3002\", \"\\u5c27\\u575b\\u5b9d\\u5323\\u4f59\\u70df\\u96fe\\uff0c\\u821c\\u6d77\\u6e14\\u821f\\u5c1a\\u5f80\\u8fd8\\u3002\", \"\\u613f\\u4f3c\\u98d8\\u98d6\\u4e94\\u4e91\\u5f71\\uff0c\\u4ece\\u6765\\u4ece\\u53bb\\u4e5d\\u5929\\u5173\\u3002\"]"', '诗', 'shi', '', NULL, '龍池篇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('383c025d-1200-4f1b-9621-0ed305aa8eeb', '奉和聖製龍池篇', '奉和圣制龙池篇', af8edfbe-dc4d-4aab-90a0-d911031fa6ff, '唐', '"[\"\\u5e1d\\u5b85\\u738b\\u5bb6\\u5927\\u9053\\u908a\\uff0c\\u795e\\u99ac\\u6f5b\\u9f8d\\u6e67\\u8056\\u6cc9\\u3002\", \"\\u6614\\u65e5\\u6614\\u6642\\u7d93\\u6b64\\u5730\\uff0c\\u770b\\u4f86\\u770b\\u53bb\\u6f38\\u6210\\u5ddd\\u3002\", \"\\u6b4c\\u81fa\\u821e\\u69ad\\u5b9c\\u6b63\\u6708\\uff0c\\u67f3\\u5cb8\\u6885\\u6d32\\u52dd\\u5f80\\u5e74\\u3002\", \"\\u83ab\\u7591\\u6ce2\\u4e0a\\u6625\\u96f2\\u5c11\\uff0c\\u7957\\u7232\\u5f9e\\u9f8d\\u76f4\\u4e0a\\u5929\\u3002\"]"', '"[\"\\u5e1d\\u5b85\\u738b\\u5bb6\\u5927\\u9053\\u8fb9\\uff0c\\u795e\\u9a6c\\u6f5c\\u9f99\\u6d8c\\u5723\\u6cc9\\u3002\", \"\\u6614\\u65e5\\u6614\\u65f6\\u7ecf\\u6b64\\u5730\\uff0c\\u770b\\u6765\\u770b\\u53bb\\u6e10\\u6210\\u5ddd\\u3002\", \"\\u6b4c\\u53f0\\u821e\\u69ad\\u5b9c\\u6b63\\u6708\\uff0c\\u67f3\\u5cb8\\u6885\\u6d32\\u80dc\\u5f80\\u5e74\\u3002\", \"\\u83ab\\u7591\\u6ce2\\u4e0a\\u6625\\u4e91\\u5c11\\uff0c\\u7957\\u4e3a\\u4ece\\u9f99\\u76f4\\u4e0a\\u5929\\u3002\"]"', '诗', 'shi', '', NULL, '奉和聖製龍池篇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88eb8c8d-e9b2-44b9-8abf-c6c697e57a8e', '打毬篇', '打毬篇', af8edfbe-dc4d-4aab-90a0-d911031fa6ff, '唐', '"[\"\\u5fb7\\u967d\\u5bae\\u5317\\u82d1\\u6771\\u982d\\uff0c\\u96f2\\u4f5c\\u9ad8\\u81fa\\u6708\\u4f5c\\u6a13\\u3002\", \"\\u91d1\\u939a\\u7389\\u93a3\\u5343\\u91d1\\u5730\\uff0c\\u5bf6\\u6756\\u7431\\u6587\\u4e03\\u5bf6\\u6bec\\u3002\", \"\\u7ac7\\u878d\\u4e00\\u5bb6\\u4e09\\u5c1a\\u4e3b\\uff0c\\u6881\\u7ffc\\u983b\\u5c01\\u842c\\u6236\\u4faf\\u3002\", \"\\u5bb9\\u8272\\u7531\\u4f86\\u8377\\u6069\\u9867\\uff0c\\u610f\\u6c23\\u5e73\\u751f\\u4e8b\\u4fe0\\u6e38\\u3002\", \"\\u5171\\u9053\\u7528\\u5175\\u5982\\u65b7\\u8517\\uff0c\\u4ff1\\u80fd\\u8d70\\u99ac\\u5165\\u9577\\u6978\\u3002\", \"\\u7d05\\u9b23\\u9326\\u9b03\\u98a8\\u9a04\\u9a65\\uff0c\\u9ec3\\u7d61\\u9752\\u7d72\\u96fb\\u7d2b\\u9a2e\\u3002\", \"\\u5954\\u661f\\u4e82\\u4e0b\\u82b1\\u5834\\u88cf\\uff0c\\u521d\\u6708\\u98db\\u4f86\\u756b\\u6756\\u982d\\u3002\", \"\\u81ea\\u6709\\u9577\\u9cf4\\u9808\\u6c7a\\u52dd\\uff0c\\u80fd\\u99b3\\u8fc5\\u8d70\\u6eff\\u5148\\u7c4c\\u3002\", \"\\u8584\\u66ae\\u6f22\\u5bae\\u6109\\u6a02\\u7f77\\uff0c\\u9084\\u6b78\\u582f\\u5ba4\\u66c9\\u5782\\u65d2\\u3002\"]"', '"[\"\\u5fb7\\u9633\\u5bab\\u5317\\u82d1\\u4e1c\\u5934\\uff0c\\u4e91\\u4f5c\\u9ad8\\u53f0\\u6708\\u4f5c\\u697c\\u3002\", \"\\u91d1\\u9524\\u7389\\u84e5\\u5343\\u91d1\\u5730\\uff0c\\u5b9d\\u6756\\u96d5\\u6587\\u4e03\\u5b9d\\u6bec\\u3002\", \"\\u7aa6\\u878d\\u4e00\\u5bb6\\u4e09\\u5c1a\\u4e3b\\uff0c\\u6881\\u7ffc\\u9891\\u5c01\\u4e07\\u6237\\u4faf\\u3002\", \"\\u5bb9\\u8272\\u7531\\u6765\\u8377\\u6069\\u987e\\uff0c\\u610f\\u6c14\\u5e73\\u751f\\u4e8b\\u4fa0\\u6e38\\u3002\", \"\\u5171\\u9053\\u7528\\u5175\\u5982\\u65ad\\u8517\\uff0c\\u4ff1\\u80fd\\u8d70\\u9a6c\\u5165\\u957f\\u6978\\u3002\", \"\\u7ea2\\u9b23\\u9526\\u9b03\\u98ce\\ud86d\\ude27\\u9aa5\\uff0c\\u9ec4\\u7edc\\u9752\\u4e1d\\u7535\\u7d2b\\u9a9d\\u3002\", \"\\u5954\\u661f\\u4e71\\u4e0b\\u82b1\\u573a\\u91cc\\uff0c\\u521d\\u6708\\u98de\\u6765\\u753b\\u6756\\u5934\\u3002\", \"\\u81ea\\u6709\\u957f\\u9e23\\u987b\\u51b3\\u80dc\\uff0c\\u80fd\\u9a70\\u8fc5\\u8d70\\u6ee1\\u5148\\u7b79\\u3002\", \"\\u8584\\u66ae\\u6c49\\u5bab\\u6109\\u4e50\\u7f62\\uff0c\\u8fd8\\u5f52\\u5c27\\u5ba4\\u6653\\u5782\\u65d2\\u3002\"]"', '诗', 'shi', '', NULL, '打毬篇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b35a9f5a-4e6b-4403-9c43-55aa047e0da9', '阮公體', '阮公体', 3fb650c9-e023-4f9e-94e1-62ffd2cebe45, '唐', '"[\"\\u79e6\\u738b\\u6309\\u5292\\u6012\\uff0c\\u767c\\u5352\\u620d\\u9f8d\\u6c99\\u3002\", \"\\u96c4\\u5716\\u5c1a\\u672a\\u7562\\uff0c\\u6d77\\u5167\\u5df2\\u7d1b\\u62cf\\u3002\", \"\\u9ec3\\u5875\\u6697\\u5929\\u8d77\\uff0c\\u767d\\u65e5\\u6582\\u7cbe\\u83ef\\u3002\", \"\\u552f\\u898b\\u9577\\u57ce\\u5916\\uff0c\\u50f5\\u5c4d\\u5982\\u4e82\\u9ebb\\u3002\"]"', '"[\"\\u79e6\\u738b\\u6309\\u5292\\u6012\\uff0c\\u53d1\\u5352\\u620d\\u9f99\\u6c99\\u3002\", \"\\u96c4\\u56fe\\u5c1a\\u672a\\u6bd5\\uff0c\\u6d77\\u5185\\u5df2\\u7eb7\\u62cf\\u3002\", \"\\u9ec4\\u5c18\\u6697\\u5929\\u8d77\\uff0c\\u767d\\u65e5\\u655b\\u7cbe\\u534e\\u3002\", \"\\u552f\\u89c1\\u957f\\u57ce\\u5916\\uff0c\\u50f5\\u5c38\\u5982\\u4e71\\u9ebb\\u3002\"]"', '诗', 'shi', '', NULL, '阮公體 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8557c5ba-f38f-463c-97a9-b955426c75de', '同蔡孚五亭詠', '同蔡孚五亭咏', 3fb650c9-e023-4f9e-94e1-62ffd2cebe45, '唐', '"[\"\\u7ae0\\u594f\\u4e2d\\u4eac\\u7f77\\uff0c\\u96f2\\u6cc9\\u5225\\u696d\\u6b78\\u3002\", \"\\u62c2\\u7434\\u92ea\\u91ce\\u5e2d\\uff0c\\u727d\\u67f3\\u6302\\u671d\\u8863\\u3002\", \"\\u7fe1\\u7fe0\\u5de2\\u66f8\\u5e4c\\uff0c\\u9d1b\\u9d26\\u7acb\\u91e3\\u78ef\\u3002\", \"\\u5e7d\\u6816\\u53ef\\u6190\\u8655\\uff0c\\u6625\\u4e8b\\u6eff\\u6797\\u6249\\u3002\"]"', '"[\"\\u7ae0\\u594f\\u4e2d\\u4eac\\u7f62\\uff0c\\u4e91\\u6cc9\\u522b\\u4e1a\\u5f52\\u3002\", \"\\u62c2\\u7434\\u94fa\\u91ce\\u5e2d\\uff0c\\u7275\\u67f3\\u6302\\u671d\\u8863\\u3002\", \"\\u7fe1\\u7fe0\\u5de2\\u4e66\\u5e4c\\uff0c\\u9e33\\u9e2f\\u7acb\\u9493\\u77f6\\u3002\", \"\\u5e7d\\u6816\\u53ef\\u601c\\u5904\\uff0c\\u6625\\u4e8b\\u6ee1\\u6797\\u6249\\u3002\"]"', '诗', 'shi', '', NULL, '同蔡孚五亭詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('189b4ea7-fc34-49e0-b413-ca72a1ddd612', '蔡起居山亭', '蔡起居山亭', 3fb650c9-e023-4f9e-94e1-62ffd2cebe45, '唐', '"[\"\\u6587\\u53f2\\u6b78\\u4f11\\u65e5\\uff0c\\u68f2\\u9591\\u81e5\\u8349\\u4ead\\u3002\", \"\\u8594\\u8587\\u4e00\\u67b6\\u7d2b\\uff0c\\u77f3\\u7af9\\u6578\\u91cd\\u9752\\u3002\", \"\\u5782\\u9732\\u548c\\u4ed9\\u85e5\\uff0c\\u71d2\\u9999\\u8aa6\\u9053\\u7d93\\u3002\", \"\\u83ab\\u5c07\\u5c71\\u6c34\\u5f04\\uff0c\\u6301\\u8207\\u4e16\\u4eba\\u807d\\u3002\"]"', '"[\"\\u6587\\u53f2\\u5f52\\u4f11\\u65e5\\uff0c\\u6816\\u95f2\\u5367\\u8349\\u4ead\\u3002\", \"\\u8537\\u8587\\u4e00\\u67b6\\u7d2b\\uff0c\\u77f3\\u7af9\\u6570\\u91cd\\u9752\\u3002\", \"\\u5782\\u9732\\u548c\\u4ed9\\u836f\\uff0c\\u70e7\\u9999\\u8bf5\\u9053\\u7ecf\\u3002\", \"\\u83ab\\u5c06\\u5c71\\u6c34\\u5f04\\uff0c\\u6301\\u4e0e\\u4e16\\u4eba\\u542c\\u3002\"]"', '诗', 'shi', '', NULL, '蔡起居山亭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c1da5d-38cc-4efc-8154-b3ef4ce762df', '送友人尉蜀中', '送友人尉蜀中', 3fb650c9-e023-4f9e-94e1-62ffd2cebe45, '唐', '"[\"\\u6545\\u53cb\\u6f22\\u4e2d\\u5c09\\uff0c\\u8acb\\u7232\\u897f\\u8700\\u541f\\u3002\", \"\\u4eba\\u5bb6\\u591a\\u7a2e\\u6a58\\uff0c\\u98a8\\u571f\\u611b\\u5f48\\u7434\\u3002\", \"\\u6c34\\u5411\\u6606\\u660e\\u95ca\\uff0c\\u5c71\\u9023\\u5927\\u590f\\u6df1\\u3002\", \"\\u7406\\u9591\\u7121\\u5225\\u4e8b\\uff0c\\u6642\\u5bc4\\u4e00\\u767b\\u81e8\\u3002\"]"', '"[\"\\u6545\\u53cb\\u6c49\\u4e2d\\u5c09\\uff0c\\u8bf7\\u4e3a\\u897f\\u8700\\u541f\\u3002\", \"\\u4eba\\u5bb6\\u591a\\u79cd\\u6a58\\uff0c\\u98ce\\u571f\\u7231\\u5f39\\u7434\\u3002\", \"\\u6c34\\u5411\\u6606\\u660e\\u9614\\uff0c\\u5c71\\u8fde\\u5927\\u590f\\u6df1\\u3002\", \"\\u7406\\u95f2\\u65e0\\u522b\\u4e8b\\uff0c\\u65f6\\u5bc4\\u4e00\\u767b\\u4e34\\u3002\"]"', '诗', 'shi', '', NULL, '送友人尉蜀中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b95bf323-577f-42fe-9da9-b9f1f69fbc87', '贈溫駙馬汝陽王', '赠温驸马汝阳王', 3fb650c9-e023-4f9e-94e1-62ffd2cebe45, '唐', '"[\"\\u7587\\u6614\\u627f\\u9918\\u8ad6\\uff0c\\u6587\\u7ae0\\u5e78\\u6feb\\u63a8\\u3002\", \"\\u591c\\u966a\\u9280\\u6f22\\u8cde\\uff0c\\u671d\\u5949\\u6842\\u5c71\\u8a5e\\u3002\", \"\\u6881\\u90b8\\u8abf\\u6b4c\\u65e5\\uff0c\\u79e6\\u6a13\\u6309\\u821e\\u6642\\u3002\", \"\\u767b\\u9ad8\\u983b\\u4f5c\\u8ce6\\uff0c\\u9ad4\\u7269\\u5c62\\u7232\\u8a69\\u3002\", \"\\u9023\\u9a0e\\u9577\\u6978\\u4e0b\\uff0c\\u6d6e\\u89f4\\u66f2\\u6c34\\u6e44\\u3002\", \"\\u5317\\u5802\\u7559\\u4e0a\\u5ba2\\uff0c\\u5357\\u964c\\u9001\\u4f73\\u671f\\u3002\", \"\\u61b6\\u6628\\u966a\\u81e8\\u6cdb\\uff0c\\u4e8e\\u4eca\\u963b\\u5bb4\\u79c1\\u3002\", \"\\u518d\\u770b\\u51ac\\u96ea\\u6eff\\uff0c\\u4e09\\u898b\\u590f\\u82b1\\u6ecb\\u3002\", \"\\u90fd\\u5c09\\u671d\\u9752\\u95a3\\uff0c\\u6dee\\u738b\\u4f8d\\u7d2b\\u5880\\u3002\", \"\\u5be7\\u77e5\\u5026\\u904a\\u8005\\uff0c\\u83ef\\u9aea\\u8001\\u4eac\\u5e2b\\u3002\"]"', '"[\"\\u7574\\u6614\\u627f\\u4f59\\u8bba\\uff0c\\u6587\\u7ae0\\u5e78\\u6ee5\\u63a8\\u3002\", \"\\u591c\\u966a\\u94f6\\u6c49\\u8d4f\\uff0c\\u671d\\u5949\\u6842\\u5c71\\u8bcd\\u3002\", \"\\u6881\\u90b8\\u8c03\\u6b4c\\u65e5\\uff0c\\u79e6\\u697c\\u6309\\u821e\\u65f6\\u3002\", \"\\u767b\\u9ad8\\u9891\\u4f5c\\u8d4b\\uff0c\\u4f53\\u7269\\u5c61\\u4e3a\\u8bd7\\u3002\", \"\\u8fde\\u9a91\\u957f\\u6978\\u4e0b\\uff0c\\u6d6e\\u89de\\u66f2\\u6c34\\u6e44\\u3002\", \"\\u5317\\u5802\\u7559\\u4e0a\\u5ba2\\uff0c\\u5357\\u964c\\u9001\\u4f73\\u671f\\u3002\", \"\\u5fc6\\u6628\\u966a\\u4e34\\u6cdb\\uff0c\\u4e8e\\u4eca\\u963b\\u5bb4\\u79c1\\u3002\", \"\\u518d\\u770b\\u51ac\\u96ea\\u6ee1\\uff0c\\u4e09\\u89c1\\u590f\\u82b1\\u6ecb\\u3002\", \"\\u90fd\\u5c09\\u671d\\u9752\\u9601\\uff0c\\u6dee\\u738b\\u4f8d\\u7d2b\\u5880\\u3002\", \"\\u5b81\\u77e5\\u5026\\u6e38\\u8005\\uff0c\\u534e\\u9aea\\u8001\\u4eac\\u5e08\\u3002\"]"', '诗', 'shi', '', NULL, '贈溫駙馬汝陽王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6af505e6-9dc4-4d56-a151-107065d0c191', '邊詞', '边词', d013ccab-1a41-4f0d-9676-9c80d576e537, '唐', '"[\"\\u4e94\\u539f\\u6625\\u8272\\u820a\\u4f86\\u9072\\uff0c\\u4e8c\\u6708\\u5782\\u694a\\u672a\\u6302\\u7d72\\u3002\", \"\\u5373\\u4eca\\u6cb3\\u7554\\u51b0\\u958b\\u65e5\\uff0c\\u6b63\\u662f\\u9577\\u5b89\\u82b1\\u843d\\u6642\\u3002\"]"', '"[\"\\u4e94\\u539f\\u6625\\u8272\\u65e7\\u6765\\u8fdf\\uff0c\\u4e8c\\u6708\\u5782\\u6768\\u672a\\u6302\\u4e1d\\u3002\", \"\\u5373\\u4eca\\u6cb3\\u7554\\u51b0\\u5f00\\u65e5\\uff0c\\u6b63\\u662f\\u957f\\u5b89\\u82b1\\u843d\\u65f6\\u3002\"]"', '诗', 'shi', '', NULL, '邊詞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d7ab58e-41a1-43b3-8901-81fa6d8f1fd4', '戲詠', '戏咏', d013ccab-1a41-4f0d-9676-9c80d576e537, '唐', '"[\"\\u6709\\u610f\\u5acc\\u5175\\u90e8\\uff0c\\u5c08\\u5fc3\\u671b\\u8003\\u529f\\u3002\", \"\\u8ab0\\u77e5\\u811a\\u8e6d\\u8e6c\\uff0c\\u5e7e\\u843d\\u7701\\u7246\\u6771\\u3002\"]"', '"[\"\\u6709\\u610f\\u5acc\\u5175\\u90e8\\uff0c\\u4e13\\u5fc3\\u671b\\u8003\\u529f\\u3002\", \"\\u8c01\\u77e5\\u811a\\u8e6d\\u8e6c\\uff0c\\u51e0\\u843d\\u7701\\u5899\\u4e1c\\u3002\"]"', '诗', 'shi', '', NULL, '戲詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3593f695-a304-4798-a88c-4f9560f9ca6c', '孤燭歎', '孤烛叹', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u5207\\u5207\\u591c\\u95a8\\u51b7\\uff0c\\u5fae\\u5fae\\u5b64\\u71ed\\u7136\\u3002\", \"\\u7389\\u76e4\\u7d05\\u6dda\\u6ef4\\uff0c\\u91d1\\u71fc\\u5f69\\u5149\\u5713\\u3002\", \"\\u7156\\u624b\\u7e2b\\u8f15\\u7d20\\uff0c\\u56ac\\u86fe\\u7e8c\\u65b7\\u5f26\\u3002\", \"\\u76f8\\u601d\\u54bd\\u4e0d\\u8a9e\\uff0c\\u56de\\u5411\\u9326\\u5c4f\\u7720\\u3002\"]"', '"[\"\\u5207\\u5207\\u591c\\u95fa\\u51b7\\uff0c\\u5fae\\u5fae\\u5b64\\u70db\\u7136\\u3002\", \"\\u7389\\u76d8\\u7ea2\\u6cea\\u6ef4\\uff0c\\u91d1\\u70ec\\u5f69\\u5149\\u5706\\u3002\", \"\\u7156\\u624b\\u7f1d\\u8f7b\\u7d20\\uff0c\\u56ac\\u86fe\\u7eed\\u65ad\\u5f26\\u3002\", \"\\u76f8\\u601d\\u54bd\\u4e0d\\u8bed\\uff0c\\u56de\\u5411\\u9526\\u5c4f\\u7720\\u3002\"]"', '诗', 'shi', '', NULL, '孤燭歎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1bb2a4e-65f5-45e4-89de-cf69074551dc', '題巴州光福寺楠木', '题巴州光福寺楠木', a22f866e-1822-4e69-b77e-6932e52836a6, '唐', '"[\"\\u8fd1\\u90ed\\u57ce\\u5357\\u5c71\\u5bfa\\u6df1\\uff0c\\u4ead\\u4ead\\u5947\\u6a39\\u51fa\\u79aa\\u6797\\u3002\", \"\\u7d50\\u6839\\u5e7d\\u58d1\\u4e0d\\u77e5\\u6b72\\uff0c\\u8073\\u5e79\\u6469\\u5929\\u51e1\\u5e7e\\u5c0b\\u3002\", \"\\u7fe0\\u8272\\u665a\\u5c07\\u5d50\\u6c23\\u5408\\uff0c\\u6708\\u5149\\u6642\\u6709\\u591c\\u7328\\u541f\\u3002\", \"\\u7d93\\u884c\\u7da0\\u8449\\u671b\\u6210\\u84cb\\uff0c\\u5bb4\\u5750\\u9ec3\\u82b1\\u9577\\u6eff\\u895f\\u3002\", \"\\u6b64\\u6728\\u5617\\u805e\\u751f\\u8c6b\\u7ae0\\uff0c\\u4eca\\u671d\\u7368\\u79c0\\u5728\\u5df4\\u9109\\u3002\", \"\\u51cc\\u971c\\u4e0d\\u80af\\u8b93\\u677e\\u67cf\\uff0c\\u4f5c\\u5b87\\u7531\\u4f86\\u7a31\\u68df\\u6881\\u3002\", \"\\u6703\\u5f85\\u826f\\u5de5\\u6642\\u4e00\\u7704\\uff0c\\u61c9\\u6b78\\u6cd5\\u6c34\\u4f5c\\u6148\\u822a\\u3002\"]"', '"[\"\\u8fd1\\u90ed\\u57ce\\u5357\\u5c71\\u5bfa\\u6df1\\uff0c\\u4ead\\u4ead\\u5947\\u6811\\u51fa\\u7985\\u6797\\u3002\", \"\\u7ed3\\u6839\\u5e7d\\u58d1\\u4e0d\\u77e5\\u5c81\\uff0c\\u8038\\u5e72\\u6469\\u5929\\u51e1\\u51e0\\u5bfb\\u3002\", \"\\u7fe0\\u8272\\u665a\\u5c06\\u5c9a\\u6c14\\u5408\\uff0c\\u6708\\u5149\\u65f6\\u6709\\u591c\\u7328\\u541f\\u3002\", \"\\u7ecf\\u884c\\u7eff\\u53f6\\u671b\\u6210\\u76d6\\uff0c\\u5bb4\\u5750\\u9ec4\\u82b1\\u957f\\u6ee1\\u895f\\u3002\", \"\\u6b64\\u6728\\u5c1d\\u95fb\\u751f\\u8c6b\\u7ae0\\uff0c\\u4eca\\u671d\\u72ec\\u79c0\\u5728\\u5df4\\u4e61\\u3002\", \"\\u51cc\\u971c\\u4e0d\\u80af\\u8ba9\\u677e\\u67cf\\uff0c\\u4f5c\\u5b87\\u7531\\u6765\\u79f0\\u680b\\u6881\\u3002\", \"\\u4f1a\\u5f85\\u826f\\u5de5\\u65f6\\u4e00\\u7704\\uff0c\\u5e94\\u5f52\\u6cd5\\u6c34\\u4f5c\\u6148\\u822a\\u3002\"]"', '诗', 'shi', '', NULL, '題巴州光福寺楠木 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b360c829-c8f4-43c2-80b7-6bbfc58e0ec3', '儀坤廟樂章 永和', '仪坤庙乐章 永和', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u7317\\u82e5\\u6e05\\u5edf\\uff0c\\u8085\\u8085\\u7192\\u7192\\u3002\", \"\\u570b\\u85a6\\u56b4\\u7940\\uff0c\\u5764\\u8208\\u6dd1\\u9748\\u3002\", \"\\u6709\\u51e0\\u5728\\u5ba4\\uff0c\\u6709\\u6a02\\u5728\\u5ead\\u3002\", \"\\u81e8\\u8332\\u5b5d\\u4eab\\uff0c\\u767e\\u797f\\u60df\\u5be7\\u3002\"]"', '"[\"\\u7317\\u82e5\\u6e05\\u5e99\\uff0c\\u8083\\u8083\\u8367\\u8367\\u3002\", \"\\u56fd\\u8350\\u4e25\\u7940\\uff0c\\u5764\\u5174\\u6dd1\\u7075\\u3002\", \"\\u6709\\u51e0\\u5728\\u5ba4\\uff0c\\u6709\\u4e50\\u5728\\u5ead\\u3002\", \"\\u4e34\\u5179\\u5b5d\\u4eab\\uff0c\\u767e\\u7984\\u60df\\u5b81\\u3002\"]"', '诗', 'shi', '', NULL, '儀坤廟樂章 永和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91381b63-1bfb-4ea1-be84-2e5dad0e2c5a', '儀坤廟樂章 金奏', '仪坤庙乐章 金奏', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u9670\\u9748\\u6548\\u7949\\uff0c\\u8ed2\\u66dc\\u964d\\u7cbe\\u3002\", \"\\u7965\\u7b26\\u6dd1\\u6c23\\uff0c\\u6176\\u96c6\\u67d4\\u660e\\u3002\", \"\\u7464\\u4fce\\u65e2\\u5217\\uff0c\\u96d5\\u6850\\u767c\\u8072\\u3002\", \"\\u5fbd\\u7337\\u6c38\\u9060\\uff0c\\u6bd4\\u5fb7\\u7687\\u82f1\\u3002\"]"', '"[\"\\u9634\\u7075\\u6548\\u7949\\uff0c\\u8f69\\u66dc\\u964d\\u7cbe\\u3002\", \"\\u7965\\u7b26\\u6dd1\\u6c14\\uff0c\\u5e86\\u96c6\\u67d4\\u660e\\u3002\", \"\\u7476\\u4fce\\u65e2\\u5217\\uff0c\\u96d5\\u6850\\u53d1\\u58f0\\u3002\", \"\\u5fbd\\u7337\\u6c38\\u8fdc\\uff0c\\u6bd4\\u5fb7\\u7687\\u82f1\\u3002\"]"', '诗', 'shi', '', NULL, '儀坤廟樂章 金奏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7bacec6-3ae8-40d5-900e-b5056ee1b774', '擬古三首 一', '拟古三首 一', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u9059\\u88d4\\u7159\\u5dbc\\u9d3b\\uff0c\\u96d9\\u5f71\\u65e6\\u5915\\u540c\\u3002\", \"\\u4ea4\\u7ff0\\u501a\\u6c99\\u6708\\uff0c\\u548c\\u9cf4\\u5f04\\u6c5f\\u98a8\\u3002\", \"\\ud85b\\udd9c\\u82e5\\u8302\\u82b3\\u5e8f\\uff0c\\u541b\\u5b50\\u5f9e\\u9060\\u620e\\u3002\", \"\\u96f2\\u751f\\u9670\\u6d77\\u6c92\\uff0c\\u82b1\\u843d\\u6625\\u6f6d\\u7a7a\\u3002\", \"\\u7d05\\u6dda\\u63a9\\u4fc3\\u67f1\\uff0c\\u9326\\u887e\\u7f85\\u85b0\\u7c60\\u3002\", \"\\u81ea\\u50b7\\u74ca\\u8349\\u7da0\\uff0c\\u8a4e\\u60dc\\u925b\\u7c89\\u7d05\\u3002\", \"\\u88c2\\u5e1b\\u9644\\u96d9\\u71d5\\uff0c\\u7232\\u4e88\\u5411\\u907c\\u6771\\u3002\"]"', '"[\"\\u9065\\u88d4\\u70df\\u5c7f\\u9e3f\\uff0c\\u53cc\\u5f71\\u65e6\\u5915\\u540c\\u3002\", \"\\u4ea4\\u7ff0\\u501a\\u6c99\\u6708\\uff0c\\u548c\\u9e23\\u5f04\\u6c5f\\u98ce\\u3002\", \"\\ud85b\\udd9c\\u82e5\\u8302\\u82b3\\u5e8f\\uff0c\\u541b\\u5b50\\u4ece\\u8fdc\\u620e\\u3002\", \"\\u4e91\\u751f\\u9634\\u6d77\\u6ca1\\uff0c\\u82b1\\u843d\\u6625\\u6f6d\\u7a7a\\u3002\", \"\\u7ea2\\u6cea\\u63a9\\u4fc3\\u67f1\\uff0c\\u9526\\u887e\\u7f57\\u85b0\\u7b3c\\u3002\", \"\\u81ea\\u4f24\\u743c\\u8349\\u7eff\\uff0c\\u8bb5\\u60dc\\u94c5\\u7c89\\u7ea2\\u3002\", \"\\u88c2\\u5e1b\\u9644\\u53cc\\u71d5\\uff0c\\u4e3a\\u4e88\\u5411\\u8fbd\\u4e1c\\u3002\"]"', '诗', 'shi', '', NULL, '擬古三首 一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('563ad62a-c721-4e4f-acd2-cf49f805c6a6', '擬古三首 二', '拟古三首 二', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u8b80\\u66f8\\u4e09\\u5341\\u8f09\\uff0c\\u99b3\\u9a16\\u5468\\u516d\\u7d93\\u3002\", \"\\u5112\\u8863\\u5e72\\u6642\\u4e3b\\uff0c\\u5fe0\\u7b56\\u737b\\u95d5\\u5ef7\\u3002\", \"\\u4e00\\u671d\\u5949\\u4f11\\u76fc\\uff0c\\u5f9e\\u5bb9\\u5ec1\\u7fa3\\u82f1\\u3002\", \"\\u675f\\u8eab\\u8da8\\u5efa\\u79ae\\uff0c\\u79c9\\u7b46\\u5750\\u627f\\u660e\\u3002\", \"\\u5ee8\\u7f72\\u76f8\\u586b\\u564e\\uff0c\\u50da\\u540f\\u7d1b\\u7e31\\u6a6b\\u3002\", \"\\u4e94\\u65e5\\u4f11\\u6fa3\\u6642\\uff0c\\u5c60\\u8607\\u7e5e\\u7389\\u5c4f\\u3002\", \"\\u6a58\\u82b1\\u8986\\u5317\\u6cbc\\uff0c\\u6842\\u6a39\\u4ea4\\u897f\\u69ae\\u3002\", \"\\u6a39\\u68f2\\u5169\\u9d1b\\u9d26\\uff0c\\u542b\\u6625\\u5411\\u6211\\u9cf4\\u3002\", \"\\u768e\\u6f54\\u7dba\\u7f85\\u8c54\\uff0c\\u4fbf\\u5a1f\\u7d72\\u7ba1\\u6e05\\u3002\", \"\\u64fe\\u64fe\\u5929\\u5730\\u9593\\uff0c\\u51fa\\u8655\\u5404\\u6709\\u60c5\\u3002\", \"\\u4f55\\u5fc5\\u5dd6\\u77f3\\u4e0b\\uff0c\\u67af\\u69c1\\u9591\\u6b64\\u751f\\u3002\"]"', '"[\"\\u8bfb\\u4e66\\u4e09\\u5341\\u8f7d\\uff0c\\u9a70\\u9a9b\\u5468\\u516d\\u7ecf\\u3002\", \"\\u5112\\u8863\\u5e72\\u65f6\\u4e3b\\uff0c\\u5fe0\\u7b56\\u732e\\u9619\\u5ef7\\u3002\", \"\\u4e00\\u671d\\u5949\\u4f11\\u76fc\\uff0c\\u4ece\\u5bb9\\u5395\\u7fa4\\u82f1\\u3002\", \"\\u675f\\u8eab\\u8d8b\\u5efa\\u793c\\uff0c\\u79c9\\u7b14\\u5750\\u627f\\u660e\\u3002\", \"\\u5ee8\\u7f72\\u76f8\\u586b\\u564e\\uff0c\\u50da\\u540f\\u7eb7\\u7eb5\\u6a2a\\u3002\", \"\\u4e94\\u65e5\\u4f11\\u6fa3\\u65f6\\uff0c\\u5c60\\u82cf\\u7ed5\\u7389\\u5c4f\\u3002\", \"\\u6a58\\u82b1\\u8986\\u5317\\u6cbc\\uff0c\\u6842\\u6811\\u4ea4\\u897f\\u8363\\u3002\", \"\\u6811\\u6816\\u4e24\\u9e33\\u9e2f\\uff0c\\u542b\\u6625\\u5411\\u6211\\u9e23\\u3002\", \"\\u768e\\u6d01\\u7eee\\u7f57\\u8273\\uff0c\\u4fbf\\u5a1f\\u4e1d\\u7ba1\\u6e05\\u3002\", \"\\u6270\\u6270\\u5929\\u5730\\u95f4\\uff0c\\u51fa\\u5904\\u5404\\u6709\\u60c5\\u3002\", \"\\u4f55\\u5fc5\\u5ca9\\u77f3\\u4e0b\\uff0c\\u67af\\u69c1\\u95f2\\u6b64\\u751f\\u3002\"]"', '诗', 'shi', '', NULL, '擬古三首 二 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3a64c16-4c41-4b43-baba-e3b6795b0dd5', '擬古三首 三', '拟古三首 三', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u983d\\u5149\\u7121\\u6df9\\u6677\\uff0c\\u901d\\u6c34\\u6709\\u8fc5\\u6d41\\u3002\", \"\\u7da0\\u82d4\\u7d1b\\u6613\\u6b47\\uff0c\\u7d05\\u984f\\u4e0d\\u518d\\u6c42\\u3002\", \"\\u6b4c\\u7b11\\u7576\\u53ca\\u6625\\uff0c\\u7121\\u4ee4\\u58ef\\u5fd7\\u79cb\\u3002\", \"\\u5f31\\u5e74\\u4ed5\\u95dc\\u8f14\\uff0c\\u7c03\\u9580\\u8c41\\u5fa1\\u6e9d\\u3002\", \"\\u6577\\u6109\\u6771\\u57ce\\u969b\\uff0c\\u5a49\\u5b4c\\u5357\\u964c\\u982d\\u3002\", \"\\u8377\\u82b1\\u5b0c\\u7da0\\u6c34\\uff0c\\u694a\\u8449\\u6696\\u9752\\u6a13\\u3002\", \"\\u4e2d\\u6709\\u7dba\\u7f85\\u4eba\\uff0c\\u53ef\\u6190\\u540d\\u83ab\\u6101\\u3002\", \"\\u756b\\u5c4f\\u7e5e\\u91d1\\u819d\\uff0c\\u73e0\\u7c3e\\u61f8\\u7389\\u9264\\u3002\", \"\\u7e96\\u6307\\u8abf\\u5bf6\\u7434\\uff0c\\u6ce0\\u6ce0\\u54c0\\u4e14\\u67d4\\u3002\", \"\\u8d08\\u541b\\u9d1b\\u9d26\\u5e36\\uff0c\\u56e0\\u4ee5\\u9deb\\u9e18\\u88d8\\u3002\", \"\\u7a97\\u66c9\\u541f\\u65e5\\u5750\\uff0c\\u95a8\\u5915\\u79c9\\u71ed\\u904a\\u3002\", \"\\u7121\\u4f5c\\u5317\\u9580\\u5ba2\\uff0c\\u5484\\u5484\\u61f7\\u767e\\u6182\\u3002\"]"', '"[\"\\u9893\\u5149\\u65e0\\u6df9\\u6677\\uff0c\\u901d\\u6c34\\u6709\\u8fc5\\u6d41\\u3002\", \"\\u7eff\\u82d4\\u7eb7\\u6613\\u6b47\\uff0c\\u7ea2\\u989c\\u4e0d\\u518d\\u6c42\\u3002\", \"\\u6b4c\\u7b11\\u5f53\\u53ca\\u6625\\uff0c\\u65e0\\u4ee4\\u58ee\\u5fd7\\u79cb\\u3002\", \"\\u5f31\\u5e74\\u4ed5\\u5173\\u8f85\\uff0c\\u7c03\\u95e8\\u8c41\\u5fa1\\u6c9f\\u3002\", \"\\u6577\\u6109\\u4e1c\\u57ce\\u9645\\uff0c\\u5a49\\u5a08\\u5357\\u964c\\u5934\\u3002\", \"\\u8377\\u82b1\\u5a07\\u7eff\\u6c34\\uff0c\\u6768\\u53f6\\u6696\\u9752\\u697c\\u3002\", \"\\u4e2d\\u6709\\u7eee\\u7f57\\u4eba\\uff0c\\u53ef\\u601c\\u540d\\u83ab\\u6101\\u3002\", \"\\u753b\\u5c4f\\u7ed5\\u91d1\\u819d\\uff0c\\u73e0\\u5e18\\u60ac\\u7389\\u94a9\\u3002\", \"\\u7ea4\\u6307\\u8c03\\u5b9d\\u7434\\uff0c\\u6ce0\\u6ce0\\u54c0\\u4e14\\u67d4\\u3002\", \"\\u8d60\\u541b\\u9e33\\u9e2f\\u5e26\\uff0c\\u56e0\\u4ee5\\u9e54\\u9e74\\u88d8\\u3002\", \"\\u7a97\\u6653\\u541f\\u65e5\\u5750\\uff0c\\u95fa\\u5915\\u79c9\\u70db\\u6e38\\u3002\", \"\\u65e0\\u4f5c\\u5317\\u95e8\\u5ba2\\uff0c\\u5484\\u5484\\u6000\\u767e\\u5fe7\\u3002\"]"', '诗', 'shi', '', NULL, '擬古三首 三 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7192e233-66b2-4182-9ef7-727e18f9f48a', '贈劉舍人古意', '赠刘舍人古意', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u5973\\u7240\\u959f\\u9748\\u9ce5\\uff0c\\u6587\\u7ae0\\u4e16\\u6240\\u5e0c\\u3002\", \"\\u5de2\\u541b\\u78a7\\u68a7\\u6a39\\uff0c\\u821e\\u541b\\u9752\\u7463\\u95c8\\u3002\", \"\\u6216\\u8a00\\u9cf3\\u6c60\\u6a02\\uff0c\\u64ab\\u7ffc\\u66f4\\u897f\\u98db\\u3002\", \"\\u9cf3\\u6c60\\u74b0\\u7981\\u6797\\uff0c\\u4ed9\\u95a3\\u9744\\u6c88\\u6c88\\u3002\", \"\\u7487\\u984c\\u6fc0\\u6d41\\u65e5\\uff0c\\u73e0\\u7db4\\u7ddc\\u6e05\\u9670\\u3002\", \"\\u90c1\\u7a46\\u7d72\\u8a00\\u91cd\\uff0c\\u7192\\u714c\\u53f0\\u5ea7\\u6df1\\u3002\", \"\\u98a8\\u5f35\\u4e39\\u623a\\u7fee\\uff0c\\u6708\\u5f04\\u7d2b\\u5ead\\u97f3\\u3002\", \"\\u8846\\u7db5\\u7d50\\u4e0d\\u6563\\uff0c\\u5b64\\u82f1\\u8dc2\\u83ab\\u5c0b\\u3002\", \"\\u6d69\\u6b4c\\u5728\\u897f\\u7701\\uff0c\\u7d93\\u50b3\\u6063\\u6f5b\\u5fc3\\u3002\"]"', '"[\"\\u5973\\u5e8a\\u959f\\u7075\\u9e1f\\uff0c\\u6587\\u7ae0\\u4e16\\u6240\\u5e0c\\u3002\", \"\\u5de2\\u541b\\u78a7\\u68a7\\u6811\\uff0c\\u821e\\u541b\\u9752\\u7410\\u95f1\\u3002\", \"\\u6216\\u8a00\\u51e4\\u6c60\\u4e50\\uff0c\\u629a\\u7ffc\\u66f4\\u897f\\u98de\\u3002\", \"\\u51e4\\u6c60\\u73af\\u7981\\u6797\\uff0c\\u4ed9\\u9601\\u972d\\u6c88\\u6c88\\u3002\", \"\\u7487\\u9898\\u6fc0\\u6d41\\u65e5\\uff0c\\u73e0\\u7f00\\u7ddc\\u6e05\\u9634\\u3002\", \"\\u90c1\\u7a46\\u4e1d\\u8a00\\u91cd\\uff0c\\u8367\\u714c\\u53f0\\u5ea7\\u6df1\\u3002\", \"\\u98ce\\u5f20\\u4e39\\u623a\\u7fee\\uff0c\\u6708\\u5f04\\u7d2b\\u5ead\\u97f3\\u3002\", \"\\u4f17\\u5f69\\u7ed3\\u4e0d\\u6563\\uff0c\\u5b64\\u82f1\\u8dc2\\u83ab\\u5bfb\\u3002\", \"\\u6d69\\u6b4c\\u5728\\u897f\\u7701\\uff0c\\u7ecf\\u4f20\\u6063\\u6f5c\\u5fc3\\u3002\"]"', '诗', 'shi', '', NULL, '贈劉舍人古意 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97e76ef8-a9b7-4516-858e-f1f676a70608', '和李適荅宋十一入崖口五渡見贈', '和李适荅宋十一入崖口五渡见赠', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u805e\\u6709\\u7368\\u5f80\\u5ba2\\uff0c\\u62c2\\u8863\\u6350\\u4e16\\u5fc3\\u3002\", \"\\u7d50\\u6b23\\u8584\\u6789\\u6e1a\\uff0c\\u64b0\\u5ff5\\u7e08\\u820a\\u6797\\u3002\", \"\\u7d93\\u4e99\\u53bb\\u5d16\\u5408\\uff0c\\u51a5\\u7ddc\\u6b78\\u58d1\\u6df1\\u3002\", \"\\u742a\\u6a39\\u74b0\\u78a7\\u5f69\\uff0c\\u91d1\\u6f6d\\u751f\\u7fe0\\u9670\\u3002\", \"\\u6cbf\\u6d04\\u5f04\\u6c99\\u699c\\uff0c\\u8a6d\\u4ec4\\u773a\\u660e\\u5c91\\u3002\", \"\\u5915\\u805e\\u6842\\u88cf\\u733f\\uff0c\\u66c9\\u73a9\\u677e\\u4e0a\\u79bd\\u3002\", \"\\u96dc\\u4f69\\u860a\\u5b64\\u8896\\uff0c\\u74ca\\u6577\\u7db4\\u96d9\\u895f\\u3002\", \"\\u6211\\u61f7\\u6ec4\\u5dde\\u60f3\\uff0c\\u61ff\\u723e\\u767d\\u96f2\\u541f\\u3002\", \"\\u79c9\\u9858\\u7406\\u65b9\\u5354\\uff0c\\u5b58\\u671f\\u8de1\\u6613\\u5c0b\\u3002\", \"\\u8332\\u8a00\\u5eb6\\u4e0d\\u8ca0\\uff0c\\u7232\\u5831\\u5dd6\\u4e2d\\u7434\\u3002\"]"', '"[\"\\u95fb\\u6709\\u72ec\\u5f80\\u5ba2\\uff0c\\u62c2\\u8863\\u6350\\u4e16\\u5fc3\\u3002\", \"\\u7ed3\\u6b23\\u8584\\u6789\\u6e1a\\uff0c\\u64b0\\u5ff5\\u8426\\u65e7\\u6797\\u3002\", \"\\u7ecf\\u4e98\\u53bb\\u5d16\\u5408\\uff0c\\u51a5\\u7ddc\\u5f52\\u58d1\\u6df1\\u3002\", \"\\u742a\\u6811\\u73af\\u78a7\\u5f69\\uff0c\\u91d1\\u6f6d\\u751f\\u7fe0\\u9634\\u3002\", \"\\u6cbf\\u6d04\\u5f04\\u6c99\\u699c\\uff0c\\u8be1\\u4ec4\\u773a\\u660e\\u5c91\\u3002\", \"\\u5915\\u95fb\\u6842\\u91cc\\u733f\\uff0c\\u6653\\u73a9\\u677e\\u4e0a\\u79bd\\u3002\", \"\\u6742\\u4f69\\u8574\\u5b64\\u8896\\uff0c\\u743c\\u6577\\u7f00\\u53cc\\u895f\\u3002\", \"\\u6211\\u6000\\u6ca7\\u5dde\\u60f3\\uff0c\\u61ff\\u5c14\\u767d\\u4e91\\u541f\\u3002\", \"\\u79c9\\u613f\\u7406\\u65b9\\u534f\\uff0c\\u5b58\\u671f\\u8ff9\\u6613\\u5bfb\\u3002\", \"\\u5179\\u8a00\\u5eb6\\u4e0d\\u8d1f\\uff0c\\u4e3a\\u62a5\\u5ca9\\u4e2d\\u7434\\u3002\"]"', '诗', 'shi', '', NULL, '和李適荅宋十一入崖口五渡見贈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb06e97-1e2c-43af-8c71-650c6b96a319', '雪', '雪', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u96ea\\u6697\\u7aae\\u6d77\\u96f2\\uff0c\\u7051\\u7a7a\\u7d1b\\u4f3c\\u9732\\u3002\", \"\\u6714\\u98a8\\u5439\\u6545\\u91cc\\uff0c\\u5b9b\\u8f49\\u7389\\u968e\\u6a39\\u3002\", \"\\u5b64\\u59be\\u8abf\\u7389\\u745f\\uff0c\\u65e9\\u5bd2\\u751f\\u9326\\u887f\\u3002\", \"\\u6cc1\\u541b\\u5f35\\u7f85\\u5e55\\uff0c\\u6101\\u5750\\u5317\\u5ead\\u9670\\u3002\"]"', '"[\"\\u96ea\\u6697\\u7a77\\u6d77\\u4e91\\uff0c\\u6d12\\u7a7a\\u7eb7\\u4f3c\\u9732\\u3002\", \"\\u6714\\u98ce\\u5439\\u6545\\u91cc\\uff0c\\u5b9b\\u8f6c\\u7389\\u9636\\u6811\\u3002\", \"\\u5b64\\u59be\\u8c03\\u7389\\u745f\\uff0c\\u65e9\\u5bd2\\u751f\\u9526\\u887f\\u3002\", \"\\u51b5\\u541b\\u5f20\\u7f57\\u5e55\\uff0c\\u6101\\u5750\\u5317\\u5ead\\u9634\\u3002\"]"', '诗', 'shi', '', NULL, '雪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6da4458b-9bed-44cd-94a7-e727694eca08', '閨怨', '闺怨', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u5f81\\u5ba2\\u620d\\u91d1\\u5fae\\uff0c\\u6101\\u95a8\\u7368\\u63a9\\u6249\\u3002\", \"\\u5875\\u57c3\\u751f\\u534a\\u69bb\\uff0c\\u82b1\\u7d6e\\u843d\\u6b98\\u6a5f\\u3002\", \"\\u892a\\u6696\\u8836\\u521d\\u81e5\\uff0c\\u5de2\\u660f\\u71d5\\u6b32\\u6b78\\u3002\", \"\\u6625\\u98a8\\u65e5\\u5411\\u76e1\\uff0c\\u929c\\u6d95\\u4f5c\\u5f81\\u8863\\u3002\"]"', '"[\"\\u5f81\\u5ba2\\u620d\\u91d1\\u5fae\\uff0c\\u6101\\u95fa\\u72ec\\u63a9\\u6249\\u3002\", \"\\u5c18\\u57c3\\u751f\\u534a\\u69bb\\uff0c\\u82b1\\u7d6e\\u843d\\u6b8b\\u673a\\u3002\", \"\\u892a\\u6696\\u8695\\u521d\\u5367\\uff0c\\u5de2\\u660f\\u71d5\\u6b32\\u5f52\\u3002\", \"\\u6625\\u98ce\\u65e5\\u5411\\u5c3d\\uff0c\\u8854\\u6d95\\u4f5c\\u5f81\\u8863\\u3002\"]"', '诗', 'shi', '', NULL, '閨怨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('292c8496-d05b-4873-af39-b950f3ea89da', '句', '句', 7b739f70-3d40-46aa-80a8-8fc1cb00c277, '唐', '"[\"\\u5730\\u9748\\u7121\\u4fd7\\u8349\\uff0c\\u5ca9\\u975c\\u6709\\u50ca\\u79bd\\u3002\"]"', '"[\"\\u5730\\u7075\\u65e0\\u4fd7\\u8349\\uff0c\\u5ca9\\u9759\\u6709\\u50ca\\u79bd\\u3002\"]"', '诗', 'shi', '', NULL, '句 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecd48411-6a89-46a3-a9b9-983d40022276', '比干墓', '比干墓', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u5927\\u4f4d\\u5929\\u4e0b\\u5bf6\\uff0c\\u7dad\\u8ce2\\u570b\\u4e4b\\u93ae\\u3002\", \"\\u6bb7\\u9053\\u5fae\\u800c\\u5728\\uff0c\\u53d7\\u8f9b\\u7e82\\u9839\\u80e4\\u3002\", \"\\u5c71\\u9cf4\\u9b3c\\u53c8\\u54ed\\uff0c\\u5730\\u88c2\\u5ddd\\u4ea6\\u9707\\u3002\", \"\\u5a9f\\u9ef7\\u7686\\u4f5e\\u8adb\\uff0c\\u8654\\u5289\\u76e1\\u82f1\\u96cb\\u3002\", \"\\u5b64\\u537f\\u5e1d\\u53d4\\u7236\\uff0c\\u7279\\u9032\\u8c9e\\u800c\\u9806\\u3002\", \"\\u7389\\u7240\\u903e\\u769c\\u6f54\\uff0c\\u9285\\u67f1\\u65b9\\u6b4a\\u712e\\u3002\", \"\\u5949\\u570b\\u6b77\\u4e09\\u671d\\uff0c\\u89c0\\u7ac5\\u660e\\u4e00\\u77ac\\u3002\", \"\\u5b63\\u4ee3\\u7316\\u72c2\\u4e3b\\uff0c\\u84c4\\u6012\\u63d0\\u767d\\u5203\\u3002\", \"\\u4e4b\\u5b50\\u5f4c\\u5fe0\\u8b9c\\uff0c\\u61a4\\u7136\\u66f4\\u52c7\\u9032\\u3002\", \"\\u64ab\\u81ba\\u8a93\\u9695\\u8d8a\\uff0c\\u77e5\\u6b7b\\u6545\\u4e0d\\u6061\\u3002\", \"\\u5df2\\u77e3\\u7adf\\u5256\\u5fc3\\uff0c\\u54f2\\u5a66\\u4ea6\\u540c\\u6b89\\u3002\", \"\\u9a6a\\u9f8d\\u66b4\\u96d9\\u9aa8\\uff0c\\u592a\\u5dbd\\u6467\\u5b64\\u4ede\\u3002\", \"\\u5468\\u767c\\u6b21\\u5546\\u90ca\\uff0c\\u51a4\\u9ab8\\u60b2\\u83ab\\u6ba3\\u3002\", \"\\u92d2\\u5292\\u527f\\u907a\\u5b7d\\uff0c\\u5831\\u5fa9\\u4e00\\u4f55\\u8fc5\\u3002\", \"\\u99d0\\u7f55\\u6b4c\\u6dd1\\u9748\\uff0c\\u547d\\u5f92\\u5c0d\\u65c5\\u6aec\\u3002\", \"\\u81ea\\u723e\\u929c\\u5e7d\\u9177\\uff0c\\u4e8e\\u55df\\u6d41\\u666f\\u99ff\\u3002\", \"\\u4e18\\u58b3\\u88ab\\u5bbf\\u83bd\\uff0c\\u58c7\\u623a\\u7de3\\u98db\\u71d0\\u3002\", \"\\u8c9e\\u89c0\\u6212\\u5317\\u5f81\\uff0c\\u7dad\\u7687\\u5ff5\\u5fe0\\u4fe1\\u3002\", \"\\u8352\\u58b3\\u8b77\\u8349\\u6728\\uff0c\\u523b\\u6877\\u5439\\u7168\\u71fc\\u3002\", \"\\u4ee3\\u9060\\u6069\\u66f4\\u5d07\\uff0c\\u8eab\\u9839\\u540d\\u76ca\\u632f\\u3002\", \"\\u5e1d\\u8a5e\\u66f8\\u6a02\\u77f3\\uff0c\\u570b\\u994c\\u7f85\\u82b3\\u8845\\u3002\", \"\\u5049\\u54c9\\u70c8\\u58eb\\u5716\\uff0c\\u5947\\u82f1\\u5343\\u53e4\\u5f87\\u3002\"]"', '"[\"\\u5927\\u4f4d\\u5929\\u4e0b\\u5b9d\\uff0c\\u7ef4\\u8d24\\u56fd\\u4e4b\\u9547\\u3002\", \"\\u6bb7\\u9053\\u5fae\\u800c\\u5728\\uff0c\\u53d7\\u8f9b\\u7e82\\u9893\\u80e4\\u3002\", \"\\u5c71\\u9e23\\u9b3c\\u53c8\\u54ed\\uff0c\\u5730\\u88c2\\u5ddd\\u4ea6\\u9707\\u3002\", \"\\u5a9f\\u9ee9\\u7686\\u4f5e\\u8c00\\uff0c\\u8654\\u5218\\u5c3d\\u82f1\\u96bd\\u3002\", \"\\u5b64\\u537f\\u5e1d\\u53d4\\u7236\\uff0c\\u7279\\u8fdb\\u8d1e\\u800c\\u987a\\u3002\", \"\\u7389\\u5e8a\\u903e\\u769c\\u6d01\\uff0c\\u94dc\\u67f1\\u65b9\\u6b4a\\u712e\\u3002\", \"\\u5949\\u56fd\\u5386\\u4e09\\u671d\\uff0c\\u89c2\\u7a8d\\u660e\\u4e00\\u77ac\\u3002\", \"\\u5b63\\u4ee3\\u7316\\u72c2\\u4e3b\\uff0c\\u84c4\\u6012\\u63d0\\u767d\\u5203\\u3002\", \"\\u4e4b\\u5b50\\u5f25\\u5fe0\\u8c20\\uff0c\\u6124\\u7136\\u66f4\\u52c7\\u8fdb\\u3002\", \"\\u629a\\u81ba\\u8a93\\u9668\\u8d8a\\uff0c\\u77e5\\u6b7b\\u6545\\u4e0d\\u6061\\u3002\", \"\\u5df2\\u77e3\\u7adf\\u5256\\u5fc3\\uff0c\\u54f2\\u5987\\u4ea6\\u540c\\u6b89\\u3002\", \"\\u9a8a\\u9f99\\u66b4\\u53cc\\u9aa8\\uff0c\\u592a\\u5cb3\\u6467\\u5b64\\u4ede\\u3002\", \"\\u5468\\u53d1\\u6b21\\u5546\\u90ca\\uff0c\\u51a4\\u9ab8\\u60b2\\u83ab\\u6ba3\\u3002\", \"\\u950b\\u5292\\u527f\\u9057\\u5b7d\\uff0c\\u62a5\\u590d\\u4e00\\u4f55\\u8fc5\\u3002\", \"\\u9a7b\\u7f55\\u6b4c\\u6dd1\\u7075\\uff0c\\u547d\\u5f92\\u5bf9\\u65c5\\u6987\\u3002\", \"\\u81ea\\u5c14\\u8854\\u5e7d\\u9177\\uff0c\\u4e8e\\u55df\\u6d41\\u666f\\u9a8f\\u3002\", \"\\u4e18\\u575f\\u88ab\\u5bbf\\u83bd\\uff0c\\u575b\\u623a\\u7f18\\u98de\\u71d0\\u3002\", \"\\u8d1e\\u89c2\\u6212\\u5317\\u5f81\\uff0c\\u7ef4\\u7687\\u5ff5\\u5fe0\\u4fe1\\u3002\", \"\\u8352\\u575f\\u62a4\\u8349\\u6728\\uff0c\\u523b\\u6877\\u5439\\u7168\\u70ec\\u3002\", \"\\u4ee3\\u8fdc\\u6069\\u66f4\\u5d07\\uff0c\\u8eab\\u9893\\u540d\\u76ca\\u632f\\u3002\", \"\\u5e1d\\u8bcd\\u4e66\\u4e50\\u77f3\\uff0c\\u56fd\\u9994\\u7f57\\u82b3\\u8845\\u3002\", \"\\u4f1f\\u54c9\\u70c8\\u58eb\\u56fe\\uff0c\\u5947\\u82f1\\u5343\\u53e4\\u5f87\\u3002\"]"', '诗', 'shi', '', NULL, '比干墓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41f61f3e-a75d-4618-b8cb-395295f56696', '題東山子李適碑陰二首 一', '题东山子李适碑阴二首 一', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u96b4\\u5d82\\u7e08\\u7d2b\\u6c23\\uff0c\\u91d1\\u5149\\u8d6b\\u6c1b\\u6c33\\u3002\", \"\\u7f8e\\u4eba\\u542b\\u9059\\u9744\\uff0c\\u6843\\u674e\\u82b3\\u81ea\\u85b0\\u3002\", \"\\u5716\\u9ad8\\u9ec3\\u9db4\\u7fbd\\uff0c\\u5bf6\\u596a\\u9a6a\\u9f8d\\u7fa3\\u3002\", \"\\u5ffd\\u9a5a\\u85a4\\u9732\\u66f2\\uff0c\\u63a9\\u564e\\u6771\\u5c71\\u96f2\\u3002\"]"', '"[\"\\u9647\\u5d82\\u8426\\u7d2b\\u6c14\\uff0c\\u91d1\\u5149\\u8d6b\\u6c1b\\u6c32\\u3002\", \"\\u7f8e\\u4eba\\u542b\\u9065\\u972d\\uff0c\\u6843\\u674e\\u82b3\\u81ea\\u85b0\\u3002\", \"\\u56fe\\u9ad8\\u9ec4\\u9e64\\u7fbd\\uff0c\\u5b9d\\u593a\\u9a8a\\u9f99\\u7fa4\\u3002\", \"\\u5ffd\\u60ca\\u85a4\\u9732\\u66f2\\uff0c\\u63a9\\u564e\\u4e1c\\u5c71\\u4e91\\u3002\"]"', '诗', 'shi', '', NULL, '題東山子李適碑陰二首 一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1727d837-7c49-4007-a188-174107315b36', '題東山子李適碑陰二首 二', '题东山子李适碑阴二首 二', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u56de\\u4e5f\\u5bd4\\u592d\\u6298\\uff0c\\u8cc8\\u751f\\u4ea6\\u8106\\u4fc3\\u3002\", \"\\u4eca\\u5fa9\\u54c0\\u82e5\\u4eba\\uff0c\\u5371\\u5149\\u8fc5\\u98a8\\u71ed\\u3002\", \"\\u591c\\u81fa\\u6dea\\u6e05\\u93e1\\uff0c\\u7aae\\u5875\\u57cb\\u7d50\\u7da0\\u3002\", \"\\u4f55\\u4ee5\\u8d08\\u4e0b\\u6cc9\\uff0c\\u751f\\u82bb\\u552f\\u4e00\\u675f\\u3002\"]"', '"[\"\\u56de\\u4e5f\\u5bd4\\u592d\\u6298\\uff0c\\u8d3e\\u751f\\u4ea6\\u8106\\u4fc3\\u3002\", \"\\u4eca\\u590d\\u54c0\\u82e5\\u4eba\\uff0c\\u5371\\u5149\\u8fc5\\u98ce\\u70db\\u3002\", \"\\u591c\\u53f0\\u6ca6\\u6e05\\u955c\\uff0c\\u7a77\\u5c18\\u57cb\\u7ed3\\u7eff\\u3002\", \"\\u4f55\\u4ee5\\u8d60\\u4e0b\\u6cc9\\uff0c\\u751f\\u520d\\u552f\\u4e00\\u675f\\u3002\"]"', '诗', 'shi', '', NULL, '題東山子李適碑陰二首 二 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31563c78-7fe5-43ae-bacc-4cac914a5259', '淮亭吟', '淮亭吟', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u8c9e\\u5bc2\\u616e\\u516e\\u6dee\\u5c71\\u5e7d\\uff0c\\u6190\\u82b3\\u82e5\\u516e{\\u81e8/\\u624b}\\u4e2d\\u6d32\\u3002\", \"\\u5d29\\u6e4d\\u59d4\\u54bd\\u65e5\\u591c\\u6d41\\uff0c\\u5b64\\u5ba2\\u5371\\u5750\\u5fc3\\u81ea\\u6101\\u3002\", \"\\u77e7\\u9db4\\u5533\\u516e\\u98a8\\u66c9\\uff0c\\u5fa9\\u733f\\u9cf4\\u516e\\u971c\\u79cb\\u3002\", \"\\u71a0\\u8000\\u98db\\u516e\\u87cb\\u87c0\\u541f\\uff0c\\u501a\\u6e05\\u745f\\u516e\\u6a6b\\u6dbc\\u7434\\u3002\", \"\\u64f7\\u7464\\u82b3\\u516e\\u5f14\\u695a\\u6c34\\uff0c\\u5f04\\u742a\\u6a39\\u516e\\u6b4c\\u8d8a\\u5c91\\u3002\", \"\\u5c71\\u7895\\u7912\\u516e\\u9688\\u66f2\\uff0c\\u6c34\\u6d93\\u6f23\\u516e\\u6d1e\\u6c69\\u3002\", \"\\u91d1\\u5149\\u5ef6\\u8d77\\u516e\\u9a5f\\u8208\\u6c92\\uff0c\\u9752\\u82d4\\u7adf\\u516e\\u7da0\\u860b\\u6b47\\u3002\", \"\\u7da0\\u860b\\u6b47\\u516e\\u51cb\\u6731\\u984f\\uff0c\\u7f8e\\u4eba\\u5bc2\\u6b77\\u516e\\u4f55\\u6642\\u9591\\u3002\", \"\\u541b\\u4e0d\\u898b\\u53ef\\u6190\\u6850\\u67cf\\u4e0a\\uff0c\\u4e30\\u8338\\u6842\\u6a39\\u82b1\\u6eff\\u5c71\\u3002\"]"', '"[\"\\u8d1e\\u5bc2\\u8651\\u516e\\u6dee\\u5c71\\u5e7d\\uff0c\\u601c\\u82b3\\u82e5\\u516e{\\u4e34/\\u624b}\\u4e2d\\u6d32\\u3002\", \"\\u5d29\\u6e4d\\u59d4\\u54bd\\u65e5\\u591c\\u6d41\\uff0c\\u5b64\\u5ba2\\u5371\\u5750\\u5fc3\\u81ea\\u6101\\u3002\", \"\\u77e7\\u9e64\\u5533\\u516e\\u98ce\\u6653\\uff0c\\u590d\\u733f\\u9e23\\u516e\\u971c\\u79cb\\u3002\", \"\\u71a0\\u8000\\u98de\\u516e\\u87cb\\u87c0\\u541f\\uff0c\\u501a\\u6e05\\u745f\\u516e\\u6a2a\\u51c9\\u7434\\u3002\", \"\\u64b7\\u7476\\u82b3\\u516e\\u540a\\u695a\\u6c34\\uff0c\\u5f04\\u742a\\u6811\\u516e\\u6b4c\\u8d8a\\u5c91\\u3002\", \"\\u5c71\\u57fc\\ud855\\udc1f\\u516e\\u9688\\u66f2\\uff0c\\u6c34\\u6d93\\u6d9f\\u516e\\u6d1e\\u6c69\\u3002\", \"\\u91d1\\u5149\\u5ef6\\u8d77\\u516e\\u9aa4\\u5174\\u6ca1\\uff0c\\u9752\\u82d4\\u7adf\\u516e\\u7eff\\u82f9\\u6b47\\u3002\", \"\\u7eff\\u82f9\\u6b47\\u516e\\u51cb\\u6731\\u989c\\uff0c\\u7f8e\\u4eba\\u5bc2\\u5386\\u516e\\u4f55\\u65f6\\u95f2\\u3002\", \"\\u541b\\u4e0d\\u89c1\\u53ef\\u601c\\u6850\\u67cf\\u4e0a\\uff0c\\u4e30\\u8338\\u6842\\u6811\\u82b1\\u6ee1\\u5c71\\u3002\"]"', '诗', 'shi', '', NULL, '淮亭吟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e96ae07-c190-4268-b81b-a5bad9fe4a82', '芳樹', '芳树', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u7389\\u82b1\\u73cd\\u7c1f\\u4e0a\\uff0c\\u91d1\\u7e37\\u756b\\u5c4f\\u958b\\u3002\", \"\\u66c9\\u6708\\u6190\\u7b8f\\u67f1\\uff0c\\u6625\\u98a8\\u61b6\\u93e1\\u81fa\\u3002\", \"\\u7b8f\\u67f1\\u6625\\u98a8\\u5439\\u66c9\\u6708\\uff0c\\u82b3\\u6a39\\u843d\\u82b1\\u671d\\u669d\\u6b47\\u3002\", \"\\u85c1\\u7827\\u5200\\u982d\\u672a\\u6709\\u671f\\uff0c\\u6500\\u689d\\u62ed\\u6dda\\u5750\\u76f8\\u601d\\u3002\"]"', '"[\"\\u7389\\u82b1\\u73cd\\u7c1f\\u4e0a\\uff0c\\u91d1\\u7f15\\u753b\\u5c4f\\u5f00\\u3002\", \"\\u6653\\u6708\\u601c\\u7b5d\\u67f1\\uff0c\\u6625\\u98ce\\u5fc6\\u955c\\u53f0\\u3002\", \"\\u7b5d\\u67f1\\u6625\\u98ce\\u5439\\u6653\\u6708\\uff0c\\u82b3\\u6811\\u843d\\u82b1\\u671d\\u669d\\u6b47\\u3002\", \"\\u85c1\\u7827\\u5200\\u5934\\u672a\\u6709\\u671f\\uff0c\\u6500\\u6761\\u62ed\\u6cea\\u5750\\u76f8\\u601d\\u3002\"]"', '诗', 'shi', '', NULL, '芳樹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59735045-588e-4ba9-a74f-c4fc0038983f', '遊禁苑幸臨渭亭遇雪應制', '游禁苑幸临渭亭遇雪应制', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u7389\\u5f8b\\u85cf\\u51b0\\u5019\\uff0c\\u5f64\\u968e\\u98db\\u96ea\\u6642\\u3002\", \"\\u65e5\\u5bd2\\u6d88\\u4e0d\\u76e1\\uff0c\\u98a8\\u5b9a\\u821e\\u9084\\u9072\\u3002\", \"\\u74ca\\u6a39\\u7559\\u5bb8\\u77da\\uff0c\\u7487\\u82b1\\u5165\\u777f\\u8a5e\\u3002\", \"\\u61f8\\u77e5\\u7a46\\u5929\\u5b50\\uff0c\\u9ec3\\u7af9\\u8b3e\\u8a00\\u8a69\\u3002\"]"', '"[\"\\u7389\\u5f8b\\u85cf\\u51b0\\u5019\\uff0c\\u5f64\\u9636\\u98de\\u96ea\\u65f6\\u3002\", \"\\u65e5\\u5bd2\\u6d88\\u4e0d\\u5c3d\\uff0c\\u98ce\\u5b9a\\u821e\\u8fd8\\u8fdf\\u3002\", \"\\u743c\\u6811\\u7559\\u5bb8\\u77a9\\uff0c\\u7487\\u82b1\\u5165\\u777f\\u8bcd\\u3002\", \"\\u60ac\\u77e5\\u7a46\\u5929\\u5b50\\uff0c\\u9ec4\\u7af9\\u8c29\\u8a00\\u8bd7\\u3002\"]"', '诗', 'shi', '', NULL, '遊禁苑幸臨渭亭遇雪應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f4e73f-94ed-4b71-a10b-68e1d240a9de', '奉和送金城公主適西蕃應制', '奉和送金城公主适西蕃应制', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u9cf3\\u6246\\u6190\\u7c2b\\u66f2\\uff0c\\u9e1e\\u95a8\\u5ff5\\u638c\\u73cd\\u3002\", \"\\u7f97\\u5ead\\u9059\\u7bc9\\u9928\\uff0c\\u5edf\\u7b56\\u91cd\\u548c\\u89aa\\u3002\", \"\\u661f\\u8f49\\u9280\\u6cb3\\u5915\\uff0c\\u82b1\\u79fb\\u7389\\u6a39\\u6625\\u3002\", \"\\u8056\\u5fc3\\u60bd\\u9001\\u9060\\uff0c\\u7559\\u8e55\\u671b\\u5f81\\u5875\\u3002\"]"', '"[\"\\u51e4\\u6246\\u601c\\u7bab\\u66f2\\uff0c\\u9e3e\\u95fa\\u5ff5\\u638c\\u73cd\\u3002\", \"\\u7f97\\u5ead\\u9065\\u7b51\\u9986\\uff0c\\u5e99\\u7b56\\u91cd\\u548c\\u4eb2\\u3002\", \"\\u661f\\u8f6c\\u94f6\\u6cb3\\u5915\\uff0c\\u82b1\\u79fb\\u7389\\u6811\\u6625\\u3002\", \"\\u5723\\u5fc3\\u51c4\\u9001\\u8fdc\\uff0c\\u7559\\u8df8\\u671b\\u5f81\\u5c18\\u3002\"]"', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcefea67-ebb8-4030-b856-2874e0b2a031', '幸白鹿觀應制', '幸白鹿观应制', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u9cf3\\u8f3f\\u4e58\\u516b\\u666f\\uff0c\\u9f9c\\u7c59\\u5411\\u4e09\\u4ed9\\u3002\", \"\\u65e5\\u6708\\u79fb\\u5e73\\u5730\\uff0c\\u96f2\\u971e\\u7db4\\u5c0f\\u5929\\u3002\", \"\\u91d1\\u7ae5\\u64ce\\u7d2b\\u85e5\\uff0c\\u7389\\u5973\\u737b\\u9752\\u84ee\\u3002\", \"\\u82b1\\u6d1e\\u7559\\u5bb8\\u8cde\\uff0c\\u9084\\u65d7\\u7e5e\\u5915\\u7159\\u3002\"]"', '"[\"\\u51e4\\u8206\\u4e58\\u516b\\u666f\\uff0c\\u9f9f\\u7b93\\u5411\\u4e09\\u4ed9\\u3002\", \"\\u65e5\\u6708\\u79fb\\u5e73\\u5730\\uff0c\\u4e91\\u971e\\u7f00\\u5c0f\\u5929\\u3002\", \"\\u91d1\\u7ae5\\u64ce\\u7d2b\\u836f\\uff0c\\u7389\\u5973\\u732e\\u9752\\u83b2\\u3002\", \"\\u82b1\\u6d1e\\u7559\\u5bb8\\u8d4f\\uff0c\\u8fd8\\u65d7\\u7ed5\\u5915\\u70df\\u3002\"]"', '诗', 'shi', '', NULL, '幸白鹿觀應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5f6485a-1f99-4459-9c35-5f934a01076b', '胡無人行', '胡无人行', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u5341\\u6708\\u7e41\\u971c\\u4e0b\\uff0c\\u5f81\\u4eba\\u9060\\u947f\\u7a7a\\u3002\", \"\\u96f2\\u6416\\u9326\\u8eca\\u7bc0\\uff0c\\u6d77\\u7167\\u89d2\\u7aef\\u5f13\\u3002\", \"\\u6697\\u78e7\\u57cb\\u6c99\\u6a39\\uff0c\\u885d\\u98c6\\u5377\\u585e\\u84ec\\u3002\", \"\\u65b9\\u96a8\\u819c\\u62dc\\u5165\\uff0c\\u6b4c\\u821e\\u7389\\u9580\\u4e2d\\u3002\"]"', '"[\"\\u5341\\u6708\\u7e41\\u971c\\u4e0b\\uff0c\\u5f81\\u4eba\\u8fdc\\u51ff\\u7a7a\\u3002\", \"\\u4e91\\u6447\\u9526\\u8f66\\u8282\\uff0c\\u6d77\\u7167\\u89d2\\u7aef\\u5f13\\u3002\", \"\\u6697\\u789b\\u57cb\\u6c99\\u6811\\uff0c\\u51b2\\u98d9\\u5377\\u585e\\u84ec\\u3002\", \"\\u65b9\\u968f\\u819c\\u62dc\\u5165\\uff0c\\u6b4c\\u821e\\u7389\\u95e8\\u4e2d\\u3002\"]"', '诗', 'shi', '', NULL, '胡無人行 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9608f9dd-a137-4659-b1cf-e0f2f5c40443', '倢伃', '倢伃', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u541b\\u6069\\u5ffd\\u65b7\\u7d55\\uff0c\\u59be\\u601d\\u7d42\\u672a\\u592e\\u3002\", \"\\u5dfe\\u6adb\\u4e0d\\u53ef\\u898b\\uff0c\\u6795\\u5e2d\\u7a7a\\u9918\\u9999\\u3002\", \"\\u7a97\\u6697\\u7db2\\u7f85\\u767d\\uff0c\\u968e\\u79cb\\u82d4\\u861a\\u9ec3\\u3002\", \"\\u61c9\\u9580\\u5bc2\\u5df2\\u9589\\uff0c\\u6d41\\u6d95\\u5411\\u662d\\u967d\\u3002\"]"', '"[\"\\u541b\\u6069\\u5ffd\\u65ad\\u7edd\\uff0c\\u59be\\u601d\\u7ec8\\u672a\\u592e\\u3002\", \"\\u5dfe\\u6809\\u4e0d\\u53ef\\u89c1\\uff0c\\u6795\\u5e2d\\u7a7a\\u4f59\\u9999\\u3002\", \"\\u7a97\\u6697\\u7f51\\u7f57\\u767d\\uff0c\\u9636\\u79cb\\u82d4\\u85d3\\u9ec4\\u3002\", \"\\u5e94\\u95e8\\u5bc2\\u5df2\\u95ed\\uff0c\\u6d41\\u6d95\\u5411\\u662d\\u9633\\u3002\"]"', '诗', 'shi', '', NULL, '倢伃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b6268e8-70ea-4bf6-8ee4-796702999202', '採蓮曲', '采莲曲', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u59be\\u5bb6\\u8d8a\\u6c34\\u908a\\uff0c\\u6416\\u8247\\u5165\\u6c5f\\u7159\\u3002\", \"\\u65e2\\u8993\\u540c\\u5fc3\\u4fb6\\uff0c\\u5fa9\\u91c7\\u540c\\u5fc3\\u84ee\\u3002\", \"\\u6298\\u85d5\\u7d72\\u80fd\\u8106\\uff0c\\u958b\\u82b1\\u8449\\u6b63\\u5713\\u3002\", \"\\u6625\\u6b4c\\u5f04\\u660e\\u6708\\uff0c\\u6b78\\u6ac2\\u843d\\u82b1\\u524d\\u3002\"]"', '"[\"\\u59be\\u5bb6\\u8d8a\\u6c34\\u8fb9\\uff0c\\u6447\\u8247\\u5165\\u6c5f\\u70df\\u3002\", \"\\u65e2\\u89c5\\u540c\\u5fc3\\u4fa3\\uff0c\\u590d\\u91c7\\u540c\\u5fc3\\u83b2\\u3002\", \"\\u6298\\u85d5\\u4e1d\\u80fd\\u8106\\uff0c\\u5f00\\u82b1\\u53f6\\u6b63\\u5706\\u3002\", \"\\u6625\\u6b4c\\u5f04\\u660e\\u6708\\uff0c\\u5f52\\u6ac2\\u843d\\u82b1\\u524d\\u3002\"]"', '诗', 'shi', '', NULL, '採蓮曲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65f1f4a4-7e57-4dd9-94fb-dea6a3863b3f', '夏日遊德州贈高四', '夏日游德州赠高四', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u65e5\\u89c0\\u9130\\u5168\\u8d99\\uff0c\\u661f\\u81e8\\u4fef\\u820a\\u5433\\u3002\", \"\\u9b32\\u6d25\\u958b\\u5de8\\u6d78\\uff0c\\u7a3d\\u961c\\u93ae\\u540d\\u90fd\\u3002\", \"\\u7d2b\\u96f2\\u6d6e\\u528d\\u5323\\uff0c\\u9752\\u5c71\\u5b55\\u5bf6\\u7b26\\u3002\", \"\\u5c01\\u7586\\u6062\\u9738\\u9053\\uff0c\\u554f\\u9f0e\\u7af6\\u96c4\\u5716\\u3002\", \"\\u795e\\u5149\\u5305\\u56db\\u5927\\uff0c\\u7687\\u5a01\\u9707\\u516b\\u5340\\u3002\", \"\\u98a8\\u7159\\u901a\\u5730\\u8ef8\\uff0c\\u661f\\u8c61\\u6b63\\u5929\\u6a1e\\u3002\", \"\\u5929\\u6a1e\\u9650\\u5357\\u5317\\uff0c\\u5730\\u8ef8\\u6b8a\\u9109\\u570b\\u3002\", \"\\u95e2\\u9580\\u901a\\u821c\\u8cd3\\uff0c\\u6bd4\\u5c4b\\u5c01\\u582f\\u5fb7\\u3002\", \"\\u8a00\\u8b1d\\u5782\\u9264\\u96b1\\uff0c\\u4f86\\u53c3\\u8ca0\\u9f0e\\u8077\\u3002\", \"\\u5929\\u5b50\\u4e0d\\u898b\\u77e5\\uff0c\\u7fa3\\u516c\\u8a4e\\u76f8\\u8b58\\u3002\", \"\\u672a\\u5c55\\u5f9e\\u6771\\u99ff\\uff0c\\u7a7a\\u6222\\u5716\\u5357\\u7ffc\\u3002\", \"\\u6642\\u547d\\u6b32\\u4f55\\u8a00\\uff0c\\u64ab\\u81ba\\u9577\\u5606\\u606f\\u3002\", \"\\u5606\\u606f\\u5c07\\u5982\\u4f55\\uff0c\\u904a\\u4eba\\u610f\\u6c23\\u591a\\u3002\", \"\\u767d\\u96ea\\u6881\\u5c71\\u66f2\\uff0c\\u5bd2\\u98a8\\u6613\\u6c34\\u6b4c\\u3002\", \"\\u6ce3\\u9b4f\\u50b7\\u5433\\u8d77\\uff0c\\u601d\\u8d99\\u5207\\u5ec9\\u9817\\u3002\", \"\\u6dd2\\u65b7\\u97d3\\u738b\\u528d\\uff0c\\u751f\\u6b7b\\u7fdf\\u516c\\u7f85\\u3002\", \"\\u7f85\\u60b2\\u7fdf\\u516c\\u610f\\uff0c\\u528d\\u8ca0\\u97d3\\u738b\\u6c23\\u3002\", \"\\u9a55\\u990c\\u53bb\\u6613\\u8ad6\\uff0c\\u5fcc\\u9014\\u826f\\u53ef\\u754f\\u3002\", \"\\u5919\\u6614\\u61f7\\u6c5f\\u6d77\\uff0c\\u5e73\\u751f\\u6df7\\u6d87\\u6e2d\\u3002\", \"\\u5343\\u8f09\\u5951\\u98a8\\u96f2\\uff0c\\u4e00\\u8a00\\u5fd8\\u8ce4\\u8cb4\\u3002\", \"\\u53bb\\u53bb\\u8a2a\\u6797\\u6cc9\\uff0c\\u7a7a\\u8c37\\u6709\\u907a\\u8ce2\\u3002\", \"\\u8a00\\u6295\\u7235\\u91cc\\u523a\\uff0c\\u4f86\\u6cdb\\u91ce\\u4eba\\u8239\\u3002\", \"\\u7de0\\u4ea4\\u541b\\u8d08\\u7e1e\\uff0c\\u6295\\u5206\\u6211\\u5fd8\\u7b4c\\u3002\", \"\\u6210\\u98a8\\u90e2\\u5320\\u65b2\\uff0c\\u6d41\\u6c34\\u4f2f\\u7259\\u5f26\\u3002\", \"\\u7259\\u5f26\\u5fd8\\u9053\\u8853\\uff0c\\u6f33\\u6ff1\\u6063\\u9591\\u9038\\u3002\", \"\\u804a\\u5b89\\u5f35\\u851a\\u5eec\\uff0c\\u8a4e\\u6383\\u9673\\u8543\\u5ba4\\u3002\", \"\\u865b\\u5ba4\\u72ce\\u62db\\u5c0b\\uff0c\\u656c\\u611b\\u6df7\\u6d6e\\u6c88\\u3002\", \"\\u4e00\\u8afe\\u9ec3\\u91d1\\u4fe1\\uff0c\\u4e09\\u5fa9\\u767d\\u73ea\\u5fc3\\u3002\", \"\\u971c\\u677e\\u8c9e\\u96c5\\u7bc0\\uff0c\\u6708\\u6842\\u6717\\u6c96\\u895f\\u3002\", \"\\u9748\\u81fa\\u842c\\u9803\\u6fec\\uff0c\\u5b78\\u5e9c\\u4e5d\\u6d41\\u6df1\\u3002\", \"\\u8ac7\\u7384\\u660e\\u6bc0\\u74a7\\uff0c\\u62fe\\u7d2b\\u964b\\u7c5d\\u91d1\\u3002\", \"\\u9dfa\\u6fe4\\u958b\\u78a7\\u6d77\\uff0c\\u9cf3\\u5f69\\u7db4\\u8a5e\\u6797\\u3002\", \"\\u6797\\u865b\\u661f\\u83ef\\u6620\\uff0c\\u6c34\\u6f88\\u971e\\u5149\\u6de8\\u3002\", \"\\u971e\\u6c34\\u5169\\u5206\\u7d05\\uff0c\\u5ddd\\u6e90\\u56db\\u671b\\u901a\\u3002\", \"\\u9727\\u5377\\u5929\\u5c71\\u975c\\uff0c\\u7159\\u92b7\\u592a\\u53f2\\u7a7a\\u3002\", \"\\u9ce5\\u8072\\u6d41\\u5411\\u8584\\uff0c\\u8776\\u5f71\\u4e82\\u82b3\\u53e2\\u3002\", \"\\u67f3\\u9670\\u4f4e\\u69e7\\u6c34\\uff0c\\u8377\\u6c23\\u4e0a\\u85b0\\u98a8\\u3002\", \"\\u98a8\\u6708\\u82b3\\u83f2\\u7bc0\\uff0c\\u7269\\u83ef\\u7d1b\\u53ef\\u6085\\u3002\", \"\\u5c07\\u6b61\\u4fc3\\u5e2d\\u8cde\\uff0c\\u907d\\u723e\\u53c8\\u6b78\\u5225\\u3002\", \"\\u7a4d\\u6c34\\u5e36\\u5433\\u9580\\uff0c\\u901a\\u6ce2\\u9023\\u79b9\\u7a74\\u3002\", \"\\u8d08\\u8a00\\u96d6\\u6b32\\u76e1\\uff0c\\u6a5f\\u5fc3\\u5eb6\\u61c9\\u7d55\\u3002\", \"\\u6f58\\u5cb3\\u672c\\u81ea\\u9591\\uff0c\\u6881\\u9d3b\\u4e0d\\u56e0\\u71b1\\u3002\", \"\\u4e00\\u74e2\\u6b23\\u72ce\\u9053\\uff0c\\u4e09\\u6708\\u804a\\u68f2\\u62d9\\u3002\", \"\\u68f2\\u62d9\\u96b1\\u91d1\\u83ef\\uff0c\\u72ce\\u9053\\u8a2a\\u4ed9\\u67e5\\u3002\", \"\\u653e\\u66e0\\u611a\\u516c\\u8c37\\uff0c\\u6d88\\u6563\\u91ce\\u4eba\\u5bb6\\u3002\", \"\\u4e00\\u9803\\u5357\\u5c71\\u8c46\\uff0c\\u4e94\\u8272\\u6771\\u9675\\u74dc\\u3002\", \"\\u91ce\\u8863\\u88c1\\u859c\\u8449\\uff0c\\u5c71\\u9152\\u914c\\u85e4\\u82b1\\u3002\", \"\\u767d\\u96f2\\u96e2\\u671b\\u9060\\uff0c\\u9752\\u8c3f\\u96b1\\u8def\\u8cd2\\u3002\", \"\\u513b\\u61b6\\u5e7d\\u5dd6\\u6842\\uff0c\\u7336\\u5180\\u6298\\u758e\\u9ebb\\u3002\"]"', '"[\"\\u65e5\\u89c2\\u90bb\\u5168\\u8d75\\uff0c\\u661f\\u4e34\\u4fef\\u65e7\\u5434\\u3002\", \"\\u9b32\\u6d25\\u5f00\\u5de8\\u6d78\\uff0c\\u7a3d\\u961c\\u9547\\u540d\\u90fd\\u3002\", \"\\u7d2b\\u4e91\\u6d6e\\u5251\\u5323\\uff0c\\u9752\\u5c71\\u5b55\\u5b9d\\u7b26\\u3002\", \"\\u5c01\\u7586\\u6062\\u9738\\u9053\\uff0c\\u95ee\\u9f0e\\u7ade\\u96c4\\u56fe\\u3002\", \"\\u795e\\u5149\\u5305\\u56db\\u5927\\uff0c\\u7687\\u5a01\\u9707\\u516b\\u533a\\u3002\", \"\\u98ce\\u70df\\u901a\\u5730\\u8f74\\uff0c\\u661f\\u8c61\\u6b63\\u5929\\u67a2\\u3002\", \"\\u5929\\u67a2\\u9650\\u5357\\u5317\\uff0c\\u5730\\u8f74\\u6b8a\\u4e61\\u56fd\\u3002\", \"\\u8f9f\\u95e8\\u901a\\u821c\\u5bbe\\uff0c\\u6bd4\\u5c4b\\u5c01\\u5c27\\u5fb7\\u3002\", \"\\u8a00\\u8c22\\u5782\\u94a9\\u9690\\uff0c\\u6765\\u53c2\\u8d1f\\u9f0e\\u804c\\u3002\", \"\\u5929\\u5b50\\u4e0d\\u89c1\\u77e5\\uff0c\\u7fa4\\u516c\\u8bb5\\u76f8\\u8bc6\\u3002\", \"\\u672a\\u5c55\\u4ece\\u4e1c\\u9a8f\\uff0c\\u7a7a\\u6222\\u56fe\\u5357\\u7ffc\\u3002\", \"\\u65f6\\u547d\\u6b32\\u4f55\\u8a00\\uff0c\\u629a\\u81ba\\u957f\\u53f9\\u606f\\u3002\", \"\\u53f9\\u606f\\u5c06\\u5982\\u4f55\\uff0c\\u6e38\\u4eba\\u610f\\u6c14\\u591a\\u3002\", \"\\u767d\\u96ea\\u6881\\u5c71\\u66f2\\uff0c\\u5bd2\\u98ce\\u6613\\u6c34\\u6b4c\\u3002\", \"\\u6ce3\\u9b4f\\u4f24\\u5434\\u8d77\\uff0c\\u601d\\u8d75\\u5207\\u5ec9\\u9887\\u3002\", \"\\u51c4\\u65ad\\u97e9\\u738b\\u5251\\uff0c\\u751f\\u6b7b\\u7fdf\\u516c\\u7f57\\u3002\", \"\\u7f57\\u60b2\\u7fdf\\u516c\\u610f\\uff0c\\u5251\\u8d1f\\u97e9\\u738b\\u6c14\\u3002\", \"\\u9a84\\u9975\\u53bb\\u6613\\u8bba\\uff0c\\u5fcc\\u9014\\u826f\\u53ef\\u754f\\u3002\", \"\\u5919\\u6614\\u6000\\u6c5f\\u6d77\\uff0c\\u5e73\\u751f\\u6df7\\u6cfe\\u6e2d\\u3002\", \"\\u5343\\u8f7d\\u5951\\u98ce\\u4e91\\uff0c\\u4e00\\u8a00\\u5fd8\\u8d31\\u8d35\\u3002\", \"\\u53bb\\u53bb\\u8bbf\\u6797\\u6cc9\\uff0c\\u7a7a\\u8c37\\u6709\\u9057\\u8d24\\u3002\", \"\\u8a00\\u6295\\u7235\\u91cc\\u523a\\uff0c\\u6765\\u6cdb\\u91ce\\u4eba\\u8239\\u3002\", \"\\u7f14\\u4ea4\\u541b\\u8d60\\u7f1f\\uff0c\\u6295\\u5206\\u6211\\u5fd8\\u7b4c\\u3002\", \"\\u6210\\u98ce\\u90e2\\u5320\\u65b2\\uff0c\\u6d41\\u6c34\\u4f2f\\u7259\\u5f26\\u3002\", \"\\u7259\\u5f26\\u5fd8\\u9053\\u672f\\uff0c\\u6f33\\u6ee8\\u6063\\u95f2\\u9038\\u3002\", \"\\u804a\\u5b89\\u5f20\\u851a\\u5e90\\uff0c\\u8bb5\\u626b\\u9648\\u8543\\u5ba4\\u3002\", \"\\u865a\\u5ba4\\u72ce\\u62db\\u5bfb\\uff0c\\u656c\\u7231\\u6df7\\u6d6e\\u6c88\\u3002\", \"\\u4e00\\u8bfa\\u9ec4\\u91d1\\u4fe1\\uff0c\\u4e09\\u590d\\u767d\\u73ea\\u5fc3\\u3002\", \"\\u971c\\u677e\\u8d1e\\u96c5\\u8282\\uff0c\\u6708\\u6842\\u6717\\u51b2\\u895f\\u3002\", \"\\u7075\\u53f0\\u4e07\\u9877\\u6fec\\uff0c\\u5b66\\u5e9c\\u4e5d\\u6d41\\u6df1\\u3002\", \"\\u8c08\\u7384\\u660e\\u6bc1\\u74a7\\uff0c\\u62fe\\u7d2b\\u964b\\u7c5d\\u91d1\\u3002\", \"\\u9e6d\\u6d9b\\u5f00\\u78a7\\u6d77\\uff0c\\u51e4\\u5f69\\u7f00\\u8bcd\\u6797\\u3002\", \"\\u6797\\u865a\\u661f\\u534e\\u6620\\uff0c\\u6c34\\u6f88\\u971e\\u5149\\u51c0\\u3002\", \"\\u971e\\u6c34\\u4e24\\u5206\\u7ea2\\uff0c\\u5ddd\\u6e90\\u56db\\u671b\\u901a\\u3002\", \"\\u96fe\\u5377\\u5929\\u5c71\\u9759\\uff0c\\u70df\\u9500\\u592a\\u53f2\\u7a7a\\u3002\", \"\\u9e1f\\u58f0\\u6d41\\u5411\\u8584\\uff0c\\u8776\\u5f71\\u4e71\\u82b3\\u4e1b\\u3002\", \"\\u67f3\\u9634\\u4f4e\\u6920\\u6c34\\uff0c\\u8377\\u6c14\\u4e0a\\u85b0\\u98ce\\u3002\", \"\\u98ce\\u6708\\u82b3\\u83f2\\u8282\\uff0c\\u7269\\u534e\\u7eb7\\u53ef\\u60a6\\u3002\", \"\\u5c06\\u6b22\\u4fc3\\u5e2d\\u8d4f\\uff0c\\u907d\\u5c14\\u53c8\\u5f52\\u522b\\u3002\", \"\\u79ef\\u6c34\\u5e26\\u5434\\u95e8\\uff0c\\u901a\\u6ce2\\u8fde\\u79b9\\u7a74\\u3002\", \"\\u8d60\\u8a00\\u867d\\u6b32\\u5c3d\\uff0c\\u673a\\u5fc3\\u5eb6\\u5e94\\u7edd\\u3002\", \"\\u6f58\\u5cb3\\u672c\\u81ea\\u95f2\\uff0c\\u6881\\u9e3f\\u4e0d\\u56e0\\u70ed\\u3002\", \"\\u4e00\\u74e2\\u6b23\\u72ce\\u9053\\uff0c\\u4e09\\u6708\\u804a\\u6816\\u62d9\\u3002\", \"\\u6816\\u62d9\\u9690\\u91d1\\u534e\\uff0c\\u72ce\\u9053\\u8bbf\\u4ed9\\u67e5\\u3002\", \"\\u653e\\u65f7\\u611a\\u516c\\u8c37\\uff0c\\u6d88\\u6563\\u91ce\\u4eba\\u5bb6\\u3002\", \"\\u4e00\\u9877\\u5357\\u5c71\\u8c46\\uff0c\\u4e94\\u8272\\u4e1c\\u9675\\u74dc\\u3002\", \"\\u91ce\\u8863\\u88c1\\u859c\\u53f6\\uff0c\\u5c71\\u9152\\u914c\\u85e4\\u82b1\\u3002\", \"\\u767d\\u4e91\\u79bb\\u671b\\u8fdc\\uff0c\\u9752\\u8c3f\\u9690\\u8def\\u8d4a\\u3002\", \"\\u50a5\\u5fc6\\u5e7d\\u5ca9\\u6842\\uff0c\\u72b9\\u5180\\u6298\\u758e\\u9ebb\\u3002\"]"', '诗', 'shi', '', NULL, '夏日遊德州贈高四 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e28fdc6f-cf53-407e-b6d6-be3385177c8c', '餞唐州高使君赴任', '饯唐州高使君赴任', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u9999\\u843c\\u5a9a\\u7d05\\u6ecb\\uff0c\\u5782\\u689d\\u7e08\\u7da0\\u7d72\\u3002\", \"\\u60c5\\u4eba\\u62c2\\u7464\\u8882\\uff0c\\u5171\\u60dc\\u6b64\\u82b3\\u6642\\u3002\", \"\\u9a4c\\u9a66\\u5df2\\u8e91\\u8e85\\uff0c\\u9ce5\\u96bc\\u65b9\\u8473\\u8564\\u3002\", \"\\u8dc2\\u4e88\\u671b\\u592a\\u5b88\\uff0c\\u6d41\\u6f64\\u53ca\\u4eac\\u5e2b\\u3002\"]"', '"[\"\\u9999\\u843c\\u5a9a\\u7ea2\\u6ecb\\uff0c\\u5782\\u6761\\u8426\\u7eff\\u4e1d\\u3002\", \"\\u60c5\\u4eba\\u62c2\\u7476\\u8882\\uff0c\\u5171\\u60dc\\u6b64\\u82b3\\u65f6\\u3002\", \"\\u9a95\\u9aa6\\u5df2\\u8e2f\\u8e85\\uff0c\\u9e1f\\u96bc\\u65b9\\u8473\\u8564\\u3002\", \"\\u8dc2\\u4e88\\u671b\\u592a\\u5b88\\uff0c\\u6d41\\u6da6\\u53ca\\u4eac\\u5e08\\u3002\"]"', '诗', 'shi', '', NULL, '餞唐州高使君赴任 shi');
