INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c3223f0-ee46-4a67-adef-f54e1b1a0448', '同韋舍人元旦早朝', '同韦舍人元旦早朝', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u5915\\u8f49\\u6e05\\u58fa\\u6f0f\\uff0c\\u6668\\u9a5a\\u9577\\u6a02\\u9418\\u3002\", \"\\u9036\\u8fe4\\u7db8\\u7981\\u5ba2\\uff0c\\u5047\\u5bd0\\u5b88\\u9285\\u9f8d\\u3002\", \"\\u4e88\\u4ea6\\u8da8\\u4e09\\u6bbf\\uff0c\\u80a9\\u96a8\\u8b01\\u4e5d\\u91cd\\u3002\", \"\\u7e41\\u73c2\\u63a5\\u66d9\\u97ff\\uff0c\\u83ef\\u5292\\u6bd4\\u6625\\u5bb9\\u3002\", \"\\u76f8\\u554f\\u97f6\\u5149\\u6b47\\uff0c\\u5f4c\\u6190\\u82b3\\u610f\\u6fc3\\u3002\", \"\\u9858\\u8a00\\u4e58\\u65e5\\u65f0\\uff0c\\u651c\\u624b\\u5373\\u96f2\\u5cf0\\u3002\"]"', '"[\"\\u5915\\u8f6c\\u6e05\\u58f6\\u6f0f\\uff0c\\u6668\\u60ca\\u957f\\u4e50\\u949f\\u3002\", \"\\u9036\\u8fe4\\u7eb6\\u7981\\u5ba2\\uff0c\\u5047\\u5bd0\\u5b88\\u94dc\\u9f99\\u3002\", \"\\u4e88\\u4ea6\\u8d8b\\u4e09\\u6bbf\\uff0c\\u80a9\\u968f\\u8c12\\u4e5d\\u91cd\\u3002\", \"\\u7e41\\u73c2\\u63a5\\u66d9\\u54cd\\uff0c\\u534e\\u5292\\u6bd4\\u6625\\u5bb9\\u3002\", \"\\u76f8\\u95ee\\u97f6\\u5149\\u6b47\\uff0c\\u5f25\\u601c\\u82b3\\u610f\\u6d53\\u3002\", \"\\u613f\\u8a00\\u4e58\\u65e5\\u65f0\\uff0c\\u643a\\u624b\\u5373\\u4e91\\u5cf0\\u3002\"]"', '诗', 'shi', '', NULL, '同韋舍人元旦早朝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e81e1db0-66d5-4b66-8e26-6df6a0bf8701', '侍宴韋嗣立山莊應制', '侍宴韦嗣立山庄应制', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u9f0e\\u81e3\\u4f11\\u6fa3\\u9699\\uff0c\\u65b9\\u5916\\u7d50\\u9059\\u5fc3\\u3002\", \"\\u5225\\u696d\\u9752\\u971e\\u5883\\uff0c\\u5b64\\u6f6d\\u78a7\\u6a39\\u6797\\u3002\", \"\\u6bcf\\u99b3\\u6771\\u5885\\u7b56\\uff0c\\u9059\\u5f04\\u5317\\u6eaa\\u7434\\u3002\", \"\\u5e1d\\u7737\\u7d13\\u6642\\u8c6b\\uff0c\\u53f0\\u5712\\u8cde\\u6b72\\u9670\\u3002\", \"\\u79fb\\u947e\\u660e\\u6708\\u6cbc\\uff0c\\u5f35\\u7d44\\u767d\\u96f2\\u5c91\\u3002\", \"\\u5fa1\\u9152\\u7464\\u89f4\\u843d\\uff0c\\u4ed9\\u58c7\\u7af9\\u5f91\\u6df1\\u3002\", \"\\u4e09\\u5149\\u61f8\\u8056\\u85fb\\uff0c\\u4e94\\u7b49\\u51a0\\u671d\\u7c2a\\u3002\", \"\\u81ea\\u6614\\u7687\\u6069\\u611f\\uff0c\\u54b8\\u8a00\\u7368\\u81ea\\u4eca\\u3002\"]"', '"[\"\\u9f0e\\u81e3\\u4f11\\u6fa3\\u9699\\uff0c\\u65b9\\u5916\\u7ed3\\u9065\\u5fc3\\u3002\", \"\\u522b\\u4e1a\\u9752\\u971e\\u5883\\uff0c\\u5b64\\u6f6d\\u78a7\\u6811\\u6797\\u3002\", \"\\u6bcf\\u9a70\\u4e1c\\u5885\\u7b56\\uff0c\\u9065\\u5f04\\u5317\\u6eaa\\u7434\\u3002\", \"\\u5e1d\\u7737\\u7ebe\\u65f6\\u8c6b\\uff0c\\u53f0\\u56ed\\u8d4f\\u5c81\\u9634\\u3002\", \"\\u79fb\\u92ae\\u660e\\u6708\\u6cbc\\uff0c\\u5f20\\u7ec4\\u767d\\u4e91\\u5c91\\u3002\", \"\\u5fa1\\u9152\\u7476\\u89de\\u843d\\uff0c\\u4ed9\\u575b\\u7af9\\u5f84\\u6df1\\u3002\", \"\\u4e09\\u5149\\u60ac\\u5723\\u85fb\\uff0c\\u4e94\\u7b49\\u51a0\\u671d\\u7c2a\\u3002\", \"\\u81ea\\u6614\\u7687\\u6069\\u611f\\uff0c\\u54b8\\u8a00\\u72ec\\u81ea\\u4eca\\u3002\"]"', '诗', 'shi', '', NULL, '侍宴韋嗣立山莊應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('151ce88f-fd6a-4e40-849d-f682d5397112', '送特進李嶠入都祔廟', '送特进李峤入都祔庙', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u7279\\u9032\\u4e09\\u516c\\u4e0b\\uff0c\\u53f0\\u81e3\\u767e\\u63c6\\u5148\\u3002\", \"\\u5b5d\\u5716\\u958b\\u5be2\\u77f3\\uff0c\\u7960\\u4e3b\\u535c\\u7272\\u7b75\\u3002\", \"\\u6069\\u7d1a\\u9752\\u7db8\\u8cdc\\uff0c\\u5f82\\u88dd\\u7d2b\\u6a50\\u61f8\\u3002\", \"\\u7da2\\u7e46\\u91d1\\u9f0e\\u5e2d\\uff0c\\u5bb4\\u991e\\u7389\\u6f62\\u5ddd\\u3002\", \"\\u5317\\u6597\\u5206\\u5f81\\u8def\\uff0c\\u6771\\u5c71\\u8d77\\u8d08\\u7bc7\\u3002\", \"\\u6a02\\u6c60\\u6b4c\\u7da0\\u85fb\\uff0c\\u6881\\u82d1\\u85c9\\u7d05\\u8343\\u3002\", \"\\u9a0e\\u8f49\\u5546\\u5dd6\\u65e5\\uff0c\\u65cc\\u6416\\u95dc\\u585e\\u7159\\u3002\", \"\\u5edf\\u5802\\u9808\\u9bc1\\u8b70\\uff0c\\u9326\\u7bc0\\u4f47\\u4f86\\u65cb\\u3002\"]"', '"[\"\\u7279\\u8fdb\\u4e09\\u516c\\u4e0b\\uff0c\\u53f0\\u81e3\\u767e\\u63c6\\u5148\\u3002\", \"\\u5b5d\\u56fe\\u5f00\\u5bdd\\u77f3\\uff0c\\u7960\\u4e3b\\u535c\\u7272\\u7b75\\u3002\", \"\\u6069\\u7ea7\\u9752\\u7eb6\\u8d50\\uff0c\\u5f82\\u88c5\\u7d2b\\u6a50\\u60ac\\u3002\", \"\\u7ef8\\u7f2a\\u91d1\\u9f0e\\u5e2d\\uff0c\\u5bb4\\u996f\\u7389\\u6f62\\u5ddd\\u3002\", \"\\u5317\\u6597\\u5206\\u5f81\\u8def\\uff0c\\u4e1c\\u5c71\\u8d77\\u8d60\\u7bc7\\u3002\", \"\\u4e50\\u6c60\\u6b4c\\u7eff\\u85fb\\uff0c\\u6881\\u82d1\\u85c9\\u7ea2\\u8343\\u3002\", \"\\u9a91\\u8f6c\\u5546\\u5ca9\\u65e5\\uff0c\\u65cc\\u6447\\u5173\\u585e\\u70df\\u3002\", \"\\u5e99\\u5802\\u987b\\u9ca0\\u8bae\\uff0c\\u9526\\u8282\\u4f2b\\u6765\\u65cb\\u3002\"]"', '诗', 'shi', '', NULL, '送特進李嶠入都祔廟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4684af77-b1b6-4a04-9799-19a138b493f2', '春閨', '春闺', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u620d\\u5ba2\\u620d\\u6e05\\u6ce2\\uff0c\\u5e7d\\u95a8\\u5e7d\\u601d\\u591a\\u3002\", \"\\u6697\\u6881\\u805e\\u8a9e\\u71d5\\uff0c\\u591c\\u71ed\\u898b\\u98db\\u86fe\\u3002\", \"\\u5bf6\\u9d28\\u85cf\\u8102\\u7c89\\uff0c\\u91d1\\u5c4f\\u7db4\\u7dba\\u7f85\\u3002\", \"\\u88c1\\u8863\\u5377\\u7d0b\\u7d20\\uff0c\\u7e54\\u9326\\u5ea6\\u9cf4\\u68ad\\u3002\", \"\\u6709\\u4f7f\\u901a\\u897f\\u6975\\uff0c\\u7dd8\\u66f8\\u5bc4\\u5317\\u6cb3\\u3002\", \"\\u5e74\\u5149\\u53ea\\u6050\\u76e1\\uff0c\\u5f81\\u6230\\u83ab\\u8e49\\u8dce\\u3002\"]"', '"[\"\\u620d\\u5ba2\\u620d\\u6e05\\u6ce2\\uff0c\\u5e7d\\u95fa\\u5e7d\\u601d\\u591a\\u3002\", \"\\u6697\\u6881\\u95fb\\u8bed\\u71d5\\uff0c\\u591c\\u70db\\u89c1\\u98de\\u86fe\\u3002\", \"\\u5b9d\\u9e2d\\u85cf\\u8102\\u7c89\\uff0c\\u91d1\\u5c4f\\u7f00\\u7eee\\u7f57\\u3002\", \"\\u88c1\\u8863\\u5377\\u7eb9\\u7d20\\uff0c\\u7ec7\\u9526\\u5ea6\\u9e23\\u68ad\\u3002\", \"\\u6709\\u4f7f\\u901a\\u897f\\u6781\\uff0c\\u7f04\\u4e66\\u5bc4\\u5317\\u6cb3\\u3002\", \"\\u5e74\\u5149\\u53ea\\u6050\\u5c3d\\uff0c\\u5f81\\u6218\\u83ab\\u8e49\\u8dce\\u3002\"]"', '诗', 'shi', '', NULL, '春閨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('841d3b78-0d9a-4d5e-af99-b51b43e21d4d', '奉和興慶池戲競渡應制', '奉和兴庆池戏竞渡应制', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u593e\\u9053\\u50b3\\u547c\\u7fca\\u7fe0\\u866c\\uff0c\\u5929\\u56de\\u65e5\\u8f49\\u5fa1\\u82b3\\u6d32\\u3002\", \"\\u9752\\u6f6d\\u66c9\\u9744\\u7c60\\u4ed9\\u8e55\\uff0c\\u7d05\\u5dbc\\u6674\\u82b1\\u9694\\u7db5\\u65d2\\u3002\", \"\\u9999\\u6ea2\\u91d1\\u676f\\u74b0\\u5ee3\\u5750\\uff0c\\u8072\\u50b3\\u5993\\u8238\\u531d\\u4e2d\\u6d41\\u3002\", \"\\u7fa3\\u81e3\\u76f8\\u6176\\u5609\\u9b5a\\u6a02\\uff0c\\u5171\\u54c2\\u6a6b\\u6c7e\\u6b4c\\u5439\\u79cb\\u3002\"]"', '"[\"\\u5939\\u9053\\u4f20\\u547c\\u7fca\\u7fe0\\u866c\\uff0c\\u5929\\u56de\\u65e5\\u8f6c\\u5fa1\\u82b3\\u6d32\\u3002\", \"\\u9752\\u6f6d\\u6653\\u972d\\u7b3c\\u4ed9\\u8df8\\uff0c\\u7ea2\\u5c7f\\u6674\\u82b1\\u9694\\u5f69\\u65d2\\u3002\", \"\\u9999\\u6ea2\\u91d1\\u676f\\u73af\\u5e7f\\u5750\\uff0c\\u58f0\\u4f20\\u5993\\u8238\\u531d\\u4e2d\\u6d41\\u3002\", \"\\u7fa4\\u81e3\\u76f8\\u5e86\\u5609\\u9c7c\\u4e50\\uff0c\\u5171\\u54c2\\u6a2a\\u6c7e\\u6b4c\\u5439\\u79cb\\u3002\"]"', '诗', 'shi', '', NULL, '奉和興慶池戲競渡應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3ffcdea-449d-4f0c-81c1-73b361aa5137', '苑中遇雪應制', '苑中遇雪应制', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u5343\\u937e\\u8056\\u9152\\u5fa1\\u7b75\\u62ab\\uff0c\\u516d\\u51fa\\u7965\\u82f1\\u4e82\\u7e5e\\u679d\\u3002\", \"\\u5373\\u6b64\\u795e\\u4ed9\\u5c0d\\u74ca\\u5703\\uff0c\\u4f55\\u7169\\u8f4d\\u8ff9\\u5411\\u7464\\u6c60\\u3002\"]"', '"[\"\\u5343\\u949f\\u5723\\u9152\\u5fa1\\u7b75\\u62ab\\uff0c\\u516d\\u51fa\\u7965\\u82f1\\u4e71\\u7ed5\\u679d\\u3002\", \"\\u5373\\u6b64\\u795e\\u4ed9\\u5bf9\\u743c\\u5703\\uff0c\\u4f55\\u70e6\\u8f99\\u8ff9\\u5411\\u7476\\u6c60\\u3002\"]"', '诗', 'shi', '', NULL, '苑中遇雪應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f52bf9-4ecd-4933-bafc-5b06492cecf0', '上巳日祓禊渭濱應制', '上巳日祓禊渭滨应制', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u6674\\u98a8\\u9e97\\u65e5\\u6eff\\u82b3\\u6d32\\uff0c\\u67f3\\u8272\\u6625\\u7b75\\u7953\\u9326\\u6d41\\u3002\", \"\\u7686\\u8a00\\u4f8d\\u8e55\\u6a6b\\u6c7e\\u5bb4\\uff0c\\u66ab\\u4f3c\\u4e58\\u69ce\\u5929\\u6f22\\u904a\\u3002\"]"', '"[\"\\u6674\\u98ce\\u4e3d\\u65e5\\u6ee1\\u82b3\\u6d32\\uff0c\\u67f3\\u8272\\u6625\\u7b75\\u7953\\u9526\\u6d41\\u3002\", \"\\u7686\\u8a00\\u4f8d\\u8df8\\u6a2a\\u6c7e\\u5bb4\\uff0c\\u6682\\u4f3c\\u4e58\\u69ce\\u5929\\u6c49\\u6e38\\u3002\"]"', '诗', 'shi', '', NULL, '上巳日祓禊渭濱應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('379b4c68-5881-405f-b802-1613bb6d1801', '夜宴安樂公主新宅應制', '夜宴安乐公主新宅应制', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u9cf3\\u6a13\\u958b\\u95d4\\u5f15\\u660e\\u5149\\uff0c\\u82b1\\u914e\\u9023\\u6dfb\\u9189\\u76ca\\u9999\\u3002\", \"\\u6b32\\u77e5\\u5e1d\\u5973\\u85b0\\u5929\\u8cb4\\uff0c\\u91d1\\u67ef\\u7389\\u67f1\\u591c\\u6210\\u884c\\u3002\"]"', '"[\"\\u51e4\\u697c\\u5f00\\u9616\\u5f15\\u660e\\u5149\\uff0c\\u82b1\\u914e\\u8fde\\u6dfb\\u9189\\u76ca\\u9999\\u3002\", \"\\u6b32\\u77e5\\u5e1d\\u5973\\u85b0\\u5929\\u8d35\\uff0c\\u91d1\\u67ef\\u7389\\u67f1\\u591c\\u6210\\u884c\\u3002\"]"', '诗', 'shi', '', NULL, '夜宴安樂公主新宅應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9231efea-be10-48be-b98b-e823a6ce7ba7', '餞唐永昌', '饯唐永昌', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u91d1\\u6eaa\\u78a7\\u6c34\\u7389\\u6f6d\\u6c99\\uff0c\\u9ce7\\u8204\\u7fe9\\u7fe9\\u5f04\\u65e5\\u83ef\\u3002\", \"\\u9b2c\\u96de\\u9999\\u964c\\u884c\\u6625\\u5026\\uff0c\\u7232\\u6458\\u6771\\u5712\\u6843\\u674e\\u82b1\\u3002\"]"', '"[\"\\u91d1\\u6eaa\\u78a7\\u6c34\\u7389\\u6f6d\\u6c99\\uff0c\\u51eb\\u8204\\u7fe9\\u7fe9\\u5f04\\u65e5\\u534e\\u3002\", \"\\u9b2c\\u9e21\\u9999\\u964c\\u884c\\u6625\\u5026\\uff0c\\u4e3a\\u6458\\u4e1c\\u56ed\\u6843\\u674e\\u82b1\\u3002\"]"', '诗', 'shi', '', NULL, '餞唐永昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0008eb80-baa2-4581-972a-3637a78f909b', '侍宴桃花園', '侍宴桃花园', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u6e90\\u6c34\\u53e2\\u82b1\\u7121\\u6578\\u958b\\uff0c\\u4e39\\u8dd7\\u7d05\\u843c\\u9593\\u9752\\u6885\\u3002\", \"\\u5f9e\\u4eca\\u7d50\\u5b50\\u4e09\\u5343\\u6b72\\uff0c\\u9810\\u559c\\u4ed9\\u904a\\u5fa9\\u6458\\u4f86\\u3002\"]"', '"[\"\\u6e90\\u6c34\\u4e1b\\u82b1\\u65e0\\u6570\\u5f00\\uff0c\\u4e39\\u8dd7\\u7ea2\\u843c\\u95f4\\u9752\\u6885\\u3002\", \"\\u4ece\\u4eca\\u7ed3\\u5b50\\u4e09\\u5343\\u5c81\\uff0c\\u9884\\u559c\\u4ed9\\u6e38\\u590d\\u6458\\u6765\\u3002\"]"', '诗', 'shi', '', NULL, '侍宴桃花園 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64c92e3d-95d0-49d5-a4b5-b3f0f2ee60e0', '石淙', '石淙', 0035879c-b0f0-4bec-9b89-0afac7cd4232, '唐', '"[\"\\u78a7\\u6dc0\\u7d05\\u6d94\\u5d3f\\u5d82\\u9593\\uff0c\\u6dd9\\u5d4c\\u6d11\\u5ca8\\u6d0a\\u6210\\u7063\\u3002\", \"\\u742a\\u6a39\\u7401\\u5a1f\\u82b1\\u672a\\u843d\\uff0c\\u9280\\u829d\\u7a8b\\u419b\\u9732\\u521d\\u9084\\u3002\", \"\\u516b\\u98a8\\u884c\\u6bbf\\u958b\\u4ed9\\u7253\\uff0c\\u4e03\\u666f\\u98db\\u8f3f\\u4e0b\\u77f3\\u95dc\\u3002\", \"\\u5f35\\u8526\\u5e2d\\u96f2\\u5e73\\u5703\\u8b8c\\uff0c\\u711c\\u714c\\u91d1\\u8a18\\u860a\\u540d\\u5c71\\u3002\"]"', '"[\"\\u78a7\\u6dc0\\u7ea2\\u6d94\\u5d3f\\u5d82\\u95f4\\uff0c\\u6dd9\\u5d4c\\u6d11\\u5ca8\\u6d0a\\u6210\\u6e7e\\u3002\", \"\\u742a\\u6811\\u7401\\u5a1f\\u82b1\\u672a\\u843d\\uff0c\\u94f6\\u829d\\u7a8b\\u419b\\u9732\\u521d\\u8fd8\\u3002\", \"\\u516b\\u98ce\\u884c\\u6bbf\\u5f00\\u4ed9\\u7253\\uff0c\\u4e03\\u666f\\u98de\\u8206\\u4e0b\\u77f3\\u5173\\u3002\", \"\\u5f20\\u8311\\u5e2d\\u4e91\\u5e73\\u5703\\u4729\\uff0c\\u711c\\u714c\\u91d1\\u8bb0\\u8574\\u540d\\u5c71\\u3002\"]"', '诗', 'shi', '', NULL, '石淙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec7e4d5-c9a4-4617-acc2-3f11320d1311', '在江南贈宋五之問', '在江南赠宋五之问', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u4e95\\u7d61\\u96d9\\u6e90\\u6fec\\uff0c\\u6f6f\\u967d\\u4e5d\\u6d3e\\u9577\\u3002\", \"\\u6dea\\u6ce2\\u901a\\u5730\\u7a74\\uff0c\\u8f38\\u59d4\\u4e0b\\u6b78\\u5858\\u3002\", \"\\u5225\\u5cf6\\u7c60\\u671d\\u8703\\uff0c\\u9023\\u6d32\\u64c1\\u5915\\u6f32\\u3002\", \"\\u97de\\u73e0\\u6f84\\u7a4d\\u6f64\\uff0c\\u8b93\\u74a7\\u52d5\\u6d6e\\u5149\\u3002\", \"\\u6d6e\\u5149\\u51dd\\u6298\\u6c34\\uff0c\\u7a4d\\u6f64\\u758e\\u5713\\u6c9a\\u3002\", \"\\u7389\\u8f2a\\u6db5\\u5730\\u958b\\uff0c\\u528d\\u95a3\\u9023\\u661f\\u8d77\\u3002\", \"\\u98a8\\u7159\\u6a19\\u8fe5\\u79c0\\uff0c\\u82f1\\u9748\\u4fe1\\u591a\\u7f8e\\u3002\", \"\\u61f7\\u5fb7\\u8e10\\u907a\\u82b3\\uff0c\\u7aef\\u64cd\\u6159\\u8b00\\u5df1\\u3002\", \"\\u8b00\\u5df1\\u8b2c\\u89c0\\u5149\\uff0c\\u727d\\u8ff9\\u5f37\\u60bd\\u60f6\\u3002\", \"\\u63c6\\u62d9\\u8ff7\\u4e09\\u7701\\uff0c\\u52de\\u751f\\u6627\\u5169\\u5fd8\\u3002\", \"\\u5f48\\u96a8\\u7a7a\\u88ab\\u7b11\\uff0c\\u737b\\u695a\\u81ea\\u591a\\u50b7\\u3002\", \"\\u4e00\\u671d\\u6b8a\\u9ed8\\u8a9e\\uff0c\\u5343\\u91cc\\u6613\\u708e\\u6dbc\\u3002\", \"\\u708e\\u6dbc\\u5e7e\\u9077\\u8cbf\\uff0c\\u5ddd\\u9678\\u75b2\\u81fb\\u6e4a\\u3002\", \"\\u7a4d\\u6c34\\u67b6\\u5433\\u6fe4\\uff0c\\u9023\\u5c71\\u6a6b\\u695a\\u5cab\\u3002\", \"\\u98a8\\u6708\\u96d6\\u6b8a\\u6614\\uff0c\\u661f\\u6cb3\\u7336\\u662f\\u820a\\u3002\", \"\\u59d1\\u8607\\u671b\\u5357\\u6d66\\uff0c\\u90af\\u9132\\u901a\\u5317\\u8d70\\u3002\", \"\\u5317\\u8d70\\u5e73\\u751f\\u89aa\\uff0c\\u5357\\u6d66\\u5225\\u96e2\\u6d25\\u3002\", \"\\u701f\\u6e58\\u4e00\\u8d85\\u5ffd\\uff0c\\u6d1e\\u5ead\\u591a\\u82e6\\u8f9b\\u3002\", \"\\u79cb\\u6c5f\\u7121\\u7da0\\u82b7\\uff0c\\u5bd2\\u6c40\\u6709\\u767d\\u860b\\u3002\", \"\\u91c7\\u4e4b\\u5c07\\u4f55\\u907a\\uff0c\\u6545\\u4eba\\u6f33\\u6c34\\u6ff1\\u3002\", \"\\u6f33\\u6ff1\\u5df2\\u907c\\u9060\\uff0c\\u6c5f\\u6f6d\\u672a\\u65cb\\u8fd4\\u3002\", \"\\u7232\\u807d\\u77ed\\u6b4c\\u884c\\uff0c\\u7576\\u60f3\\u9577\\u6d32\\u82d1\\u3002\", \"\\u9732\\u91d1\\u718f\\u83ca\\u5cb8\\uff0c\\u98a8\\u4f69\\u6416\\u862d\\u5742\\u3002\", \"\\u87ec\\u9cf4\\u7a3b\\u8449\\u79cb\\uff0c\\u96c1\\u8d77\\u8606\\u82b1\\u665a\\u3002\", \"\\u665a\\u79cb\\u96f2\\u65e5\\u660e\\uff0c\\u4ead\\u81ef\\u98a8\\u9727\\u6e05\\u3002\", \"\\u7368\\u8ca0\\u5e73\\u751f\\u6c23\\uff0c\\u91cd\\u727d\\u6416\\u843d\\u60c5\\u3002\", \"\\u5360\\u661f\\u975e\\u805a\\u5fb7\\uff0c\\u5922\\u6708\\u8a4e\\u61f8\\u540d\\u3002\", \"\\u5bc2\\u5be5\\u50b7\\u695a\\u594f\\uff0c\\u6dd2\\u65b7\\u6ce3\\u79e6\\u8072\\u3002\", \"\\u79e6\\u8072\\u61f7\\u820a\\u91cc\\uff0c\\u695a\\u594f\\u60b2\\u7121\\u5df2\\u3002\", \"\\u90e2\\u8def\\u5c11\\u77e5\\u97f3\\uff0c\\u53e2\\u81fa\\u5bcc\\u5947\\u58eb\\u3002\", \"\\u6eab\\u8f1d\\u51cc\\u611b\\u65e5\\uff0c\\u58ef\\u6c23\\u9a5a\\u5bd2\\u6c34\\u3002\", \"\\u4e00\\u9867\\u91cd\\u98a8\\u96f2\\uff0c\\u4e09\\u51ac\\u8db3\\u6587\\u53f2\\u3002\", \"\\u6587\\u53f2\\u76db\\u7d1b\\u7db8\\uff0c\\u4eac\\u6d1b\\u591a\\u98a8\\u5875\\u3002\", \"\\u7336\\u8f15\\u4e94\\u8eca\\u5bcc\\uff0c\\u672a\\u91cd\\u4e00\\u56ca\\u8ca7\\u3002\", \"\\u674e\\u4ed9\\u975e\\u6613\\u8a17\\uff0c\\u8607\\u9b3c\\u5c1a\\u96e3\\u56e0\\u3002\", \"\\u4e0d\\u60dc\\u52de\\u6b4c\\u76e1\\uff0c\\u8ab0\\u7232\\u807d\\u967d\\u6625\\u3002\"]"', '"[\"\\u4e95\\u7edc\\u53cc\\u6e90\\u6fec\\uff0c\\u6d54\\u9633\\u4e5d\\u6d3e\\u957f\\u3002\", \"\\u6ca6\\u6ce2\\u901a\\u5730\\u7a74\\uff0c\\u8f93\\u59d4\\u4e0b\\u5f52\\u5858\\u3002\", \"\\u522b\\u5c9b\\u7b3c\\u671d\\u8703\\uff0c\\u8fde\\u6d32\\u62e5\\u5915\\u6da8\\u3002\", \"\\u97eb\\u73e0\\u6f84\\u79ef\\u6da6\\uff0c\\u8ba9\\u74a7\\u52a8\\u6d6e\\u5149\\u3002\", \"\\u6d6e\\u5149\\u51dd\\u6298\\u6c34\\uff0c\\u79ef\\u6da6\\u758e\\u5706\\u6c9a\\u3002\", \"\\u7389\\u8f6e\\u6db5\\u5730\\u5f00\\uff0c\\u5251\\u9601\\u8fde\\u661f\\u8d77\\u3002\", \"\\u98ce\\u70df\\u6807\\u8fe5\\u79c0\\uff0c\\u82f1\\u7075\\u4fe1\\u591a\\u7f8e\\u3002\", \"\\u6000\\u5fb7\\u8df5\\u9057\\u82b3\\uff0c\\u7aef\\u64cd\\u6159\\u8c0b\\u5df1\\u3002\", \"\\u8c0b\\u5df1\\u8c2c\\u89c2\\u5149\\uff0c\\u7275\\u8ff9\\u5f3a\\u51c4\\u60f6\\u3002\", \"\\u63c6\\u62d9\\u8ff7\\u4e09\\u7701\\uff0c\\u52b3\\u751f\\u6627\\u4e24\\u5fd8\\u3002\", \"\\u5f39\\u968f\\u7a7a\\u88ab\\u7b11\\uff0c\\u732e\\u695a\\u81ea\\u591a\\u4f24\\u3002\", \"\\u4e00\\u671d\\u6b8a\\u9ed8\\u8bed\\uff0c\\u5343\\u91cc\\u6613\\u708e\\u51c9\\u3002\", \"\\u708e\\u51c9\\u51e0\\u8fc1\\u8d38\\uff0c\\u5ddd\\u9646\\u75b2\\u81fb\\u51d1\\u3002\", \"\\u79ef\\u6c34\\u67b6\\u5434\\u6d9b\\uff0c\\u8fde\\u5c71\\u6a2a\\u695a\\u5cab\\u3002\", \"\\u98ce\\u6708\\u867d\\u6b8a\\u6614\\uff0c\\u661f\\u6cb3\\u72b9\\u662f\\u65e7\\u3002\", \"\\u59d1\\u82cf\\u671b\\u5357\\u6d66\\uff0c\\u90af\\u90f8\\u901a\\u5317\\u8d70\\u3002\", \"\\u5317\\u8d70\\u5e73\\u751f\\u4eb2\\uff0c\\u5357\\u6d66\\u522b\\u79bb\\u6d25\\u3002\", \"\\u6f47\\u6e58\\u4e00\\u8d85\\u5ffd\\uff0c\\u6d1e\\u5ead\\u591a\\u82e6\\u8f9b\\u3002\", \"\\u79cb\\u6c5f\\u65e0\\u7eff\\u82b7\\uff0c\\u5bd2\\u6c40\\u6709\\u767d\\u82f9\\u3002\", \"\\u91c7\\u4e4b\\u5c06\\u4f55\\u9057\\uff0c\\u6545\\u4eba\\u6f33\\u6c34\\u6ee8\\u3002\", \"\\u6f33\\u6ee8\\u5df2\\u8fbd\\u8fdc\\uff0c\\u6c5f\\u6f6d\\u672a\\u65cb\\u8fd4\\u3002\", \"\\u4e3a\\u542c\\u77ed\\u6b4c\\u884c\\uff0c\\u5f53\\u60f3\\u957f\\u6d32\\u82d1\\u3002\", \"\\u9732\\u91d1\\u718f\\u83ca\\u5cb8\\uff0c\\u98ce\\u4f69\\u6447\\u5170\\u5742\\u3002\", \"\\u8749\\u9e23\\u7a3b\\u53f6\\u79cb\\uff0c\\u96c1\\u8d77\\u82a6\\u82b1\\u665a\\u3002\", \"\\u665a\\u79cb\\u4e91\\u65e5\\u660e\\uff0c\\u4ead\\u81ef\\u98ce\\u96fe\\u6e05\\u3002\", \"\\u72ec\\u8d1f\\u5e73\\u751f\\u6c14\\uff0c\\u91cd\\u7275\\u6447\\u843d\\u60c5\\u3002\", \"\\u5360\\u661f\\u975e\\u805a\\u5fb7\\uff0c\\u68a6\\u6708\\u8bb5\\u60ac\\u540d\\u3002\", \"\\u5bc2\\u5be5\\u4f24\\u695a\\u594f\\uff0c\\u51c4\\u65ad\\u6ce3\\u79e6\\u58f0\\u3002\", \"\\u79e6\\u58f0\\u6000\\u65e7\\u91cc\\uff0c\\u695a\\u594f\\u60b2\\u65e0\\u5df2\\u3002\", \"\\u90e2\\u8def\\u5c11\\u77e5\\u97f3\\uff0c\\u4e1b\\u53f0\\u5bcc\\u5947\\u58eb\\u3002\", \"\\u6e29\\u8f89\\u51cc\\u7231\\u65e5\\uff0c\\u58ee\\u6c14\\u60ca\\u5bd2\\u6c34\\u3002\", \"\\u4e00\\u987e\\u91cd\\u98ce\\u4e91\\uff0c\\u4e09\\u51ac\\u8db3\\u6587\\u53f2\\u3002\", \"\\u6587\\u53f2\\u76db\\u7eb7\\u7eb6\\uff0c\\u4eac\\u6d1b\\u591a\\u98ce\\u5c18\\u3002\", \"\\u72b9\\u8f7b\\u4e94\\u8f66\\u5bcc\\uff0c\\u672a\\u91cd\\u4e00\\u56ca\\u8d2b\\u3002\", \"\\u674e\\u4ed9\\u975e\\u6613\\u6258\\uff0c\\u82cf\\u9b3c\\u5c1a\\u96be\\u56e0\\u3002\", \"\\u4e0d\\u60dc\\u52b3\\u6b4c\\u5c3d\\uff0c\\u8c01\\u4e3a\\u542c\\u9633\\u6625\\u3002\"]"', '诗', 'shi', '', NULL, '在江南贈宋五之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c25a672-ea4a-44fa-bd0f-44d87cca8fef', '晚憩田家', '晚憩田家', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u8f49\\u84ec\\u52de\\u9060\\u5f79\\uff0c\\u62ab\\u859c\\u4e0b\\u7530\\u5bb6\\u3002\", \"\\u5c71\\u5f62\\u985e\\u4e5d\\u6298\\uff0c\\u6c34\\u52e2\\u6025\\u4e09\\u5df4\\u3002\", \"\\u61f8\\u6881\\u63a5\\u65b7\\u5cb8\\uff0c\\u6f80\\u8def\\u64c1\\u5d29\\u67e5\\u3002\", \"\\u9727\\u5dd6\\u6dea\\u66c9\\u9b44\\uff0c\\u98a8\\u6f35\\u6f32\\u5bd2\\u6c99\\u3002\", \"\\u5fc3\\u8ff9\\u4e00\\u671d\\u821b\\uff0c\\u95dc\\u5c71\\u842c\\u91cc\\u8cd2\\u3002\", \"\\u9f8d\\u7ae0\\u5f92\\u8868\\u8d8a\\uff0c\\u95a9\\u4fd7\\u672c\\u6b8a\\u83ef\\u3002\", \"\\u65c5\\u884c\\u60b2\\u6cdb\\u6897\\uff0c\\u96e2\\u8d08\\u6298\\u758e\\u9ebb\\u3002\", \"\\u552f\\u6709\\u5bd2\\u6f6d\\u83ca\\uff0c\\u7368\\u4f3c\\u6545\\u5712\\u82b1\\u3002\"]"', '"[\"\\u8f6c\\u84ec\\u52b3\\u8fdc\\u5f79\\uff0c\\u62ab\\u859c\\u4e0b\\u7530\\u5bb6\\u3002\", \"\\u5c71\\u5f62\\u7c7b\\u4e5d\\u6298\\uff0c\\u6c34\\u52bf\\u6025\\u4e09\\u5df4\\u3002\", \"\\u60ac\\u6881\\u63a5\\u65ad\\u5cb8\\uff0c\\u6da9\\u8def\\u62e5\\u5d29\\u67e5\\u3002\", \"\\u96fe\\u5ca9\\u6ca6\\u6653\\u9b44\\uff0c\\u98ce\\u6e86\\u6da8\\u5bd2\\u6c99\\u3002\", \"\\u5fc3\\u8ff9\\u4e00\\u671d\\u821b\\uff0c\\u5173\\u5c71\\u4e07\\u91cc\\u8d4a\\u3002\", \"\\u9f99\\u7ae0\\u5f92\\u8868\\u8d8a\\uff0c\\u95fd\\u4fd7\\u672c\\u6b8a\\u534e\\u3002\", \"\\u65c5\\u884c\\u60b2\\u6cdb\\u6897\\uff0c\\u79bb\\u8d60\\u6298\\u758e\\u9ebb\\u3002\", \"\\u552f\\u6709\\u5bd2\\u6f6d\\u83ca\\uff0c\\u72ec\\u4f3c\\u6545\\u56ed\\u82b1\\u3002\"]"', '诗', 'shi', '', NULL, '晚憩田家 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e654986-7570-4fd7-bd24-a404bb559231', '出石門', '出石门', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u5c64\\u5dd6\\u9060\\u63a5\\u5929\\uff0c\\u7d55\\u5dba\\u4e0a\\u68f2\\u70df\\u3002\", \"\\u677e\\u4f4e\\u8f15\\u84cb\\u5043\\uff0c\\u85e4\\u7d30\\u5f31\\u7d72\\u61f8\\u3002\", \"\\u77f3\\u660e\\u5982\\u6302\\u93e1\\uff0c\\u82d4\\u5206\\u4f3c\\u5217\\u9322\\u3002\"]"', '"[\"\\u5c42\\u5ca9\\u8fdc\\u63a5\\u5929\\uff0c\\u7edd\\u5cad\\u4e0a\\u6816\\u70df\\u3002\", \"\\u677e\\u4f4e\\u8f7b\\u76d6\\u5043\\uff0c\\u85e4\\u7ec6\\u5f31\\u4e1d\\u60ac\\u3002\", \"\\u77f3\\u660e\\u5982\\u6302\\u955c\\uff0c\\u82d4\\u5206\\u4f3c\\u5217\\u94b1\\u3002\"]"', '诗', 'shi', '', NULL, '出石門 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8a2598a-eac5-4f9b-bf91-28a0f8b551d3', '至分陝', '至分陕', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u965d\\u897f\\u958b\\u52dd\\u58e4\\uff0c\\u53ec\\u5357\\u5206\\u6c83\\u7587\\u3002\", \"\\u5217\\u6a39\\u5de2\\u7dad\\u9d72\\uff0c\\u5e73\\u6e1a\\u4e0b\\u96ce\\u9ce9\\u3002\", \"\\u61a9\\u68e0\\u7591\\u52ff\\u526a\\uff0c\\u66f3\\u845b\\u4f3c\\u6500\\u6a1b\\u3002\", \"\\u81f3\\u4eca\\u738b\\u5316\\u7f8e\\uff0c\\u975e\\u7368\\u5728\\u9686\\u5468\\u3002\"]"', '"[\"\\u9655\\u897f\\u5f00\\u80dc\\u58e4\\uff0c\\u53ec\\u5357\\u5206\\u6c83\\u7574\\u3002\", \"\\u5217\\u6811\\u5de2\\u7ef4\\u9e4a\\uff0c\\u5e73\\u6e1a\\u4e0b\\u96ce\\u9e20\\u3002\", \"\\u61a9\\u68e0\\u7591\\u52ff\\u526a\\uff0c\\u66f3\\u845b\\u4f3c\\u6500\\u6a1b\\u3002\", \"\\u81f3\\u4eca\\u738b\\u5316\\u7f8e\\uff0c\\u975e\\u72ec\\u5728\\u9686\\u5468\\u3002\"]"', '诗', 'shi', '', NULL, '至分陝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('559b5111-b3a5-4f30-8ecf-e4f8c241bfd3', '寓居洛濱對雪憶謝二', '寓居洛滨对雪忆谢二', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u65c5\\u601d\\u7707\\u96e3\\u88c1\\uff0c\\u885d\\u98c6\\u6068\\u6613\\u54c0\\u3002\", \"\\u66e0\\u671b\\u6d1b\\u5ddd\\u665a\\uff0c\\u98c4\\u98bb\\u745e\\u96ea\\u4f86\\u3002\", \"\\u7a4d\\u5f69\\u660e\\u66f8\\u5e4c\\uff0c\\u6d41\\u97fb\\u7e5e\\u7434\\u81fa\\u3002\", \"\\u8272\\u596a\\u8fce\\u4ed9\\u7fbd\\uff0c\\u82b1\\u907f\\u72af\\u971c\\u6885\\u3002\", \"\\u8b1d\\u5ead\\u8cde\\u65b9\\u9038\\uff0c\\u8881\\u6249\\u63a9\\u672a\\u958b\\u3002\", \"\\u9ad8\\u4eba\\u513b\\u6709\\u8a2a\\uff0c\\u8208\\u76e1\\u8a4e\\u9808\\u56de\\u3002\"]"', '"[\"\\u65c5\\u601d\\u7707\\u96be\\u88c1\\uff0c\\u51b2\\u98d9\\u6068\\u6613\\u54c0\\u3002\", \"\\u65f7\\u671b\\u6d1b\\u5ddd\\u665a\\uff0c\\u98d8\\u98d6\\u745e\\u96ea\\u6765\\u3002\", \"\\u79ef\\u5f69\\u660e\\u4e66\\u5e4c\\uff0c\\u6d41\\u97f5\\u7ed5\\u7434\\u53f0\\u3002\", \"\\u8272\\u593a\\u8fce\\u4ed9\\u7fbd\\uff0c\\u82b1\\u907f\\u72af\\u971c\\u6885\\u3002\", \"\\u8c22\\u5ead\\u8d4f\\u65b9\\u9038\\uff0c\\u8881\\u6249\\u63a9\\u672a\\u5f00\\u3002\", \"\\u9ad8\\u4eba\\u50a5\\u6709\\u8bbf\\uff0c\\u5174\\u5c3d\\u8bb5\\u987b\\u56de\\u3002\"]"', '诗', 'shi', '', NULL, '寓居洛濱對雪憶謝二 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b53202-0db0-4bee-a5a4-3c4f6a593441', '北眺舂陵', '北眺舂陵', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u652c\\u8f61\\u75b2\\u5bb5\\u9081\\uff0c\\u9a45\\u99ac\\u5026\\u6668\\u8208\\u3002\", \"\\u65e2\\u51fa\\u5c01\\u6ce5\\u8c37\\uff0c\\u9084\\u904e\\u907f\\u96e8\\u9675\\u3002\", \"\\u5c71\\u884c\\u660e\\u7167\\u4e0a\\uff0c\\u8c3f\\u5bbf\\u5bc6\\u96f2\\u84b8\\u3002\", \"\\u767b\\u9ad8\\u5f92\\u6b32\\u8ce6\\uff0c\\u8a5e\\u6bab\\u7368\\u64ab\\u81ba\\u3002\"]"', '"[\"\\u63fd\\u8f94\\u75b2\\u5bb5\\u8fc8\\uff0c\\u9a71\\u9a6c\\u5026\\u6668\\u5174\\u3002\", \"\\u65e2\\u51fa\\u5c01\\u6ce5\\u8c37\\uff0c\\u8fd8\\u8fc7\\u907f\\u96e8\\u9675\\u3002\", \"\\u5c71\\u884c\\u660e\\u7167\\u4e0a\\uff0c\\u8c3f\\u5bbf\\u5bc6\\u4e91\\u84b8\\u3002\", \"\\u767b\\u9ad8\\u5f92\\u6b32\\u8d4b\\uff0c\\u8bcd\\u6b9a\\u72ec\\u629a\\u81ba\\u3002\"]"', '诗', 'shi', '', NULL, '北眺舂陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40f98789-087f-4f4e-9912-df084e93bd4b', '夏日遊目聊作', '夏日游目聊作', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u66ab\\u5c4f\\u56c2\\u5875\\u7d2f\\uff0c\\u8a00\\u5c0b\\u7269\\u5916\\u60c5\\u3002\", \"\\u81f4\\u9038\\u5fc3\\u903e\\u9ed8\\uff0c\\u795e\\u5e7d\\u9ad4\\u81ea\\u8f15\\u3002\", \"\\u6d66\\u590f\\u8377\\u9999\\u6eff\\uff0c\\u7530\\u79cb\\u9ea5\\u6c23\\u6e05\\u3002\", \"\\u8a4e\\u5047\\u6ec4\\u6d6a\\u4e0a\\uff0c\\u5c07\\u6fef\\u695a\\u81e3\\u7e93\\u3002\"]"', '"[\"\\u6682\\u5c4f\\u56a3\\u5c18\\u7d2f\\uff0c\\u8a00\\u5bfb\\u7269\\u5916\\u60c5\\u3002\", \"\\u81f4\\u9038\\u5fc3\\u903e\\u9ed8\\uff0c\\u795e\\u5e7d\\u4f53\\u81ea\\u8f7b\\u3002\", \"\\u6d66\\u590f\\u8377\\u9999\\u6ee1\\uff0c\\u7530\\u79cb\\u9ea6\\u6c14\\u6e05\\u3002\", \"\\u8bb5\\u5047\\u6ca7\\u6d6a\\u4e0a\\uff0c\\u5c06\\u6fef\\u695a\\u81e3\\u7f28\\u3002\"]"', '诗', 'shi', '', NULL, '夏日遊目聊作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba03d8d7-455d-4243-9abe-cd6f4422ab7c', '同崔駙馬曉初登樓思京', '同崔驸马晓初登楼思京', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u9e97\\u8b59\\u901a\\u56db\\u671b\\uff0c\\u7e41\\u6182\\u8d77\\u842c\\u7aef\\u3002\", \"\\u7dba\\u758f\\u4f4e\\u665a\\u9b44\\uff0c\\u93e4\\u6abb\\u8085\\u521d\\u5bd2\\u3002\", \"\\u767d\\u96f2\\u9109\\u601d\\u9060\\uff0c\\u9ec3\\u5716\\u6b78\\u8def\\u96e3\\u3002\", \"\\u552f\\u9918\\u897f\\u5411\\u7b11\\uff0c\\u66ab\\u4f3c\\u7576\\u9577\\u5b89\\u3002\"]"', '"[\"\\u4e3d\\u8c2f\\u901a\\u56db\\u671b\\uff0c\\u7e41\\u5fe7\\u8d77\\u4e07\\u7aef\\u3002\", \"\\u7eee\\u758f\\u4f4e\\u665a\\u9b44\\uff0c\\u9542\\u69db\\u8083\\u521d\\u5bd2\\u3002\", \"\\u767d\\u4e91\\u4e61\\u601d\\u8fdc\\uff0c\\u9ec4\\u56fe\\u5f52\\u8def\\u96be\\u3002\", \"\\u552f\\u4f59\\u897f\\u5411\\u7b11\\uff0c\\u6682\\u4f3c\\u5f53\\u957f\\u5b89\\u3002\"]"', '诗', 'shi', '', NULL, '同崔駙馬曉初登樓思京 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fe224ee-4774-4382-9d86-f594c49cc1ac', '月夜有懷簡諸同病', '月夜有怀简诸同病', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u9591\\u5ead\\u843d\\u666f\\u76e1\\uff0c\\u758e\\u7c3e\\u591c\\u6708\\u901a\\u3002\", \"\\u5c71\\u9748\\u97ff\\u4f3c\\u61c9\\uff0c\\u6c34\\u6de8\\u671b\\u5982\\u7a7a\\u3002\", \"\\u68f2\\u679d\\u7336\\u7e5e\\u9d72\\uff0c\\u9075\\u6e1a\\u672a\\u4f86\\u9d3b\\u3002\", \"\\u53ef\\u6b4e\\u9ad8\\u6a13\\u5a66\\uff0c\\u60b2\\u601d\\u6773\\u96e3\\u7d42\\u3002\"]"', '"[\"\\u95f2\\u5ead\\u843d\\u666f\\u5c3d\\uff0c\\u758e\\u5e18\\u591c\\u6708\\u901a\\u3002\", \"\\u5c71\\u7075\\u54cd\\u4f3c\\u5e94\\uff0c\\u6c34\\u51c0\\u671b\\u5982\\u7a7a\\u3002\", \"\\u6816\\u679d\\u72b9\\u7ed5\\u9e4a\\uff0c\\u9075\\u6e1a\\u672a\\u6765\\u9e3f\\u3002\", \"\\u53ef\\u53f9\\u9ad8\\u697c\\u5987\\uff0c\\u60b2\\u601d\\u6773\\u96be\\u7ec8\\u3002\"]"', '诗', 'shi', '', NULL, '月夜有懷簡諸同病 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64c7e2d4-b307-45a8-99a4-746811580560', '敘寄員半千', '叙寄员半千', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u8584\\u5ba6\\u4e09\\u6cb3\\u9053\\uff0c\\u81ea\\u8ca0\\u5341\\u9918\\u5e74\\u3002\", \"\\u4e0d\\u61c9\\u9a5a\\u82e5\\u53b2\\uff0c\\u79ea\\u7232\\u76f4\\u5982\\u5f26\\u3002\", \"\\u5750\\u6b77\\u5c71\\u5ddd\\u96aa\\uff0c\\u5401\\u55df\\u9675\\u8c37\\u9077\\u3002\", \"\\u9577\\u541f\\u7a7a\\u62b1\\u819d\\uff0c\\u77ed\\u7fee\\u8a4e\\u6c96\\u5929\\u3002\", \"\\u9b42\\u6b78\\u6ec4\\u6d77\\u4e0a\\uff0c\\u671b\\u65b7\\u767d\\u96f2\\u524d\\u3002\", \"\\u91e3\\u540d\\u52de\\u62fe\\u7d2b\\uff0c\\u96b1\\u8ff9\\u81ea\\u8ac7\\u7384\\u3002\", \"\\u4e0d\\u5b78\\u591a\\u80fd\\u8056\\uff0c\\u5f92\\u601d\\u9d3b\\u5bf6\\u4ed9\\u3002\", \"\\u65af\\u5fd7\\u826f\\u96e3\\u5df2\\uff0c\\u6b64\\u9053\\u8c48\\u5f92\\u7136\\u3002\", \"\\u55df\\u7232\\u5200\\u7b46\\u540f\\uff0c\\u6065\\u5f9e\\u7e69\\u58a8\\u727d\\u3002\", \"\\u5c90\\u8def\\u60c5\\u96d6\\u72ce\\uff0c\\u4eba\\u502b\\u5730\\u672c\\u504f\\u3002\", \"\\u9577\\u63d6\\u8b1d\\u6642\\u4e8b\\uff0c\\u7368\\u5f80\\u8a2a\\u6797\\u6cc9\\u3002\", \"\\u5bc4\\u8a00\\u4e8c\\u4e09\\u5b50\\uff0c\\u751f\\u6b7b\\u4e0d\\u4f86\\u65cb\\u3002\"]"', '"[\"\\u8584\\u5ba6\\u4e09\\u6cb3\\u9053\\uff0c\\u81ea\\u8d1f\\u5341\\u4f59\\u5e74\\u3002\", \"\\u4e0d\\u5e94\\u60ca\\u82e5\\u5389\\uff0c\\u79ea\\u4e3a\\u76f4\\u5982\\u5f26\\u3002\", \"\\u5750\\u5386\\u5c71\\u5ddd\\u9669\\uff0c\\u5401\\u55df\\u9675\\u8c37\\u8fc1\\u3002\", \"\\u957f\\u541f\\u7a7a\\u62b1\\u819d\\uff0c\\u77ed\\u7fee\\u8bb5\\u51b2\\u5929\\u3002\", \"\\u9b42\\u5f52\\u6ca7\\u6d77\\u4e0a\\uff0c\\u671b\\u65ad\\u767d\\u4e91\\u524d\\u3002\", \"\\u9493\\u540d\\u52b3\\u62fe\\u7d2b\\uff0c\\u9690\\u8ff9\\u81ea\\u8c08\\u7384\\u3002\", \"\\u4e0d\\u5b66\\u591a\\u80fd\\u5723\\uff0c\\u5f92\\u601d\\u9e3f\\u5b9d\\u4ed9\\u3002\", \"\\u65af\\u5fd7\\u826f\\u96be\\u5df2\\uff0c\\u6b64\\u9053\\u5c82\\u5f92\\u7136\\u3002\", \"\\u55df\\u4e3a\\u5200\\u7b14\\u540f\\uff0c\\u803b\\u4ece\\u7ef3\\u58a8\\u7275\\u3002\", \"\\u5c90\\u8def\\u60c5\\u867d\\u72ce\\uff0c\\u4eba\\u4f26\\u5730\\u672c\\u504f\\u3002\", \"\\u957f\\u63d6\\u8c22\\u65f6\\u4e8b\\uff0c\\u72ec\\u5f80\\u8bbf\\u6797\\u6cc9\\u3002\", \"\\u5bc4\\u8a00\\u4e8c\\u4e09\\u5b50\\uff0c\\u751f\\u6b7b\\u4e0d\\u6765\\u65cb\\u3002\"]"', '诗', 'shi', '', NULL, '敘寄員半千 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6088068-092c-4c42-b8dc-a478b18c68a1', '代女道士王靈妃贈道士李榮', '代女道士王灵妃赠道士李荣', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u7384\\u90fd\\u4e94\\u5e9c\\u98a8\\u5875\\u7d55\\uff0c\\u78a7\\u6d77\\u4e09\\u5c71\\u6ce2\\u6d6a\\u6df1\\u3002\", \"\\u6843\\u5be6\\u5343\\u5e74\\u975e\\u6613\\u5f85\\uff0c\\u6851\\u7530\\u4e00\\u8b8a\\u5df2\\u96e3\\u5c0b\\u3002\", \"\\u5225\\u6709\\u4ed9\\u5c45\\u5c0d\\u4e09\\u5e02\\uff0c\\u91d1\\u95d5\\u9280\\u5bae\\u76f8\\u5411\\u8d77\\u3002\", \"\\u81fa\\u524d\\u93e1\\u5f71\\u4f34\\u4ed9\\u5a25\\uff0c\\u6a13\\u4e0a\\u7c2b\\u8072\\u96a8\\u9cf3\\u53f2\\u3002\", \"\\u9cf3\\u6a13\\u8fe2\\u905e\\u7d55\\u5875\\u57c3\\uff0c\\u9daf\\u6642\\u7269\\u8272\\u6b63\\u88f4\\u56de\\u3002\", \"\\u9748\\u829d\\u7d2b\\u6aa2\\u53c3\\u5dee\\u9577\\uff0c\\u4ed9\\u6842\\u4e39\\u82b1\\u91cd\\u758a\\u958b\\u3002\", \"\\u96d9\\u7ae5\\u7dbd\\u7d04\\u6642\\u904a\\u965f\\uff0c\\u4e09\\u9ce5\\u806f\\u7fe9\\u5831\\u6d88\\u606f\\u3002\", \"\\u76e1\\u8a00\\u771f\\u4fb6\\u51fa\\u9068\\u904a\\uff0c\\u50b3\\u9053\\u98a8\\u5149\\u7121\\u9650\\u6975\\u3002\", \"\\u8f15\\u82b1\\u59d4\\u780c\\u60f9\\u88fe\\u9999\\uff0c\\u6b98\\u6708\\u7aba\\u7a97\\u8998\\u5e4c\\u8272\\u3002\", \"\\u7b87\\u6642\\u7121\\u6578\\u5002\\u5996\\u598d\\uff0c\\u7b87\\u88cf\\u7121\\u7aae\\u7e3d\\u53ef\\u6190\\u3002\", \"\\u5225\\u6709\\u8846\\u4e2d\\u7a31\\u9edc\\u5e1d\\uff0c\\u5929\\u4e0a\\u4eba\\u9593\\u5c11\\u6d41\\u4f8b\\u3002\", \"\\u6d1b\\u6ff1\\u4ed9\\u99d5\\u5553\\u9059\\u6e90\\uff0c\\u6dee\\u6d66\\u9748\\u6d25\\u7b26\\u9060\\u7b6e\\u3002\", \"\\u81ea\\u8a00\\u5c11\\u5c0f\\u6155\\u5e7d\\u7384\\uff0c\\u53ea\\u8a00\\u5bb9\\u6613\\u5f97\\u795e\\u4ed9\\u3002\", \"\\u73ee\\u4e2d\\u9080\\u52d2\\u7d93\\u6642\\u5e8f\\uff0c\\u7c2b\\u88cf\\u5c0b\\u601d\\u5fa9\\u5e7e\\u5e74\\u3002\", \"\\u5c0b\\u601d\\u8a31\\u4e8b\\u771f\\u60c5\\u8b8a\\uff0c\\u4e8c\\u4eba\\u5bb9\\u83ef\\u8b58\\u5c11\\u9078\\u3002\", \"\\u6f2b\\u9053\\u71d2\\u4e39\\u6b62\\u4e03\\u98db\\uff0c\\u7a7a\\u50b3\\u5316\\u77f3\\u66fe\\u4e09\\u8f49\\u3002\", \"\\u5bc4\\u8a9e\\u5929\\u4e0a\\u5f04\\u6a5f\\u4eba\\uff0c\\u5bc4\\u8a9e\\u6cb3\\u908a\\u503c\\u67e5\\u5ba2\\u3002\", \"\\u4e4d\\u53ef\\u60a4\\u60a4\\u5171\\u767e\\u5e74\\uff0c\\u8ab0\\u4f7f\\u9059\\u9059\\u671f\\u4e03\\u5915\\u3002\", \"\\u60f3\\u77e5\\u4eba\\u610f\\u81ea\\u76f8\\u5c0b\\uff0c\\u679c\\u5f97\\u6df1\\u5fc3\\u5171\\u4e00\\u5fc3\\u3002\", \"\\u4e00\\u5fc3\\u4e00\\u610f\\u7121\\u7aae\\u5df2\\uff0c\\u6295\\u6f06\\u6295\\u81a0\\u975e\\u8db3\\u64ec\\u3002\", \"\\u53ea\\u5c07\\u7f9e\\u6f80\\u7576\\u98a8\\u6d41\\uff0c\\u6301\\u6b64\\u76f8\\u6190\\u4fdd\\u7d42\\u59cb\\u3002\", \"\\u76f8\\u6190\\u76f8\\u5ff5\\u500d\\u76f8\\u89aa\\uff0c\\u4e00\\u751f\\u4e00\\u4ee3\\u4e00\\u96d9\\u4eba\\u3002\", \"\\u4e0d\\u628a\\u4e39\\u5fc3\\u6bd4\\u7384\\u77f3\\uff0c\\u60df\\u5c07\\u6fc1\\u6c34\\u6cc1\\u6e05\\u5875\\u3002\", \"\\u53ea\\u8a00\\u67f1\\u4e0b\\u7559\\u671f\\u4fe1\\uff0c\\u597d\\u6b32\\u5c07\\u5fc3\\u5b78\\u677e\\u8563\\u3002\", \"\\u4e0d\\u80fd\\u4eac\\u5146\\u756b\\u5ce8\\u7709\\uff0c\\u7ffb\\u5411\\u6210\\u90fd\\u9a01\\u9a36\\u5f15\\u3002\", \"\\u9752\\u725b\\u7d2b\\u6c23\\u5ea6\\u9748\\u95dc\\uff0c\\u5c3a\\u7d20\\u8d69\\u9c57\\u53bb\\u4e0d\\u9084\\u3002\", \"\\u9023\\u82d4\\u4e0a\\u780c\\u7121\\u7aae\\u7da0\\uff0c\\u4fee\\u7af9\\u81e8\\u58c7\\u5e7e\\u8655\\u6591\\u3002\", \"\\u6b64\\u6642\\u7a7a\\u7240\\u96e3\\u7368\\u5b88\\uff0c\\u6b64\\u65e5\\u5225\\u96e2\\u90a3\\u53ef\\u4e45\\u3002\", \"\\u6885\\u82b1\\u5982\\u96ea\\u67f3\\u5982\\u7d72\\uff0c\\u5e74\\u53bb\\u5e74\\u4f86\\u4e0d\\u81ea\\u6301\\u3002\", \"\\u521d\\u8a00\\u5225\\u5728\\u5bd2\\u504f\\u5728\\uff0c\\u4f55\\u609f\\u6625\\u4f86\\u6625\\u66f4\\u601d\\u3002\", \"\\u6625\\u6642\\u7269\\u8272\\u7121\\u7aef\\u7dd2\\uff0c\\u96d9\\u6795\\u5b64\\u7720\\u8ab0\\u5206\\u8a31\\u3002\", \"\\u5206\\u5ff5\\u5b0c\\u9daf\\u4e00\\u7a2e\\u557c\\uff0c\\u751f\\u618e\\u71d5\\u5b50\\u5343\\u822c\\u8a9e\\u3002\", \"\\u671d\\u96f2\\u65ed\\u65e5\\u7167\\u9752\\u6a13\\uff0c\\u9072\\u6689\\u9e97\\u8272\\u6eff\\u7687\\u5dde\\u3002\", \"\\u843d\\u82b1\\u6cdb\\u6cdb\\u6d6e\\u9748\\u6cbc\\uff0c\\u5782\\u67f3\\u9577\\u9577\\u62c2\\u5fa1\\u6e9d\\u3002\", \"\\u5fa1\\u6e9d\\u5927\\u9053\\u591a\\u5947\\u8cde\\uff0c\\u4fe0\\u5ba2\\u5996\\u5bb9\\u905e\\u4f86\\u5f80\\u3002\", \"\\u5bf6\\u9a0e\\u9023\\u82b1\\u9435\\u4f5c\\u9322\\uff0c\\u9999\\u8f2a\\u9a16\\u6c34\\u73e0\\u7232\\u7db2\\u3002\", \"\\u9999\\u8f2a\\u5bf6\\u9a0e\\u7af6\\u7e41\\u83ef\\uff0c\\u53ef\\u6190\\u4eca\\u591c\\u5bbf\\u5021\\u5bb6\\u3002\", \"\\u9e1a\\u9d61\\u676f\\u4e2d\\u6d6e\\u7af9\\u8449\\uff0c\\u9cf3\\u51f0\\u7434\\u88cf\\u843d\\u6885\\u82b1\\u3002\", \"\\u8a31\\u8f29\\u591a\\u60c5\\u504f\\u9001\\u6b3e\\uff0c\\u7232\\u554f\\u6625\\u82b1\\u5e7e\\u6642\\u6eff\\u3002\", \"\\u5343\\u56de\\u9ce5\\u4fe1\\u8aaa\\u8846\\u8af8\\uff0c\\u767e\\u904e\\u9daf\\u557c\\u8aaa\\u9577\\u77ed\\u3002\", \"\\u9577\\u77ed\\u8846\\u8af8\\u5224\\u4e0d\\u5c0b\\uff0c\\u5343\\u56de\\u767e\\u904e\\u6d6a\\u95dc\\u5fc3\\u3002\", \"\\u4f55\\u66fe\\u8209\\u610f\\u897f\\u9130\\u7389\\uff0c\\u672a\\u80af\\u7559\\u60c5\\u5357\\u964c\\u91d1\\u3002\", \"\\u5357\\u964c\\u897f\\u9130\\u54b8\\u81ea\\u4fdd\\uff0c\\u9084\\u8f61\\u6b78\\u671f\\u9808\\u53ca\\u65e9\\u3002\", \"\\u7232\\u60f3\\u4e09\\u6625\\u72f9\\u659c\\u8def\\uff0c\\u83ab\\u8fad\\u4e5d\\u6298\\u909b\\u95dc\\u9053\\u3002\", \"\\u5047\\u4ee4\\u767d\\u91cc\\u4f3c\\u9577\\u5b89\\uff0c\\u9808\\u4f7f\\u9752\\u725b\\u5b78\\u528d\\u7aef\\u3002\", \"\\u860b\\u98a8\\u5165\\u99ad\\u4f86\\u61c9\\u6613\\uff0c\\u7af9\\u6756\\u6210\\u9f8d\\u53bb\\u4e0d\\u96e3\\u3002\", \"\\u9f8d\\u98c6\\u53bb\\u53bb\\u7121\\u6d88\\u606f\\uff0c\\u9e1e\\u93e1\\u671d\\u671d\\u6e1b\\u5bb9\\u8272\\u3002\", \"\\u541b\\u5fc3\\u4e0d\\u8a18\\u4e0b\\u5c71\\u4eba\\uff0c\\u59be\\u6b32\\u7a7a\\u671f\\u4e0a\\u6797\\u7ffc\\u3002\", \"\\u4e0a\\u6797\\u4e09\\u6708\\u9d3b\\u6b32\\u7a00\\uff0c\\u83ef\\u8868\\u5343\\u5e74\\u9db4\\u672a\\u6b78\\u3002\", \"\\u4e0d\\u5206\\u6df9\\u7559\\u6851\\u8def\\u5f85\\uff0c\\u79ea\\u61c9\\u76f4\\u53d6\\u6842\\u8f2a\\u98db\\u3002\"]"', '"[\"\\u7384\\u90fd\\u4e94\\u5e9c\\u98ce\\u5c18\\u7edd\\uff0c\\u78a7\\u6d77\\u4e09\\u5c71\\u6ce2\\u6d6a\\u6df1\\u3002\", \"\\u6843\\u5b9e\\u5343\\u5e74\\u975e\\u6613\\u5f85\\uff0c\\u6851\\u7530\\u4e00\\u53d8\\u5df2\\u96be\\u5bfb\\u3002\", \"\\u522b\\u6709\\u4ed9\\u5c45\\u5bf9\\u4e09\\u5e02\\uff0c\\u91d1\\u9619\\u94f6\\u5bab\\u76f8\\u5411\\u8d77\\u3002\", \"\\u53f0\\u524d\\u955c\\u5f71\\u4f34\\u4ed9\\u5a25\\uff0c\\u697c\\u4e0a\\u7bab\\u58f0\\u968f\\u51e4\\u53f2\\u3002\", \"\\u51e4\\u697c\\u8fe2\\u9012\\u7edd\\u5c18\\u57c3\\uff0c\\u83ba\\u65f6\\u7269\\u8272\\u6b63\\u88f4\\u56de\\u3002\", \"\\u7075\\u829d\\u7d2b\\u68c0\\u53c2\\u5dee\\u957f\\uff0c\\u4ed9\\u6842\\u4e39\\u82b1\\u91cd\\u53e0\\u5f00\\u3002\", \"\\u53cc\\u7ae5\\u7ef0\\u7ea6\\u65f6\\u6e38\\u965f\\uff0c\\u4e09\\u9e1f\\u8054\\u7fe9\\u62a5\\u6d88\\u606f\\u3002\", \"\\u5c3d\\u8a00\\u771f\\u4fa3\\u51fa\\u9068\\u6e38\\uff0c\\u4f20\\u9053\\u98ce\\u5149\\u65e0\\u9650\\u6781\\u3002\", \"\\u8f7b\\u82b1\\u59d4\\u780c\\u60f9\\u88fe\\u9999\\uff0c\\u6b8b\\u6708\\u7aa5\\u7a97\\u89c7\\u5e4c\\u8272\\u3002\", \"\\u4e2a\\u65f6\\u65e0\\u6570\\u5002\\u5996\\u598d\\uff0c\\u4e2a\\u91cc\\u65e0\\u7a77\\u603b\\u53ef\\u601c\\u3002\", \"\\u522b\\u6709\\u4f17\\u4e2d\\u79f0\\u9edc\\u5e1d\\uff0c\\u5929\\u4e0a\\u4eba\\u95f4\\u5c11\\u6d41\\u4f8b\\u3002\", \"\\u6d1b\\u6ee8\\u4ed9\\u9a7e\\u542f\\u9065\\u6e90\\uff0c\\u6dee\\u6d66\\u7075\\u6d25\\u7b26\\u8fdc\\u7b6e\\u3002\", \"\\u81ea\\u8a00\\u5c11\\u5c0f\\u6155\\u5e7d\\u7384\\uff0c\\u53ea\\u8a00\\u5bb9\\u6613\\u5f97\\u795e\\u4ed9\\u3002\", \"\\u73ee\\u4e2d\\u9080\\u52d2\\u7ecf\\u65f6\\u5e8f\\uff0c\\u7bab\\u91cc\\u5bfb\\u601d\\u590d\\u51e0\\u5e74\\u3002\", \"\\u5bfb\\u601d\\u8bb8\\u4e8b\\u771f\\u60c5\\u53d8\\uff0c\\u4e8c\\u4eba\\u5bb9\\u534e\\u8bc6\\u5c11\\u9009\\u3002\", \"\\u6f2b\\u9053\\u70e7\\u4e39\\u6b62\\u4e03\\u98de\\uff0c\\u7a7a\\u4f20\\u5316\\u77f3\\u66fe\\u4e09\\u8f6c\\u3002\", \"\\u5bc4\\u8bed\\u5929\\u4e0a\\u5f04\\u673a\\u4eba\\uff0c\\u5bc4\\u8bed\\u6cb3\\u8fb9\\u503c\\u67e5\\u5ba2\\u3002\", \"\\u4e4d\\u53ef\\u60a4\\u60a4\\u5171\\u767e\\u5e74\\uff0c\\u8c01\\u4f7f\\u9065\\u9065\\u671f\\u4e03\\u5915\\u3002\", \"\\u60f3\\u77e5\\u4eba\\u610f\\u81ea\\u76f8\\u5bfb\\uff0c\\u679c\\u5f97\\u6df1\\u5fc3\\u5171\\u4e00\\u5fc3\\u3002\", \"\\u4e00\\u5fc3\\u4e00\\u610f\\u65e0\\u7a77\\u5df2\\uff0c\\u6295\\u6f06\\u6295\\u80f6\\u975e\\u8db3\\u62df\\u3002\", \"\\u53ea\\u5c06\\u7f9e\\u6da9\\u5f53\\u98ce\\u6d41\\uff0c\\u6301\\u6b64\\u76f8\\u601c\\u4fdd\\u7ec8\\u59cb\\u3002\", \"\\u76f8\\u601c\\u76f8\\u5ff5\\u500d\\u76f8\\u4eb2\\uff0c\\u4e00\\u751f\\u4e00\\u4ee3\\u4e00\\u53cc\\u4eba\\u3002\", \"\\u4e0d\\u628a\\u4e39\\u5fc3\\u6bd4\\u7384\\u77f3\\uff0c\\u60df\\u5c06\\u6d4a\\u6c34\\u51b5\\u6e05\\u5c18\\u3002\", \"\\u53ea\\u8a00\\u67f1\\u4e0b\\u7559\\u671f\\u4fe1\\uff0c\\u597d\\u6b32\\u5c06\\u5fc3\\u5b66\\u677e\\u8563\\u3002\", \"\\u4e0d\\u80fd\\u4eac\\u5146\\u753b\\u5ce8\\u7709\\uff0c\\u7ffb\\u5411\\u6210\\u90fd\\u9a8b\\u9a7a\\u5f15\\u3002\", \"\\u9752\\u725b\\u7d2b\\u6c14\\u5ea6\\u7075\\u5173\\uff0c\\u5c3a\\u7d20\\u8d69\\u9cde\\u53bb\\u4e0d\\u8fd8\\u3002\", \"\\u8fde\\u82d4\\u4e0a\\u780c\\u65e0\\u7a77\\u7eff\\uff0c\\u4fee\\u7af9\\u4e34\\u575b\\u51e0\\u5904\\u6591\\u3002\", \"\\u6b64\\u65f6\\u7a7a\\u5e8a\\u96be\\u72ec\\u5b88\\uff0c\\u6b64\\u65e5\\u522b\\u79bb\\u90a3\\u53ef\\u4e45\\u3002\", \"\\u6885\\u82b1\\u5982\\u96ea\\u67f3\\u5982\\u4e1d\\uff0c\\u5e74\\u53bb\\u5e74\\u6765\\u4e0d\\u81ea\\u6301\\u3002\", \"\\u521d\\u8a00\\u522b\\u5728\\u5bd2\\u504f\\u5728\\uff0c\\u4f55\\u609f\\u6625\\u6765\\u6625\\u66f4\\u601d\\u3002\", \"\\u6625\\u65f6\\u7269\\u8272\\u65e0\\u7aef\\u7eea\\uff0c\\u53cc\\u6795\\u5b64\\u7720\\u8c01\\u5206\\u8bb8\\u3002\", \"\\u5206\\u5ff5\\u5a07\\u83ba\\u4e00\\u79cd\\u557c\\uff0c\\u751f\\u618e\\u71d5\\u5b50\\u5343\\u822c\\u8bed\\u3002\", \"\\u671d\\u4e91\\u65ed\\u65e5\\u7167\\u9752\\u697c\\uff0c\\u8fdf\\u6656\\u4e3d\\u8272\\u6ee1\\u7687\\u5dde\\u3002\", \"\\u843d\\u82b1\\u6cdb\\u6cdb\\u6d6e\\u7075\\u6cbc\\uff0c\\u5782\\u67f3\\u957f\\u957f\\u62c2\\u5fa1\\u6c9f\\u3002\", \"\\u5fa1\\u6c9f\\u5927\\u9053\\u591a\\u5947\\u8d4f\\uff0c\\u4fa0\\u5ba2\\u5996\\u5bb9\\u9012\\u6765\\u5f80\\u3002\", \"\\u5b9d\\u9a91\\u8fde\\u82b1\\u94c1\\u4f5c\\u94b1\\uff0c\\u9999\\u8f6e\\u9a9b\\u6c34\\u73e0\\u4e3a\\u7f51\\u3002\", \"\\u9999\\u8f6e\\u5b9d\\u9a91\\u7ade\\u7e41\\u534e\\uff0c\\u53ef\\u601c\\u4eca\\u591c\\u5bbf\\u5021\\u5bb6\\u3002\", \"\\u9e66\\u9e49\\u676f\\u4e2d\\u6d6e\\u7af9\\u53f6\\uff0c\\u51e4\\u51f0\\u7434\\u91cc\\u843d\\u6885\\u82b1\\u3002\", \"\\u8bb8\\u8f88\\u591a\\u60c5\\u504f\\u9001\\u6b3e\\uff0c\\u4e3a\\u95ee\\u6625\\u82b1\\u51e0\\u65f6\\u6ee1\\u3002\", \"\\u5343\\u56de\\u9e1f\\u4fe1\\u8bf4\\u4f17\\u8bf8\\uff0c\\u767e\\u8fc7\\u83ba\\u557c\\u8bf4\\u957f\\u77ed\\u3002\", \"\\u957f\\u77ed\\u4f17\\u8bf8\\u5224\\u4e0d\\u5bfb\\uff0c\\u5343\\u56de\\u767e\\u8fc7\\u6d6a\\u5173\\u5fc3\\u3002\", \"\\u4f55\\u66fe\\u4e3e\\u610f\\u897f\\u90bb\\u7389\\uff0c\\u672a\\u80af\\u7559\\u60c5\\u5357\\u964c\\u91d1\\u3002\", \"\\u5357\\u964c\\u897f\\u90bb\\u54b8\\u81ea\\u4fdd\\uff0c\\u8fd8\\u8f94\\u5f52\\u671f\\u987b\\u53ca\\u65e9\\u3002\", \"\\u4e3a\\u60f3\\u4e09\\u6625\\u72ed\\u659c\\u8def\\uff0c\\u83ab\\u8f9e\\u4e5d\\u6298\\u909b\\u5173\\u9053\\u3002\", \"\\u5047\\u4ee4\\u767d\\u91cc\\u4f3c\\u957f\\u5b89\\uff0c\\u987b\\u4f7f\\u9752\\u725b\\u5b66\\u5251\\u7aef\\u3002\", \"\\u82f9\\u98ce\\u5165\\u9a6d\\u6765\\u5e94\\u6613\\uff0c\\u7af9\\u6756\\u6210\\u9f99\\u53bb\\u4e0d\\u96be\\u3002\", \"\\u9f99\\u98d9\\u53bb\\u53bb\\u65e0\\u6d88\\u606f\\uff0c\\u9e3e\\u955c\\u671d\\u671d\\u51cf\\u5bb9\\u8272\\u3002\", \"\\u541b\\u5fc3\\u4e0d\\u8bb0\\u4e0b\\u5c71\\u4eba\\uff0c\\u59be\\u6b32\\u7a7a\\u671f\\u4e0a\\u6797\\u7ffc\\u3002\", \"\\u4e0a\\u6797\\u4e09\\u6708\\u9e3f\\u6b32\\u7a00\\uff0c\\u534e\\u8868\\u5343\\u5e74\\u9e64\\u672a\\u5f52\\u3002\", \"\\u4e0d\\u5206\\u6df9\\u7559\\u6851\\u8def\\u5f85\\uff0c\\u79ea\\u5e94\\u76f4\\u53d6\\u6842\\u8f6e\\u98de\\u3002\"]"', '诗', 'shi', '', NULL, '代女道士王靈妃贈道士李榮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4ef7758-9966-4ae8-b560-6fcaf595f6b8', '從軍行', '从军行', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u5e73\\u751f\\u4e00\\u9867\\u91cd\\uff0c\\u610f\\u6c23\\u6ea2\\u4e09\\u8ecd\\u3002\", \"\\u57dc\\u65e5\\u5206\\u6208\\u5f71\\uff0c\\u5929\\u661f\\u5408\\u528d\\u6587\\u3002\", \"\\u5f13\\u5f26\\u62b1\\u6f22\\u6708\\uff0c\\u99ac\\u8db3\\u8e10\\u80e1\\u5875\\u3002\", \"\\u4e0d\\u6c42\\u751f\\u5165\\u585e\\uff0c\\u552f\\u7576\\u6b7b\\u5831\\u541b\\u3002\"]"', '"[\"\\u5e73\\u751f\\u4e00\\u987e\\u91cd\\uff0c\\u610f\\u6c14\\u6ea2\\u4e09\\u519b\\u3002\", \"\\u57dc\\u65e5\\u5206\\u6208\\u5f71\\uff0c\\u5929\\u661f\\u5408\\u5251\\u6587\\u3002\", \"\\u5f13\\u5f26\\u62b1\\u6c49\\u6708\\uff0c\\u9a6c\\u8db3\\u8df5\\u80e1\\u5c18\\u3002\", \"\\u4e0d\\u6c42\\u751f\\u5165\\u585e\\uff0c\\u552f\\u5f53\\u6b7b\\u62a5\\u541b\\u3002\"]"', '诗', 'shi', '', NULL, '從軍行 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92bb86c6-5106-458c-af9d-2fae96b9384e', '詠懷古意上裴侍郎', '咏怀古意上裴侍郎', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u4e09\\u5341\\u4e8c\\u9918\\u7f77\\uff0c\\u9b22\\u662f\\u6f58\\u5b89\\u4ec1\\u3002\", \"\\u56db\\u5341\\u4e5d\\u4ecd\\u5165\\uff0c\\u5e74\\u975e\\u6731\\u8cb7\\u81e3\\u3002\", \"\\u7e31\\u6a6b\\u6101\\u7e6b\\u8d8a\\uff0c\\u574e\\u58c8\\u5026\\u904a\\u79e6\\u3002\", \"\\u51fa\\u7c60\\u7aae\\u77ed\\u7fee\\uff0c\\u59d4\\u8f4d\\u6db8\\u67af\\u9c57\\u3002\", \"\\u7aae\\u7d93\\u4e0d\\u9711\\u7528\\uff0c\\u5f48\\u92cf\\u6b32\\u8ab0\\u7533\\u3002\", \"\\u5929\\u5b50\\u672a\\u9a45\\u7b56\\uff0c\\u6b72\\u6708\\u5e7e\\u6c88\\u6dea\\u3002\", \"\\u8f15\\u751f\\u9577\\u6177\\u6168\\uff0c\\u6548\\u6b7b\\u7368\\u6bb7\\u52e4\\u3002\", \"\\u5f92\\u6b4c\\u6613\\u6c34\\u5ba2\\uff0c\\u7a7a\\u8001\\u6e2d\\u5ddd\\u4eba\\u3002\", \"\\u4e00\\u5f97\\u8996\\u908a\\u585e\\uff0c\\u842c\\u91cc\\u4f55\\u82e6\\u8f9b\\u3002\", \"\\u528d\\u5323\\u80e1\\u971c\\u5f71\\uff0c\\u5f13\\u958b\\u6f22\\u6708\\u8f2a\\u3002\", \"\\u91d1\\u5200\\u52d5\\u79cb\\u8272\\uff0c\\u9435\\u9a0e\\u60f3\\u98a8\\u5875\\u3002\", \"\\u7232\\u570b\\u5805\\u8aa0\\u6b3e\\uff0c\\u6350\\u8ec0\\u5fd8\\u8ce4\\u8ca7\\u3002\", \"\\u52d2\\u529f\\u601d\\u6bd4\\u61b2\\uff0c\\u6c7a\\u7565\\u6697\\u6b3a\\u9673\\u3002\", \"\\u82e5\\u4e0d\\u72af\\u971c\\u96ea\\uff0c\\u865b\\u64f2\\u7389\\u4eac\\u6625\\u3002\"]"', '"[\"\\u4e09\\u5341\\u4e8c\\u4f59\\u7f62\\uff0c\\u9b13\\u662f\\u6f58\\u5b89\\u4ec1\\u3002\", \"\\u56db\\u5341\\u4e5d\\u4ecd\\u5165\\uff0c\\u5e74\\u975e\\u6731\\u4e70\\u81e3\\u3002\", \"\\u7eb5\\u6a2a\\u6101\\u7cfb\\u8d8a\\uff0c\\u574e\\ud845\\udc84\\u5026\\u6e38\\u79e6\\u3002\", \"\\u51fa\\u7b3c\\u7a77\\u77ed\\u7fee\\uff0c\\u59d4\\u8f99\\u6db8\\u67af\\u9cde\\u3002\", \"\\u7a77\\u7ecf\\u4e0d\\u6cbe\\u7528\\uff0c\\u5f39\\u94d7\\u6b32\\u8c01\\u7533\\u3002\", \"\\u5929\\u5b50\\u672a\\u9a71\\u7b56\\uff0c\\u5c81\\u6708\\u51e0\\u6c88\\u6ca6\\u3002\", \"\\u8f7b\\u751f\\u957f\\u6177\\u6168\\uff0c\\u6548\\u6b7b\\u72ec\\u6bb7\\u52e4\\u3002\", \"\\u5f92\\u6b4c\\u6613\\u6c34\\u5ba2\\uff0c\\u7a7a\\u8001\\u6e2d\\u5ddd\\u4eba\\u3002\", \"\\u4e00\\u5f97\\u89c6\\u8fb9\\u585e\\uff0c\\u4e07\\u91cc\\u4f55\\u82e6\\u8f9b\\u3002\", \"\\u5251\\u5323\\u80e1\\u971c\\u5f71\\uff0c\\u5f13\\u5f00\\u6c49\\u6708\\u8f6e\\u3002\", \"\\u91d1\\u5200\\u52a8\\u79cb\\u8272\\uff0c\\u94c1\\u9a91\\u60f3\\u98ce\\u5c18\\u3002\", \"\\u4e3a\\u56fd\\u575a\\u8bda\\u6b3e\\uff0c\\u6350\\u8eaf\\u5fd8\\u8d31\\u8d2b\\u3002\", \"\\u52d2\\u529f\\u601d\\u6bd4\\u5baa\\uff0c\\u51b3\\u7565\\u6697\\u6b3a\\u9648\\u3002\", \"\\u82e5\\u4e0d\\u72af\\u971c\\u96ea\\uff0c\\u865a\\u63b7\\u7389\\u4eac\\u6625\\u3002\"]"', '诗', 'shi', '', NULL, '詠懷古意上裴侍郎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d90d5ff0-e94a-4f79-9742-b616e9b4e68b', '春夜韋明府宅宴得春字', '春夜韦明府宅宴得春字', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u914c\\u6842\\u9676\\u82b3\\u591c\\uff0c\\u62ab\\u859c\\u562f\\u5e7d\\u4eba\\u3002\", \"\\u96c5\\u7434\\u99b4\\u9b6f\\u96c9\\uff0c\\u6e05\\u6b4c\\u843d\\u8303\\u5875\\u3002\", \"\\u5bbf\\u96f2\\u4f4e\\u8fe5\\u84cb\\uff0c\\u6b98\\u6708\\u4e0a\\u865b\\u8f2a\\u3002\", \"\\u5e78\\u6b64\\u627f\\u6069\\u6d3d\\uff0c\\u804a\\u7576\\u6545\\u9109\\u6625\\u3002\"]"', '"[\"\\u914c\\u6842\\u9676\\u82b3\\u591c\\uff0c\\u62ab\\u859c\\u5578\\u5e7d\\u4eba\\u3002\", \"\\u96c5\\u7434\\u9a6f\\u9c81\\u96c9\\uff0c\\u6e05\\u6b4c\\u843d\\u8303\\u5c18\\u3002\", \"\\u5bbf\\u4e91\\u4f4e\\u8fe5\\u76d6\\uff0c\\u6b8b\\u6708\\u4e0a\\u865a\\u8f6e\\u3002\", \"\\u5e78\\u6b64\\u627f\\u6069\\u6d3d\\uff0c\\u804a\\u5f53\\u6545\\u4e61\\u6625\\u3002\"]"', '诗', 'shi', '', NULL, '春夜韋明府宅宴得春字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99bd292d-15f6-41ee-a17c-42cca0a2ea5f', '過張平子墓', '过张平子墓', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u897f\\u9102\\u8a72\\u901a\\u7406\\uff0c\\u5357\\u967d\\u64c5\\u5fb7\\u97f3\\u3002\", \"\\u7389\\u5df5\\u6d6e\\u85fb\\u9e97\\uff0c\\u9285\\u6e3e\\u7a4d\\u601d\\u6df1\\u3002\", \"\\u5ffd\\u61f7\\u4eca\\u65e5\\u6614\\uff0c\\u975e\\u5fa9\\u6614\\u6642\\u4eca\\u3002\", \"\\u65e5\\u843d\\u8c50\\u7891\\u6697\\uff0c\\u98a8\\u4f86\\u53e4\\u6728\\u541f\\u3002\", \"\\u60df\\u6b4e\\u7aae\\u6cc9\\u4e0b\\uff0c\\u7d42\\u9b31\\u7fa8\\u9b5a\\u5fc3\\u3002\"]"', '"[\"\\u897f\\u9102\\u8be5\\u901a\\u7406\\uff0c\\u5357\\u9633\\u64c5\\u5fb7\\u97f3\\u3002\", \"\\u7389\\u5df5\\u6d6e\\u85fb\\u4e3d\\uff0c\\u94dc\\u6d51\\u79ef\\u601d\\u6df1\\u3002\", \"\\u5ffd\\u6000\\u4eca\\u65e5\\u6614\\uff0c\\u975e\\u590d\\u6614\\u65f6\\u4eca\\u3002\", \"\\u65e5\\u843d\\u4e30\\u7891\\u6697\\uff0c\\u98ce\\u6765\\u53e4\\u6728\\u541f\\u3002\", \"\\u60df\\u53f9\\u7a77\\u6cc9\\u4e0b\\uff0c\\u7ec8\\u90c1\\u7fa1\\u9c7c\\u5fc3\\u3002\"]"', '诗', 'shi', '', NULL, '過張平子墓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aacf7660-986a-4161-89f1-66809f7c1c0c', '從軍中行路難二首 一', '从军中行路难二首 一', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u541b\\u4e0d\\u898b\\u5c01\\u72d0\\u96c4\\u867a\\u81ea\\u6210\\u7fa3\\uff0c\\u99ae\\u6df1\\u8ca0\\u56fa\\u7d50\\u5996\\u6c1b\\u3002\", \"\\u7389\\u74bd\\u5206\\u5175\\u5fb5\\u60e1\\u5c11\\uff0c\\u91d1\\u58c7\\u53d7\\u5f8b\\u52d5\\u5c07\\u8ecd\\u3002\", \"\\u5c07\\u8ecd\\u64c1\\u65c4\\u5ba3\\u5edf\\u7565\\uff0c\\u6230\\u58eb\\u6a6b\\u884c\\u975c\\u5937\\u843d\\u3002\", \"\\u9577\\u9a45\\u4e00\\u606f\\u80cc\\u9285\\u6881\\uff0c\\u76f4\\u6307\\u4e09\\u5df4\\u767b\\u528d\\u95a3\\u3002\", \"\\u95a3\\u9053\\u5ca7\\u5da4\\u8d77\\u620d\\u6a13\\uff0c\\u528d\\u9580\\u9059\\u88d4\\u4fef\\u9748\\u4e18\\u3002\", \"\\u909b\\u95dc\\u4e5d\\u6298\\u7121\\u5e73\\u8def\\uff0c\\u6c5f\\u6c34\\u96d9\\u6e90\\u6709\\u6025\\u6d41\\u3002\", \"\\u5f81\\u5f79\\u7121\\u671f\\u8fd4\\uff0c\\u4ed6\\u9109\\u6b72\\u83ef\\u665a\\u3002\", \"\\u6773\\u6773\\u4e18\\u9675\\u51fa\\uff0c\\u84bc\\u84bc\\u6797\\u8584\\u9060\\u3002\", \"\\u9014\\u5371\\u7d2b\\u84cb\\u5cf0\\uff0c\\u8def\\u6f80\\u9752\\u6ce5\\u5742\\u3002\", \"\\u53bb\\u53bb\\u6307\\u54c0\\u7262\\uff0c\\u884c\\u884c\\u5165\\u4e0d\\u6bdb\\u3002\", \"\\u7d55\\u58c1\\u5343\\u91cc\\u96aa\\uff0c\\u9023\\u5c71\\u56db\\u671b\\u9ad8\\u3002\", \"\\u4e2d\\u5916\\u5206\\u5340\\u5b87\\uff0c\\u5937\\u590f\\u6b8a\\u98a8\\u571f\\u3002\", \"\\u4ea4\\u8dbe\\u6795\\u5357\\u8352\\uff0c\\u6606\\u5f4c\\u81e8\\u5317\\u6236\\u3002\", \"\\u5ddd\\u539f\\u7e5e\\u6bd2\\u9727\\uff0c\\u6eaa\\u8c37\\u591a\\u6deb\\u96e8\\u3002\", \"\\u884c\\u6f66\\u56db\\u6642\\u6d41\\uff0c\\u5d29\\u67e5\\u5343\\u6b72\\u53e4\\u3002\", \"\\u6f02\\u6897\\u98db\\u84ec\\u4e0d\\u81ea\\u5b89\\uff0c\\u636b\\u85e4\\u5f15\\u845b\\u5ea6\\u5371\\u5dd2\\u3002\", \"\\u6614\\u6642\\u805e\\u9053\\u5f9e\\u8ecd\\u6a02\\uff0c\\u4eca\\u65e5\\u65b9\\u77e5\\u884c\\u8def\\u96e3\\u3002\", \"\\u6ec4\\u6c5f\\u7da0\\u6c34\\u6771\\u6d41\\u99db\\uff0c\\u708e\\u6d32\\u4e39\\u5fbc\\u5357\\u4e2d\\u5730\\u3002\", \"\\u5357\\u4e2d\\u5357\\u6597\\u6620\\u661f\\u6cb3\\uff0c\\u79e6\\u5ddd\\u79e6\\u585e\\u963b\\u7159\\u6ce2\\u3002\", \"\\u4e09\\u6625\\u908a\\u5730\\u98a8\\u5149\\u5c11\\uff0c\\u4e94\\u6708\\u7018\\u4e2d\\u7634\\u7658\\u591a\\u3002\", \"\\u671d\\u9a45\\u75b2\\u65a5\\u5019\\uff0c\\u5915\\u606f\\u5026\\u6a35\\u6b4c\\u3002\", \"\\u5411\\u6708\\u5f4e\\u7e41\\u5f31\\uff0c\\u9023\\u661f\\u8f49\\u592a\\u963f\\u3002\", \"\\u91cd\\u7fa9\\u8f15\\u751f\\u61f7\\u4e00\\u9867\\uff0c\\u6771\\u4f10\\u897f\\u5f81\\u51e1\\u5e7e\\u5ea6\\u3002\", \"\\u591c\\u591c\\u671d\\u671d\\u6591\\u9b22\\u65b0\\uff0c\\u5e74\\u5e74\\u6b72\\u6b72\\u620e\\u8863\\u6545\\u3002\", \"\\u705e\\u57ce\\u9685\\uff0c\\u6ec7\\u6c60\\u6c34\\u3002\", \"\\u5929\\u96c5\\u671b\\u8f49\\u7a4d\\uff0c\\u5730\\u969b\\u884c\\u7121\\u5df2\\u3002\", \"\\u5f92\\u89ba\\u708e\\u6dbc\\u7bc0\\u7269\\u975e\\uff0c\\u4e0d\\u77e5\\u95dc\\u5c71\\u5343\\u842c\\u91cc\\u3002\", \"\\u68c4\\u7f6e\\u52ff\\u91cd\\u9673\\uff0c\\u5f81\\u884c\\u591a\\u82e6\\u8f9b\\u3002\", \"\\u4e14\\u6085\\u6e05\\u7b33\\u694a\\u67f3\\u66f2\\uff0c\\u8a4e\\u61b6\\u82b3\\u5712\\u6843\\u674e\\u4eba\\u3002\", \"\\u7d73\\u7bc0\\u6731\\u65d7\\u5206\\u767d\\u7fbd\\uff0c\\u4e39\\u5fc3\\u767d\\u5203\\u916c\\u660e\\u4e3b\\u3002\", \"\\u4f46\\u4ee4\\u4e00\\u88ab\\u541b\\u738b\\u77e5\\uff0c\\u8ab0\\u619a\\u4e09\\u908a\\u5f81\\u6230\\u82e6\\u3002\", \"\\u884c\\u8def\\u96e3\\uff0c\\u5e7e\\u5343\\u7aef\\u3002\", \"\\u7121\\u5fa9\\u6b78\\u96f2\\u6191\\u77ed\\u7ff0\\uff0c\\u7a7a\\u9918\\u671b\\u65e5\\u60f3\\u9577\\u5b89\\u3002\"]"', '"[\"\\u541b\\u4e0d\\u89c1\\u5c01\\u72d0\\u96c4\\u867a\\u81ea\\u6210\\u7fa4\\uff0c\\u51af\\u6df1\\u8d1f\\u56fa\\u7ed3\\u5996\\u6c1b\\u3002\", \"\\u7389\\u73ba\\u5206\\u5175\\u5f81\\u6076\\u5c11\\uff0c\\u91d1\\u575b\\u53d7\\u5f8b\\u52a8\\u5c06\\u519b\\u3002\", \"\\u5c06\\u519b\\u62e5\\u65c4\\u5ba3\\u5e99\\u7565\\uff0c\\u6218\\u58eb\\u6a2a\\u884c\\u9759\\u5937\\u843d\\u3002\", \"\\u957f\\u9a71\\u4e00\\u606f\\u80cc\\u94dc\\u6881\\uff0c\\u76f4\\u6307\\u4e09\\u5df4\\u767b\\u5251\\u9601\\u3002\", \"\\u9601\\u9053\\u5ca7\\u5da4\\u8d77\\u620d\\u697c\\uff0c\\u5251\\u95e8\\u9065\\u88d4\\u4fef\\u7075\\u4e18\\u3002\", \"\\u909b\\u5173\\u4e5d\\u6298\\u65e0\\u5e73\\u8def\\uff0c\\u6c5f\\u6c34\\u53cc\\u6e90\\u6709\\u6025\\u6d41\\u3002\", \"\\u5f81\\u5f79\\u65e0\\u671f\\u8fd4\\uff0c\\u4ed6\\u4e61\\u5c81\\u534e\\u665a\\u3002\", \"\\u6773\\u6773\\u4e18\\u9675\\u51fa\\uff0c\\u82cd\\u82cd\\u6797\\u8584\\u8fdc\\u3002\", \"\\u9014\\u5371\\u7d2b\\u76d6\\u5cf0\\uff0c\\u8def\\u6da9\\u9752\\u6ce5\\u5742\\u3002\", \"\\u53bb\\u53bb\\u6307\\u54c0\\u7262\\uff0c\\u884c\\u884c\\u5165\\u4e0d\\u6bdb\\u3002\", \"\\u7edd\\u58c1\\u5343\\u91cc\\u9669\\uff0c\\u8fde\\u5c71\\u56db\\u671b\\u9ad8\\u3002\", \"\\u4e2d\\u5916\\u5206\\u533a\\u5b87\\uff0c\\u5937\\u590f\\u6b8a\\u98ce\\u571f\\u3002\", \"\\u4ea4\\u8dbe\\u6795\\u5357\\u8352\\uff0c\\u6606\\u5f25\\u4e34\\u5317\\u6237\\u3002\", \"\\u5ddd\\u539f\\u7ed5\\u6bd2\\u96fe\\uff0c\\u6eaa\\u8c37\\u591a\\u6deb\\u96e8\\u3002\", \"\\u884c\\u6f66\\u56db\\u65f6\\u6d41\\uff0c\\u5d29\\u67e5\\u5343\\u5c81\\u53e4\\u3002\", \"\\u6f02\\u6897\\u98de\\u84ec\\u4e0d\\u81ea\\u5b89\\uff0c\\u626a\\u85e4\\u5f15\\u845b\\u5ea6\\u5371\\u5ce6\\u3002\", \"\\u6614\\u65f6\\u95fb\\u9053\\u4ece\\u519b\\u4e50\\uff0c\\u4eca\\u65e5\\u65b9\\u77e5\\u884c\\u8def\\u96be\\u3002\", \"\\u6ca7\\u6c5f\\u7eff\\u6c34\\u4e1c\\u6d41\\u9a76\\uff0c\\u708e\\u6d32\\u4e39\\u5fbc\\u5357\\u4e2d\\u5730\\u3002\", \"\\u5357\\u4e2d\\u5357\\u6597\\u6620\\u661f\\u6cb3\\uff0c\\u79e6\\u5ddd\\u79e6\\u585e\\u963b\\u70df\\u6ce2\\u3002\", \"\\u4e09\\u6625\\u8fb9\\u5730\\u98ce\\u5149\\u5c11\\uff0c\\u4e94\\u6708\\u6cf8\\u4e2d\\u7634\\u75a0\\u591a\\u3002\", \"\\u671d\\u9a71\\u75b2\\u65a5\\u5019\\uff0c\\u5915\\u606f\\u5026\\u6a35\\u6b4c\\u3002\", \"\\u5411\\u6708\\u5f2f\\u7e41\\u5f31\\uff0c\\u8fde\\u661f\\u8f6c\\u592a\\u963f\\u3002\", \"\\u91cd\\u4e49\\u8f7b\\u751f\\u6000\\u4e00\\u987e\\uff0c\\u4e1c\\u4f10\\u897f\\u5f81\\u51e1\\u51e0\\u5ea6\\u3002\", \"\\u591c\\u591c\\u671d\\u671d\\u6591\\u9b13\\u65b0\\uff0c\\u5e74\\u5e74\\u5c81\\u5c81\\u620e\\u8863\\u6545\\u3002\", \"\\u705e\\u57ce\\u9685\\uff0c\\u6ec7\\u6c60\\u6c34\\u3002\", \"\\u5929\\u96c5\\u671b\\u8f6c\\u79ef\\uff0c\\u5730\\u9645\\u884c\\u65e0\\u5df2\\u3002\", \"\\u5f92\\u89c9\\u708e\\u51c9\\u8282\\u7269\\u975e\\uff0c\\u4e0d\\u77e5\\u5173\\u5c71\\u5343\\u4e07\\u91cc\\u3002\", \"\\u5f03\\u7f6e\\u52ff\\u91cd\\u9648\\uff0c\\u5f81\\u884c\\u591a\\u82e6\\u8f9b\\u3002\", \"\\u4e14\\u60a6\\u6e05\\u7b33\\u6768\\u67f3\\u66f2\\uff0c\\u8bb5\\u5fc6\\u82b3\\u56ed\\u6843\\u674e\\u4eba\\u3002\", \"\\u7edb\\u8282\\u6731\\u65d7\\u5206\\u767d\\u7fbd\\uff0c\\u4e39\\u5fc3\\u767d\\u5203\\u916c\\u660e\\u4e3b\\u3002\", \"\\u4f46\\u4ee4\\u4e00\\u88ab\\u541b\\u738b\\u77e5\\uff0c\\u8c01\\u60ee\\u4e09\\u8fb9\\u5f81\\u6218\\u82e6\\u3002\", \"\\u884c\\u8def\\u96be\\uff0c\\u51e0\\u5343\\u7aef\\u3002\", \"\\u65e0\\u590d\\u5f52\\u4e91\\u51ed\\u77ed\\u7ff0\\uff0c\\u7a7a\\u4f59\\u671b\\u65e5\\u60f3\\u957f\\u5b89\\u3002\"]"', '诗', 'shi', '', NULL, '從軍中行路難二首 一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68aa731f-b05b-40a4-ba99-81fa61551e0d', '從軍中行路難二首 二', '从军中行路难二首 二', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u541b\\u4e0d\\u898b\\u7389\\u95dc\\u5875\\u8272\\u6697\\u908a\\u5ead\\uff0c\\u9285\\u97ae\\u96dc\\u865c\\u5bc7\\u9577\\u57ce\\u3002\", \"\\u5929\\u5b50\\u6309\\u528d\\u5fb5\\u9918\\u52c7\\uff0c\\u5c07\\u8ecd\\u53d7\\u8124\\u4e8b\\u6a6b\\u884c\\u3002\", \"\\u4e03\\u5fb7\\u9f8d\\u97dc\\u958b\\u7389\\u5e33\\uff0c\\u5343\\u91cc\\u9f09\\u9f13\\u58d8\\u91d1\\u9266\\u3002\", \"\\u9670\\u5c71\\u82e6\\u9727\\u57cb\\u9ad8\\u58d8\\uff0c\\u4ea4\\u6cb3\\u5b64\\u6708\\u7167\\u9023\\u71df\\u3002\", \"\\u9023\\u71df\\u53bb\\u53bb\\u7121\\u7aae\\u6975\\uff0c\\u64c1\\u65be\\u9059\\u9059\\u904e\\u7d55\\u570b\\u3002\", \"\\u9663\\u96f2\\u671d\\u7d50\\u6666\\u5929\\u5c71\\uff0c\\u5bd2\\u6c99\\u5915\\u6f32\\u8ff7\\u758e\\u52d2\\u3002\", \"\\u9f8d\\u9c57\\u6c34\\u4e0a\\u958b\\u9b5a\\u8cab\\uff0c\\u99ac\\u9996\\u5c71\\u524d\\u632f\\u96d5\\u7ffc\\u3002\", \"\\u9577\\u9a45\\u842c\\u91cc\\u8b8b\\u7948\\u9023\\uff0c\\u5206\\u9ebe\\u4e09\\u547d\\u6b66\\u529f\\u5ba3\\u3002\", \"\\u767e\\u767c\\u70cf\\u865f\\u9059\\u788e\\u67f3\\uff0c\\u4e03\\u5c3a\\u9f8d\\u6587\\u8fe5\\u7167\\u84ee\\u3002\", \"\\u6625\\u4f86\\u79cb\\u53bb\\u79fb\\u7070\\u742f\\uff0c\\u862d\\u95a8\\u67f3\\u5e02\\u82b3\\u5875\\u65b7\\u3002\", \"\\u96c1\\u9580\\u8fe2\\u905e\\u5c3a\\u66f8\\u7a00\\uff0c\\u9d1b\\u88ab\\u76f8\\u601d\\u96d9\\u5e36\\u7de9\\u3002\", \"\\u884c\\u8def\\u96e3\\uff0c\\u884c\\u8def\\u96e3\\uff0c\\u8a93\\u4ee4\\u6c1b\\u7972\\u975c\\u81ef\\u862d\\u3002\", \"\\u4f46\\u4f7f\\u5c01\\u4faf\\u9f8d\\u981f\\u8cb4\\uff0c\\u8a4e\\u96a8\\u4e2d\\u5a66\\u9cf3\\u6a13\\u5bd2\\u3002\"]"', '"[\"\\u541b\\u4e0d\\u89c1\\u7389\\u5173\\u5c18\\u8272\\u6697\\u8fb9\\u5ead\\uff0c\\u94dc\\u97ae\\u6742\\u864f\\u5bc7\\u957f\\u57ce\\u3002\", \"\\u5929\\u5b50\\u6309\\u5251\\u5f81\\u4f59\\u52c7\\uff0c\\u5c06\\u519b\\u53d7\\u8124\\u4e8b\\u6a2a\\u884c\\u3002\", \"\\u4e03\\u5fb7\\u9f99\\u97ec\\u5f00\\u7389\\u5e10\\uff0c\\u5343\\u91cc\\u9f0d\\u9f13\\u5792\\u91d1\\u94b2\\u3002\", \"\\u9634\\u5c71\\u82e6\\u96fe\\u57cb\\u9ad8\\u5792\\uff0c\\u4ea4\\u6cb3\\u5b64\\u6708\\u7167\\u8fde\\u8425\\u3002\", \"\\u8fde\\u8425\\u53bb\\u53bb\\u65e0\\u7a77\\u6781\\uff0c\\u62e5\\u65be\\u9065\\u9065\\u8fc7\\u7edd\\u56fd\\u3002\", \"\\u9635\\u4e91\\u671d\\u7ed3\\u6666\\u5929\\u5c71\\uff0c\\u5bd2\\u6c99\\u5915\\u6da8\\u8ff7\\u758e\\u52d2\\u3002\", \"\\u9f99\\u9cde\\u6c34\\u4e0a\\u5f00\\u9c7c\\u8d2f\\uff0c\\u9a6c\\u9996\\u5c71\\u524d\\u632f\\u96d5\\u7ffc\\u3002\", \"\\u957f\\u9a71\\u4e07\\u91cc\\u8a5f\\u7948\\u8fde\\uff0c\\u5206\\u9ebe\\u4e09\\u547d\\u6b66\\u529f\\u5ba3\\u3002\", \"\\u767e\\u53d1\\u4e4c\\u53f7\\u9065\\u788e\\u67f3\\uff0c\\u4e03\\u5c3a\\u9f99\\u6587\\u8fe5\\u7167\\u83b2\\u3002\", \"\\u6625\\u6765\\u79cb\\u53bb\\u79fb\\u7070\\u742f\\uff0c\\u5170\\u95fa\\u67f3\\u5e02\\u82b3\\u5c18\\u65ad\\u3002\", \"\\u96c1\\u95e8\\u8fe2\\u9012\\u5c3a\\u4e66\\u7a00\\uff0c\\u9e33\\u88ab\\u76f8\\u601d\\u53cc\\u5e26\\u7f13\\u3002\", \"\\u884c\\u8def\\u96be\\uff0c\\u884c\\u8def\\u96be\\uff0c\\u8a93\\u4ee4\\u6c1b\\u7972\\u9759\\u81ef\\u5170\\u3002\", \"\\u4f46\\u4f7f\\u5c01\\u4faf\\u9f99\\u981f\\u8d35\\uff0c\\u8bb5\\u968f\\u4e2d\\u5987\\u51e4\\u697c\\u5bd2\\u3002\"]"', '诗', 'shi', '', NULL, '從軍中行路難二首 二 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17da968a-a783-4f6c-9e15-d26b50b583ee', '帝京篇', '帝京篇', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u5c71\\u6cb3\\u5343\\u91cc\\u570b\\uff0c\\u57ce\\u95d5\\u4e5d\\u91cd\\u9580\\u3002\", \"\\u4e0d\\u89a9\\u7687\\u5c45\\u58ef\\uff0c\\u5b89\\u77e5\\u5929\\u5b50\\u5c0a\\u3002\", \"\\u7687\\u5c45\\u5e1d\\u91cc\\u5d24\\u51fd\\u8c37\\uff0c\\u9d89\\u91ce\\u9f8d\\u5c71\\u4faf\\u7538\\u670d\\u3002\", \"\\u4e94\\u7def\\u9023\\u5f71\\u96c6\\u661f\\u8e94\\uff0c\\u516b\\u6c34\\u5206\\u6d41\\u6a6b\\u5730\\u8ef8\\u3002\", \"\\u79e6\\u585e\\u91cd\\u95dc\\u4e00\\u767e\\u4e8c\\uff0c\\u6f22\\u5bb6\\u96e2\\u5bae\\u4e09\\u5341\\u516d\\u3002\", \"\\u6842\\u6bbf\\u5d94\\u5c91\\u5c0d\\u7389\\u6a13\\uff0c\\u6912\\u623f\\u7a88\\u7a95\\u9023\\u91d1\\u5c4b\\u3002\", \"\\u4e09\\u689d\\u4e5d\\u964c\\u9e97\\u57ce\\u9688\\uff0c\\u842c\\u6236\\u5343\\u9580\\u5e73\\u65e6\\u958b\\u3002\", \"\\u8907\\u9053\\u659c\\u901a\\u9cf7\\u9d72\\u89c0\\uff0c\\u4ea4\\u8862\\u76f4\\u6307\\u9cf3\\u7687\\u81fa\\u3002\", \"\\u528d\\u5c65\\u5357\\u5bae\\u5165\\uff0c\\u7c2a\\u7e93\\u5317\\u95d5\\u4f86\\u3002\", \"\\u8072\\u540d\\u51a0\\u5bf0\\u5b87\\uff0c\\u6587\\u7269\\u8c61\\u662d\\u56de\\u3002\", \"\\u9264\\u9673\\u8085\\u862d\\u623a\\uff0c\\u74a7\\u6cbc\\u6d6e\\u69d0\\u5e02\\u3002\", \"\\u9285\\u7fbd\\u61c9\\u98a8\\u56de\\uff0c\\u91d1\\u8396\\u627f\\u9732\\u8d77\\u3002\", \"\\u6821\\u6587\\u5929\\u797f\\u95a3\\uff0c\\u7fd2\\u6230\\u6606\\u660e\\u6c34\\u3002\", \"\\u6731\\u90b8\\u6297\\u5e73\\u81fa\\uff0c\\u9ec3\\u6249\\u901a\\u621a\\u91cc\\u3002\", \"\\u5e73\\u81fa\\u621a\\u91cc\\u5e36\\u5d07\\u5889\\uff0c\\u708a\\u91d1\\u994c\\u7389\\u5f85\\u9cf4\\u9418\\u3002\", \"\\u5c0f\\u5802\\u7dba\\u5e33\\u4e09\\u5343\\u6236\\uff0c\\u5927\\u9053\\u9752\\u6a13\\u5341\\u4e8c\\u91cd\\u3002\", \"\\u5bf6\\u84cb\\u96d5\\u978d\\u91d1\\u7d61\\u99ac\\uff0c\\u862d\\u7a97\\u7e61\\u67f1\\u7389\\u76e4\\u9f8d\\u3002\", \"\\u7e61\\u67f1\\u7487\\u984c\\u7c89\\u58c1\\u6620\\uff0c\\u93d8\\u91d1\\u9cf4\\u7389\\u738b\\u4faf\\u76db\\u3002\", \"\\u738b\\u4faf\\u8cb4\\u4eba\\u591a\\u8fd1\\u81e3\\uff0c\\u671d\\u904a\\u5317\\u91cc\\u66ae\\u5357\\u9130\\u3002\", \"\\u9678\\u8cc8\\u5206\\u91d1\\u5c07\\u8b8c\\u559c\\uff0c\\u9673\\u9075\\u6295\\u8f44\\u6b63\\u7559\\u8cd3\\u3002\", \"\\u8d99\\u674e\\u7d93\\u904e\\u5bc6\\uff0c\\u856d\\u6731\\u4ea4\\u7d50\\u89aa\\u3002\", \"\\u4e39\\u9cf3\\u6731\\u57ce\\u767d\\u65e5\\u66ae\\uff0c\\u9752\\u725b\\u7d3a\\u5e70\\u7d05\\u5875\\u5ea6\\u3002\", \"\\u4fe0\\u5ba2\\u73e0\\u5f48\\u5782\\u694a\\u9053\\uff0c\\u5021\\u5a66\\u9280\\u9264\\u91c7\\u6851\\u8def\\u3002\", \"\\u5021\\u5bb6\\u6843\\u674e\\u81ea\\u82b3\\u83f2\\uff0c\\u4eac\\u83ef\\u904a\\u4fe0\\u76db\\u8f15\\u80a5\\u3002\", \"\\u5ef6\\u5e74\\u5973\\u5f1f\\u96d9\\u9cf3\\u5165\\uff0c\\u7f85\\u6577\\u4f7f\\u541b\\u5343\\u9a0e\\u6b78\\u3002\", \"\\u540c\\u5fc3\\u7d50\\u7e37\\u5e36\\uff0c\\u9023\\u7406\\u7e54\\u6210\\u8863\\u3002\", \"\\u6625\\u671d\\u6842\\u5c0a\\u5c0a\\u767e\\u5473\\uff0c\\u79cb\\u591c\\u862d\\u71c8\\u71c8\\u4e5d\\u5fae\\u3002\", \"\\u7fe0\\u5e4c\\u73e0\\u7c3e\\u4e0d\\u7368\\u6620\\uff0c\\u6e05\\u6b4c\\u5bf6\\u745f\\u81ea\\u76f8\\u4f9d\\u3002\", \"\\u4e14\\u8ad6\\u4e09\\u842c\\u516d\\u5343\\u662f\\uff0c\\u5be7\\u77e5\\u56db\\u5341\\u4e5d\\u5e74\\u975e\\u3002\", \"\\u53e4\\u4f86\\u69ae\\u5229\\u82e5\\u6d6e\\u96f2\\uff0c\\u4eba\\u751f\\u501a\\u4f0f\\u4fe1\\u96e3\\u5206\\u3002\", \"\\u59cb\\u898b\\u7530\\u7ac7\\u76f8\\u79fb\\u596a\\uff0c\\u4fc4\\u805e\\u885e\\u970d\\u6709\\u529f\\u52f3\\u3002\", \"\\u672a\\u53ad\\u91d1\\u9675\\u6c23\\uff0c\\u5148\\u958b\\u77f3\\u69e8\\u6587\\u3002\", \"\\u6731\\u9580\\u7121\\u5fa9\\u5f35\\u516c\\u5b50\\uff0c\\u705e\\u4ead\\u8ab0\\u754f\\u674e\\u5c07\\u8ecd\\u3002\", \"\\u76f8\\u9867\\u767e\\u9f61\\u7686\\u6709\\u5f85\\uff0c\\u5c45\\u7136\\u842c\\u5316\\u54b8\\u61c9\\u6539\\u3002\", \"\\u6842\\u679d\\u82b3\\u6c23\\u5df2