f\\u3002\", \"\\u5021\\u5bb6\\u6843\\u674e\\u81ea\\u82b3\\u83f2\\uff0c\\u4eac\\u534e\\u6e38\\u4fa0\\u76db\\u8f7b\\u80a5\\u3002\", \"\\u5ef6\\u5e74\\u5973\\u5f1f\\u53cc\\u51e4\\u5165\\uff0c\\u7f57\\u6577\\u4f7f\\u541b\\u5343\\u9a91\\u5f52\\u3002\", \"\\u540c\\u5fc3\\u7ed3\\u7f15\\u5e26\\uff0c\\u8fde\\u7406\\u7ec7\\u6210\\u8863\\u3002\", \"\\u6625\\u671d\\u6842\\u5c0a\\u5c0a\\u767e\\u5473\\uff0c\\u79cb\\u591c\\u5170\\u706f\\u706f\\u4e5d\\u5fae\\u3002\", \"\\u7fe0\\u5e4c\\u73e0\\u5e18\\u4e0d\\u72ec\\u6620\\uff0c\\u6e05\\u6b4c\\u5b9d\\u745f\\u81ea\\u76f8\\u4f9d\\u3002\", \"\\u4e14\\u8bba\\u4e09\\u4e07\\u516d\\u5343\\u662f\\uff0c\\u5b81\\u77e5\\u56db\\u5341\\u4e5d\\u5e74\\u975e\\u3002\", \"\\u53e4\\u6765\\u8363\\u5229\\u82e5\\u6d6e\\u4e91\\uff0c\\u4eba\\u751f\\u501a\\u4f0f\\u4fe1\\u96be\\u5206\\u3002\", \"\\u59cb\\u89c1\\u7530\\u7aa6\\u76f8\\u79fb\\u593a\\uff0c\\u4fc4\\u95fb\\u885e\\u970d\\u6709\\u529f\\u52cb\\u3002\", \"\\u672a\\u538c\\u91d1\\u9675\\u6c14\\uff0c\\u5148\\u5f00\\u77f3\\u6901\\u6587\\u3002\", \"\\u6731\\u95e8\\u65e0\\u590d\\u5f20\\u516c\\u5b50\\uff0c\\u705e\\u4ead\\u8c01\\u754f\\u674e\\u5c06\\u519b\\u3002\", \"\\u76f8\\u987e\\u767e\\u9f84\\u7686\\u6709\\u5f85\\uff0c\\u5c45\\u7136\\u4e07\\u5316\\u54b8\\u5e94\\u6539\\u3002\", \"\\u6842\\u679d\\u82b3\\u6c14\\u5df2\\u9500\\u4ea1\\uff0c\\u67cf\\u6881\\u9ad8\\u5bb4\\u4eca\\u4f55\\u5728\\uff1f\", \"\\u6625\\u53bb\\u6625\\u6765\\u82e6\\u81ea\\u9a70\\uff0c\\u4e89\\u540d\\u4e89\\u5229\\u5f92\\u5c14\\u4e3a\\u3002\", \"\\u4e45\\u7559\\u90ce\\u7f72\\u7ec8\\u96be\\u9047\\uff0c\\u7a7a\\u626b\\u76f8\\u95e8\\u8c01\\u89c1\\u77e5\\u3002\", \"\\u5f53\\u65f6\\u4e00\\u65e6\\u64c5\\u8c6a\\u534e\\uff0c\\u81ea\\u8a00\\u5343\\u8f7d\\u957f\\u9a84\\u5962\\u3002\", \"\\u500f\\u5ffd\\u629f\\u98ce\\u751f\\u7fbd\\u7ffc\\uff0c\\u987b\\u81fe\\u5931\\u6d6a\\u59d4\\u6ce5\\u6c99\\u3002\", \"\\u9ec4\\u96c0\\u5f92\\u5de2\\u6842\\uff0c\\u9752\\u95e8\\u9042\\u79cd\\u74dc\\u3002\", \"\\u9ec4\\u91d1\\u9500\\u94c4\\u7d20\\u4e1d\\u53d8\\uff0c\\u4e00\\u8d35\\u4e00\\u8d31\\u4ea4\\u60c5\\u89c1\\u3002\", \"\\u7ea2\\u989c\\u5bbf\\u6614\\u767d\\u5934\\u65b0\\uff0c\\u8131\\u7c9f\\u5e03\\u8863\\u8f7b\\u6545\\u4eba\\u3002\", \"\\u6545\\u4eba\\u6709\\u6e6e\\u6ca6\\uff0c\\u65b0\\u77e5\\u65e0\\u610f\\u6c14\\u3002\", \"\\u7070\\u6b7b\\u97e9\\u5b89\\u56fd\\uff0c\\u7f57\\u4f24\\u7fdf\\u5ef7\\u5c09\\u3002\", \"\\u5df2\\u77e3\\u54c9\\uff0c\\u5f52\\u53bb\\u6765\\u3002\", \"\\u9a6c\\u537f\\u8f9e\\u8700\\u591a\\u6587\\u85fb\\uff0c\\u626c\\u96c4\\u4ed5\\u6c49\\u4e4f\\u826f\\u5a92\\u3002\", \"\\u4e09\\u51ac\\u81ea\\u77dc\\u8bda\\u8db3\\u7528\\uff0c\\u5341\\u5e74\\u4e0d\\u8c03\\u51e0\\u9085\\u56de\\u3002\", \"\\u6c72\\u9eef\\u85aa\\u903e\\u79ef\\uff0c\\u5b59\\u5f18\\u9601\\u672a\\u5f00\\u3002\", \"\\u8c01\\u60dc\\u957f\\u6c99\\u5085\\uff0c\\u72ec\\u8d1f\\u6d1b\\u9633\\u624d\\u3002\"]"', '诗', 'shi', '', NULL, '帝京篇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7422cc6-565f-4952-b27d-829c27408a58', '疇昔篇', '畴昔篇', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u5c11\\u5e74\\u91cd\\u82f1\\u4fe0\\uff0c\\u5f31\\u6b72\\u8ce4\\u8863\\u51a0\\u3002\", \"\\u65e2\\u8a17\\u5bf0\\u4e2d\\u8cde\\uff0c\\u65b9\\u627f\\u819d\\u4e0b\\u6b61\\u3002\", \"\\u9068\\u904a\\u705e\\u6c34\\u66f2\\uff0c\\u98a8\\u6708\\u6d1b\\u57ce\\u7aef\\u3002\", \"\\u4e14\\u77e5\\u7121\\u7389\\u994c\\uff0c\\u8ab0\\u80af\\u9010\\u91d1\\u4e38\\u3002\", \"\\u91d1\\u4e38\\u7389\\u994c\\u76db\\u7e41\\u83ef\\uff0c\\u81ea\\u8a00\\u8f15\\u4fae\\u5b63\\u502b\\u5bb6\\u3002\", \"\\u4e94\\u9738\\u722d\\u99b3\\u5343\\u91cc\\u99ac\\uff0c\\u4e09\\u689d\\u7af6\\u9a16\\u4e03\\u9999\\u8eca\\u3002\", \"\\u63a9\\u6620\\u98db\\u8ed2\\u4e58\\u843d\\u7167\\uff0c\\u53c3\\u5dee\\u6b65\\u969c\\u5f15\\u671d\\u971e\\u3002\", \"\\u6c60\\u4e2d\\u820a\\u6c34\\u5982\\u61f8\\u93e1\\uff0c\\u5c4b\\u88cf\\u65b0\\u599d\\u4e0d\\u8b93\\u82b1\\u3002\", \"\\u610f\\u6c23\\u98a8\\u96f2\\u500f\\u5982\\u6628\\uff0c\\u6b72\\u6708\\u6625\\u79cb\\u5c62\\u56de\\u8584\\u3002\", \"\\u4e0a\\u82d1\\u983b\\u7d93\\u67f3\\u7d6e\\u98db\\uff0c\\u4e2d\\u5712\\u5e7e\\u898b\\u6885\\u82b1\\u843d\\u3002\", \"\\u7576\\u6642\\u9580\\u5ba2\\u4eca\\u4f55\\u5728\\uff1f\\u7587\\u6614\\u4ea4\\u670b\\u5df2\\u758e\\u7d22\\u3002\", \"\\u83ab\\u6559\\u6194\\u60b4\\u640d\\u5bb9\\u5100\\uff0c\\u6703\\u5f97\\u9ad8\\u79cb\\u96f2\\u9727\\u5ed3\\u3002\", \"\\u6df9\\u7559\\u5750\\u5e1d\\u9109\\uff0c\\u7121\\u4e8b\\u7a4d\\u708e\\u6dbc\\u3002\", \"\\u4e00\\u671d\\u62ab\\u77ed\\u8910\\uff0c\\u516d\\u8f09\\u5949\\u9577\\u5eca\\u3002\", \"\\u8ce6\\u6587\\u6159\\u6614\\u99ac\\uff0c\\u57f7\\u621f\\u6b4e\\u524d\\u63da\\u3002\", \"\\u63ee\\u6208\\u51fa\\u6b66\\u5e33\\uff0c\\u8377\\u7b46\\u5165\\u6587\\u660c\\u3002\", \"\\u6587\\u660c\\u96b1\\u96b1\\u7687\\u57ce\\u88cf\\uff0c\\u7531\\u4f86\\u5955\\u5955\\u591a\\u624d\\u5b50\\u3002\", \"\\u6f58\\u9678\\u8a5e\\u92d2\\u99f1\\u9a5b\\u98db\\uff0c\\u5f35\\u66f9\\u7ff0\\u82d1\\u7e31\\u6a6b\\u8d77\\u3002\", \"\\u537f\\u76f8\\u672a\\u66fe\\u8b58\\uff0c\\u738b\\u4faf\\u5be7\\u898b\\u64ec\\u3002\", \"\\u5782\\u91e3\\u7518\\u6210\\u767d\\u9996\\u7fc1\\uff0c\\u8ca0\\u85aa\\u4f55\\u8655\\u9022\\u77e5\\u5df1\\uff1f\", \"\\u5224\\u5c07\\u904b\\u547d\\u8ce6\\u7aae\\u901a\\uff0c\\u5f9e\\u4f86\\u5947\\u821b\\u4efb\\u897f\\u6771\\u3002\", \"\\u4e0d\\u61c9\\u6c38\\u68c4\\u540c\\u82bb\\u72d7\\uff0c\\u4e14\\u5fa9\\u98c4\\u98bb\\u985e\\u8f49\\u84ec\\u3002\", \"\\u5bb9\\u9b22\\u5e74\\u5e74\\u7570\\uff0c\\u6625\\u83ef\\u6b72\\u6b72\\u540c\\u3002\", \"\\u69ae\\u89c0\\u672a\\u76e1\\u79ae\\uff0c\\u5f87\\u4e3b\\u6b32\\u7533\\u529f\\u3002\", \"\\u8102\\u8eca\\u79e3\\u99ac\\u8fad\\u9109\\u570b\\uff0c\\u7e08\\u8f61\\u897f\\u5357\\u4f7f\\u909b\\u50f0\\u3002\", \"\\u7389\\u58d8\\u9285\\u6881\\u4e0d\\u6613\\u6500\\uff0c\\u5730\\u89d2\\u5929\\u6daf\\u7707\\u96e3\\u6e2c\\u3002\", \"\\u9daf\\u56c0\\u87ec\\u541f\\u6709\\u60b2\\u671b\\uff0c\\u9d3b\\u4f86\\u96c1\\u5ea6\\u7121\\u97f3\\u606f\\u3002\", \"\\u967d\\u95dc\\u7a4d\\u9727\\u842c\\u91cc\\u660f\\uff0c\\u528d\\u95a3\\u9023\\u5c71\\u5343\\u7a2e\\u8272\\u3002\", \"\\u8700\\u8def\\u4f55\\u60a0\\u60a0\\uff0c\\u5cb7\\u5cef\\u963b\\u4e14\\u4fee\\u3002\", \"\\u56de\\u8178\\u96a8\\u4e5d\\u6298\\uff0c\\u8ff8\\u6dda\\u9023\\u96d9\\u6d41\\u3002\", \"\\u5bd2\\u5149\\u5343\\u91cc\\u66ae\\uff0c\\u9732\\u6c23\\u4e8c\\u6c5f\\u79cb\\u3002\", \"\\u9577\\u9014\\u770b\\u675f\\u99ac\\uff0c\\u5e73\\u6c34\\u4e14\\u6c88\\u725b\\u3002\", \"\\u83ef\\u967d\\u820a\\u5730\\u6a19\\u795e\\u5236\\uff0c\\u77f3\\u93e1\\u86fe\\u7709\\u771f\\u79c0\\u9e97\\u3002\", \"\\u8af8\\u845b\\u624d\\u96c4\\u5df2\\u865f\\u9f8d\\uff0c\\u516c\\u5b6b\\u8e8d\\u99ac\\u8f15\\u7a31\\u5e1d\\u3002\", \"\\u4e94\\u4e01\\u5353\\u7296\\u591a\\u5947\\u529b\\uff0c\\u56db\\u58eb\\u82f1\\u9748\\u5bcc\\u6587\\u85dd\\u3002\", \"\\u96f2\\u6c23\\u6a6b\\u958b\\u516b\\u9663\\u5f62\\uff0c\\u6a4b\\u5f62\\u9059\\u5206\\u4e03\\u661f\\u52e2\\u3002\", \"\\u5ddd\\u5e73\\u7159\\u9727\\u958b\\uff0c\\u904a\\u6232\\u9326\\u57ce\\u9688\\u3002\", \"\\u5889\\u9ad8\\u9f9c\\u671b\\u51fa\\uff0c\\u6c34\\u6de8\\u96c1\\u6587\\u56de\\u3002\", \"\\u5c0b\\u59dd\\u5165\\u9152\\u8086\\uff0c\\u8a2a\\u5ba2\\u4e0a\\u7434\\u81fa\\u3002\", \"\\u4e0d\\u8b58\\u91d1\\u8c82\\u91cd\\uff0c\\u504f\\u60dc\\u7389\\u5c71\\u9839\\u3002\", \"\\u4ed6\\u9109\\u5189\\u5189\\u6d88\\u5e74\\u6708\\uff0c\\u5e1d\\u91cc\\u6c88\\u6c88\\u9650\\u57ce\\u95d5\\u3002\", \"\\u4e0d\\u898b\\u733f\\u8072\\u52a9\\u5ba2\\u557c\\uff0c\\u552f\\u805e\\u65c5\\u601d\\u5c07\\u82b1\\u767c\\u3002\", \"\\u6211\\u5bb6\\u8fe2\\u905e\\u95dc\\u5c71\\u88cf\\uff0c\\u95dc\\u5c71\\u8fe2\\u905e\\u4e0d\\u53ef\\u8d8a\\u3002\", \"\\u6545\\u5712\\u6885\\u67f3\\u5c1a\\u9918\\u6625\\uff0c\\u4f86\\u6642\\u52ff\\u4f7f\\u82b3\\u83f2\\u6b47\\u3002\", \"\\u89e3\\u9785\\u6b32\\u8a00\\u6b78\\uff0c\\u57f7\\u8882\\u6134\\u591a\\u9055\\u3002\", \"\\u5317\\u6881\\u4ff1\\u63e1\\u624b\\uff0c\\u5357\\u6d66\\u5171\\u6cbe\\u8863\\u3002\", \"\\u5225\\u60c5\\u50b7\\u53bb\\u84cb\\uff0c\\u96e2\\u5ff5\\u60dc\\u5f82\\u8f1d\\u3002\", \"\\u77e5\\u97f3\\u4f55\\u6240\\u6258\\uff0c\\u6728\\u843d\\u96c1\\u5357\\u98db\\u3002\", \"\\u56de\\u4f86\\u671b\\u5e73\\u9678\\uff0c\\u6625\\u4f86\\u9152\\u61c9\\u719f\\u3002\", \"\\u76f8\\u5c07\\u83cc\\u95a3\\u81e5\\u9752\\u6eaa\\uff0c\\u4e14\\u7528\\u85e4\\u676f\\u6cdb\\u9ec3\\u83ca\\u3002\", \"\\u5341\\u5e74\\u4e0d\\u8abf\\u7232\\u8ca7\\u8ce4\\uff0c\\u767e\\u65e5\\u5c62\\u9077\\u96a8\\u501a\\u4f0f\\u3002\", \"\\u7957\\u7232\\u9808\\u6c42\\u8ca0\\u90ed\\u7530\\uff0c\\u4f7f\\u6211\\u518d\\u5e72\\u5dde\\u7e23\\u797f\\u3002\", \"\\u767e\\u5e74\\u9b31\\u9b31\\u5c11\\u9a30\\u9077\\uff0c\\u842c\\u91cc\\u9059\\u9059\\u5165\\u93e1\\u5ddd\\u3002\", \"\\u6d98\\u6c5f\\u62c2\\u6f6e\\u885d\\u767d\\u65e5\\uff0c\\u6dee\\u6d77\\u9577\\u6ce2\\u63a5\\u9060\\u5929\\u3002\", \"\\u53e2\\u7af9\\u51dd\\u671d\\u9732\\uff0c\\u5b64\\u5c71\\u8d77\\u669d\\u7159\\u3002\", \"\\u8cf4\\u6709\\u908a\\u57ce\\u6708\\uff0c\\u5e38\\u4f34\\u5ba2\\u65cc\\u61f8\\u3002\", \"\\u6771\\u5357\\u7f8e\\u7bad\\u7a31\\u5433\\u6703\\uff0c\\u540d\\u90fd\\u96b1\\u8eeb\\u4e09\\u6c5f\\u5916\\u3002\", \"\\u5857\\u5c71\\u57f7\\u7389\\u61c9\\u660c\\u671f\\uff0c\\u66f2\\u6c34\\u958b\\u895f\\u91cd\\u6587\\u6703\\u3002\", \"\\u4ed9\\u93d1\\u6d41\\u97f3\\u9cf4\\u9db4\\u5dba\\uff0c\\u5bf6\\u528d\\u5206\\u8f1d\\u843d\\u86df\\u7028\\u3002\", \"\\u672a\\u770b\\u767d\\u99ac\\u5c0d\\u8606\\u82bb\\uff0c\\u4e14\\u89ba\\u6d6e\\u96f2\\u4f3c\\u8eca\\u84cb\\u3002\", \"\\u6c5f\\u5357\\u7bc0\\u5e8f\\u591a\\uff0c\\u6587\\u9152\\u5c62\\u7d93\\u904e\\u3002\", \"\\u5171\\u8e0f\\u6625\\u6c5f\\u66f2\\uff0c\\u4ff1\\u5531\\u91c7\\u83f1\\u6b4c\\u3002\", \"\\u821f\\u79fb\\u7591\\u5165\\u93e1\\uff0c\\u68f9\\u8209\\u82e5\\u4e58\\u6ce2\\u3002\", \"\\u98a8\\u5149\\u7121\\u9650\\u6975\\uff0c\\u6b78\\u6a9d\\u7919\\u6c60\\u8377\\u3002\", \"\\u773a\\u807d\\u70df\\u971e\\u6b63\\u6d41\\u7704\\uff0c\\u5373\\u5f9e\\u738b\\u4e8b\\u6b78\\u826b\\u8f49\\u3002\", \"\\u829d\\u7530\\u82b1\\u6708\\u5c62\\u88f4\\u56de\\uff0c\\u91d1\\u8c37\\u4f73\\u671f\\u91cd\\u904a\\u884d\\u3002\", \"\\u767b\\u9ad8\\u5317\\u671b\\u55e4\\u6881\\u53df\\uff0c\\u6191\\u8efe\\u897f\\u5f81\\u60f3\\u6f58\\u63be\\u3002\", \"\\u5cef\\u958b\\u83ef\\u5cb3\\u8073\\u7591\\u84ee\\uff0c\\u6c34\\u6fc0\\u9f8d\\u9580\\u6025\\u5982\\u7bad\\u3002\", \"\\u4eba\\u4e8b\\u8b1d\\u5149\\u9670\\uff0c\\u4fc4\\u906d\\u971c\\u9732\\u4fb5\\u3002\", \"\\u5077\\u5b58\\u4e03\\u5c3a\\u5f71\\uff0c\\u5206\\u6c92\\u4e5d\\u6cc9\\u6df1\\u3002\", \"\\u7aae\\u9014\\u884c\\u6ce3\\u7389\\uff0c\\u61a4\\u8def\\u672a\\u85cf\\u91d1\\u3002\", \"\\u8339\\u837c\\u7a7a\\u6709\\u6b4e\\uff0c\\u61f7\\u6a58\\u7368\\u50b7\\u5fc3\\u3002\", \"\\u5e74\\u4f86\\u6b72\\u53bb\\u6210\\u92b7\\u9460\\uff0c\\u61f7\\u62b1\\u5fc3\\u671f\\u6f38\\u5be5\\u843d\\u3002\", \"\\u6302\\u51a0\\u88c2\\u5195\\u5df2\\u8fad\\u69ae\\uff0c\\u5357\\u755d\\u6771\\u81ef\\u4e8b\\u8015\\u947f\\u3002\", \"\\u8cd3\\u968e\\u5ba2\\u9662\\u5e38\\u758f\\u6563\\uff0c\\u84ec\\u5f91\\u67f4\\u6249\\u7d42\\u5bc2\\u5bde\\u3002\", \"\\u81ea\\u6709\\u6797\\u6cc9\\u582a\\u96b1\\u68f2\\uff0c\\u4f55\\u5fc5\\u5c71\\u4e2d\\u4e8b\\u4e18\\u58d1\\u3002\", \"\\u6211\\u4f4f\\u9752\\u9580\\u5916\\uff0c\\u5bb6\\u81e8\\u7d20\\u6efb\\u6ff1\\u3002\", \"\\u9059\\u77bb\\u4e39\\u9cf3\\u95d5\\uff0c\\u659c\\u671b\\u9ed1\\u9f8d\\u6d25\\u3002\", \"\\u8352\\u8862\\u901a\\u7375\\u9a0e\\uff0c\\u7aae\\u5df7\\u62b5\\u6a35\\u8f2a\\u3002\", \"\\u6642\\u6709\\u6843\\u6e90\\u5ba2\\uff0c\\u4f86\\u8a2a\\u7af9\\u6797\\u4eba\\u3002\", \"\\u6628\\u591c\\u7434\\u8072\\u594f\\u60b2\\u8abf\\uff0c\\u65ed\\u65e6\\u542b\\u9870\\u4e0d\\u6210\\u7b11\\u3002\", \"\\u679c\\u4e58\\u9a44\\u99ac\\u767c\\u56c2\\u66f8\\uff0c\\u5fa9\\u9053\\u90ce\\u5b98\\u7a1f\\u7db8\\u8aa5\\u3002\", \"\\u51b6\\u9577\\u975e\\u7f6a\\u66fe\\u7e32\\u7d4f\\uff0c\\u9577\\u5b7a\\u7136\\u7070\\u4e5f\\u7d93\\u6eba\\u3002\", \"\\u9ad8\\u9580\\u6709\\u95b1\\u4e0d\\u5716\\u5c01\\uff0c\\u5cfb\\u7b46\\u7121\\u805e\\u6b5b\\u6577\\u5999\\u3002\", \"\\u9069\\u96e2\\u4eac\\u5146\\u8b17\\uff0c\\u9084\\u5f9e\\u5fa1\\u53f2\\u5f48\\u3002\", \"\\u708e\\u5a01\\u8cc7\\u590f\\u666f\\uff0c\\u5e73\\u66f2\\u6cc1\\u79cb\\u7ff0\\u3002\", \"\\u756b\\u5730\\u7d42\\u96e3\\u5165\\uff0c\\u66f8\\u7a7a\\u81ea\\u4e0d\\u5b89\\u3002\", \"\\u5439\\u6bdb\\u672a\\u53ef\\u5f85\\uff0c\\u6416\\u5c3e\\u4e14\\u6c42\\u9910\\u3002\", \"\\u4e08\\u592b\\u574e\\u58c8\\u591a\\u6101\\u75be\\uff0c\\u5951\\u95ca\\u8fcd\\u9085\\u76e1\\u4eca\\u65e5\\u3002\", \"\\u614e\\u7f70\\u5be7\\u6191\\u5169\\u9020\\u8fad\\uff0c\\u56b4\\u79d1\\u76f4\\u6302\\u4e09\\u7ae0\\u5f8b\\u3002\", \"\\u9112\\u884d\\u929c\\u60b2\\u7e6b\\u71d5\\u7344\\uff0c\\u674e\\u65af\\u62b1\\u6028\\u62d8\\u79e6\\u684e\\u3002\", \"\\u4e0d\\u61c9\\u767d\\u9aee\\u9813\\u6210\\u7d72\\uff0c\\u76f4\\u7232\\u9ec3\\u6c99\\u6697\\u5982\\u6f06\\u3002\", \"\\u7d2b\\u7981\\u7d42\\u96e3\\u544c\\uff0c\\u6731\\u9580\\u4e0d\\u6613\\u6392\\u3002\", \"\\u9a5a\\u9b42\\u805e\\u8449\\u843d\\uff0c\\u5371\\u9b44\\u9010\\u8f2a\\u57cb\\u3002\", \"\\u971c\\u5a01\\u9059\\u6709\\u53b2\\uff0c\\u96ea[\\u6789]\\u9042\\u7121\\u968e\\u3002\", \"\\u542b\\u51a4\\u6b32\\u8ab0\\u9053\\uff0c\\u98f2\\u6c23\\u7368\\u5c45\\u61f7\\u3002\", \"\\u5ffd\\u805e\\u9a5b\\u4f7f\\u767c\\u95dc\\u6771\\uff0c\\u50b3\\u9053\\u5929\\u6ce2\\u842c\\u91cc\\u901a\\u3002\", \"\\u6db8\\u9c57\\u53bb\\u8f4d\\u9084\\u904a\\u6d77\\uff0c\\u5e7d\\u79bd\\u91cb\\u7db2\\u4fbf\\u7fd4\\u7a7a\\u3002\", \"\\u821c\\u6fa4\\u582f\\u66e6\\u65b9\\u6709\\u6975\\uff0c\\u8b92\\u8a00\\u5de7\\u4f5e\\u513b\\u7121\\u7aae\\u3002\", \"\\u8ab0\\u80fd\\u8dfc\\u8ff9\\u4f9d\\u4e09\\u8f14\\uff0c\\u6703\\u5c31\\u5546\\u5c71\\u8a2a\\u56db\\u7fc1\\u3002\"]"', '"[\"\\u5c11\\u5e74\\u91cd\\u82f1\\u4fa0\\uff0c\\u5f31\\u5c81\\u8d31\\u8863\\u51a0\\u3002\", \"\\u65e2\\u6258\\u5bf0\\u4e2d\\u8d4f\\uff0c\\u65b9\\u627f\\u819d\\u4e0b\\u6b22\\u3002\", \"\\u9068\\u6e38\\u705e\\u6c34\\u66f2\\uff0c\\u98ce\\u6708\\u6d1b\\u57ce\\u7aef\\u3002\", \"\\u4e14\\u77e5\\u65e0\\u7389\\u9994\\uff0c\\u8c01\\u80af\\u9010\\u91d1\\u4e38\\u3002\", \"\\u91d1\\u4e38\\u7389\\u9994\\u76db\\u7e41\\u534e\\uff0c\\u81ea\\u8a00\\u8f7b\\u4fae\\u5b63\\u4f26\\u5bb6\\u3002\", \"\\u4e94\\u9738\\u4e89\\u9a70\\u5343\\u91cc\\u9a6c\\uff0c\\u4e09\\u6761\\u7ade\\u9a9b\\u4e03\\u9999\\u8f66\\u3002\", \"\\u63a9\\u6620\\u98de\\u8f69\\u4e58\\u843d\\u7167\\uff0c\\u53c2\\u5dee\\u6b65\\u969c\\u5f15\\u671d\\u971e\\u3002\", \"\\u6c60\\u4e2d\\u65e7\\u6c34\\u5982\\u60ac\\u955c\\uff0c\\u5c4b\\u91cc\\u65b0\\u5986\\u4e0d\\u8ba9\\u82b1\\u3002\", \"\\u610f\\u6c14\\u98ce\\u4e91\\u500f\\u5982\\u6628\\uff0c\\u5c81\\u6708\\u6625\\u79cb\\u5c61\\u56de\\u8584\\u3002\", \"\\u4e0a\\u82d1\\u9891\\u7ecf\\u67f3\\u7d6e\\u98de\\uff0c\\u4e2d\\u56ed\\u51e0\\u89c1\\u6885\\u82b1\\u843d\\u3002\", \"\\u5f53\\u65f6\\u95e8\\u5ba2\\u4eca\\u4f55\\u5728\\uff1f\\u7574\\u6614\\u4ea4\\u670b\\u5df2\\u758e\\u7d22\\u3002\", \"\\u83ab\\u6559\\u6194\\u60b4\\u635f\\u5bb9\\u4eea\\uff0c\\u4f1a\\u5f97\\u9ad8\\u79cb\\u4e91\\u96fe\\u5ed3\\u3002\", \"\\u6df9\\u7559\\u5750\\u5e1d\\u4e61\\uff0c\\u65e0\\u4e8b\\u79ef\\u708e\\u51c9\\u3002\", \"\\u4e00\\u671d\\u62ab\\u77ed\\u8910\\uff0c\\u516d\\u8f7d\\u5949\\u957f\\u5eca\\u3002\", \"\\u8d4b\\u6587\\u6159\\u6614\\u9a6c\\uff0c\\u6267\\u621f\\u53f9\\u524d\\u626c\\u3002\", \"\\u6325\\u6208\\u51fa\\u6b66\\u5e10\\uff0c\\u8377\\u7b14\\u5165\\u6587\\u660c\\u3002\", \"\\u6587\\u660c\\u9690\\u9690\\u7687\\u57ce\\u91cc\\uff0c\\u7531\\u6765\\u5955\\u5955\\u591a\\u624d\\u5b50\\u3002\", \"\\u6f58\\u9646\\u8bcd\\u950b\\u9a86\\u9a7f\\u98de\\uff0c\\u5f20\\u66f9\\u7ff0\\u82d1\\u7eb5\\u6a2a\\u8d77\\u3002\", \"\\u537f\\u76f8\\u672a\\u66fe\\u8bc6\\uff0c\\u738b\\u4faf\\u5b81\\u89c1\\u62df\\u3002\", \"\\u5782\\u9493\\u7518\\u6210\\u767d\\u9996\\u7fc1\\uff0c\\u8d1f\\u85aa\\u4f55\\u5904\\u9022\\u77e5\\u5df1\\uff1f\", \"\\u5224\\u5c06\\u8fd0\\u547d\\u8d4b\\u7a77\\u901a\\uff0c\\u4ece\\u6765\\u5947\\u821b\\u4efb\\u897f\\u4e1c\\u3002\", \"\\u4e0d\\u5e94\\u6c38\\u5f03\\u540c\\u520d\\u72d7\\uff0c\\u4e14\\u590d\\u98d8\\u98d6\\u7c7b\\u8f6c\\u84ec\\u3002\", \"\\u5bb9\\u9b13\\u5e74\\u5e74\\u5f02\\uff0c\\u6625\\u534e\\u5c81\\u5c81\\u540c\\u3002\", \"\\u8363\\u89c2\\u672a\\u5c3d\\u793c\\uff0c\\u5f87\\u4e3b\\u6b32\\u7533\\u529f\\u3002\", \"\\u8102\\u8f66\\u79e3\\u9a6c\\u8f9e\\u4e61\\u56fd\\uff0c\\u8426\\u8f94\\u897f\\u5357\\u4f7f\\u909b\\u50f0\\u3002\", \"\\u7389\\u5792\\u94dc\\u6881\\u4e0d\\u6613\\u6500\\uff0c\\u5730\\u89d2\\u5929\\u6daf\\u7707\\u96be\\u6d4b\\u3002\", \"\\u83ba\\u556d\\u8749\\u541f\\u6709\\u60b2\\u671b\\uff0c\\u9e3f\\u6765\\u96c1\\u5ea6\\u65e0\\u97f3\\u606f\\u3002\", \"\\u9633\\u5173\\u79ef\\u96fe\\u4e07\\u91cc\\u660f\\uff0c\\u5251\\u9601\\u8fde\\u5c71\\u5343\\u79cd\\u8272\\u3002\", \"\\u8700\\u8def\\u4f55\\u60a0\\u60a0\\uff0c\\u5cb7\\u5cf0\\u963b\\u4e14\\u4fee\\u3002\", \"\\u56de\\u80a0\\u968f\\u4e5d\\u6298\\uff0c\\u8ff8\\u6cea\\u8fde\\u53cc\\u6d41\\u3002\", \"\\u5bd2\\u5149\\u5343\\u91cc\\u66ae\\uff0c\\u9732\\u6c14\\u4e8c\\u6c5f\\u79cb\\u3002\", \"\\u957f\\u9014\\u770b\\u675f\\u9a6c\\uff0c\\u5e73\\u6c34\\u4e14\\u6c88\\u725b\\u3002\", \"\\u534e\\u9633\\u65e7\\u5730\\u6807\\u795e\\u5236\\uff0c\\u77f3\\u955c\\u86fe\\u7709\\u771f\\u79c0\\u4e3d\\u3002\", \"\\u8bf8\\u845b\\u624d\\u96c4\\u5df2\\u53f7\\u9f99\\uff0c\\u516c\\u5b59\\u8dc3\\u9a6c\\u8f7b\\u79f0\\u5e1d\\u3002\", \"\\u4e94\\u4e01\\u5353\\u8366\\u591a\\u5947\\u529b\\uff0c\\u56db\\u58eb\\u82f1\\u7075\\u5bcc\\u6587\\u827a\\u3002\", \"\\u4e91\\u6c14\\u6a2a\\u5f00\\u516b\\u9635\\u5f62\\uff0c\\u6865\\u5f62\\u9065\\u5206\\u4e03\\u661f\\u52bf\\u3002\", \"\\u5ddd\\u5e73\\u70df\\u96fe\\u5f00\\uff0c\\u6e38\\u620f\\u9526\\u57ce\\u9688\\u3002\", \"\\u5889\\u9ad8\\u9f9f\\u671b\\u51fa\\uff0c\\u6c34\\u51c0\\u96c1\\u6587\\u56de\\u3002\", \"\\u5bfb\\u59dd\\u5165\\u9152\\u8086\\uff0c\\u8bbf\\u5ba2\\u4e0a\\u7434\\u53f0\\u3002\", \"\\u4e0d\\u8bc6\\u91d1\\u8c82\\u91cd\\uff0c\\u504f\\u60dc\\u7389\\u5c71\\u9893\\u3002\", \"\\u4ed6\\u4e61\\u5189\\u5189\\u6d88\\u5e74\\u6708\\uff0c\\u5e1d\\u91cc\\u6c88\\u6c88\\u9650\\u57ce\\u9619\\u3002\", \"\\u4e0d\\u89c1\\u733f\\u58f0\\u52a9\\u5ba2\\u557c\\uff0c\\u552f\\u95fb\\u65c5\\u601d\\u5c06\\u82b1\\u53d1\\u3002\", \"\\u6211\\u5bb6\\u8fe2\\u9012\\u5173\\u5c71\\u91cc\\uff0c\\u5173\\u5c71\\u8fe2\\u9012\\u4e0d\\u53ef\\u8d8a\\u3002\", \"\\u6545\\u56ed\\u6885\\u67f3\\u5c1a\\u4f59\\u6625\\uff0c\\u6765\\u65f6\\u52ff\\u4f7f\\u82b3\\u83f2\\u6b47\\u3002\", \"\\u89e3\\u9785\\u6b32\\u8a00\\u5f52\\uff0c\\u6267\\u8882\\u6006\\u591a\\u8fdd\\u3002\", \"\\u5317\\u6881\\u4ff1\\u63e1\\u624b\\uff0c\\u5357\\u6d66\\u5171\\u6cbe\\u8863\\u3002\", \"\\u522b\\u60c5\\u4f24\\u53bb\\u76d6\\uff0c\\u79bb\\u5ff5\\u60dc\\u5f82\\u8f89\\u3002\", \"\\u77e5\\u97f3\\u4f55\\u6240\\u6258\\uff0c\\u6728\\u843d\\u96c1\\u5357\\u98de\\u3002\", \"\\u56de\\u6765\\u671b\\u5e73\\u9646\\uff0c\\u6625\\u6765\\u9152\\u5e94\\u719f\\u3002\", \"\\u76f8\\u5c06\\u83cc\\u9601\\u5367\\u9752\\u6eaa\\uff0c\\u4e14\\u7528\\u85e4\\u676f\\u6cdb\\u9ec4\\u83ca\\u3002\", \"\\u5341\\u5e74\\u4e0d\\u8c03\\u4e3a\\u8d2b\\u8d31\\uff0c\\u767e\\u65e5\\u5c61\\u8fc1\\u968f\\u501a\\u4f0f\\u3002\", \"\\u7957\\u4e3a\\u987b\\u6c42\\u8d1f\\u90ed\\u7530\\uff0c\\u4f7f\\u6211\\u518d\\u5e72\\u5dde\\u53bf\\u7984\\u3002\", \"\\u767e\\u5e74\\u90c1\\u90c1\\u5c11\\u817e\\u8fc1\\uff0c\\u4e07\\u91cc\\u9065\\u9065\\u5165\\u955c\\u5ddd\\u3002\", \"\\u6d98\\u6c5f\\u62c2\\u6f6e\\u51b2\\u767d\\u65e5\\uff0c\\u6dee\\u6d77\\u957f\\u6ce2\\u63a5\\u8fdc\\u5929\\u3002\", \"\\u4e1b\\u7af9\\u51dd\\u671d\\u9732\\uff0c\\u5b64\\u5c71\\u8d77\\u669d\\u70df\\u3002\", \"\\u8d56\\u6709\\u8fb9\\u57ce\\u6708\\uff0c\\u5e38\\u4f34\\u5ba2\\u65cc\\u60ac\\u3002\", \"\\u4e1c\\u5357\\u7f8e\\u7bad\\u79f0\\u5434\\u4f1a\\uff0c\\u540d\\u90fd\\u9690\\u8f78\\u4e09\\u6c5f\\u5916\\u3002\", \"\\u6d82\\u5c71\\u6267\\u7389\\u5e94\\u660c\\u671f\\uff0c\\u66f2\\u6c34\\u5f00\\u895f\\u91cd\\u6587\\u4f1a\\u3002\", \"\\u4ed9\\u955d\\u6d41\\u97f3\\u9e23\\u9e64\\u5cad\\uff0c\\u5b9d\\u5251\\u5206\\u8f89\\u843d\\u86df\\u6fd1\\u3002\", \"\\u672a\\u770b\\u767d\\u9a6c\\u5bf9\\u82a6\\u520d\\uff0c\\u4e14\\u89c9\\u6d6e\\u4e91\\u4f3c\\u8f66\\u76d6\\u3002\", \"\\u6c5f\\u5357\\u8282\\u5e8f\\u591a\\uff0c\\u6587\\u9152\\u5c61\\u7ecf\\u8fc7\\u3002\", \"\\u5171\\u8e0f\\u6625\\u6c5f\\u66f2\\uff0c\\u4ff1\\u5531\\u91c7\\u83f1\\u6b4c\\u3002\", \"\\u821f\\u79fb\\u7591\\u5165\\u955c\\uff0c\\u68f9\\u4e3e\\u82e5\\u4e58\\u6ce2\\u3002\", \"\\u98ce\\u5149\\u65e0\\u9650\\u6781\\uff0c\\u5f52\\u6a9d\\u788d\\u6c60\\u8377\\u3002\", \"\\u773a\\u542c\\u70df\\u971e\\u6b63\\u6d41\\u7704\\uff0c\\u5373\\u4ece\\u738b\\u4e8b\\u5f52\\u823b\\u8f6c\\u3002\", \"\\u829d\\u7530\\u82b1\\u6708\\u5c61\\u88f4\\u56de\\uff0c\\u91d1\\u8c37\\u4f73\\u671f\\u91cd\\u6e38\\u884d\\u3002\", \"\\u767b\\u9ad8\\u5317\\u671b\\u55e4\\u6881\\u53df\\uff0c\\u51ed\\u8f7c\\u897f\\u5f81\\u60f3\\u6f58\\u63be\\u3002\", \"\\u5cf0\\u5f00\\u534e\\u5cb3\\u8038\\u7591\\u83b2\\uff0c\\u6c34\\u6fc0\\u9f99\\u95e8\\u6025\\u5982\\u7bad\\u3002\", \"\\u4eba\\u4e8b\\u8c22\\u5149\\u9634\\uff0c\\u4fc4\\u906d\\u971c\\u9732\\u4fb5\\u3002\", \"\\u5077\\u5b58\\u4e03\\u5c3a\\u5f71\\uff0c\\u5206\\u6ca1\\u4e5d\\u6cc9\\u6df1\\u3002\", \"\\u7a77\\u9014\\u884c\\u6ce3\\u7389\\uff0c\\u6124\\u8def\\u672a\\u85cf\\u91d1\\u3002\", \"\\u8339\\u837c\\u7a7a\\u6709\\u53f9\\uff0c\\u6000\\u6a58\\u72ec\\u4f24\\u5fc3\\u3002\", \"\\u5e74\\u6765\\u5c81\\u53bb\\u6210\\u9500\\u94c4\\uff0c\\u6000\\u62b1\\u5fc3\\u671f\\u6e10\\u5be5\\u843d\\u3002\", \"\\u6302\\u51a0\\u88c2\\u5195\\u5df2\\u8f9e\\u8363\\uff0c\\u5357\\u4ea9\\u4e1c\\u81ef\\u4e8b\\u8015\\u51ff\\u3002\", \"\\u5bbe\\u9636\\u5ba2\\u9662\\u5e38\\u758f\\u6563\\uff0c\\u84ec\\u5f84\\u67f4\\u6249\\u7ec8\\u5bc2\\u5bde\\u3002\", \"\\u81ea\\u6709\\u6797\\u6cc9\\u582a\\u9690\\u6816\\uff0c\\u4f55\\u5fc5\\u5c71\\u4e2d\\u4e8b\\u4e18\\u58d1\\u3002\", \"\\u6211\\u4f4f\\u9752\\u95e8\\u5916\\uff0c\\u5bb6\\u4e34\\u7d20\\u6d50\\u6ee8\\u3002\", \"\\u9065\\u77bb\\u4e39\\u51e4\\u9619\\uff0c\\u659c\\u671b\\u9ed1\\u9f99\\u6d25\\u3002\", \"\\u8352\\u8862\\u901a\\u730e\\u9a91\\uff0c\\u7a77\\u5df7\\u62b5\\u6a35\\u8f6e\\u3002\", \"\\u65f6\\u6709\\u6843\\u6e90\\u5ba2\\uff0c\\u6765\\u8bbf\\u7af9\\u6797\\u4eba\\u3002\", \"\\u6628\\u591c\\u7434\\u58f0\\u594f\\u60b2\\u8c03\\uff0c\\u65ed\\u65e6\\u542b\\u98a6\\u4e0d\\u6210\\u7b11\\u3002\", \"\\u679c\\u4e58\\u9aa2\\u9a6c\\u53d1\\u56a3\\u4e66\\uff0c\\u590d\\u9053\\u90ce\\u5b98\\u7980\\u7eb6\\u8bf0\\u3002\", \"\\u51b6\\u957f\\u975e\\u7f6a\\u66fe\\u7f27\\u7d4f\\uff0c\\u957f\\u5b7a\\u7136\\u7070\\u4e5f\\u7ecf\\u6eba\\u3002\", \"\\u9ad8\\u95e8\\u6709\\u9605\\u4e0d\\u56fe\\u5c01\\uff0c\\u5cfb\\u7b14\\u65e0\\u95fb\\u6b5b\\u6577\\u5999\\u3002\", \"\\u9002\\u79bb\\u4eac\\u5146\\u8c24\\uff0c\\u8fd8\\u4ece\\u5fa1\\u53f2\\u5f39\\u3002\", \"\\u708e\\u5a01\\u8d44\\u590f\\u666f\\uff0c\\u5e73\\u66f2\\u51b5\\u79cb\\u7ff0\\u3002\", \"\\u753b\\u5730\\u7ec8\\u96be\\u5165\\uff0c\\u4e66\\u7a7a\\u81ea\\u4e0d\\u5b89\\u3002\", \"\\u5439\\u6bdb\\u672a\\u53ef\\u5f85\\uff0c\\u6447\\u5c3e\\u4e14\\u6c42\\u9910\\u3002\", \"\\u4e08\\u592b\\u574e\\ud845\\udc84\\u591a\\u6101\\u75be\\uff0c\\u5951\\u9614\\u8fcd\\u9085\\u5c3d\\u4eca\\u65e5\\u3002\", \"\\u614e\\u7f5a\\u5b81\\u51ed\\u4e24\\u9020\\u8f9e\\uff0c\\u4e25\\u79d1\\u76f4\\u6302\\u4e09\\u7ae0\\u5f8b\\u3002\", \"\\u90b9\\u884d\\u8854\\u60b2\\u7cfb\\u71d5\\u72f1\\uff0c\\u674e\\u65af\\u62b1\\u6028\\u62d8\\u79e6\\u684e\\u3002\", \"\\u4e0d\\u5e94\\u767d\\u53d1\\u987f\\u6210\\u4e1d\\uff0c\\u76f4\\u4e3a\\u9ec4\\u6c99\\u6697\\u5982\\u6f06\\u3002\", \"\\u7d2b\\u7981\\u7ec8\\u96be\\u544c\\uff0c\\u6731\\u95e8\\u4e0d\\u6613\\u6392\\u3002\", \"\\u60ca\\u9b42\\u95fb\\u53f6\\u843d\\uff0c\\u5371\\u9b44\\u9010\\u8f6e\\u57cb\\u3002\", \"\\u971c\\u5a01\\u9065\\u6709\\u5389\\uff0c\\u96ea[\\u6789]\\u9042\\u65e0\\u9636\\u3002\", \"\\u542b\\u51a4\\u6b32\\u8c01\\u9053\\uff0c\\u996e\\u6c14\\u72ec\\u5c45\\u6000\\u3002\", \"\\u5ffd\\u95fb\\u9a7f\\u4f7f\\u53d1\\u5173\\u4e1c\\uff0c\\u4f20\\u9053\\u5929\\u6ce2\\u4e07\\u91cc\\u901a\\u3002\", \"\\u6db8\\u9cde\\u53bb\\u8f99\\u8fd8\\u6e38\\u6d77\\uff0c\\u5e7d\\u79bd\\u91ca\\u7f51\\u4fbf\\u7fd4\\u7a7a\\u3002\", \"\\u821c\\u6cfd\\u5c27\\u66e6\\u65b9\\u6709\\u6781\\uff0c\\u8c17\\u8a00\\u5de7\\u4f5e\\u50a5\\u65e0\\u7a77\\u3002\", \"\\u8c01\\u80fd\\u8dfc\\u8ff9\\u4f9d\\u4e09\\u8f85\\uff0c\\u4f1a\\u5c31\\u5546\\u5c71\\u8bbf\\u56db\\u7fc1\\u3002\"]"', '诗', 'shi', '', NULL, '疇昔篇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd3f6ad-3956-41bb-b792-bbea3f08decd', '豔情代郭氏荅盧照鄰', '艳情代郭氏荅卢照邻', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u8fe2\\u8fe2\\u828a\\u8def\\u671b\\u829d\\u7530\\uff0c\\u7707\\u7707\\u51fd\\u95dc\\u6068\\u8700\\u5ddd\\u3002\", \"\\u6b78\\u96f2\\u5df2\\u843d\\u6daa\\u6c5f\\u5916\\uff0c\\u9084\\u96c1\\u61c9\\u904e\\u6d1b\\u6c34\\u700d\\u3002\", \"\\u6d1b\\u6c34\\u508d\\u9023\\u5e1d\\u57ce\\u5074\\uff0c\\u5e1d\\u5b85\\u5c64\\u750d\\u5782\\u9cf3\\u7ffc\\u3002\", \"\\u9285\\u99dd\\u8def\\u4e0a\\u67f3\\u5343\\u689d\\uff0c\\u91d1\\u8c37\\u5712\\u4e2d\\u82b1\\u5e7e\\u8272\\u3002\", \"\\u67f3\\u8449\\u5712\\u82b1\\u8655\\u8655\\u65b0\\uff0c\\u6d1b\\u967d\\u6843\\u674e\\u61c9\\u82b3\\u6625\\u3002\", \"\\u59be\\u5411\\u96d9\\u6d41\\u7aba\\u77f3\\u93e1\\uff0c\\u541b\\u4f4f\\u4e09\\u5ddd\\u5b88\\u7389\\u4eba\\u3002\", \"\\u6b64\\u6642\\u96e2\\u5225\\u90a3\\u582a\\u9053\\uff0c\\u6b64\\u65e5\\u7a7a\\u7240\\u5c0d\\u82b3\\u6cbc\\u3002\", \"\\u82b3\\u6cbc\\u5f92\\u904a\\u6bd4\\u76ee\\u9b5a\\uff0c\\u5e7d\\u5f91\\u9084\\u751f\\u62d4\\u5fc3\\u8278\\u3002\", \"\\u6d41\\u98a8\\u56de\\u96ea\\u513b\\u4fbf\\u5a1f\\uff0c\\u9a65\\u5b50\\u9b5a\\u6587\\u5be6\\u53ef\\u6190\\u3002\", \"\\u64f2\\u679c\\u6cb3\\u967d\\u541b\\u6709\\u5206\\uff0c\\u8ca8\\u9152\\u6210\\u90fd\\u59be\\u4ea6\\u7136\\u3002\", \"\\u83ab\\u8a00\\u8ca7\\u8ce4\\u7121\\u4eba\\u91cd\\uff0c\\u83ab\\u8a00\\u5bcc\\u8cb4\\u61c9\\u9808\\u7a2e\\u3002\", \"\\u7da0\\u73e0\\u7336\\u5f97\\u77f3\\u5d07\\u6190\\uff0c\\u98db\\u71d5\\u66fe\\u7d93\\u6f22\\u7687\\u5bf5\\u3002\", \"\\u826f\\u4eba\\u4f55\\u8655\\u9189\\u7e31\\u6a6b\\uff1f\\u76f4\\u5982\\u5faa\\u9ed8\\u5b88\\u7a7a\\u540d\\u3002\", \"\\u5012\\u63d0\\u65b0\\u7e11\\u6210\\u614a\\u614a\\uff0c\\u7ffb\\u5c07\\u6545\\u528d\\u4f5c\\u5e73\\u5e73\\u3002\", \"\\u96e2\\u524d\\u5409\\u5922\\u6210\\u862d\\u5146\\uff0c\\u5225\\u5f8c\\u557c\\u75d5\\u4e0a\\u7af9\\u751f\\u3002\", \"\\u5225\\u65e5\\u5206\\u660e\\u76f8\\u7d04\\u675f\\uff0c\\u5df2\\u53d6\\u5b9c\\u5bb6\\u6210\\u8aa1\\u52d6\\u3002\", \"\\u7576\\u6642\\u64ec\\u5f04\\u638c\\u4e2d\\u73e0\\uff0c\\u8c48\\u8b02\\u5148\\u6467\\u5ead\\u969b\\u7389\\u3002\", \"\\u60b2\\u9cf4\\u4e94\\u91cc\\u7121\\u4eba\\u554f\\uff0c\\u8178\\u65b7\\u4e09\\u8072\\u8ab0\\u7232\\u7e8c\\u3002\", \"\\u601d\\u541b\\u6b32\\u4e0a\\u671b\\u592b\\u81fa\\uff0c\\u7aef\\u5c45\\u61f6\\u807d\\u5c07\\u96db\\u66f2\\u3002\", \"\\u6c88\\u6c88\\u843d\\u65e5\\u5411\\u5c71\\u4f4e\\uff0c\\u6a90\\u524d\\u6b78\\u71d5\\u7add\\u982d\\u6816\\u3002\", \"\\u62b1\\u819d\\u7576\\u7a97\\u770b\\u5915\\u5154\\uff0c\\u5074\\u8033\\u7a7a\\u623f\\u807d\\u66c9\\u96de\\u3002\", \"\\u821e\\u8776\\u81e8\\u968e\\u79ea\\u81ea\\u821e\\uff0c\\u557c\\u9ce5\\u9022\\u4eba\\u4ea6\\u52a9\\u557c\\u3002\", \"\\u7368\\u5750\\u50b7\\u5b64\\u6795\\uff0c\\u6625\\u4f86\\u60b2\\u66f4\\u751a\\u3002\", \"\\u5ce8\\u7709\\u5c71\\u4e0a\\u6708\\u5982\\u7709\\uff0c\\u6fef\\u9326\\u6c5f\\u4e2d\\u971e\\u4f3c\\u9326\\u3002\", \"\\u9326\\u5b57\\u56de\\u6587\\u6b32\\u8d08\\u541b\\uff0c\\u528d\\u58c1\\u5c64\\u5cf0\\u81ea\\u7cfe\\u7d1b\\u3002\", \"\\u5e73\\u6c5f\\u6dfc\\u6dfc\\u5206\\u6e05\\u6d66\\uff0c\\u9577\\u8def\\u60a0\\u60a0\\u9593\\u767d\\u96f2\\u3002\", \"\\u4e5f\\u77e5\\u4eac\\u6d1b\\u591a\\u4f73\\u9e97\\uff0c\\u4e5f\\u77e5\\u5c71\\u5cab\\u9059\\u8667\\u853d\\u3002\", \"\\u7121\\u90a3\\u77ed\\u5c01\\u5373\\u758e\\u7d22\\uff0c\\u4e0d\\u5728\\u9577\\u60c5\\u5b88\\u671f\\u5951\\u3002\", \"\\u50b3\\u805e\\u7e54\\u5973\\u5c0d\\u727d\\u725b\\uff0c\\u76f8\\u671b\\u91cd\\u6cb3\\u9694\\u6dfa\\u6d41\\u3002\", \"\\u8ab0\\u5206\\u8fe2\\u8fe2\\u7d93\\u5169\\u6b72\\uff0c\\u8ab0\\u80fd\\u8108\\u8108\\u5f85\\u4e09\\u79cb\\u3002\", \"\\u60c5\\u77e5\\u553e\\u4e95\\u7d42\\u7121\\u7406\\uff0c\\u60c5\\u77e5\\u8986\\u6c34\\u4e5f\\u96e3\\u6536\\u3002\", \"\\u4e0d\\u5fa9\\u4e0b\\u5c71\\u80fd\\u501f\\u554f\\uff0c\\u66f4\\u5411\\u76e7\\u5bb6\\u5b57\\u83ab\\u6101\\u3002\"]"', '"[\"\\u8fe2\\u8fe2\\u828a\\u8def\\u671b\\u829d\\u7530\\uff0c\\u7707\\u7707\\u51fd\\u5173\\u6068\\u8700\\u5ddd\\u3002\", \"\\u5f52\\u4e91\\u5df2\\u843d\\u6daa\\u6c5f\\u5916\\uff0c\\u8fd8\\u96c1\\u5e94\\u8fc7\\u6d1b\\u6c34\\u700d\\u3002\", \"\\u6d1b\\u6c34\\u508d\\u8fde\\u5e1d\\u57ce\\u4fa7\\uff0c\\u5e1d\\u5b85\\u5c42\\u750d\\u5782\\u51e4\\u7ffc\\u3002\", \"\\u94dc\\u9a7c\\u8def\\u4e0a\\u67f3\\u5343\\u6761\\uff0c\\u91d1\\u8c37\\u56ed\\u4e2d\\u82b1\\u51e0\\u8272\\u3002\", \"\\u67f3\\u53f6\\u56ed\\u82b1\\u5904\\u5904\\u65b0\\uff0c\\u6d1b\\u9633\\u6843\\u674e\\u5e94\\u82b3\\u6625\\u3002\", \"\\u59be\\u5411\\u53cc\\u6d41\\u7aa5\\u77f3\\u955c\\uff0c\\u541b\\u4f4f\\u4e09\\u5ddd\\u5b88\\u7389\\u4eba\\u3002\", \"\\u6b64\\u65f6\\u79bb\\u522b\\u90a3\\u582a\\u9053\\uff0c\\u6b64\\u65e5\\u7a7a\\u5e8a\\u5bf9\\u82b3\\u6cbc\\u3002\", \"\\u82b3\\u6cbc\\u5f92\\u6e38\\u6bd4\\u76ee\\u9c7c\\uff0c\\u5e7d\\u5f84\\u8fd8\\u751f\\u62d4\\u5fc3\\u8278\\u3002\", \"\\u6d41\\u98ce\\u56de\\u96ea\\u50a5\\u4fbf\\u5a1f\\uff0c\\u9aa5\\u5b50\\u9c7c\\u6587\\u5b9e\\u53ef\\u601c\\u3002\", \"\\u63b7\\u679c\\u6cb3\\u9633\\u541b\\u6709\\u5206\\uff0c\\u8d27\\u9152\\u6210\\u90fd\\u59be\\u4ea6\\u7136\\u3002\", \"\\u83ab\\u8a00\\u8d2b\\u8d31\\u65e0\\u4eba\\u91cd\\uff0c\\u83ab\\u8a00\\u5bcc\\u8d35\\u5e94\\u987b\\u79cd\\u3002\", \"\\u7eff\\u73e0\\u72b9\\u5f97\\u77f3\\u5d07\\u601c\\uff0c\\u98de\\u71d5\\u66fe\\u7ecf\\u6c49\\u7687\\u5ba0\\u3002\", \"\\u826f\\u4eba\\u4f55\\u5904\\u9189\\u7eb5\\u6a2a\\uff1f\\u76f4\\u5982\\u5faa\\u9ed8\\u5b88\\u7a7a\\u540d\\u3002\", \"\\u5012\\u63d0\\u65b0\\u7f23\\u6210\\u614a\\u614a\\uff0c\\u7ffb\\u5c06\\u6545\\u5251\\u4f5c\\u5e73\\u5e73\\u3002\", \"\\u79bb\\u524d\\u5409\\u68a6\\u6210\\u5170\\u5146\\uff0c\\u522b\\u540e\\u557c\\u75d5\\u4e0a\\u7af9\\u751f\\u3002\", \"\\u522b\\u65e5\\u5206\\u660e\\u76f8\\u7ea6\\u675f\\uff0c\\u5df2\\u53d6\\u5b9c\\u5bb6\\u6210\\u8beb\\u52d6\\u3002\", \"\\u5f53\\u65f6\\u62df\\u5f04\\u638c\\u4e2d\\u73e0\\uff0c\\u5c82\\u8c13\\u5148\\u6467\\u5ead\\u9645\\u7389\\u3002\", \"\\u60b2\\u9e23\\u4e94\\u91cc\\u65e0\\u4eba\\u95ee\\uff0c\\u80a0\\u65ad\\u4e09\\u58f0\\u8c01\\u4e3a\\u7eed\\u3002\", \"\\u601d\\u541b\\u6b32\\u4e0a\\u671b\\u592b\\u53f0\\uff0c\\u7aef\\u5c45\\u61d2\\u542c\\u5c06\\u96cf\\u66f2\\u3002\", \"\\u6c88\\u6c88\\u843d\\u65e5\\u5411\\u5c71\\u4f4e\\uff0c\\u6a90\\u524d\\u5f52\\u71d5\\u7add\\u5934\\u6816\\u3002\", \"\\u62b1\\u819d\\u5f53\\u7a97\\u770b\\u5915\\u5154\\uff0c\\u4fa7\\u8033\\u7a7a\\u623f\\u542c\\u6653\\u9e21\\u3002\", \"\\u821e\\u8776\\u4e34\\u9636\\u79ea\\u81ea\\u821e\\uff0c\\u557c\\u9e1f\\u9022\\u4eba\\u4ea6\\u52a9\\u557c\\u3002\", \"\\u72ec\\u5750\\u4f24\\u5b64\\u6795\\uff0c\\u6625\\u6765\\u60b2\\u66f4\\u751a\\u3002\", \"\\u5ce8\\u7709\\u5c71\\u4e0a\\u6708\\u5982\\u7709\\uff0c\\u6fef\\u9526\\u6c5f\\u4e2d\\u971e\\u4f3c\\u9526\\u3002\", \"\\u9526\\u5b57\\u56de\\u6587\\u6b32\\u8d60\\u541b\\uff0c\\u5251\\u58c1\\u5c42\\u5cf0\\u81ea\\u7ea0\\u7eb7\\u3002\", \"\\u5e73\\u6c5f\\u6dfc\\u6dfc\\u5206\\u6e05\\u6d66\\uff0c\\u957f\\u8def\\u60a0\\u60a0\\u95f4\\u767d\\u4e91\\u3002\", \"\\u4e5f\\u77e5\\u4eac\\u6d1b\\u591a\\u4f73\\u4e3d\\uff0c\\u4e5f\\u77e5\\u5c71\\u5cab\\u9065\\u4e8f\\u853d\\u3002\", \"\\u65e0\\u90a3\\u77ed\\u5c01\\u5373\\u758e\\u7d22\\uff0c\\u4e0d\\u5728\\u957f\\u60c5\\u5b88\\u671f\\u5951\\u3002\", \"\\u4f20\\u95fb\\u7ec7\\u5973\\u5bf9\\u7275\\u725b\\uff0c\\u76f8\\u671b\\u91cd\\u6cb3\\u9694\\u6d45\\u6d41\\u3002\", \"\\u8c01\\u5206\\u8fe2\\u8fe2\\u7ecf\\u4e24\\u5c81\\uff0c\\u8c01\\u80fd\\u8109\\u8109\\u5f85\\u4e09\\u79cb\\u3002\", \"\\u60c5\\u77e5\\u553e\\u4e95\\u7ec8\\u65e0\\u7406\\uff0c\\u60c5\\u77e5\\u8986\\u6c34\\u4e5f\\u96be\\u6536\\u3002\", \"\\u4e0d\\u590d\\u4e0b\\u5c71\\u80fd\\u501f\\u95ee\\uff0c\\u66f4\\u5411\\u5362\\u5bb6\\u5b57\\u83ab\\u6101\\u3002\"]"', '诗', 'shi', '', NULL, '豔情代郭氏荅盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e18c281e-d737-4c42-af64-9bdaa41f7ff7', '王昭君', '王昭君', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u6b5b\\u5bb9\\u8fad\\u8c79\\u5c3e\\uff0c\\u7dd8\\u6068\\u5ea6\\u9f8d\\u9c57\\u3002\", \"\\u91d1\\u923f\\u660e\\u6f22\\u6708\\uff0c\\u7389\\u7b6f\\u67d3\\u80e1\\u5875\\u3002\", \"\\u53e4\\u93e1\\u83f1\\u82b1\\u6697\\uff0c\\u6101\\u7709\\u67f3\\u8449\\u9870\\u3002\", \"\\u552f\\u6709\\u6e05\\u7b33\\u66f2\\uff0c\\u6642\\u805e\\u82b3\\u6a39\\u6625\\u3002\"]"', '"[\"\\u6b5b\\u5bb9\\u8f9e\\u8c79\\u5c3e\\uff0c\\u7f04\\u6068\\u5ea6\\u9f99\\u9cde\\u3002\", \"\\u91d1\\u94bf\\u660e\\u6c49\\u6708\\uff0c\\u7389\\u7b6f\\u67d3\\u80e1\\u5c18\\u3002\", \"\\u53e4\\u955c\\u83f1\\u82b1\\u6697\\uff0c\\u6101\\u7709\\u67f3\\u53f6\\u98a6\\u3002\", \"\\u552f\\u6709\\u6e05\\u7b33\\u66f2\\uff0c\\u65f6\\u95fb\\u82b3\\u6811\\u6625\\u3002\"]"', '诗', 'shi', '', NULL, '王昭君 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('001a1111-9d70-49e5-a4bf-2f7a96656682', '於紫雲觀贈道士', '于紫云观赠道士', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u78a7\\u843d\\u6f84\\u79cb\\u666f\\uff0c\\u7384\\u9580\\u5553\\u66d9\\u95dc\\u3002\", \"\\u4eba\\u7591\\u5217\\u79a6\\u81f3\\uff0c\\u5ba2\\u4f3c\\u4ee4\\u5a01\\u9084\\u3002\", \"\\u7fbd\\u84cb\\u5f92\\u6b23\\u4ef0\\uff0c\\u96f2\\u8eca\\u672a\\u53ef\\u6500\\u3002\", \"\\u8879\\u61c9\\u50be\\u7389\\u91b4\\uff0c\\u6642\\u8a31\\u5bc4\\u9839\\u984f\\u3002\"]"', '"[\"\\u78a7\\u843d\\u6f84\\u79cb\\u666f\\uff0c\\u7384\\u95e8\\u542f\\u66d9\\u5173\\u3002\", \"\\u4eba\\u7591\\u5217\\u5fa1\\u81f3\\uff0c\\u5ba2\\u4f3c\\u4ee4\\u5a01\\u8fd8\\u3002\", \"\\u7fbd\\u76d6\\u5f92\\u6b23\\u4ef0\\uff0c\\u4e91\\u8f66\\u672a\\u53ef\\u6500\\u3002\", \"\\u8879\\u5e94\\u503e\\u7389\\u91b4\\uff0c\\u65f6\\u8bb8\\u5bc4\\u9893\\u989c\\u3002\"]"', '诗', 'shi', '', NULL, '於紫雲觀贈道士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32670eea-75d3-43aa-af05-e37f822a360b', '渡瓜步江', '渡瓜步江', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u6367\\u6a84\\u8fad\\u5e7d\\u5f91\\uff0c\\u9cf4\\u6994\\u4e0b\\u8cb4\\u6d32\\u3002\", \"\\u9a5a\\u6fe4\\u7591\\u8e8d\\u99ac\\uff0c\\u7a4d\\u6c23\\u4f3c\\u9023\\u725b\\u3002\", \"\\u6708\\u8fe5\\u5bd2\\u6c99\\u6de8\\uff0c\\u98a8\\u6025\\u591c\\u6c5f\\u79cb\\u3002\", \"\\u4e0d\\u5b78\\u6d6e\\u96f2\\u5f71\\uff0c\\u4ed6\\u9109\\u7a7a\\u6eef\\u7559\\u3002\"]"', '"[\"\\u6367\\u6a84\\u8f9e\\u5e7d\\u5f84\\uff0c\\u9e23\\u6994\\u4e0b\\u8d35\\u6d32\\u3002\", \"\\u60ca\\u6d9b\\u7591\\u8dc3\\u9a6c\\uff0c\\u79ef\\u6c14\\u4f3c\\u8fde\\u725b\\u3002\", \"\\u6708\\u8fe5\\u5bd2\\u6c99\\u51c0\\uff0c\\u98ce\\u6025\\u591c\\u6c5f\\u79cb\\u3002\", \"\\u4e0d\\u5b66\\u6d6e\\u4e91\\u5f71\\uff0c\\u4ed6\\u4e61\\u7a7a\\u6ede\\u7559\\u3002\"]"', '诗', 'shi', '', NULL, '渡瓜步江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c3ffb73-e43a-4d7b-b2af-c7e4d9366c7c', '途中有懷', '途中有怀', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u7760\\u7136\\u61f7\\u695a\\u594f\\uff0c\\u60b5\\u77e3\\u80cc\\u79e6\\u95dc\\u3002\", \"\\u6db8\\u9c57\\u9a5a\\u7167\\u8f4d\\uff0c\\u589c\\u7fbd\\u602f\\u865b\\u5f4e\\u3002\", \"\\u7d20\\u670d\\u4e09\\u5ddd\\u5316\\uff0c\\u70cf\\u88d8\\u5341\\u4e0a\\u9084\\u3002\", \"\\u83ab\\u8a00\\u7121\\u7693\\u9f52\\uff0c\\u6642\\u4fd7\\u8584\\u6731\\u984f\\u3002\"]"', '"[\"\\u7760\\u7136\\u6000\\u695a\\u594f\\uff0c\\u6005\\u77e3\\u80cc\\u79e6\\u5173\\u3002\", \"\\u6db8\\u9cde\\u60ca\\u7167\\u8f99\\uff0c\\u5760\\u7fbd\\u602f\\u865a\\u5f2f\\u3002\", \"\\u7d20\\u670d\\u4e09\\u5ddd\\u5316\\uff0c\\u4e4c\\u88d8\\u5341\\u4e0a\\u8fd8\\u3002\", \"\\u83ab\\u8a00\\u65e0\\u7693\\u9f7f\\uff0c\\u65f6\\u4fd7\\u8584\\u6731\\u989c\\u3002\"]"', '诗', 'shi', '', NULL, '途中有懷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7271af44-1385-42b3-91c1-d613099eafe3', '至分水戍', '至分水戍', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u884c\\u5f79\\u5ffd\\u96e2\\u6182\\uff0c\\u5fa9\\u6b64\\u6134\\u5206\\u6d41\\u3002\", \"\\u6ffa\\u77f3\\u56de\\u6e4d\\u54bd\\uff0c\\u7e08\\u53e2\\u66f2\\u6f97\\u5e7d\\u3002\", \"\\u9670\\u5dd6\\u5e38\\u7d50\\u6666\\uff0c\\u5bbf\\u83bd\\u7af6\\u542b\\u79cb\\u3002\", \"\\u6cc1\\u4e43\\u971c\\u6668\\u65e9\\uff0c\\u5bd2\\u98a8\\u5165\\u620d\\u6a13\\u3002\"]"', '"[\"\\u884c\\u5f79\\u5ffd\\u79bb\\u5fe7\\uff0c\\u590d\\u6b64\\u6006\\u5206\\u6d41\\u3002\", \"\\u6e85\\u77f3\\u56de\\u6e4d\\u54bd\\uff0c\\u8426\\u4e1b\\u66f2\\u6da7\\u5e7d\\u3002\", \"\\u9634\\u5ca9\\u5e38\\u7ed3\\u6666\\uff0c\\u5bbf\\u83bd\\u7ade\\u542b\\u79cb\\u3002\", \"\\u51b5\\u4e43\\u971c\\u6668\\u65e9\\uff0c\\u5bd2\\u98ce\\u5165\\u620d\\u697c\\u3002\"]"', '诗', 'shi', '', NULL, '至分水戍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70d2639f-8d13-4c3d-8aa1-c8273e7c648f', '望鄉夕泛', '望乡夕泛', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u6b78\\u61f7\\u5269\\u4e0d\\u5b89\\uff0c\\u4fc3\\u699c\\u72af\\u98a8\\u703e\\u3002\", \"\\u843d\\u5bbf\\u542b\\u6a13\\u8fd1\\uff0c\\u6d6e\\u6708\\u5e36\\u6c5f\\u5bd2\\u3002\", \"\\u559c\\u9010\\u884c\\u524d\\u81f3\\uff0c\\u6182\\u5f9e\\u671b\\u88cf\\u5bec\\u3002\", \"\\u4eca\\u591c\\u5357\\u679d\\u9d72\\uff0c\\u61c9\\u7121\\u7e5e\\u6a39\\u96e3\\u3002\"]"', '"[\"\\u5f52\\u6000\\u5269\\u4e0d\\u5b89\\uff0c\\u4fc3\\u699c\\u72af\\u98ce\\u6f9c\\u3002\", \"\\u843d\\u5bbf\\u542b\\u697c\\u8fd1\\uff0c\\u6d6e\\u6708\\u5e26\\u6c5f\\u5bd2\\u3002\", \"\\u559c\\u9010\\u884c\\u524d\\u81f3\\uff0c\\u5fe7\\u4ece\\u671b\\u91cc\\u5bbd\\u3002\", \"\\u4eca\\u591c\\u5357\\u679d\\u9e4a\\uff0c\\u5e94\\u65e0\\u7ed5\\u6811\\u96be\\u3002\"]"', '诗', 'shi', '', NULL, '望鄉夕泛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1c53beb-7132-4f59-8243-459845f7c9c2', '久客臨海有懷', '久客临海有怀', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u5929\\u6daf\\u975e\\u65e5\\u89c0\\uff0c\\u5730\\u5c7a\\u671b\\u661f\\u6a13\\u3002\", \"\\u7df4\\u5149\\u6416\\u4e82\\u99ac\\uff0c\\u528d\\u6c23\\u4e0a\\u9023\\u725b\\u3002\", \"\\u8349\\u6fd5\\u59d1\\u8607\\u5915\\uff0c\\u8449\\u4e0b\\u6d1e\\u5ead\\u79cb\\u3002\", \"\\u6b32\\u77e5\\u60bd\\u65b7\\u610f\\uff0c\\u6c5f\\u4e0a\\u6d89\\u5b89\\u6d41\\u3002\"]"', '"[\"\\u5929\\u6daf\\u975e\\u65e5\\u89c2\\uff0c\\u5730\\u5c7a\\u671b\\u661f\\u697c\\u3002\", \"\\u7ec3\\u5149\\u6447\\u4e71\\u9a6c\\uff0c\\u5251\\u6c14\\u4e0a\\u8fde\\u725b\\u3002\", \"\\u8349\\u6e7f\\u59d1\\u82cf\\u5915\\uff0c\\u53f6\\u4e0b\\u6d1e\\u5ead\\u79cb\\u3002\", \"\\u6b32\\u77e5\\u51c4\\u65ad\\u610f\\uff0c\\u6c5f\\u4e0a\\u6d89\\u5b89\\u6d41\\u3002\"]"', '诗', 'shi', '', NULL, '久客臨海有懷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d51e4e09-6f51-422d-915d-0c2ac475201b', '遊兗部逢孔君自衞來欣然相遇若舊', '游兖部逢孔君自衞来欣然相遇若旧', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u904a\\u4eba\\u81ea\\u885e\\u8fd4\\uff0c\\u80cc\\u5ba2\\u9694\\u6dee\\u4f86\\u3002\", \"\\u50be\\u84cb\\u91d1\\u862d\\u5408\\uff0c\\u5fd8\\u7b4c\\u7389\\u8449\\u958b\\u3002\", \"\\u7e41\\u82b1\\u660e\\u65e5\\u67f3\\uff0c\\u758e\\u854a\\u843d\\u98a8\\u6885\\u3002\", \"\\u5c07\\u671f\\u91cd\\u4ea4\\u614b\\uff0c\\u6642\\u6170\\u4e0d\\u7136\\u7070\\u3002\"]"', '"[\"\\u6e38\\u4eba\\u81ea\\u885e\\u8fd4\\uff0c\\u80cc\\u5ba2\\u9694\\u6dee\\u6765\\u3002\", \"\\u503e\\u76d6\\u91d1\\u5170\\u5408\\uff0c\\u5fd8\\u7b4c\\u7389\\u53f6\\u5f00\\u3002\", \"\\u7e41\\u82b1\\u660e\\u65e5\\u67f3\\uff0c\\u758e\\u854a\\u843d\\u98ce\\u6885\\u3002\", \"\\u5c06\\u671f\\u91cd\\u4ea4\\u6001\\uff0c\\u65f6\\u6170\\u4e0d\\u7136\\u7070\\u3002\"]"', '诗', 'shi', '', NULL, '遊兗部逢孔君自衞來欣然相遇若舊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('445a865f-d856-4109-b818-d95b5e19f50b', '西京守歲', '西京守岁', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u9591\\u5c45\\u5be1\\u8a00\\u5bb4\\uff0c\\u7368\\u5750\\u6158\\u98a8\\u5875\\u3002\", \"\\u5ffd\\u898b\\u56b4\\u51ac\\u76e1\\uff0c\\u65b9\\u77e5\\u5217\\u5bbf\\u6625\\u3002\", \"\\u591c\\u5c07\\u5bd2\\u8272\\u53bb\\uff0c\\u5e74\\u5171\\u66c9\\u5149\\u65b0\\u3002\", \"\\u803f\\u803f\\u4ed6\\u9109\\u5915\\uff0c\\u7121\\u7531\\u5c55\\u820a\\u89aa\\u3002\"]"', '"[\"\\u95f2\\u5c45\\u5be1\\u8a00\\u5bb4\\uff0c\\u72ec\\u5750\\u60e8\\u98ce\\u5c18\\u3002\", \"\\u5ffd\\u89c1\\u4e25\\u51ac\\u5c3d\\uff0c\\u65b9\\u77e5\\u5217\\u5bbf\\u6625\\u3002\", \"\\u591c\\u5c06\\u5bd2\\u8272\\u53bb\\uff0c\\u5e74\\u5171\\u6653\\u5149\\u65b0\\u3002\", \"\\u803f\\u803f\\u4ed6\\u4e61\\u5915\\uff0c\\u65e0\\u7531\\u5c55\\u65e7\\u4eb2\\u3002\"]"', '诗', 'shi', '', NULL, '西京守歲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f0f7eb7-8cac-48e2-bf44-6f54f71e5552', '同辛簿簡仰酬思玄上人林泉四首 一', '同辛簿简仰酬思玄上人林泉四首 一', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u805e\\u541b\\u62db\\u96b1\\u5730\\uff0c\\u9ae3\\u9af4\\u6b66\\u9675\\u6625\\u3002\", \"\\u7ddd\\u82b0\\u77e5\\u9084\\u695a\\uff0c\\u62ab\\u699b\\u4f3c\\u907f\\u79e6\\u3002\", \"\\u5d29\\u67e5\\u5e74\\u7940\\u7a4d\\uff0c\\u5e7d\\u8349\\u6b72\\u6642\\u65b0\\u3002\", \"\\u4e00\\u8b1d\\u6ec4\\u6d6a\\u6c34\\uff0c\\u5b89\\u77e5\\u6709\\u9038\\u4eba\\u3002\"]"', '"[\"\\u95fb\\u541b\\u62db\\u9690\\u5730\\uff0c\\u9ae3\\u9af4\\u6b66\\u9675\\u6625\\u3002\", \"\\u7f09\\u82b0\\u77e5\\u8fd8\\u695a\\uff0c\\u62ab\\u699b\\u4f3c\\u907f\\u79e6\\u3002\", \"\\u5d29\\u67e5\\u5e74\\u7940\\u79ef\\uff0c\\u5e7d\\u8349\\u5c81\\u65f6\\u65b0\\u3002\", \"\\u4e00\\u8c22\\u6ca7\\u6d6a\\u6c34\\uff0c\\u5b89\\u77e5\\u6709\\u9038\\u4eba\\u3002\"]"', '诗', 'shi', '', NULL, '同辛簿簡仰酬思玄上人林泉四首 一 shi');
