INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdb261df-5b9e-4ad0-8a6a-64e925a48360', '秋日餞陸道士陳文林', '秋日饯陆道士陈文林', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u9752\\u725b\\u904a\\u83ef\\u5dbd\\uff0c\\u8d64\\u99ac\\u8d70\\u5433\\u5bae\\u3002\", \"\\u7389\\u67f1\\u96e2\\u9d3b\\u6028\\uff0c\\u91d1\\u7f4d\\u6d6e\\u87fb\\u7a7a\\u3002\", \"\\u65e5\\u973d\\u5d24\\u9675\\u96e8\\uff0c\\u5875\\u8d77\\u6d1b\\u967d\\u98a8\\u3002\", \"\\u552f\\u7576\\u7384\\u5ea6\\u6708\\uff0c\\u5343\\u91cc\\u8207\\u541b\\u540c\\u3002\"]"', '"[\"\\u9752\\u725b\\u6e38\\u534e\\u5cb3\\uff0c\\u8d64\\u9a6c\\u8d70\\u5434\\u5bab\\u3002\", \"\\u7389\\u67f1\\u79bb\\u9e3f\\u6028\\uff0c\\u91d1\\u7f4d\\u6d6e\\u8681\\u7a7a\\u3002\", \"\\u65e5\\u9701\\u5d24\\u9675\\u96e8\\uff0c\\u5c18\\u8d77\\u6d1b\\u9633\\u98ce\\u3002\", \"\\u552f\\u5f53\\u7384\\u5ea6\\u6708\\uff0c\\u5343\\u91cc\\u4e0e\\u541b\\u540c\\u3002\"]"', '诗', 'shi', '', NULL, '秋日餞陸道士陳文林 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ee92b53-6d15-45cd-9096-4bed714107ff', '送鄭少府入遼共賦俠客遠從戎', '送郑少府入辽共赋侠客远从戎', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u908a\\u70fd\\u8b66\\u6986\\u585e\\uff0c\\u4fe0\\u5ba2\\u5ea6\\u6851\\u4e7e\\u3002\", \"\\u67f3\\u8449\\u958b\\u9280\\u93d1\\uff0c\\u6843\\u82b1\\u7167\\u7389\\u978d\\u3002\", \"\\u6eff\\u6708\\u81e8\\u5f13\\u5f71\\uff0c\\u9023\\u661f\\u5165\\u528d\\u7aef\\u3002\", \"\\u4e0d\\u5b78\\u71d5\\u4e39\\u5ba2\\uff0c\\u7a7a\\u6b4c\\u6613\\u6c34\\u5bd2\\u3002\"]"', '"[\"\\u8fb9\\u70fd\\u8b66\\u6986\\u585e\\uff0c\\u4fa0\\u5ba2\\u5ea6\\u6851\\u5e72\\u3002\", \"\\u67f3\\u53f6\\u5f00\\u94f6\\u955d\\uff0c\\u6843\\u82b1\\u7167\\u7389\\u978d\\u3002\", \"\\u6ee1\\u6708\\u4e34\\u5f13\\u5f71\\uff0c\\u8fde\\u661f\\u5165\\u5251\\u7aef\\u3002\", \"\\u4e0d\\u5b66\\u71d5\\u4e39\\u5ba2\\uff0c\\u7a7a\\u6b4c\\u6613\\u6c34\\u5bd2\\u3002\"]"', '诗', 'shi', '', NULL, '送鄭少府入遼共賦俠客遠從戎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c0b55f8-96a5-4744-ab32-00fe4282a127', '送費六還蜀', '送费六还蜀', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u661f\\u6a13\\u671b\\u8700\\u9053\\uff0c\\u6708\\u5cfd\\u6307\\u5433\\u9580\\u3002\", \"\\u842c\\u884c\\u6d41\\u5225\\u6dda\\uff0c\\u4e5d\\u6298\\u5207\\u9a5a\\u9b42\\u3002\", \"\\u96ea\\u5f71\\u542b\\u82b1\\u843d\\uff0c\\u96f2\\u9670\\u5e36\\u8449\\u660f\\u3002\", \"\\u9084\\u6101\\u4e09\\u5f91\\u665a\\uff0c\\u7368\\u5c0d\\u4e00\\u6e05\\u5c0a\\u3002\"]"', '"[\"\\u661f\\u697c\\u671b\\u8700\\u9053\\uff0c\\u6708\\u5ce1\\u6307\\u5434\\u95e8\\u3002\", \"\\u4e07\\u884c\\u6d41\\u522b\\u6cea\\uff0c\\u4e5d\\u6298\\u5207\\u60ca\\u9b42\\u3002\", \"\\u96ea\\u5f71\\u542b\\u82b1\\u843d\\uff0c\\u4e91\\u9634\\u5e26\\u53f6\\u660f\\u3002\", \"\\u8fd8\\u6101\\u4e09\\u5f84\\u665a\\uff0c\\u72ec\\u5bf9\\u4e00\\u6e05\\u5c0a\\u3002\"]"', '诗', 'shi', '', NULL, '送費六還蜀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a362a90-f640-43f0-a1bd-5bc9a191027e', '秋日送侯四得彈字', '秋日送侯四得弹字', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u6211\\u7559\\u5b89\\u8c79\\u96b1\\uff0c\\u541b\\u53bb\\u5b78\\u9d6c\\u6476\\u3002\", \"\\u5c90\\u8def\\u5206\\u895f\\u6613\\uff0c\\u98a8\\u96f2\\u4fc3\\u819d\\u96e3\\u3002\", \"\\u5915\\u6f32\\u6d41\\u6ce2\\u6025\\uff0c\\u79cb\\u5c71\\u843d\\u65e5\\u5bd2\\u3002\", \"\\u60df\\u6709\\u601d\\u6b78\\u5f15\\uff0c\\u60bd\\u65b7\\u7232\\u541b\\u5f48\\u3002\"]"', '"[\"\\u6211\\u7559\\u5b89\\u8c79\\u9690\\uff0c\\u541b\\u53bb\\u5b66\\u9e4f\\u629f\\u3002\", \"\\u5c90\\u8def\\u5206\\u895f\\u6613\\uff0c\\u98ce\\u4e91\\u4fc3\\u819d\\u96be\\u3002\", \"\\u5915\\u6da8\\u6d41\\u6ce2\\u6025\\uff0c\\u79cb\\u5c71\\u843d\\u65e5\\u5bd2\\u3002\", \"\\u60df\\u6709\\u601d\\u5f52\\u5f15\\uff0c\\u51c4\\u65ad\\u4e3a\\u541b\\u5f39\\u3002\"]"', '诗', 'shi', '', NULL, '秋日送侯四得彈字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79490fcc-6112-4ea4-9972-e52f0478e852', '秋日送尹大赴京', '秋日送尹大赴京', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u6302\\u74e2\\u4f59\\u96b1\\u821c\\uff0c\\u8ca0\\u9f0e\\u723e\\u5e72\\u6e6f\\u3002\", \"\\u7af9\\u8449\\u96e2\\u7f47\\u6eff\\uff0c\\u6843\\u82b1\\u5225\\u8def\\u9577\\u3002\", \"\\u4f4e\\u6cb3\\u803f\\u79cb\\u8272\\uff0c\\u843d\\u6708\\u62b1\\u5bd2\\u5149\\u3002\", \"\\u7d20\\u66f8\\u5982\\u53ef\\u55e3\\uff0c\\u5e7d\\u8c37\\u7ada\\u8cd3\\u884c\\u3002\"]"', '"[\"\\u6302\\u74e2\\u4f59\\u9690\\u821c\\uff0c\\u8d1f\\u9f0e\\u5c14\\u5e72\\u6c64\\u3002\", \"\\u7af9\\u53f6\\u79bb\\u7f47\\u6ee1\\uff0c\\u6843\\u82b1\\u522b\\u8def\\u957f\\u3002\", \"\\u4f4e\\u6cb3\\u803f\\u79cb\\u8272\\uff0c\\u843d\\u6708\\u62b1\\u5bd2\\u5149\\u3002\", \"\\u7d20\\u4e66\\u5982\\u53ef\\u55e3\\uff0c\\u5e7d\\u8c37\\ud856\\ude5f\\u5bbe\\u884c\\u3002\"]"', '诗', 'shi', '', NULL, '秋日送尹大赴京 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb9d6302-7111-405b-9c89-3819fda539fa', '秋夜送閰五還潤州', '秋夜送閰五还润州', 063c2396-8277-4e2b-a3df-e067749946da, '唐', '"[\"\\u901a\\u838a\\u62b5\\u820a\\u91cc\\uff0c\\u6e9d\\u6c34\\u6ce3\\u65b0\\u77e5\\u3002\", \"\\u65b7\\u96f2\\u98c4\\u6613\\u6eef\\uff0c\\u9023\\u9732\\u7a4d\\u96e3\\u62ab\\u3002\", \"\\u7d20\\u98a8\\u557c\\u8fe5\\u581e\\uff0c\\u9a5a\\u6708\\u7e5e\\u758e\\u679d\\u3002\", \"\\u7121\\u529b\\u52f5\\u77ed\\u7ff0\\uff0c\\u8f15\\u8209\\u9001\\u9577\\u96e2\\u3002\"]"', '"[\"\\u901a\\u5e84\\u62b5\\u65e7\\u91cc\\uff0c\\u6c9f\\u6c34\\u6ce3\\u65b0\\u77e5\\u3002\", \"\\u65ad\\u4e91\\u98d8\\u6613\\u6ede\\uff0c\\u8fde\\u9732\\u79ef\\u96be\\u62ab\\u3002\", \"\\u7d20\\u98ce\\u557c\\u8fe5\\u581e\\uff0c\\u60ca\\u6708\\u7ed5\\u758e\\u679d\\u3002\", \"\\u65e0\\u529b\\u52b1\\u77ed\\u7ff0\\uff0c\\u8f7b\\u4e3e\\u9001\\u957f\\u79bb\\u3002\"]"', '诗', 'shi', '', NULL, '秋夜送閰五還潤州 shi');